  @doc """
  Builds a JSON-serializable candidate refresh artifact.
  """
  def build(%ResultSet{} = result_set, opts \\ []) do
    refresh = stringify_keys(Keyword.fetch!(opts, :candidate_refresh))
    generated_at = Keyword.get_lazy(opts, :generated_at, &DateTime.utc_now/0)
    policy = Map.get(refresh, "scoring_policy", %{})
    constraints = Map.get(refresh, "constraints", %{})

    event_results = canonical_event_results(result_set.event_results)
    windows = refreshed_windows(event_results)
    {resource_summaries, resource_filter_summaries} = resource_summary_inputs(refresh)

    raw_candidates =
      event_results
      |> candidate_activities(refresh, constraints, policy)
      |> Enum.sort_by(&{&1["scenario_id"], &1["starts_at_s"], &1["id"]})

    {contact_candidates, contact_filter_report} =
      apply_contact_filters(raw_candidates, refresh)

    {candidates, resource_filter_report} =
      apply_resource_filters(
        contact_candidates,
        refresh,
        resource_summaries,
        resource_filter_summaries
      )

    contact_allocation_report =
      candidates
      |> contact_allocation_candidates(contact_filter_report)
      |> contact_allocation_report(refresh)

    {candidates, allocation_dropped_candidates} =
      apply_contact_allocation(candidates, contact_allocation_report)

    {candidates, budget_dropped_candidates, refresh_budget_report} =
      apply_candidate_budget(candidates, refresh)

    candidates = attach_candidate_activity_context(candidates)

    invalidated_candidates =
      invalidated_candidates(
        refresh,
        candidates,
        mark_dropped_candidates(allocation_dropped_candidates, "dropped_by_contact_allocation") ++
          mark_dropped_candidates(budget_dropped_candidates, "dropped_by_candidate_budget")
      )

    candidate_diff_report = candidate_diff_report(refresh, candidates, invalidated_candidates)
    freshness_report = freshness_report(refresh, generated_at)

    %{
      "schema_version" => @schema_version,
      "schema_contract" => "candidate_refresh.v1",
      "artifact_type" => "candidate_refresh",
      "generated_at" => DateTime.to_iso8601(generated_at),
      "planner" => "OrbitalDynamics.CandidateRefresh.V1",
      "refresh_id" => refresh_id(refresh, result_set.study_id),
      "study_id" => encode_value(result_set.study_id),
      "snapshot_id" => snapshot_id(refresh),
      "current_epoch_s" => current_epoch_s(refresh),
      "remaining_horizon" => remaining_horizon(refresh),
      "accepted_planning_state" => accepted_planning_state_ref(refresh),
      "refreshed_windows" => windows,
      "candidate_activities" => candidates,
      "contact_intents" => contact_intents(candidates, refresh),
      "contact_filter_report" => contact_filter_report,
      "resource_summaries" => resource_summaries,
      "resource_filter_report" => resource_filter_report,
      "refresh_budget_report" => refresh_budget_report,
      "candidate_diff_report" => candidate_diff_report,
      "freshness_report" => freshness_report,
      "invalidated_candidates" => invalidated_candidates,
      "contact_allocation_report" => contact_allocation_report,
      "validation_records" => Validation.records_for_result_set(result_set),
      "warnings" =>
        warnings(
          refresh,
          candidates,
          result_set,
          contact_filter_report,
          allocation_dropped_candidates,
          resource_filter_report,
          refresh_budget_report,
          freshness_report
        ),
      "model_limits" => model_limits(),
      "assumptions" => assumptions(refresh, result_set),
      "provenance" => provenance(refresh, result_set),
      "source_window_lineage" => source_window_lineage(candidates)
    }
    |> maybe_put_artifact_operational_feedback(refresh)
  end

  defp maybe_put_artifact_operational_feedback(artifact, refresh) do
    feedback = operational_feedback(refresh)

    if operational_feedback_data_keys(feedback) == [] do
      artifact
    else
      Map.put(artifact, "operational_feedback", feedback)
    end
  end

