  @doc """
  Builds a compact branch-local candidate-diff replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not replay refresh generation, mutate
  candidates, select candidates, or write to Cadence.
  """
  def candidate_diff_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    branch_diff_summary =
      source_report_summary_branch_family(refresh_or_artifact, "candidate_diff_report")

    diff_summary =
      branch_diff_summary ||
        get_in(source_summary, ["source_reports", "candidate_diff_report"]) || %{}

    {summary_source, replay_scope} =
      if branch_diff_summary do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.candidate_diff_report",
          "candidate_diff_candidate_source_report_summary_only"
        }
      else
        {
          "candidate_refresh.source_report_provenance.candidate_diff_report",
          "candidate_diff_source_report_provenance_only"
        }
      end

    retained_candidate_count = summary_integer(diff_summary, "retained_candidate_count")
    new_candidate_count = summary_integer(diff_summary, "new_candidate_count")
    invalidated_candidate_count = summary_integer(diff_summary, "invalidated_candidate_count")

    diff_reason_counts = Map.get(diff_summary, "diff_reason_counts", %{})
    invalidated_reason_counts = Map.get(diff_summary, "invalidated_reason_counts", %{})
    semantic_change_reason_counts = Map.get(diff_summary, "semantic_change_reason_counts", %{})

    changed_field_counts =
      Map.get(diff_summary, "candidate_diff_changed_field_counts", %{})

    candidate_id_counts = Map.get(diff_summary, "candidate_diff_candidate_id_counts", %{})
    ground_station_counts = Map.get(diff_summary, "candidate_diff_ground_station_counts", %{})

    diff_pressure =
      new_candidate_count + invalidated_candidate_count > 0 or
        map_size(diff_reason_counts) > 0 or map_size(invalidated_reason_counts) > 0 or
        map_size(semantic_change_reason_counts) > 0 or map_size(changed_field_counts) > 0 or
        map_size(candidate_id_counts) > 0 or map_size(ground_station_counts) > 0

    new_candidate_pressure =
      new_candidate_count > 0 or
        summary_integer(diff_reason_counts, "not_present_in_prior_candidate_set") > 0

    invalidated_candidate_pressure =
      invalidated_candidate_count > 0 or map_size(invalidated_reason_counts) > 0

    semantic_change_pressure =
      map_size(semantic_change_reason_counts) > 0 or map_size(changed_field_counts) > 0 or
        summary_integer(
          diff_reason_counts,
          "present_in_prior_candidate_set_with_semantic_changes"
        ) >
          0

    %{
      "model" => "artifact_only_candidate_refresh_candidate_diff_replay_summary",
      "source" => summary_source,
      "contract" => source_report_summary_contract(diff_summary, "candidate_diff_report.v1"),
      "source_report_count" => summary_integer(diff_summary, "count"),
      "source_report_row_count" => summary_integer(diff_summary, "row_count"),
      "source_report_paths" => Map.get(diff_summary, "paths", []),
      "retained_candidate_count" => retained_candidate_count,
      "new_candidate_count" => new_candidate_count,
      "invalidated_candidate_count" => invalidated_candidate_count,
      "diff_reason_counts" => diff_reason_counts,
      "invalidated_reason_counts" => invalidated_reason_counts,
      "semantic_change_reason_counts" => semantic_change_reason_counts,
      "candidate_diff_changed_field_counts" => changed_field_counts,
      "candidate_diff_candidate_id_counts" => candidate_id_counts,
      "candidate_diff_ground_station_counts" => ground_station_counts,
      "trust_boundary_status" => Map.get(diff_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(diff_summary, "trust_boundaries", []),
      "branch_local_diff_pressure" => diff_pressure,
      "branch_local_new_candidate_pressure" => new_candidate_pressure,
      "branch_local_invalidated_candidate_pressure" => invalidated_candidate_pressure,
      "branch_local_semantic_change_pressure" => semantic_change_pressure,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => "not_granted_by_candidate_diff_replay_summary",
        "candidate_selection" => "not_performed_by_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local candidate-rejection replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not replay refresh generation, mutate
  candidates, select candidates, import rejected candidates, or write to
  Cadence.
  """
  def candidate_rejection_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    branch_rejection_summary =
      source_report_summary_branch_family(refresh_or_artifact, "candidate_rejection_report")

    rejection_summary =
      branch_rejection_summary ||
        get_in(source_summary, ["source_reports", "candidate_rejection_report"]) || %{}

    {summary_source, replay_scope} =
      if branch_rejection_summary do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.candidate_rejection_report",
          "candidate_rejection_candidate_source_report_summary_only"
        }
      else
        {
          "candidate_refresh.source_report_provenance.candidate_rejection_report",
          "candidate_rejection_source_report_provenance_only"
        }
      end

    rejected_count = summary_integer(rejection_summary, "rejected_count")
    reviewable_count = summary_integer(rejection_summary, "reviewable_count")

    invalid_candidate_input_count =
      summary_integer(rejection_summary, "invalid_candidate_input_count")

    rejection_reason_counts = Map.get(rejection_summary, "rejection_reason_counts", %{})
    required_action_counts = Map.get(rejection_summary, "required_operator_action_counts", %{})

    candidate_id_counts =
      Map.get(rejection_summary, "candidate_rejection_candidate_id_counts", %{})

    ground_station_counts =
      Map.get(rejection_summary, "candidate_rejection_ground_station_counts", %{})

    rejection_pressure =
      rejected_count + reviewable_count + invalid_candidate_input_count > 0 or
        map_size(rejection_reason_counts) > 0 or map_size(required_action_counts) > 0 or
        map_size(candidate_id_counts) > 0 or map_size(ground_station_counts) > 0

    review_pressure = reviewable_count > 0 or map_size(required_action_counts) > 0

    invalid_input_pressure =
      invalid_candidate_input_count > 0 or
        summary_integer(rejection_reason_counts, "invalid_candidate_input") > 0

    %{
      "model" => "artifact_only_candidate_refresh_candidate_rejection_replay_summary",
      "source" => summary_source,
      "contract" =>
        source_report_summary_contract(rejection_summary, "candidate_rejection_report.v1"),
      "source_report_count" => summary_integer(rejection_summary, "count"),
      "source_report_row_count" => summary_integer(rejection_summary, "row_count"),
      "source_report_paths" => Map.get(rejection_summary, "paths", []),
      "rejected_count" => rejected_count,
      "reviewable_count" => reviewable_count,
      "invalid_candidate_input_count" => invalid_candidate_input_count,
      "rejection_reason_counts" => rejection_reason_counts,
      "required_operator_action_counts" => required_action_counts,
      "candidate_rejection_candidate_id_counts" => candidate_id_counts,
      "candidate_rejection_ground_station_counts" => ground_station_counts,
      "trust_boundary_status" => Map.get(rejection_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(rejection_summary, "trust_boundaries", []),
      "branch_local_rejection_pressure" => rejection_pressure,
      "branch_local_review_pressure" => review_pressure,
      "branch_local_invalid_input_pressure" => invalid_input_pressure,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => "not_granted_by_candidate_rejection_replay_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_candidate_rejection_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local provider-counteroffer replay summary.

  The summary is derived from candidate-refresh source-report provenance. It
  does not replay refresh generation, accept counteroffers, mutate schedules,
  approve imports, or write to Cadence.
  """
  def provider_counteroffer_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    branch_counteroffer_summary =
      source_report_summary_branch_family(refresh_or_artifact, "provider_counteroffer_report")

    counteroffer_summary =
      branch_counteroffer_summary ||
        get_in(source_summary, ["source_reports", "provider_counteroffer_report"]) || %{}

    {summary_source, replay_scope} =
      if branch_counteroffer_summary do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.timeline_activity_state",
          "provider_counteroffer_candidate_source_report_summary_only"
        }
      else
        {
          "candidate_refresh.source_report_provenance.provider_counteroffer_report",
          "provider_counteroffer_source_report_provenance_only"
        }
      end

    reviewable_count = summary_integer(counteroffer_summary, "reviewable_count")
    cost_delta_count = summary_integer(counteroffer_summary, "counteroffer_cost_delta_count")
    timing_shift_count = summary_integer(counteroffer_summary, "counteroffer_timing_shift_count")
    start_delta_count = summary_integer(counteroffer_summary, "counteroffer_start_delta_count")
    end_delta_count = summary_integer(counteroffer_summary, "counteroffer_end_delta_count")

    duration_delta_count =
      summary_integer(counteroffer_summary, "counteroffer_duration_delta_count")

    lock_deadline_count =
      summary_integer(counteroffer_summary, "counteroffer_lock_deadline_count")

    plan_impact_summary_count = summary_integer(counteroffer_summary, "plan_impact_summary_count")

    cost_delta_total =
      numeric_value(Map.get(counteroffer_summary, "counteroffer_cost_delta_total")) || 0.0

    earliest_lock_deadline_s =
      numeric_value(Map.get(counteroffer_summary, "earliest_counteroffer_lock_deadline_s"))

    status_counts = Map.get(counteroffer_summary, "counteroffer_status_counts", %{})
    required_action_counts = Map.get(counteroffer_summary, "required_operator_action_counts", %{})

    import_readiness_summary_count =
      summary_integer(counteroffer_summary, "import_readiness_summary_count")

    import_readiness_status_counts =
      Map.get(counteroffer_summary, "import_readiness_status_counts", %{})

    import_classification_counts =
      Map.get(counteroffer_summary, "import_classification_counts", %{})

    import_status_counts =
      Map.get(counteroffer_summary, "provider_counteroffer_import_status_counts", %{})

    lock_deadline_status_counts =
      Map.get(counteroffer_summary, "counteroffer_lock_deadline_status_counts", %{})

    ids_by_import_status =
      Map.get(counteroffer_summary, "counteroffer_ids_by_import_status", %{})

    ids_by_required_import_action =
      Map.get(counteroffer_summary, "counteroffer_ids_by_required_import_action", %{})

    ids_by_lock_deadline_status =
      Map.get(counteroffer_summary, "counteroffer_ids_by_lock_deadline_status", %{})

    review_counteroffer_ids = Map.get(counteroffer_summary, "review_counteroffer_ids", [])

    no_import_required_counteroffer_ids =
      Map.get(counteroffer_summary, "no_import_required_counteroffer_ids", [])

    plan_impact_status_counts = Map.get(counteroffer_summary, "plan_impact_status_counts", %{})

    affected_station_entry_ids =
      Map.get(counteroffer_summary, "affected_station_calendar_entry_ids", [])

    affected_provider_entry_ids = Map.get(counteroffer_summary, "affected_provider_entry_ids", [])
    impact_counteroffer_ids = Map.get(counteroffer_summary, "impact_counteroffer_ids", [])

    timing_shift_counteroffer_ids =
      Map.get(counteroffer_summary, "timing_shift_counteroffer_ids", [])

    cost_delta_counteroffer_ids = Map.get(counteroffer_summary, "cost_delta_counteroffer_ids", [])

    review_pressure = reviewable_count > 0 or map_size(required_action_counts) > 0

    cost_pressure = cost_delta_count > 0 or length(cost_delta_counteroffer_ids) > 0

    timing_pressure =
      timing_shift_count + start_delta_count + end_delta_count + duration_delta_count > 0 or
        length(timing_shift_counteroffer_ids) > 0

    lock_pressure = lock_deadline_count > 0 or is_number(earliest_lock_deadline_s)

    import_readiness_pressure =
      import_readiness_summary_count > 0 or map_size(import_readiness_status_counts) > 0 or
        map_size(import_classification_counts) > 0 or map_size(import_status_counts) > 0 or
        map_size(lock_deadline_status_counts) > 0 or map_size(ids_by_import_status) > 0 or
        map_size(ids_by_required_import_action) > 0 or map_size(ids_by_lock_deadline_status) > 0 or
        length(review_counteroffer_ids) > 0 or length(no_import_required_counteroffer_ids) > 0

    plan_impact_pressure =
      plan_impact_summary_count > 0 or map_size(plan_impact_status_counts) > 0 or
        length(affected_station_entry_ids) > 0 or length(affected_provider_entry_ids) > 0 or
        length(impact_counteroffer_ids) > 0

    %{
      "model" => "artifact_only_candidate_refresh_provider_counteroffer_replay_summary",
      "source" => summary_source,
      "contract" =>
        source_report_summary_contract(counteroffer_summary, "provider_counteroffer_report.v1"),
      "source_report_count" => summary_integer(counteroffer_summary, "count"),
      "source_report_row_count" => summary_integer(counteroffer_summary, "row_count"),
      "source_report_paths" => Map.get(counteroffer_summary, "paths", []),
      "reviewable_count" => reviewable_count,
      "counteroffer_cost_delta_count" => cost_delta_count,
      "counteroffer_cost_delta_total" => cost_delta_total,
      "counteroffer_timing_shift_count" => timing_shift_count,
      "counteroffer_start_delta_count" => start_delta_count,
      "counteroffer_end_delta_count" => end_delta_count,
      "counteroffer_duration_delta_count" => duration_delta_count,
      "counteroffer_lock_deadline_count" => lock_deadline_count,
      "earliest_counteroffer_lock_deadline_s" => earliest_lock_deadline_s,
      "counteroffer_status_counts" => status_counts,
      "required_operator_action_counts" => required_action_counts,
      "import_readiness_summary_count" => import_readiness_summary_count,
      "import_readiness_status_counts" => import_readiness_status_counts,
      "import_classification_counts" => import_classification_counts,
      "provider_counteroffer_import_status_counts" => import_status_counts,
      "counteroffer_lock_deadline_status_counts" => lock_deadline_status_counts,
      "counteroffer_ids_by_import_status" => ids_by_import_status,
      "counteroffer_ids_by_required_import_action" => ids_by_required_import_action,
      "counteroffer_ids_by_lock_deadline_status" => ids_by_lock_deadline_status,
      "review_counteroffer_ids" => review_counteroffer_ids,
      "no_import_required_counteroffer_ids" => no_import_required_counteroffer_ids,
      "plan_impact_summary_count" => plan_impact_summary_count,
      "plan_impact_status_counts" => plan_impact_status_counts,
      "affected_station_calendar_entry_ids" => affected_station_entry_ids,
      "affected_provider_entry_ids" => affected_provider_entry_ids,
      "impact_counteroffer_ids" => impact_counteroffer_ids,
      "timing_shift_counteroffer_ids" => timing_shift_counteroffer_ids,
      "cost_delta_counteroffer_ids" => cost_delta_counteroffer_ids,
      "trust_boundary_status" => Map.get(counteroffer_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(counteroffer_summary, "trust_boundaries", []),
      "branch_local_counteroffer_pressure" =>
        review_pressure or cost_pressure or timing_pressure or lock_pressure or
          import_readiness_pressure or plan_impact_pressure or map_size(status_counts) > 0,
      "branch_local_counteroffer_review_pressure" => review_pressure,
      "branch_local_counteroffer_cost_pressure" => cost_pressure,
      "branch_local_counteroffer_timing_pressure" => timing_pressure,
      "branch_local_counteroffer_lock_pressure" => lock_pressure,
      "branch_local_counteroffer_import_readiness_pressure" => import_readiness_pressure,
      "branch_local_plan_impact_pressure" => plan_impact_pressure,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => "not_granted_by_provider_counteroffer_replay_summary",
        "provider_write" => "not_performed_by_summary",
        "schedule_mutation" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_provider_counteroffer_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local contact-contention replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not replay refresh generation, mutate
  contact allocation, select candidates, approve imports, or write to Cadence.
  """
  def contact_contention_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    branch_contention_summary =
      source_report_summary_branch_family(refresh_or_artifact, "contact_contention_report")

    contention_summary =
      branch_contention_summary ||
        get_in(source_summary, ["source_reports", "contact_contention_report"]) || %{}

    {summary_source, replay_scope} =
      if branch_contention_summary do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.contact_contention_report",
          "contact_contention_candidate_source_report_summary_only"
        }
      else
        {
          "candidate_refresh.source_report_provenance.contact_contention_report",
          "contact_contention_source_report_provenance_only"
        }
      end

    conflict_group_count = summary_integer(contention_summary, "conflict_group_count")

    invalid_contact_input_count =
      summary_integer(contention_summary, "invalid_contact_input_count")

    invalid_contact_input_ids = Map.get(contention_summary, "invalid_contact_input_ids")

    resource_scope_counts = Map.get(contention_summary, "resource_scope_counts", %{})

    ground_station_counts =
      Map.get(contention_summary, "contact_contention_ground_station_counts", %{})

    contact_id_counts = Map.get(contention_summary, "contact_contention_contact_id_counts", %{})
    required_action_counts = Map.get(contention_summary, "required_operator_action_counts", %{})
    direction_counts = Map.get(contention_summary, "direction_counts", %{})
    contact_ids_by_direction = Map.get(contention_summary, "contact_ids_by_direction", %{})
    direction_routing = Map.get(contention_summary, "direction_routing", %{})

    %{
      "model" => "artifact_only_candidate_refresh_contact_contention_replay_summary",
      "source" => summary_source,
      "contract" =>
        source_report_summary_contract(contention_summary, "contact_contention_report.v1"),
      "source_report_count" => summary_integer(contention_summary, "count"),
      "source_report_row_count" => summary_integer(contention_summary, "row_count"),
      "source_report_paths" => Map.get(contention_summary, "paths", []),
      "conflict_group_count" => conflict_group_count,
      "invalid_contact_input_count" => invalid_contact_input_count,
      "invalid_contact_input_ids" => invalid_contact_input_ids,
      "resource_scope_counts" => resource_scope_counts,
      "contact_contention_ground_station_counts" => ground_station_counts,
      "contact_contention_contact_id_counts" => contact_id_counts,
      "required_operator_action_counts" => required_action_counts,
      "direction_counts" => direction_counts,
      "contact_ids_by_direction" => contact_ids_by_direction,
      "direction_routing" => direction_routing,
      "trust_boundary_status" => Map.get(contention_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(contention_summary, "trust_boundaries", []),
      "branch_local_contact_contention_pressure" =>
        conflict_group_count + invalid_contact_input_count > 0 or
          invalid_contact_input_ids not in [nil, []] or
          map_size(resource_scope_counts) > 0 or map_size(ground_station_counts) > 0 or
          map_size(contact_id_counts) > 0 or map_size(required_action_counts) > 0 or
          map_size(direction_counts) > 0 or map_size(contact_ids_by_direction) > 0 or
          map_size(direction_routing) > 0,
      "branch_local_contact_contention_conflict_pressure" => conflict_group_count > 0,
      "branch_local_invalid_contact_input_pressure" =>
        invalid_contact_input_count > 0 or invalid_contact_input_ids not in [nil, []],
      "branch_local_contact_contention_review_pressure" => map_size(required_action_counts) > 0,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => "not_granted_by_contact_contention_replay_summary",
        "contact_allocation" => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_contact_contention_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local contact-contention-resolution replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not replay refresh generation, mutate
  contact allocation, select candidates, approve imports, or write to Cadence.
  """
  def contact_contention_resolution_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    branch_resolution_summary =
      source_report_summary_branch_family(
        refresh_or_artifact,
        "contact_contention_resolution_report"
      )

    resolution_summary =
      branch_resolution_summary ||
        get_in(source_summary, ["source_reports", "contact_contention_resolution_report"]) ||
        %{}

    {summary_source, replay_scope} =
      if branch_resolution_summary do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.contact_contention_resolution_report",
          "contact_contention_resolution_candidate_source_report_summary_only"
        }
      else
        {
          "candidate_refresh.source_report_provenance.contact_contention_resolution_report",
          "contact_contention_resolution_source_report_provenance_only"
        }
      end

    recommendation_count = summary_integer(resolution_summary, "recommendation_count")
    deferred_contact_count = summary_integer(resolution_summary, "deferred_contact_count")
    resolution_status_counts = Map.get(resolution_summary, "resolution_status_counts", %{})
    selection_reason_counts = Map.get(resolution_summary, "selection_reason_counts", %{})

    source_summary_model_counts =
      Map.get(resolution_summary, "source_summary_model_counts", %{}) |> non_empty_map()

    source_summary_schema_contract_counts =
      Map.get(resolution_summary, "source_summary_schema_contract_counts", %{})
      |> non_empty_map()

    source_artifact_type_counts =
      Map.get(resolution_summary, "source_artifact_type_counts", %{}) |> non_empty_map()

    conflict_group_count = summary_integer(resolution_summary, "conflict_group_count")

    review_recommendation_count =
      summary_integer(resolution_summary, "review_recommendation_count")

    recommendation_group_ids = Map.get(resolution_summary, "recommendation_group_ids", [])
    review_group_ids = Map.get(resolution_summary, "review_group_ids", [])
    ambiguous_group_ids = Map.get(resolution_summary, "ambiguous_group_ids", [])

    ambiguous_duplicate_contact_ids =
      Map.get(resolution_summary, "ambiguous_duplicate_contact_ids", [])

    ambiguous_duplicate_contact_ids_by_group =
      Map.get(resolution_summary, "ambiguous_duplicate_contact_ids_by_group_id", %{})

    required_capacity_fraction =
      numeric_value(Map.get(resolution_summary, "capacity_pack_required_capacity_fraction")) ||
        0.0

    selected_capacity_fraction =
      numeric_value(
        Map.get(resolution_summary, "capacity_pack_selected_required_capacity_fraction")
      ) || 0.0

    deferred_capacity_fraction =
      numeric_value(
        Map.get(resolution_summary, "capacity_pack_deferred_required_capacity_fraction")
      ) || 0.0

    required_by_station =
      Map.get(
        resolution_summary,
        "capacity_pack_required_capacity_fraction_by_ground_station",
        %{}
      )

    selected_by_station =
      Map.get(
        resolution_summary,
        "capacity_pack_selected_required_capacity_fraction_by_ground_station",
        %{}
      )

    deferred_by_station =
      Map.get(
        resolution_summary,
        "capacity_pack_deferred_required_capacity_fraction_by_ground_station",
        %{}
      )

    required_by_status =
      Map.get(resolution_summary, "capacity_pack_required_capacity_fraction_by_status", %{})

    required_source_counts =
      Map.get(resolution_summary, "required_capacity_fraction_source_counts", %{})

    required_contact_ids_by_source =
      Map.get(resolution_summary, "required_capacity_fraction_contact_ids_by_source", %{})

    selected_contact_ids = Map.get(resolution_summary, "selected_contact_ids", [])
    deferred_contact_ids = Map.get(resolution_summary, "deferred_contact_ids", [])
    review_contact_ids = Map.get(resolution_summary, "review_contact_ids", [])

    selected_contact_ids_by_group =
      Map.get(resolution_summary, "selected_contact_ids_by_group_id", %{})

    deferred_contact_ids_by_group =
      Map.get(resolution_summary, "deferred_contact_ids_by_group_id", %{})

    review_contact_ids_by_group =
      Map.get(resolution_summary, "review_contact_ids_by_group_id", %{})

    selected_contact_ids_by_selection_reason =
      Map.get(resolution_summary, "selected_contact_ids_by_selection_reason", %{})

    selected_contact_ids_by_station =
      Map.get(resolution_summary, "selected_contact_ids_by_ground_station", %{})

    deferred_contact_ids_by_station =
      Map.get(resolution_summary, "deferred_contact_ids_by_ground_station", %{})

    resource_scope_counts = Map.get(resolution_summary, "resource_scope_counts", %{})

    selected_contact_ids_by_resource_scope =
      Map.get(resolution_summary, "selected_contact_ids_by_resource_scope", %{})

    deferred_contact_ids_by_resource_scope =
      Map.get(resolution_summary, "deferred_contact_ids_by_resource_scope", %{})

    review_contact_ids_by_resource_scope =
      Map.get(resolution_summary, "review_contact_ids_by_resource_scope", %{})

    direction_counts = Map.get(resolution_summary, "direction_counts", %{})
    contact_ids_by_direction = Map.get(resolution_summary, "contact_ids_by_direction", %{})
    direction_routing = Map.get(resolution_summary, "direction_routing", %{})
    required_action_counts = Map.get(resolution_summary, "required_operator_action_counts", %{})

    review_contact_ids_by_action =
      Map.get(resolution_summary, "review_contact_ids_by_action", %{})

    source_report_paths = Map.get(resolution_summary, "paths") || []

    capacity_pack_pressure =
      required_capacity_fraction + selected_capacity_fraction + deferred_capacity_fraction > 0.0 or
        map_size(required_by_station) > 0 or map_size(selected_by_station) > 0 or
        map_size(deferred_by_station) > 0 or map_size(required_by_status) > 0 or
        map_size(required_source_counts) > 0 or map_size(required_contact_ids_by_source) > 0

    deferred_contact_pressure =
      deferred_contact_count > 0 or deferred_contact_ids != [] or
        map_size(deferred_contact_ids_by_station) > 0 or deferred_capacity_fraction > 0.0 or
        map_size(deferred_by_station) > 0 or map_size(deferred_contact_ids_by_group) > 0 or
        map_size(deferred_contact_ids_by_resource_scope) > 0

    compact_resolution_pressure =
      conflict_group_count > 0 or review_recommendation_count > 0 or
        recommendation_group_ids != [] or review_group_ids != [] or review_contact_ids != [] or
        ambiguous_group_ids != [] or ambiguous_duplicate_contact_ids != [] or
        map_size(ambiguous_duplicate_contact_ids_by_group) > 0 or
        map_size(selected_contact_ids_by_group) > 0 or
        map_size(deferred_contact_ids_by_group) > 0 or
        map_size(review_contact_ids_by_group) > 0 or map_size(resource_scope_counts) > 0 or
        map_size(selected_contact_ids_by_selection_reason) > 0 or
        map_size(selected_contact_ids_by_resource_scope) > 0 or
        map_size(deferred_contact_ids_by_resource_scope) > 0 or
        map_size(review_contact_ids_by_resource_scope) > 0 or
        map_size(review_contact_ids_by_action) > 0

    %{
      "model" => "artifact_only_candidate_refresh_contact_contention_resolution_replay_summary",
      "source" => summary_source,
      "contract" =>
        source_report_summary_contract(
          resolution_summary,
          "contact_contention_resolution_report.v1"
        ),
      "source_report_count" => summary_integer(resolution_summary, "count"),
      "source_report_row_count" => summary_integer(resolution_summary, "row_count"),
      "source_report_paths" => source_report_paths,
      "source_summary_model_counts" => source_summary_model_counts,
      "source_summary_schema_contract_counts" => source_summary_schema_contract_counts,
      "source_artifact_type_counts" => source_artifact_type_counts,
      "conflict_group_count" =>
        case conflict_group_count do
          count when count > 0 -> count
          _count -> nil
        end,
      "recommendation_count" => recommendation_count,
      "review_recommendation_count" =>
        case review_recommendation_count do
          count when count > 0 -> count
          _count -> nil
        end,
      "recommendation_group_ids" => non_empty_list(recommendation_group_ids),
      "review_group_ids" => non_empty_list(review_group_ids),
      "ambiguous_group_ids" => non_empty_list(ambiguous_group_ids),
      "ambiguous_duplicate_contact_ids" => non_empty_list(ambiguous_duplicate_contact_ids),
      "ambiguous_duplicate_contact_ids_by_group_id" =>
        non_empty_map(ambiguous_duplicate_contact_ids_by_group),
      "deferred_contact_count" => deferred_contact_count,
      "resolution_status_counts" => resolution_status_counts,
      "selection_reason_counts" => selection_reason_counts,
      "capacity_pack_required_capacity_fraction" => required_capacity_fraction,
      "capacity_pack_selected_required_capacity_fraction" => selected_capacity_fraction,
      "capacity_pack_deferred_required_capacity_fraction" => deferred_capacity_fraction,
      "capacity_pack_required_capacity_fraction_by_ground_station" => required_by_station,
      "capacity_pack_selected_required_capacity_fraction_by_ground_station" =>
        selected_by_station,
      "capacity_pack_deferred_required_capacity_fraction_by_ground_station" =>
        deferred_by_station,
      "capacity_pack_required_capacity_fraction_by_status" => non_empty_map(required_by_status),
      "required_capacity_fraction_source_counts" => non_empty_map(required_source_counts),
      "required_capacity_fraction_contact_ids_by_source" =>
        non_empty_map(required_contact_ids_by_source),
      "selected_contact_ids" => selected_contact_ids,
      "deferred_contact_ids" => deferred_contact_ids,
      "review_contact_ids" => non_empty_list(review_contact_ids),
      "selected_contact_ids_by_group_id" => non_empty_map(selected_contact_ids_by_group),
      "deferred_contact_ids_by_group_id" => non_empty_map(deferred_contact_ids_by_group),
      "review_contact_ids_by_group_id" => non_empty_map(review_contact_ids_by_group),
      "selected_contact_ids_by_selection_reason" =>
        non_empty_map(selected_contact_ids_by_selection_reason),
      "selected_contact_ids_by_ground_station" => selected_contact_ids_by_station,
      "deferred_contact_ids_by_ground_station" => deferred_contact_ids_by_station,
      "resource_scope_counts" => non_empty_map(resource_scope_counts),
      "selected_contact_ids_by_resource_scope" =>
        non_empty_map(selected_contact_ids_by_resource_scope),
      "deferred_contact_ids_by_resource_scope" =>
        non_empty_map(deferred_contact_ids_by_resource_scope),
      "review_contact_ids_by_resource_scope" =>
        non_empty_map(review_contact_ids_by_resource_scope),
      "direction_counts" => direction_counts,
      "contact_ids_by_direction" => contact_ids_by_direction,
      "direction_routing" => direction_routing,
      "required_operator_action_counts" => required_action_counts,
      "review_contact_ids_by_action" => non_empty_map(review_contact_ids_by_action),
      "trust_boundary_status" => Map.get(resolution_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(resolution_summary, "trust_boundaries", []),
      "branch_local_contact_contention_resolution_pressure" =>
        recommendation_count + deferred_contact_count > 0 or
          map_size(resolution_status_counts) > 0 or map_size(selection_reason_counts) > 0 or
          compact_resolution_pressure or
          selected_contact_ids != [] or deferred_contact_ids != [] or
          map_size(selected_contact_ids_by_station) > 0 or
          map_size(deferred_contact_ids_by_station) > 0 or capacity_pack_pressure or
          map_size(direction_counts) > 0 or map_size(contact_ids_by_direction) > 0 or
          map_size(direction_routing) > 0 or
          map_size(required_action_counts) > 0,
      "branch_local_deferred_contact_pressure" => deferred_contact_pressure,
      "branch_local_capacity_pack_pressure" => capacity_pack_pressure,
      "branch_local_contact_contention_resolution_action_pressure" =>
        map_size(required_action_counts) > 0,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => "not_granted_by_contact_contention_resolution_replay_summary",
        "contact_allocation" => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_contact_contention_resolution_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local contact-allocation replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not replay refresh generation, mutate
