      "station_reservation_ids" => station_reservation_ids,
      "station_reservation_contact_ids_by_status" => station_reservation_contact_ids_by_status,
      "station_reservation_contact_ids_by_reserved_by" =>
        station_reservation_contact_ids_by_reserved_by,
      "station_reservation_ids_by_status" => station_reservation_ids_by_status,
      "station_reservation_ids_by_reserved_by" => station_reservation_ids_by_reserved_by,
      "station_reservation_expires_at_s" => station_reservation_expires_at_s,
      "station_reservation_expiration_now_s" => station_reservation_expiration_now_s,
      "station_reservation_expiration_status_counts" =>
        station_reservation_expiration_status_counts,
      "station_reservation_active_contact_count" => station_reservation_active_contact_count,
      "station_reservation_expired_contact_count" => station_reservation_expired_contact_count,
      "station_reservation_declared_expiration_contact_count" =>
        station_reservation_declared_expiration_contact_count,
      "station_reservation_missing_expiration_contact_count" =>
        station_reservation_missing_expiration_contact_count,
      "earliest_station_reservation_expires_at_s" => earliest_station_reservation_expires_at_s,
      "station_reservation_contact_ids_by_expiration_status" =>
        station_reservation_contact_ids_by_expiration_status,
      "station_reservation_ids_by_expiration_status" =>
        station_reservation_ids_by_expiration_status,
      "provider_reservation_candidate_contact_count" =>
        provider_reservation_candidate_contact_count,
      "provider_reservation_request_contact_count" => provider_reservation_request_contact_count,
      "provider_reservation_review_contact_count" => provider_reservation_review_contact_count,
      "provider_reservation_no_request_contact_count" =>
        provider_reservation_no_request_contact_count,
      "provider_reservation_request_status_counts" => provider_reservation_request_status_counts,
      "source_summary_model_counts" => source_summary_model_counts,
      "source_summary_schema_contract_counts" => source_summary_schema_contract_counts,
      "source_artifact_type_counts" => source_artifact_type_counts,
      "provider_reservation_request_summary_schema_contract" =>
        provider_reservation_request_summary_schema_contract,
      "contact_allocation_summary_schema_contract" => contact_allocation_summary_schema_contract,
      "station_pressure_summary_schema_contract" => station_pressure_summary_schema_contract,
      "reservation_conflict_summary_schema_contract" =>
        reservation_conflict_summary_schema_contract,
      "capacity_pack_summary_schema_contract" => capacity_pack_summary_schema_contract,
      "provider_reservation_request_contact_ids" => provider_reservation_request_contact_ids,
      "provider_reservation_review_contact_ids" => provider_reservation_review_contact_ids,
      "provider_reservation_no_request_contact_ids" =>
        provider_reservation_no_request_contact_ids,
      "provider_reservation_request_contact_ids_by_ground_station" =>
        provider_reservation_request_contact_ids_by_station,
      "provider_reservation_review_contact_ids_by_ground_station" =>
        provider_reservation_review_contact_ids_by_station,
      "provider_reservation_no_request_contact_ids_by_direction" =>
        provider_reservation_no_request_contact_ids_by_direction,
      "provider_reservation_request_contact_ids_by_direction" =>
        provider_reservation_request_contact_ids_by_direction,
      "provider_reservation_review_contact_ids_by_direction" =>
        provider_reservation_review_contact_ids_by_direction,
      "provider_reservation_request_contact_ids_by_match_status" =>
        provider_reservation_request_contact_ids_by_match_status,
      "provider_reservation_review_contact_ids_by_match_status" =>
        provider_reservation_review_contact_ids_by_match_status,
      "provider_reservation_request_ids_by_match_status" =>
        provider_reservation_request_ids_by_match_status,
      "provider_reservation_review_ids_by_match_status" =>
        provider_reservation_review_ids_by_match_status,
      "trust_boundary_status" => Map.get(allocation_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(allocation_summary, "trust_boundaries", []),
      "branch_local_contact_allocation_pressure" =>
        blocked_row_count + deferred_row_count + station_pressure_contact_count > 0 or
          map_size(allocation_status_counts) > 0 or map_size(allocation_reason_counts) > 0 or
          map_size(effective_allocation_status_counts) > 0 or
          map_size(capacity_pack_status_counts) > 0 or
          (capacity_pack_contact_count || 0) > 0 or
          capacity_pack_pressure or
          (allocated_contact_ids || []) != [] or
          (returned_allocated_contact_ids || []) != [] or
          (deferred_contact_count || 0) > 0 or
          (deferred_contact_ids || []) != [] or
          (blocked_contact_count || 0) > 0 or
          (blocked_contact_ids || []) != [] or
          map_size(direction_counts || %{}) > 0 or
          map_size(contact_ids_by_direction || %{}) > 0 or
          map_size(direction_routing) > 0 or
          (policy_blocked_contact_ids || []) != [] or
          (invalid_contact_input_count || 0) > 0 or
          (duplicate_contact_id_count || 0) > 0 or
          (invalid_contact_input_ids || []) != [] or
          (status_blocked_contact_count || 0) > 0 or
          (status_blocked_contact_ids || []) != [] or
          (resource_blocked_contact_count || 0) > 0 or
          (resource_blocked_contact_ids || []) != [] or
          (review_contact_ids || []) != [] or
          provider_reservation_request_pressure or
          map_size(allocated_contact_ids_by_station || %{}) > 0 or
          map_size(returned_allocated_contact_ids_by_station || %{}) > 0 or
          map_size(deferred_contact_ids_by_general_station || %{}) > 0 or
          map_size(blocked_contact_ids_by_station || %{}) > 0 or
          map_size(policy_blocked_contact_ids_by_station || %{}) > 0 or
          map_size(resource_blocking_dimension_counts || %{}) > 0 or
          map_size(resource_blocked_contact_ids_by_blocking_dimension || %{}) > 0 or
          map_size(resource_blocked_contact_ids_by_spacecraft || %{}) > 0 or
          map_size(contact_ids_by_allocation_reason || %{}) > 0,
      "branch_local_blocked_allocation_pressure" => blocked_row_count > 0,
      "branch_local_deferred_allocation_pressure" =>
        deferred_row_count > 0 or (deferred_contact_count || 0) > 0 or
          (deferred_contact_ids || []) != [] or
          map_size(deferred_contact_ids_by_general_station || %{}) > 0 or
          map_size(deferred_contact_ids_by_station) > 0 or deferred_capacity_fraction > 0.0 or
          map_size(deferred_by_station) > 0 or map_size(deferred_by_direction) > 0 or
          map_size(deferred_contact_ids_by_direction) > 0 or
          (reduced_capacity_deferred_contact_ids || []) != [],
      "branch_local_station_pressure" =>
        station_pressure_contact_count > 0 or map_size(station_pressure_ground_station_counts) > 0 or
          map_size(station_pressure_contact_ids_by_ground_station) > 0 or
          map_size(station_pressure_availability_counts) > 0 or
          map_size(station_pressure_contact_ids_by_availability) > 0 or
          map_size(station_pressure_precedence_availability_counts) > 0 or
          map_size(station_pressure_contact_ids_by_precedence_availability) > 0 or
          map_size(station_pressure_precedence_rank_counts) > 0 or
          map_size(station_pressure_contact_ids_by_precedence_rank) > 0 or
          (station_pressure_review_contact_ids || []) != [] or
          station_pressure_review_contact_count > 0 or
          map_size(station_pressure_direction_counts || %{}) > 0 or
          map_size(station_pressure_contact_ids_by_direction || %{}) > 0 or
          map_size(station_pressure_contact_ids_by_direction_and_station || %{}) > 0,
      "branch_local_capacity_pack_pressure" => capacity_pack_pressure,
      "branch_local_reservation_conflict_pressure" =>
        if(
          (reservation_conflict_contact_count || 0) > 0 or
            (reservation_conflict_contact_ids || []) != [] or
            map_size(reservation_conflict_match_status_counts || %{}) > 0 or
            map_size(reservation_conflict_contact_ids_by_match_status || %{}) > 0 or
            map_size(reservation_conflict_reservation_ids_by_match_status || %{}) > 0 or
            map_size(reservation_conflict_direction_counts || %{}) > 0 or
            map_size(reservation_conflict_contact_ids_by_direction || %{}) > 0 or
            map_size(reservation_conflict_contact_ids_by_direction_and_station || %{}) > 0,
          do: true
        ),
      "branch_local_station_reservation_pressure" =>
        if(
          map_size(station_reservation_match_status_counts || %{}) > 0 or
            map_size(station_reservation_contact_ids_by_match_status || %{}) > 0 or
            map_size(station_reservation_ids_by_match_status || %{}) > 0 or
            map_size(station_reservation_status_counts || %{}) > 0 or
            map_size(station_reserved_by_counts || %{}) > 0 or
            (station_reservation_ids || []) != [] or
            map_size(station_reservation_contact_ids_by_status || %{}) > 0 or
            map_size(station_reservation_contact_ids_by_reserved_by || %{}) > 0 or
            map_size(station_reservation_ids_by_status || %{}) > 0 or
            map_size(station_reservation_ids_by_reserved_by || %{}) > 0 or
            (station_reservation_expires_at_s || []) != [] or
            not is_nil(station_reservation_expiration_now_s) or
            map_size(station_reservation_expiration_status_counts || %{}) > 0 or
            (station_reservation_active_contact_count || 0) > 0 or
            (station_reservation_expired_contact_count || 0) > 0 or
            (station_reservation_declared_expiration_contact_count || 0) > 0 or
            (station_reservation_missing_expiration_contact_count || 0) > 0 or
            not is_nil(earliest_station_reservation_expires_at_s) or
            map_size(station_reservation_contact_ids_by_expiration_status || %{}) > 0 or
            map_size(station_reservation_ids_by_expiration_status || %{}) > 0,
          do: true
        ),
      "branch_local_provider_reservation_request_pressure" =>
        if(provider_reservation_request_pressure, do: true),
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => "not_granted_by_contact_allocation_replay_summary",
        "contact_allocation" => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_contact_allocation_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local link-capacity replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not replay refresh generation, mutate
  contact allocation, select candidates, approve imports, or write to Cadence.
  """
  def link_capacity_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    branch_link_summary =
      source_report_summary_branch_family(refresh_or_artifact, "link_capacity_report")

    link_summary =
      branch_link_summary ||
        get_in(source_summary, ["source_reports", "link_capacity_report"]) || %{}

    {summary_source, replay_scope} =
      if branch_link_summary do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.link_capacity_report",
          "link_capacity_candidate_source_report_summary_only"
        }
      else
        {
          "candidate_refresh.source_report_provenance.link_capacity_report",
          "link_capacity_source_report_provenance_only"
        }
      end

    selected_shortfall_row_count = summary_integer(link_summary, "selected_shortfall_row_count")
    actual_shortfall_row_count = summary_integer(link_summary, "actual_shortfall_row_count")
    actual_throughput_row_count = summary_integer(link_summary, "actual_throughput_row_count")

    capacity_adjusted_row_count =
      summary_integer(link_summary, "capacity_adjusted_throughput_row_count")

    capacity_adjusted_total =
      numeric_value(Map.get(link_summary, "capacity_adjusted_throughput_mb_total")) || 0.0

    selected_capacity_adjusted_total =
      numeric_value(Map.get(link_summary, "selected_capacity_adjusted_throughput_mb_total")) ||
        0.0

    unused_capacity_adjusted_total =
      numeric_value(Map.get(link_summary, "unused_capacity_adjusted_throughput_mb_total")) || 0.0

    ground_station_counts = Map.get(link_summary, "ground_station_counts", %{})

    capacity_adjusted_by_station =
      Map.get(link_summary, "capacity_adjusted_throughput_mb_by_ground_station", %{})

    selected_capacity_adjusted_by_station =
      Map.get(link_summary, "selected_capacity_adjusted_throughput_mb_by_ground_station", %{})

    unused_capacity_adjusted_by_station =
      Map.get(link_summary, "unused_capacity_adjusted_throughput_mb_by_ground_station", %{})

    capacity_adjusted_by_direction =
      Map.get(link_summary, "capacity_adjusted_throughput_mb_by_direction", %{})

    selected_capacity_adjusted_by_direction =
      Map.get(link_summary, "selected_capacity_adjusted_throughput_mb_by_direction", %{})

    unused_capacity_adjusted_by_direction =
      Map.get(link_summary, "unused_capacity_adjusted_throughput_mb_by_direction", %{})

    direction_counts = Map.get(link_summary, "direction_counts", %{})
    directions = Map.get(link_summary, "directions", [])
    spacecraft_counts = Map.get(link_summary, "spacecraft_counts", %{})
    contact_ids_by_direction = Map.get(link_summary, "contact_ids_by_direction", %{})
    source_window_ids_by_direction = Map.get(link_summary, "source_window_ids_by_direction", %{})

    station_calendar_entry_ids_by_direction =
      Map.get(link_summary, "station_calendar_entry_ids_by_direction", %{})

    station_calendar_provider_entry_ids_by_direction =
      Map.get(link_summary, "station_calendar_provider_entry_ids_by_direction", %{})

    direction_routing = Map.get(link_summary, "direction_routing", %{})

    contact_ids_by_ground_station = Map.get(link_summary, "contact_ids_by_ground_station", %{})

    source_window_ids_by_ground_station =
      Map.get(link_summary, "source_window_ids_by_ground_station", %{})

    station_calendar_entry_ids_by_ground_station =
      Map.get(link_summary, "station_calendar_entry_ids_by_ground_station", %{})

    station_calendar_provider_entry_ids_by_ground_station =
      Map.get(link_summary, "station_calendar_provider_entry_ids_by_ground_station", %{})

    contact_ids_by_spacecraft = Map.get(link_summary, "contact_ids_by_spacecraft", %{})

    source_window_ids_by_spacecraft =
      Map.get(link_summary, "source_window_ids_by_spacecraft", %{})

    station_calendar_entry_ids_by_spacecraft =
      Map.get(link_summary, "station_calendar_entry_ids_by_spacecraft", %{})

    station_calendar_provider_entry_ids_by_spacecraft =
      Map.get(link_summary, "station_calendar_provider_entry_ids_by_spacecraft", %{})

    selected_contact_id_counts = Map.get(link_summary, "selected_contact_id_counts", %{})
    selected_contact_ids = Map.get(link_summary, "selected_contact_ids", [])
    selected_source_window_ids = Map.get(link_summary, "selected_source_window_ids", [])

    selected_station_calendar_entry_ids =
      Map.get(link_summary, "selected_station_calendar_entry_ids", [])

    selected_station_calendar_provider_entry_ids =
      Map.get(link_summary, "selected_station_calendar_provider_entry_ids", [])

    actual_throughput_contact_id_counts =
      Map.get(link_summary, "actual_throughput_contact_id_counts", %{})

    actual_throughput_contact_ids =
      Map.get(link_summary, "actual_throughput_contact_ids", [])

    actual_throughput_source_window_ids =
      Map.get(link_summary, "actual_throughput_source_window_ids", [])

    actual_throughput_station_calendar_entry_ids =
      Map.get(link_summary, "actual_throughput_station_calendar_entry_ids", [])

    actual_throughput_station_calendar_provider_entry_ids =
      Map.get(link_summary, "actual_throughput_station_calendar_provider_entry_ids", [])

    downlink_requirement_status_counts =
      Map.get(link_summary, "downlink_requirement_status_counts", %{})

    contact_ids_by_requirement_status =
      Map.get(link_summary, "contact_ids_by_requirement_status", %{})

    source_window_ids_by_requirement_status =
      Map.get(link_summary, "source_window_ids_by_requirement_status", %{})

    station_calendar_entry_ids_by_requirement_status =
      Map.get(link_summary, "station_calendar_entry_ids_by_requirement_status", %{})

    station_calendar_provider_entry_ids_by_requirement_status =
      Map.get(link_summary, "station_calendar_provider_entry_ids_by_requirement_status", %{})

    actual_requirement_status_contact_pressure =
      link_capacity_requirement_status_actual_pressure?(contact_ids_by_requirement_status)

    actual_requirement_status_source_window_pressure =
      link_capacity_requirement_status_actual_pressure?(source_window_ids_by_requirement_status)

    actual_requirement_status_station_calendar_entry_pressure =
      link_capacity_requirement_status_actual_pressure?(
        station_calendar_entry_ids_by_requirement_status
      )

    actual_requirement_status_station_calendar_provider_entry_pressure =
      link_capacity_requirement_status_actual_pressure?(
        station_calendar_provider_entry_ids_by_requirement_status
      )

    capacity_adjusted_throughput_pressure =
      capacity_adjusted_row_count > 0 or capacity_adjusted_total > 0.0 or
        selected_capacity_adjusted_total > 0.0 or unused_capacity_adjusted_total > 0.0 or
        map_size(capacity_adjusted_by_station) > 0 or
        map_size(selected_capacity_adjusted_by_station) > 0 or
        map_size(unused_capacity_adjusted_by_station) > 0 or
        map_size(capacity_adjusted_by_direction) > 0 or
        map_size(selected_capacity_adjusted_by_direction) > 0 or
        map_size(unused_capacity_adjusted_by_direction) > 0

    %{
      "model" => "artifact_only_candidate_refresh_link_capacity_replay_summary",
      "source" => summary_source,
      "contract" => source_report_summary_contract(link_summary, "link_capacity_report.v1"),
      "source_report_count" => summary_integer(link_summary, "count"),
      "source_report_row_count" => summary_integer(link_summary, "row_count"),
      "source_report_paths" => Map.get(link_summary, "paths", []),
      "selected_shortfall_row_count" => selected_shortfall_row_count,
      "actual_shortfall_row_count" => actual_shortfall_row_count,
      "actual_throughput_row_count" => actual_throughput_row_count,
      "capacity_adjusted_throughput_row_count" => capacity_adjusted_row_count,
      "capacity_adjusted_throughput_mb_total" => capacity_adjusted_total,
      "selected_capacity_adjusted_throughput_mb_total" => selected_capacity_adjusted_total,
      "unused_capacity_adjusted_throughput_mb_total" => unused_capacity_adjusted_total,
      "ground_station_counts" => ground_station_counts,
      "capacity_adjusted_throughput_mb_by_ground_station" => capacity_adjusted_by_station,
      "selected_capacity_adjusted_throughput_mb_by_ground_station" =>
        selected_capacity_adjusted_by_station,
      "unused_capacity_adjusted_throughput_mb_by_ground_station" =>
        unused_capacity_adjusted_by_station,
      "capacity_adjusted_throughput_mb_by_direction" => capacity_adjusted_by_direction,
      "selected_capacity_adjusted_throughput_mb_by_direction" =>
        selected_capacity_adjusted_by_direction,
      "unused_capacity_adjusted_throughput_mb_by_direction" =>
        unused_capacity_adjusted_by_direction,
      "direction_counts" => direction_counts,
      "directions" => directions,
      "spacecraft_counts" => spacecraft_counts,
      "contact_ids_by_direction" => contact_ids_by_direction,
      "source_window_ids_by_direction" => source_window_ids_by_direction,
      "station_calendar_entry_ids_by_direction" => station_calendar_entry_ids_by_direction,
      "station_calendar_provider_entry_ids_by_direction" =>
        station_calendar_provider_entry_ids_by_direction,
      "direction_routing" => direction_routing,
      "contact_ids_by_ground_station" => contact_ids_by_ground_station,
      "source_window_ids_by_ground_station" => source_window_ids_by_ground_station,
      "station_calendar_entry_ids_by_ground_station" =>
        station_calendar_entry_ids_by_ground_station,
      "station_calendar_provider_entry_ids_by_ground_station" =>
        station_calendar_provider_entry_ids_by_ground_station,
      "contact_ids_by_spacecraft" => contact_ids_by_spacecraft,
      "source_window_ids_by_spacecraft" => source_window_ids_by_spacecraft,
      "station_calendar_entry_ids_by_spacecraft" => station_calendar_entry_ids_by_spacecraft,
      "station_calendar_provider_entry_ids_by_spacecraft" =>
        station_calendar_provider_entry_ids_by_spacecraft,
      "selected_contact_id_counts" => selected_contact_id_counts,
      "selected_contact_ids" => selected_contact_ids,
      "selected_source_window_ids" => selected_source_window_ids,
      "selected_station_calendar_entry_ids" => selected_station_calendar_entry_ids,
      "selected_station_calendar_provider_entry_ids" =>
        selected_station_calendar_provider_entry_ids,
      "actual_throughput_contact_id_counts" => actual_throughput_contact_id_counts,
      "actual_throughput_contact_ids" => actual_throughput_contact_ids,
      "actual_throughput_source_window_ids" => actual_throughput_source_window_ids,
      "actual_throughput_station_calendar_entry_ids" =>
        actual_throughput_station_calendar_entry_ids,
      "actual_throughput_station_calendar_provider_entry_ids" =>
        actual_throughput_station_calendar_provider_entry_ids,
      "downlink_requirement_status_counts" => downlink_requirement_status_counts,
      "contact_ids_by_requirement_status" => contact_ids_by_requirement_status,
      "source_window_ids_by_requirement_status" => source_window_ids_by_requirement_status,
      "station_calendar_entry_ids_by_requirement_status" =>
        station_calendar_entry_ids_by_requirement_status,
      "station_calendar_provider_entry_ids_by_requirement_status" =>
        station_calendar_provider_entry_ids_by_requirement_status,
      "trust_boundary_status" => Map.get(link_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(link_summary, "trust_boundaries", []),
      "branch_local_link_capacity_pressure" =>
        selected_shortfall_row_count + actual_shortfall_row_count +
          actual_throughput_row_count + capacity_adjusted_row_count >
          0 or map_size(ground_station_counts) > 0 or
          map_size(downlink_requirement_status_counts) > 0 or map_size(direction_counts) > 0 or
          length(List.wrap(directions)) > 0 or
          map_size(spacecraft_counts) > 0 or
          map_size(contact_ids_by_direction) > 0 or
          map_size(source_window_ids_by_direction) > 0 or
          map_size(station_calendar_entry_ids_by_direction) > 0 or
          map_size(station_calendar_provider_entry_ids_by_direction) > 0 or
          map_size(direction_routing) > 0 or
          map_size(contact_ids_by_ground_station) > 0 or
          map_size(source_window_ids_by_ground_station) > 0 or
          map_size(station_calendar_entry_ids_by_ground_station) > 0 or
          map_size(station_calendar_provider_entry_ids_by_ground_station) > 0 or
          map_size(contact_ids_by_spacecraft) > 0 or
          map_size(source_window_ids_by_spacecraft) > 0 or
          map_size(station_calendar_entry_ids_by_spacecraft) > 0 or
          map_size(station_calendar_provider_entry_ids_by_spacecraft) > 0 or
          map_size(contact_ids_by_requirement_status) > 0 or
          map_size(source_window_ids_by_requirement_status) > 0 or
          map_size(station_calendar_entry_ids_by_requirement_status) > 0 or
          map_size(station_calendar_provider_entry_ids_by_requirement_status) > 0 or
          map_size(selected_contact_id_counts) > 0 or selected_contact_ids != [] or
          selected_source_window_ids != [] or
          selected_station_calendar_entry_ids != [] or
          selected_station_calendar_provider_entry_ids != [] or
          map_size(actual_throughput_contact_id_counts) > 0 or
          actual_throughput_contact_ids != [] or actual_throughput_source_window_ids != [] or
          actual_throughput_station_calendar_entry_ids != [] or
          actual_throughput_station_calendar_provider_entry_ids != [] or
          capacity_adjusted_throughput_pressure,
      "branch_local_capacity_adjusted_throughput_pressure" =>
        capacity_adjusted_throughput_pressure,
      "branch_local_downlink_shortfall_pressure" =>
        selected_shortfall_row_count + actual_shortfall_row_count > 0 or
          map_size(downlink_requirement_status_counts) > 0 or
          map_size(contact_ids_by_requirement_status) > 0 or
