        length(List.wrap(resource_pressure_directions)) > 0 or
        map_size(resource_pressure_activity_ids_by_direction) > 0 or
        map_size(resource_pressure_direction_routing) > 0 or
        map_size(resource_pressure_ground_station_ids_by_type || %{}) > 0 or
        map_size(resource_pressure_source_window_ids_by_status || %{}) > 0 or
        map_size(resource_pressure_source_window_ids_by_type || %{}) > 0 or
        map_size(resource_pressure_station_calendar_entry_ids_by_status || %{}) > 0 or
        map_size(resource_pressure_station_calendar_entry_ids_by_type || %{}) > 0 or
        map_size(resource_pressure_station_calendar_provider_ids_by_status || %{}) > 0 or
        map_size(resource_pressure_station_calendar_provider_ids_by_type || %{}) > 0 or
        map_size(resource_pressure_station_calendar_provider_entry_ids_by_status || %{}) > 0 or
        map_size(resource_pressure_station_calendar_provider_entry_ids_by_type || %{}) > 0

    invalid_input_pressure =
      invalid_activity_input_count + invalid_resource_summary_input_count > 0 or
        invalid_activity_input_ids not in [nil, []] or
        invalid_resource_summary_input_ids not in [nil, []]

    %{
      "model" => "artifact_only_candidate_refresh_resource_projection_replay_summary",
      "source" => summary_source,
      "contract" =>
        source_report_summary_contract(projection_summary, "resource_projection_report.v1"),
      "source_report_count" => summary_integer(projection_summary, "count"),
      "source_report_row_count" => summary_integer(projection_summary, "row_count"),
      "source_report_paths" => Map.get(projection_summary, "paths", []),
      "projected_resource_count" => projected_resource_count,
      "source_artifact_type_counts" => source_artifact_type_counts,
      "source_flow_summary_model_counts" => source_flow_summary_model_counts,
      "invalid_activity_input_count" => invalid_activity_input_count,
      "invalid_resource_summary_input_count" => invalid_resource_summary_input_count,
      "resource_pressure_status_counts" => resource_pressure_status_counts,
      "ground_station_counts" => ground_station_counts,
      "resource_projection_spacecraft_counts" => spacecraft_counts,
      "resource_pressure_type_counts" => resource_pressure_type_counts,
      "resource_pressure_activity_id_counts" => resource_pressure_activity_id_counts,
      "resource_pressure_activity_ids_by_status" => resource_pressure_activity_ids_by_status,
      "resource_pressure_activity_ids_by_type" => resource_pressure_activity_ids_by_type,
      "resource_pressure_activity_ids_by_ground_station" =>
        resource_pressure_activity_ids_by_ground_station,
      "resource_pressure_activity_ids_by_spacecraft" =>
        resource_pressure_activity_ids_by_spacecraft,
      "resource_pressure_direction_counts" => resource_pressure_direction_counts,
      "resource_pressure_directions" => resource_pressure_directions,
      "resource_pressure_activity_ids_by_direction" =>
        resource_pressure_activity_ids_by_direction,
      "resource_pressure_direction_routing" => resource_pressure_direction_routing,
      "resource_pressure_ground_station_ids_by_type" =>
        resource_pressure_ground_station_ids_by_type,
      "resource_pressure_source_window_ids_by_status" =>
        resource_pressure_source_window_ids_by_status,
      "resource_pressure_source_window_ids_by_type" =>
        resource_pressure_source_window_ids_by_type,
      "resource_pressure_station_calendar_entry_ids_by_status" =>
        resource_pressure_station_calendar_entry_ids_by_status,
      "resource_pressure_station_calendar_entry_ids_by_type" =>
        resource_pressure_station_calendar_entry_ids_by_type,
      "resource_pressure_station_calendar_provider_ids_by_status" =>
        resource_pressure_station_calendar_provider_ids_by_status,
      "resource_pressure_station_calendar_provider_ids_by_type" =>
        resource_pressure_station_calendar_provider_ids_by_type,
      "resource_pressure_station_calendar_provider_entry_ids_by_status" =>
        resource_pressure_station_calendar_provider_entry_ids_by_status,
      "resource_pressure_station_calendar_provider_entry_ids_by_type" =>
        resource_pressure_station_calendar_provider_entry_ids_by_type,
      "invalid_activity_input_ids" => invalid_activity_input_ids,
      "invalid_resource_summary_input_ids" => invalid_resource_summary_input_ids,
      "trust_boundary_status" => Map.get(projection_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(projection_summary, "trust_boundaries", []),
      "branch_local_resource_projection_pressure" =>
        projected_resource_count > 0 or invalid_input_pressure or resource_routing_pressure,
      "branch_local_projected_resource_pressure" =>
        projected_resource_count > 0 or resource_routing_pressure,
      "branch_local_invalid_resource_projection_pressure" => invalid_input_pressure,
      "branch_local_activity_pressure" =>
        map_size(resource_pressure_activity_id_counts) > 0 or
          map_size(resource_pressure_activity_ids_by_status) > 0 or
          map_size(resource_pressure_activity_ids_by_type) > 0 or
          map_size(resource_pressure_activity_ids_by_ground_station) > 0 or
          map_size(resource_pressure_activity_ids_by_spacecraft) > 0 or
          map_size(resource_pressure_activity_ids_by_direction) > 0,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => "not_granted_by_resource_projection_replay_summary",
        "resource_projection" => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_resource_projection_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local storage/downlink pressure replay summary.

  The summary composes contact-allocation, link-capacity, and
  resource-projection source-report provenance. It does not replay refresh
  generation, mutate projections or allocations, select candidates, approve
  imports, or write to Cadence.
  """
  def storage_downlink_pressure_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)
    source_reports = Map.get(source_summary, "source_reports", %{})

    pressure_reports =
      Map.take(source_reports, [
        "contact_allocation_report",
        "link_capacity_report",
        "resource_projection_report"
      ])

    allocation_summary = Map.get(pressure_reports, "contact_allocation_report", %{})
    link_summary = Map.get(pressure_reports, "link_capacity_report", %{})
    projection_summary = Map.get(pressure_reports, "resource_projection_report", %{})

    source_report_count = pressure_summary_integer_sum(pressure_reports, "count")
    source_report_row_count = pressure_summary_integer_sum(pressure_reports, "row_count")

    capacity_pack_required_fraction =
      numeric_value(Map.get(allocation_summary, "capacity_pack_required_capacity_fraction")) ||
        0.0

    capacity_pack_selected_fraction =
      numeric_value(
        Map.get(allocation_summary, "capacity_pack_selected_required_capacity_fraction")
      ) || 0.0

    capacity_pack_deferred_fraction =
      numeric_value(
        Map.get(allocation_summary, "capacity_pack_deferred_required_capacity_fraction")
      ) || 0.0

    selected_shortfall_row_count = summary_integer(link_summary, "selected_shortfall_row_count")
    actual_shortfall_row_count = summary_integer(link_summary, "actual_shortfall_row_count")
    actual_throughput_row_count = summary_integer(link_summary, "actual_throughput_row_count")

    capacity_adjusted_row_count =
      summary_integer(link_summary, "capacity_adjusted_throughput_row_count")

    capacity_adjusted_total =
      numeric_value(Map.get(link_summary, "capacity_adjusted_throughput_mb_total")) || 0.0

    selected_capacity_adjusted_total =
      numeric_value(Map.get(link_summary, "selected_capacity_adjusted_throughput_mb_total")) ||
        0.0

    unused_capacity_adjusted_total =
      numeric_value(Map.get(link_summary, "unused_capacity_adjusted_throughput_mb_total")) ||
        0.0

    resource_pressure_status_counts =
      Map.get(projection_summary, "resource_pressure_status_counts", %{})

    resource_pressure_type_counts =
      Map.get(projection_summary, "resource_pressure_type_counts", %{})

    storage_pressure_status_counts =
      pressure_count_map_matching(resource_pressure_status_counts, "storage")

    storage_pressure_type_counts =
      pressure_count_map_matching(resource_pressure_type_counts, "storage")

    downlink_pressure_status_counts =
      pressure_count_map_matching(resource_pressure_status_counts, "downlink")

    downlink_pressure_type_counts =
      pressure_count_map_matching(resource_pressure_type_counts, "downlink")

    ground_station_counts =
      merge_count_maps([
        Map.get(allocation_summary, "station_pressure_ground_station_counts", %{}),
        Map.get(link_summary, "ground_station_counts", %{}),
        Map.get(projection_summary, "ground_station_counts", %{})
      ]) || %{}

    spacecraft_counts =
      Map.get(projection_summary, "resource_projection_spacecraft_counts", %{})

    resource_pressure_activity_id_counts =
      Map.get(projection_summary, "resource_pressure_activity_id_counts", %{})

    resource_pressure_direction_counts =
      Map.get(projection_summary, "resource_pressure_direction_counts", %{})

    resource_pressure_activity_ids_by_direction =
      Map.get(projection_summary, "resource_pressure_activity_ids_by_direction", %{})

    resource_pressure_ground_station_ids_by_type =
      Map.get(projection_summary, "resource_pressure_ground_station_ids_by_type", %{})

    resource_pressure_source_window_ids_by_type =
      Map.get(projection_summary, "resource_pressure_source_window_ids_by_type", %{})

    resource_pressure_station_calendar_entry_ids_by_type =
      Map.get(projection_summary, "resource_pressure_station_calendar_entry_ids_by_type", %{})

    resource_pressure_station_calendar_provider_ids_by_type =
      Map.get(
        projection_summary,
        "resource_pressure_station_calendar_provider_ids_by_type",
        %{}
      )

    resource_pressure_station_calendar_provider_entry_ids_by_type =
      Map.get(
        projection_summary,
        "resource_pressure_station_calendar_provider_entry_ids_by_type",
        %{}
      )

    allocation_status_counts = Map.get(allocation_summary, "allocation_status_counts", %{})
    allocation_reason_counts = Map.get(allocation_summary, "allocation_reason_counts", %{})
    capacity_pack_status_counts = Map.get(allocation_summary, "capacity_pack_status_counts", %{})

    capacity_pack_contact_status_counts =
      Map.get(allocation_summary, "capacity_pack_contact_status_counts", %{})

    link_requirement_status_counts =
      Map.get(link_summary, "downlink_requirement_status_counts", %{})

    selected_contact_id_counts = Map.get(link_summary, "selected_contact_id_counts", %{})

    actual_throughput_contact_id_counts =
      Map.get(link_summary, "actual_throughput_contact_id_counts", %{})

    link_direction_counts = Map.get(link_summary, "direction_counts", %{})
    link_contact_ids_by_direction = Map.get(link_summary, "contact_ids_by_direction", %{})

    capacity_pack_by_station =
      Map.get(
        allocation_summary,
        "capacity_pack_required_capacity_fraction_by_ground_station",
        %{}
      )

    capacity_pack_selected_by_station =
      Map.get(
        allocation_summary,
        "capacity_pack_selected_required_capacity_fraction_by_ground_station",
        %{}
      )

    capacity_pack_deferred_by_station =
      Map.get(
        allocation_summary,
        "capacity_pack_deferred_required_capacity_fraction_by_ground_station",
        %{}
      )

    capacity_pack_by_status =
      Map.get(allocation_summary, "capacity_pack_required_capacity_fraction_by_status", %{})

    capacity_pack_by_direction =
      Map.get(allocation_summary, "capacity_pack_required_capacity_fraction_by_direction", %{})

    capacity_pack_selected_by_direction =
      Map.get(
        allocation_summary,
        "capacity_pack_selected_required_capacity_fraction_by_direction",
        %{}
      )

    capacity_pack_deferred_by_direction =
      Map.get(
        allocation_summary,
        "capacity_pack_deferred_required_capacity_fraction_by_direction",
        %{}
      )

    capacity_pack_selected_contact_ids_by_station =
      Map.get(allocation_summary, "capacity_pack_selected_contact_ids_by_ground_station", %{})

    capacity_pack_deferred_contact_ids_by_station =
      Map.get(allocation_summary, "capacity_pack_deferred_contact_ids_by_ground_station", %{})

    capacity_pack_contact_ids_by_station =
      Map.get(allocation_summary, "capacity_pack_contact_ids_by_ground_station", %{})

    capacity_pack_selected_contact_ids_by_direction =
      Map.get(allocation_summary, "capacity_pack_selected_contact_ids_by_direction", %{})

    capacity_pack_deferred_contact_ids_by_direction =
      Map.get(allocation_summary, "capacity_pack_deferred_contact_ids_by_direction", %{})

    capacity_pack_contact_ids_by_direction =
      Map.get(allocation_summary, "capacity_pack_contact_ids_by_direction", %{})

    capacity_pack_contact_ids_by_status =
      Map.get(allocation_summary, "capacity_pack_contact_ids_by_status", %{})

    capacity_pack_contact_count =
      case summary_integer(allocation_summary, "capacity_pack_contact_count") do
        0 -> nil
        count -> count
      end

    reduced_capacity_packed_contact_ids =
      Map.get(allocation_summary, "reduced_capacity_packed_contact_ids")

    reduced_capacity_deferred_contact_ids =
      Map.get(allocation_summary, "reduced_capacity_deferred_contact_ids")

    reduced_capacity_pack_group_count =
      case summary_integer(allocation_summary, "reduced_capacity_pack_group_count") do
        0 -> nil
        count -> count
      end

    reduced_capacity_pack_status_counts =
      Map.get(allocation_summary, "reduced_capacity_pack_status_counts")

    capacity_pack_group_ids =
      Map.get(allocation_summary, "capacity_pack_group_ids")

    capacity_pack_group_ids_by_status =
      Map.get(allocation_summary, "capacity_pack_group_ids_by_status")

    required_capacity_source_counts =
      Map.get(allocation_summary, "required_capacity_fraction_source_counts", %{})

    required_capacity_contact_ids_by_source =
      Map.get(allocation_summary, "required_capacity_fraction_contact_ids_by_source", %{})

    capacity_adjusted_by_station =
      Map.get(link_summary, "capacity_adjusted_throughput_mb_by_ground_station", %{})

    selected_capacity_adjusted_by_station =
      Map.get(link_summary, "selected_capacity_adjusted_throughput_mb_by_ground_station", %{})

    unused_capacity_adjusted_by_station =
      Map.get(link_summary, "unused_capacity_adjusted_throughput_mb_by_ground_station", %{})

    capacity_adjusted_by_direction =
      Map.get(link_summary, "capacity_adjusted_throughput_mb_by_direction", %{})

    selected_capacity_adjusted_by_direction =
      Map.get(link_summary, "selected_capacity_adjusted_throughput_mb_by_direction", %{})

    unused_capacity_adjusted_by_direction =
      Map.get(link_summary, "unused_capacity_adjusted_throughput_mb_by_direction", %{})

    branch_local_storage_pressure =
      map_size(storage_pressure_status_counts) > 0 or map_size(storage_pressure_type_counts) > 0

    branch_local_capacity_adjusted_throughput_pressure =
      capacity_adjusted_row_count > 0 or
        capacity_adjusted_total + selected_capacity_adjusted_total +
          unused_capacity_adjusted_total > 0.0 or map_size(capacity_adjusted_by_station) > 0 or
        map_size(selected_capacity_adjusted_by_station) > 0 or
        map_size(unused_capacity_adjusted_by_station) > 0 or
        map_size(capacity_adjusted_by_direction) > 0 or
        map_size(selected_capacity_adjusted_by_direction) > 0 or
        map_size(unused_capacity_adjusted_by_direction) > 0

    branch_local_actual_throughput_pressure =
      actual_throughput_row_count > 0 or map_size(actual_throughput_contact_id_counts) > 0

    branch_local_resource_activity_pressure =
      map_size(resource_pressure_activity_id_counts) > 0 or
        map_size(resource_pressure_activity_ids_by_direction) > 0

    branch_local_downlink_pressure =
      selected_shortfall_row_count + actual_shortfall_row_count > 0 or
        branch_local_capacity_adjusted_throughput_pressure or
        branch_local_actual_throughput_pressure or
        map_size(downlink_pressure_status_counts) > 0 or
        map_size(downlink_pressure_type_counts) > 0 or
        map_size(resource_pressure_direction_counts) > 0 or
        map_size(resource_pressure_activity_ids_by_direction) > 0 or
        map_size(resource_pressure_ground_station_ids_by_type) > 0 or
        map_size(resource_pressure_source_window_ids_by_type) > 0 or
        map_size(resource_pressure_station_calendar_entry_ids_by_type) > 0 or
        map_size(resource_pressure_station_calendar_provider_ids_by_type) > 0 or
        map_size(resource_pressure_station_calendar_provider_entry_ids_by_type) > 0 or
        map_size(link_requirement_status_counts) > 0 or
        map_size(link_direction_counts) > 0 or
        map_size(link_contact_ids_by_direction) > 0 or
        map_size(selected_contact_id_counts) > 0 or
        capacity_pack_required_fraction + capacity_pack_selected_fraction +
          capacity_pack_deferred_fraction > 0.0 or
        map_size(capacity_pack_by_status) > 0 or
        map_size(capacity_pack_by_direction) > 0 or
        map_size(capacity_pack_selected_by_direction) > 0 or
        map_size(capacity_pack_deferred_by_direction) > 0 or
        map_size(capacity_pack_contact_status_counts) > 0 or
        (capacity_pack_contact_count || 0) > 0 or
        map_size(capacity_pack_contact_ids_by_station) > 0 or
        map_size(capacity_pack_contact_ids_by_direction) > 0 or
        map_size(capacity_pack_contact_ids_by_status) > 0 or
        map_size(capacity_pack_selected_contact_ids_by_station) > 0 or
        map_size(capacity_pack_deferred_contact_ids_by_station) > 0 or
        map_size(capacity_pack_selected_contact_ids_by_direction) > 0 or
        map_size(capacity_pack_deferred_contact_ids_by_direction) > 0 or
        (reduced_capacity_packed_contact_ids || []) != [] or
        (reduced_capacity_deferred_contact_ids || []) != [] or
        (reduced_capacity_pack_group_count || 0) > 0 or
        map_size(reduced_capacity_pack_status_counts || %{}) > 0 or
        (capacity_pack_group_ids || []) != [] or
        map_size(capacity_pack_group_ids_by_status || %{}) > 0 or
        map_size(required_capacity_source_counts) > 0 or
        map_size(required_capacity_contact_ids_by_source) > 0 or
        map_size(capacity_pack_status_counts) > 0

    %{
      "model" => "artifact_only_candidate_refresh_storage_downlink_pressure_replay_summary",
      "source" => "candidate_refresh.source_report_provenance.storage_downlink_pressure",
      "source_report_count" => source_report_count,
      "source_report_row_count" => source_report_row_count,
      "source_report_families" =>
        pressure_summary_values(pressure_reports, fn {family, _summary} -> family end),
      "source_report_contracts" =>
        pressure_summary_values(pressure_reports, fn {_family, summary} ->
          Map.get(summary, "contract")
        end),
      "source_report_counts_by_family" => pressure_summary_counts_by_family(pressure_reports),
      "source_report_row_counts_by_family" =>
        pressure_summary_counts_by_family(pressure_reports, "row_count"),
      "source_report_paths" => pressure_summary_paths(pressure_reports),
      "source_report_paths_by_family" => pressure_summary_paths_by_family(pressure_reports),
      "source_report_counts_by_trust_boundary_status" =>
        pressure_summary_counts_by_trust_boundary_status(pressure_reports),
      "trust_boundaries" => pressure_summary_trust_boundaries(pressure_reports),
      "contact_allocation_status_counts" => allocation_status_counts,
      "contact_allocation_reason_counts" => allocation_reason_counts,
      "capacity_pack_status_counts" => capacity_pack_status_counts,
      "capacity_pack_contact_status_counts" => capacity_pack_contact_status_counts,
      "capacity_pack_required_capacity_fraction" => capacity_pack_required_fraction,
      "capacity_pack_selected_required_capacity_fraction" => capacity_pack_selected_fraction,
      "capacity_pack_deferred_required_capacity_fraction" => capacity_pack_deferred_fraction,
      "capacity_pack_required_capacity_fraction_by_ground_station" => capacity_pack_by_station,
      "capacity_pack_required_capacity_fraction_by_status" => capacity_pack_by_status,
      "capacity_pack_required_capacity_fraction_by_direction" => capacity_pack_by_direction,
      "capacity_pack_selected_required_capacity_fraction_by_ground_station" =>
        capacity_pack_selected_by_station,
      "capacity_pack_deferred_required_capacity_fraction_by_ground_station" =>
        capacity_pack_deferred_by_station,
      "capacity_pack_selected_required_capacity_fraction_by_direction" =>
        capacity_pack_selected_by_direction,
      "capacity_pack_deferred_required_capacity_fraction_by_direction" =>
        capacity_pack_deferred_by_direction,
      "capacity_pack_contact_count" => capacity_pack_contact_count,
      "capacity_pack_contact_ids_by_ground_station" => capacity_pack_contact_ids_by_station,
      "capacity_pack_contact_ids_by_direction" => capacity_pack_contact_ids_by_direction,
      "capacity_pack_contact_ids_by_status" => capacity_pack_contact_ids_by_status,
      "capacity_pack_selected_contact_ids_by_ground_station" =>
        capacity_pack_selected_contact_ids_by_station,
      "capacity_pack_deferred_contact_ids_by_ground_station" =>
        capacity_pack_deferred_contact_ids_by_station,
      "capacity_pack_selected_contact_ids_by_direction" =>
        capacity_pack_selected_contact_ids_by_direction,
      "capacity_pack_deferred_contact_ids_by_direction" =>
        capacity_pack_deferred_contact_ids_by_direction,
      "reduced_capacity_packed_contact_ids" => reduced_capacity_packed_contact_ids,
      "reduced_capacity_deferred_contact_ids" => reduced_capacity_deferred_contact_ids,
      "reduced_capacity_pack_group_count" => reduced_capacity_pack_group_count,
      "reduced_capacity_pack_status_counts" => reduced_capacity_pack_status_counts,
      "capacity_pack_group_ids" => capacity_pack_group_ids,
      "capacity_pack_group_ids_by_status" => capacity_pack_group_ids_by_status,
      "required_capacity_fraction_source_counts" => required_capacity_source_counts,
      "required_capacity_fraction_contact_ids_by_source" =>
        required_capacity_contact_ids_by_source,
      "selected_shortfall_row_count" => selected_shortfall_row_count,
      "actual_shortfall_row_count" => actual_shortfall_row_count,
      "actual_throughput_row_count" => actual_throughput_row_count,
      "capacity_adjusted_throughput_row_count" => capacity_adjusted_row_count,
      "downlink_requirement_status_counts" => link_requirement_status_counts,
      "capacity_adjusted_throughput_mb_total" => capacity_adjusted_total,
      "selected_capacity_adjusted_throughput_mb_total" => selected_capacity_adjusted_total,
      "unused_capacity_adjusted_throughput_mb_total" => unused_capacity_adjusted_total,
      "capacity_adjusted_throughput_mb_by_ground_station" => capacity_adjusted_by_station,
      "selected_capacity_adjusted_throughput_mb_by_ground_station" =>
        selected_capacity_adjusted_by_station,
      "unused_capacity_adjusted_throughput_mb_by_ground_station" =>
        unused_capacity_adjusted_by_station,
      "capacity_adjusted_throughput_mb_by_direction" => capacity_adjusted_by_direction,
      "selected_capacity_adjusted_throughput_mb_by_direction" =>
        selected_capacity_adjusted_by_direction,
      "unused_capacity_adjusted_throughput_mb_by_direction" =>
        unused_capacity_adjusted_by_direction,
      "direction_counts" => link_direction_counts,
      "contact_ids_by_direction" => link_contact_ids_by_direction,
      "selected_contact_id_counts" => selected_contact_id_counts,
      "actual_throughput_contact_id_counts" => actual_throughput_contact_id_counts,
      "resource_projection_spacecraft_counts" => spacecraft_counts,
      "ground_station_counts" => ground_station_counts,
      "resource_pressure_activity_id_counts" => resource_pressure_activity_id_counts,
      "resource_pressure_direction_counts" => resource_pressure_direction_counts,
      "resource_pressure_activity_ids_by_direction" =>
        resource_pressure_activity_ids_by_direction,
      "resource_pressure_ground_station_ids_by_type" =>
        resource_pressure_ground_station_ids_by_type,
      "resource_pressure_source_window_ids_by_type" =>
        resource_pressure_source_window_ids_by_type,
      "resource_pressure_station_calendar_entry_ids_by_type" =>
        resource_pressure_station_calendar_entry_ids_by_type,
      "resource_pressure_station_calendar_provider_ids_by_type" =>
        resource_pressure_station_calendar_provider_ids_by_type,
      "resource_pressure_station_calendar_provider_entry_ids_by_type" =>
        resource_pressure_station_calendar_provider_entry_ids_by_type,
      "storage_pressure_status_counts" => storage_pressure_status_counts,
      "storage_pressure_type_counts" => storage_pressure_type_counts,
      "downlink_pressure_status_counts" => downlink_pressure_status_counts,
      "downlink_pressure_type_counts" => downlink_pressure_type_counts,
      "branch_local_storage_downlink_pressure" =>
        branch_local_storage_pressure or branch_local_downlink_pressure or
          branch_local_resource_activity_pressure,
      "branch_local_storage_pressure" => branch_local_storage_pressure,
      "branch_local_downlink_pressure" => branch_local_downlink_pressure,
      "branch_local_capacity_pack_pressure" =>
        capacity_pack_required_fraction + capacity_pack_selected_fraction +
          capacity_pack_deferred_fraction > 0.0 or
          map_size(capacity_pack_by_status) > 0 or
          map_size(capacity_pack_by_direction) > 0 or
          map_size(capacity_pack_selected_by_direction) > 0 or
          map_size(capacity_pack_deferred_by_direction) > 0 or
          map_size(capacity_pack_contact_status_counts) > 0 or
          (capacity_pack_contact_count || 0) > 0 or
          map_size(capacity_pack_contact_ids_by_station) > 0 or
          map_size(capacity_pack_contact_ids_by_direction) > 0 or
          map_size(capacity_pack_contact_ids_by_status) > 0 or
          map_size(capacity_pack_selected_contact_ids_by_station) > 0 or
          map_size(capacity_pack_deferred_contact_ids_by_station) > 0 or
          map_size(capacity_pack_selected_contact_ids_by_direction) > 0 or
          map_size(capacity_pack_deferred_contact_ids_by_direction) > 0 or
          (reduced_capacity_packed_contact_ids || []) != [] or
          (reduced_capacity_deferred_contact_ids || []) != [] or
          (reduced_capacity_pack_group_count || 0) > 0 or
          map_size(reduced_capacity_pack_status_counts || %{}) > 0 or
          (capacity_pack_group_ids || []) != [] or
          map_size(capacity_pack_group_ids_by_status || %{}) > 0 or
          map_size(required_capacity_source_counts) > 0 or
          map_size(required_capacity_contact_ids_by_source) > 0 or
          map_size(capacity_pack_status_counts) > 0 or
          map_size(capacity_pack_contact_status_counts) > 0,
      "branch_local_downlink_shortfall_pressure" =>
        selected_shortfall_row_count + actual_shortfall_row_count > 0 or
          map_size(downlink_pressure_status_counts) > 0 or
          map_size(downlink_pressure_type_counts) > 0 or
          map_size(resource_pressure_direction_counts) > 0 or
          map_size(resource_pressure_activity_ids_by_direction) > 0 or
          map_size(resource_pressure_ground_station_ids_by_type) > 0 or
          map_size(resource_pressure_source_window_ids_by_type) > 0 or
          map_size(resource_pressure_station_calendar_entry_ids_by_type) > 0 or
          map_size(resource_pressure_station_calendar_provider_ids_by_type) > 0 or
          map_size(resource_pressure_station_calendar_provider_entry_ids_by_type) > 0,
      "branch_local_capacity_adjusted_throughput_pressure" =>
        branch_local_capacity_adjusted_throughput_pressure,
      "branch_local_actual_throughput_pressure" => branch_local_actual_throughput_pressure,
      "branch_local_resource_activity_pressure" => branch_local_resource_activity_pressure,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" =>
          "contact_allocation_link_capacity_resource_projection_source_report_provenance_only",
        "operator_authority" => "not_granted_by_storage_downlink_pressure_replay_summary",
        "contact_allocation" => "not_performed_by_summary",
        "resource_projection" => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_storage_downlink_pressure_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local station-calendar replay summary.

  The summary is derived from candidate-refresh source-report provenance. It
  does not replay refresh generation, mutate station calendars or schedules,
  select candidates, approve imports, or write to Cadence.
  """
  def station_calendar_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    station_summary =
      get_in(source_summary, ["source_reports", "station_calendar_report"]) || %{}

    affected_contact_count = summary_integer(station_summary, "affected_contact_count")

    source_summary_model_counts =
      Map.get(station_summary, "source_summary_model_counts", %{}) |> non_empty_map()

    source_summary_schema_contract_counts =
      Map.get(station_summary, "source_summary_schema_contract_counts", %{})
      |> non_empty_map()

    source_artifact_type_counts =
      Map.get(station_summary, "source_artifact_type_counts", %{}) |> non_empty_map()

    provider_contention_group_count =
      summary_integer(station_summary, "provider_calendar_contention_group_count")

    provider_counts =
      Map.get(station_summary, "provider_calendar_contention_provider_counts", %{})

    provider_ground_station_counts =
      Map.get(station_summary, "provider_calendar_contention_ground_station_counts", %{})

    provider_contention_group_ids =
      Map.get(station_summary, "provider_calendar_contention_group_ids", [])

    provider_contention_source_entry_ids =
      Map.get(station_summary, "provider_calendar_contention_source_entry_ids", [])

    provider_contention_provider_entry_ids =
      Map.get(station_summary, "provider_calendar_contention_provider_entry_ids", [])

    provider_contention_capacity_fractions =
      Map.get(station_summary, "provider_calendar_contention_capacity_fractions", [])

    provider_contention_minimum_capacity_fraction =
      Map.get(station_summary, "provider_calendar_contention_minimum_capacity_fraction")

    provider_contention_capacity_fractions_by_provider =
      Map.get(station_summary, "provider_calendar_contention_capacity_fractions_by_provider", %{})

    provider_contention_capacity_fractions_by_ground_station =
      Map.get(
        station_summary,
        "provider_calendar_contention_capacity_fractions_by_ground_station",
        %{}
      )

    provider_contention_provider_entry_ids_by_provider =
      Map.get(station_summary, "provider_calendar_contention_provider_entry_ids_by_provider", %{})

    provider_contention_provider_entry_ids_by_ground_station =
      Map.get(
        station_summary,
        "provider_calendar_contention_provider_entry_ids_by_ground_station",
        %{}
      )

    provider_contention_provider_ids_by_direction =
      Map.get(station_summary, "provider_calendar_contention_provider_ids_by_direction", %{})

    provider_contention_direction_counts =
      Map.get(station_summary, "provider_calendar_contention_direction_counts", %{})

    provider_contention_group_ids_by_direction =
      Map.get(station_summary, "provider_calendar_contention_group_ids_by_direction", %{})

    provider_contention_source_entry_ids_by_direction =
      Map.get(station_summary, "provider_calendar_contention_source_entry_ids_by_direction", %{})

    provider_contention_provider_entry_ids_by_direction =
      Map.get(
        station_summary,
        "provider_calendar_contention_provider_entry_ids_by_direction",
        %{}
      )

    provider_contention_capacity_fractions_by_direction =
      Map.get(
        station_summary,
        "provider_calendar_contention_capacity_fractions_by_direction",
        %{}
      )

    status_counts = Map.get(station_summary, "station_calendar_status_counts", %{})

    affected_ground_station_counts =
      Map.get(station_summary, "affected_contact_ground_station_counts", %{})

    affected_availability_counts =
      Map.get(station_summary, "affected_contact_availability_counts", %{})

    precedence_review_status_counts =
      Map.get(station_summary, "precedence_review_status_counts", %{}) |> non_empty_map()

    applied_availability_counts =
      Map.get(station_summary, "applied_availability_counts", %{}) |> non_empty_map()

    overlap_availability_counts =
      Map.get(station_summary, "overlap_availability_counts", %{}) |> non_empty_map()

    affected_contact_ids_by_applied_availability =
      Map.get(station_summary, "affected_contact_ids_by_applied_availability", %{})
      |> non_empty_map()

    affected_contact_ids_by_overlap_availability =
      Map.get(station_summary, "affected_contact_ids_by_overlap_availability", %{})
      |> non_empty_map()

    reserved_under_higher_precedence_contact_count =
      summary_integer(station_summary, "reserved_under_higher_precedence_contact_count")

    reserved_under_higher_precedence_contact_ids =
      Map.get(station_summary, "reserved_under_higher_precedence_contact_ids", [])

    reserved_under_higher_precedence_contact_ids_by_applied_availability =
      Map.get(
        station_summary,
        "reserved_under_higher_precedence_contact_ids_by_applied_availability",
        %{}
      )
      |> non_empty_map()

    precedence_pressure =
      not is_nil(precedence_review_status_counts) or
        not is_nil(applied_availability_counts) or
        not is_nil(overlap_availability_counts) or
        not is_nil(affected_contact_ids_by_applied_availability) or
        not is_nil(affected_contact_ids_by_overlap_availability) or
        reserved_under_higher_precedence_contact_count > 0 or
        reserved_under_higher_precedence_contact_ids != [] or
        not is_nil(reserved_under_higher_precedence_contact_ids_by_applied_availability)

    affected_contact_ids = Map.get(station_summary, "affected_contact_ids", [])

    affected_station_calendar_entry_ids =
      Map.get(station_summary, "affected_station_calendar_entry_ids", [])

    affected_station_reservation_ids =
      Map.get(station_summary, "affected_station_reservation_ids", [])

    direction_counts = Map.get(station_summary, "direction_counts", %{})
    contact_ids_by_direction = Map.get(station_summary, "contact_ids_by_direction", %{})

    station_calendar_entry_ids_by_direction =
      Map.get(station_summary, "station_calendar_entry_ids_by_direction", %{})

    station_reservation_ids_by_direction =
      Map.get(station_summary, "station_reservation_ids_by_direction", %{})

    station_capacity_fractions_by_direction =
      Map.get(station_summary, "station_capacity_fractions_by_direction", %{})

    direction_routing = Map.get(station_summary, "direction_routing", %{})

    reserved_by_counts = Map.get(station_summary, "reserved_by_counts", %{})
    contact_ids_by_reserved_by = Map.get(station_summary, "contact_ids_by_reserved_by", %{})

    station_calendar_entry_ids_by_reserved_by =
      Map.get(station_summary, "station_calendar_entry_ids_by_reserved_by", %{})

    station_reservation_ids_by_reserved_by =
      Map.get(station_summary, "station_reservation_ids_by_reserved_by", %{})

    station_reservation_expires_at_s =
      Map.get(station_summary, "station_reservation_expires_at_s", [])

    earliest_station_reservation_expires_at_s =
      Map.get(station_summary, "earliest_station_reservation_expires_at_s")

    station_capacity_fractions = Map.get(station_summary, "station_capacity_fractions", [])

    minimum_station_capacity_fraction =
      Map.get(station_summary, "minimum_station_capacity_fraction")

    station_capacity_fractions_by_status =
      Map.get(station_summary, "station_capacity_fractions_by_status", %{})

    station_capacity_fractions_by_ground_station =
      Map.get(station_summary, "station_capacity_fractions_by_ground_station", %{})

    station_capacity_fractions_by_availability =
      Map.get(station_summary, "station_capacity_fractions_by_availability", %{})

    contact_ids_by_status = Map.get(station_summary, "contact_ids_by_status", %{})
    contact_ids_by_ground_station = Map.get(station_summary, "contact_ids_by_ground_station", %{})
    contact_ids_by_availability = Map.get(station_summary, "contact_ids_by_availability", %{})

    station_calendar_entry_ids_by_status =
      Map.get(station_summary, "station_calendar_entry_ids_by_status", %{})

    station_calendar_entry_ids_by_ground_station =
      Map.get(station_summary, "station_calendar_entry_ids_by_ground_station", %{})

    station_calendar_entry_ids_by_availability =
      Map.get(station_summary, "station_calendar_entry_ids_by_availability", %{})

    station_reservation_ids_by_status =
      Map.get(station_summary, "station_reservation_ids_by_status", %{})

    station_reservation_ids_by_ground_station =
      Map.get(station_summary, "station_reservation_ids_by_ground_station", %{})

    station_reservation_ids_by_availability =
      Map.get(station_summary, "station_reservation_ids_by_availability", %{})

    %{
      "model" => "artifact_only_candidate_refresh_station_calendar_replay_summary",
      "source" => "candidate_refresh.source_report_provenance.station_calendar_report",
      "contract" => source_report_summary_contract(station_summary, "station_calendar_report.v1"),
      "source_report_count" => summary_integer(station_summary, "count"),
      "source_report_row_count" => summary_integer(station_summary, "row_count"),
      "source_report_paths" => Map.get(station_summary, "paths", []),
      "source_summary_model_counts" => source_summary_model_counts,
      "source_summary_schema_contract_counts" => source_summary_schema_contract_counts,
      "source_artifact_type_counts" => source_artifact_type_counts,
      "affected_contact_count" => affected_contact_count,
      "provider_calendar_contention_group_count" => provider_contention_group_count,
      "provider_calendar_contention_provider_counts" => provider_counts,
      "provider_calendar_contention_ground_station_counts" => provider_ground_station_counts,
      "provider_calendar_contention_group_ids" => provider_contention_group_ids,
      "provider_calendar_contention_source_entry_ids" => provider_contention_source_entry_ids,
      "provider_calendar_contention_provider_entry_ids" => provider_contention_provider_entry_ids,
      "provider_calendar_contention_capacity_fractions" => provider_contention_capacity_fractions,
      "provider_calendar_contention_minimum_capacity_fraction" =>
        provider_contention_minimum_capacity_fraction,
      "provider_calendar_contention_capacity_fractions_by_provider" =>
        provider_contention_capacity_fractions_by_provider,
      "provider_calendar_contention_capacity_fractions_by_ground_station" =>
        provider_contention_capacity_fractions_by_ground_station,
      "provider_calendar_contention_provider_entry_ids_by_provider" =>
        provider_contention_provider_entry_ids_by_provider,
      "provider_calendar_contention_provider_entry_ids_by_ground_station" =>
        provider_contention_provider_entry_ids_by_ground_station,
      "provider_calendar_contention_provider_ids_by_direction" =>
        provider_contention_provider_ids_by_direction,
      "provider_calendar_contention_direction_counts" => provider_contention_direction_counts,
      "provider_calendar_contention_group_ids_by_direction" =>
        provider_contention_group_ids_by_direction,
      "provider_calendar_contention_source_entry_ids_by_direction" =>
        provider_contention_source_entry_ids_by_direction,
      "provider_calendar_contention_provider_entry_ids_by_direction" =>
        provider_contention_provider_entry_ids_by_direction,
      "provider_calendar_contention_capacity_fractions_by_direction" =>
        provider_contention_capacity_fractions_by_direction,
      "affected_contact_ids" => affected_contact_ids,
      "affected_station_calendar_entry_ids" => affected_station_calendar_entry_ids,
      "affected_station_reservation_ids" => affected_station_reservation_ids,
      "direction_counts" => direction_counts,
      "contact_ids_by_direction" => contact_ids_by_direction,
      "station_calendar_entry_ids_by_direction" => station_calendar_entry_ids_by_direction,
      "station_reservation_ids_by_direction" => station_reservation_ids_by_direction,
      "station_capacity_fractions_by_direction" => station_capacity_fractions_by_direction,
      "direction_routing" => direction_routing,
      "reserved_by_counts" => reserved_by_counts,
      "contact_ids_by_reserved_by" => contact_ids_by_reserved_by,
      "station_calendar_entry_ids_by_reserved_by" => station_calendar_entry_ids_by_reserved_by,
      "station_reservation_ids_by_reserved_by" => station_reservation_ids_by_reserved_by,
      "station_reservation_expires_at_s" => station_reservation_expires_at_s,
      "earliest_station_reservation_expires_at_s" => earliest_station_reservation_expires_at_s,
      "station_capacity_fractions" => station_capacity_fractions,
      "minimum_station_capacity_fraction" => minimum_station_capacity_fraction,
      "station_capacity_fractions_by_status" => station_capacity_fractions_by_status,
      "station_capacity_fractions_by_ground_station" =>
        station_capacity_fractions_by_ground_station,
      "station_capacity_fractions_by_availability" => station_capacity_fractions_by_availability,
      "contact_ids_by_status" => contact_ids_by_status,
      "contact_ids_by_ground_station" => contact_ids_by_ground_station,
      "contact_ids_by_availability" => contact_ids_by_availability,
      "station_calendar_entry_ids_by_status" => station_calendar_entry_ids_by_status,
      "station_calendar_entry_ids_by_ground_station" =>
        station_calendar_entry_ids_by_ground_station,
      "station_calendar_entry_ids_by_availability" => station_calendar_entry_ids_by_availability,
      "station_reservation_ids_by_status" => station_reservation_ids_by_status,
      "station_reservation_ids_by_ground_station" => station_reservation_ids_by_ground_station,
      "station_reservation_ids_by_availability" => station_reservation_ids_by_availability,
      "station_calendar_status_counts" => status_counts,
      "affected_contact_ground_station_counts" => affected_ground_station_counts,
      "affected_contact_availability_counts" => affected_availability_counts,
      "precedence_review_status_counts" => precedence_review_status_counts,
      "applied_availability_counts" => applied_availability_counts,
      "overlap_availability_counts" => overlap_availability_counts,
      "affected_contact_ids_by_applied_availability" =>
        affected_contact_ids_by_applied_availability,
      "affected_contact_ids_by_overlap_availability" =>
        affected_contact_ids_by_overlap_availability,
      "reserved_under_higher_precedence_contact_count" =>
        case reserved_under_higher_precedence_contact_count do
          count when count > 0 -> count
          _count -> nil
        end,
      "reserved_under_higher_precedence_contact_ids" =>
        case reserved_under_higher_precedence_contact_ids do
          [] -> nil
          contact_ids -> contact_ids
        end,
      "reserved_under_higher_precedence_contact_ids_by_applied_availability" =>
        reserved_under_higher_precedence_contact_ids_by_applied_availability,
      "trust_boundary_status" => Map.get(station_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(station_summary, "trust_boundaries", []),
      "branch_local_station_calendar_pressure" =>
        affected_contact_count + provider_contention_group_count > 0 or
          map_size(status_counts) > 0 or map_size(affected_ground_station_counts) > 0 or
          map_size(affected_availability_counts) > 0 or map_size(provider_counts) > 0 or
          precedence_pressure or
          map_size(provider_ground_station_counts) > 0 or affected_contact_ids != [] or
          affected_station_calendar_entry_ids != [] or
          affected_station_reservation_ids != [] or
          map_size(direction_counts) > 0 or map_size(contact_ids_by_direction) > 0 or
          map_size(station_calendar_entry_ids_by_direction) > 0 or
          map_size(station_reservation_ids_by_direction) > 0 or
          map_size(station_capacity_fractions_by_direction) > 0 or
          map_size(direction_routing) > 0 or
          map_size(reserved_by_counts) > 0 or map_size(contact_ids_by_reserved_by) > 0 or
          map_size(station_calendar_entry_ids_by_reserved_by) > 0 or
          map_size(station_reservation_ids_by_reserved_by) > 0 or
          station_reservation_expires_at_s != [] or
          not is_nil(earliest_station_reservation_expires_at_s) or
          station_capacity_fractions != [] or not is_nil(minimum_station_capacity_fraction) or
          map_size(station_capacity_fractions_by_status) > 0 or
          map_size(station_capacity_fractions_by_ground_station) > 0 or
          map_size(station_capacity_fractions_by_availability) > 0 or
          provider_contention_capacity_fractions != [] or
          not is_nil(provider_contention_minimum_capacity_fraction) or
          map_size(provider_contention_capacity_fractions_by_provider) > 0 or
          map_size(provider_contention_capacity_fractions_by_ground_station) > 0 or
          map_size(provider_contention_provider_entry_ids_by_provider) > 0 or
          map_size(provider_contention_provider_entry_ids_by_ground_station) > 0 or
          map_size(provider_contention_provider_ids_by_direction) > 0 or
          map_size(provider_contention_direction_counts) > 0 or
          map_size(provider_contention_group_ids_by_direction) > 0 or
          map_size(provider_contention_source_entry_ids_by_direction) > 0 or
          map_size(provider_contention_provider_entry_ids_by_direction) > 0 or
          map_size(provider_contention_capacity_fractions_by_direction) > 0 or
          provider_contention_group_ids != [] or provider_contention_source_entry_ids != [] or
          provider_contention_provider_entry_ids != [] or
          map_size(contact_ids_by_status) > 0 or map_size(contact_ids_by_ground_station) > 0 or
          map_size(contact_ids_by_availability) > 0 or
          map_size(station_calendar_entry_ids_by_status) > 0 or
          map_size(station_calendar_entry_ids_by_ground_station) > 0 or
          map_size(station_calendar_entry_ids_by_availability) > 0 or
          map_size(station_reservation_ids_by_status) > 0 or
          map_size(station_reservation_ids_by_ground_station) > 0 or
          map_size(station_reservation_ids_by_availability) > 0,
      "branch_local_affected_contact_pressure" =>
        affected_contact_count > 0 or map_size(status_counts) > 0 or
          map_size(affected_ground_station_counts) > 0 or
          map_size(affected_availability_counts) > 0 or affected_contact_ids != [] or
          precedence_pressure or
          affected_station_calendar_entry_ids != [] or
          affected_station_reservation_ids != [] or
          map_size(direction_counts) > 0 or map_size(contact_ids_by_direction) > 0 or
          map_size(station_calendar_entry_ids_by_direction) > 0 or
          map_size(station_reservation_ids_by_direction) > 0 or
          map_size(station_capacity_fractions_by_direction) > 0 or
          map_size(reserved_by_counts) > 0 or map_size(contact_ids_by_reserved_by) > 0 or
          map_size(station_calendar_entry_ids_by_reserved_by) > 0 or
          map_size(station_reservation_ids_by_reserved_by) > 0 or
          station_reservation_expires_at_s != [] or
          not is_nil(earliest_station_reservation_expires_at_s) or
          station_capacity_fractions != [] or not is_nil(minimum_station_capacity_fraction) or
          map_size(station_capacity_fractions_by_status) > 0 or
          map_size(station_capacity_fractions_by_ground_station) > 0 or
          map_size(station_capacity_fractions_by_availability) > 0 or
          map_size(contact_ids_by_status) > 0 or map_size(contact_ids_by_ground_station) > 0 or
          map_size(contact_ids_by_availability) > 0 or
          map_size(station_calendar_entry_ids_by_status) > 0 or
          map_size(station_calendar_entry_ids_by_ground_station) > 0 or
          map_size(station_calendar_entry_ids_by_availability) > 0 or
          map_size(station_reservation_ids_by_status) > 0 or
          map_size(station_reservation_ids_by_ground_station) > 0 or
          map_size(station_reservation_ids_by_availability) > 0,
      "branch_local_provider_contention_pressure" =>
        provider_contention_group_count > 0 or map_size(provider_counts) > 0 or
          map_size(provider_ground_station_counts) > 0 or provider_contention_group_ids != [] or
          provider_contention_source_entry_ids != [] or
          provider_contention_provider_entry_ids != [] or
          provider_contention_capacity_fractions != [] or
          not is_nil(provider_contention_minimum_capacity_fraction) or
          map_size(provider_contention_capacity_fractions_by_provider) > 0 or
          map_size(provider_contention_capacity_fractions_by_ground_station) > 0 or
          map_size(provider_contention_provider_entry_ids_by_provider) > 0 or
          map_size(provider_contention_provider_entry_ids_by_ground_station) > 0 or
          map_size(provider_contention_provider_ids_by_direction) > 0 or
          map_size(provider_contention_direction_counts) > 0 or
          map_size(provider_contention_group_ids_by_direction) > 0 or
          map_size(provider_contention_source_entry_ids_by_direction) > 0 or
          map_size(provider_contention_provider_entry_ids_by_direction) > 0 or
          map_size(provider_contention_capacity_fractions_by_direction) > 0,
      "branch_local_station_availability_pressure" =>
        map_size(status_counts) > 0 or map_size(affected_availability_counts) > 0 or
          precedence_pressure or
          map_size(contact_ids_by_status) > 0 or map_size(contact_ids_by_availability) > 0 or
          map_size(station_calendar_entry_ids_by_status) > 0 or
          map_size(station_calendar_entry_ids_by_availability) > 0 or
          map_size(station_reservation_ids_by_status) > 0 or
          map_size(station_reservation_ids_by_availability) > 0 or
          map_size(reserved_by_counts) > 0 or map_size(contact_ids_by_reserved_by) > 0 or
          map_size(station_calendar_entry_ids_by_reserved_by) > 0 or
          map_size(station_reservation_ids_by_reserved_by) > 0 or
          station_reservation_expires_at_s != [] or
          not is_nil(earliest_station_reservation_expires_at_s) or
          station_capacity_fractions != [] or not is_nil(minimum_station_capacity_fraction) or
          map_size(station_capacity_fractions_by_status) > 0 or
          map_size(station_capacity_fractions_by_ground_station) > 0 or
          map_size(station_capacity_fractions_by_availability) > 0 or
          provider_contention_capacity_fractions != [] or
          not is_nil(provider_contention_minimum_capacity_fraction) or
          map_size(provider_contention_capacity_fractions_by_provider) > 0 or
          map_size(provider_contention_capacity_fractions_by_ground_station) > 0 or
          map_size(provider_contention_capacity_fractions_by_direction) > 0,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => "station_calendar_source_report_provenance_only",
        "operator_authority" => "not_granted_by_station_calendar_replay_summary",
        "station_calendar_mutation" => "not_performed_by_summary",
        "schedule_mutation" => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_station_calendar_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local station-reservation replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not reserve provider time, mutate station
  calendars or schedules, select candidates, approve imports, write to Cadence,
  or regenerate candidates.
  """
  def station_reservation_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    branch_reservation_summary =
      source_report_summary_branch_family(refresh_or_artifact, "station_reservation_report")

    reservation_summary =
      branch_reservation_summary ||
        get_in(source_summary, ["source_reports", "station_reservation_report"]) || %{}

    {summary_source, replay_scope} =
      if branch_reservation_summary do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.station_reservation_report",
          "station_reservation_candidate_source_report_summary_only"
        }
      else
        {
          "candidate_refresh.source_report_provenance.station_reservation_report",
          "station_reservation_source_report_provenance_only"
