    reservation_hold_ready_for_import_count =
      if Map.has_key?(reservation_summary, "reservation_hold_ready_for_import_count") do
        summary_integer(reservation_summary, "reservation_hold_ready_for_import_count")
      end

    reservation_hold_review_required_before_import_count =
      if Map.has_key?(
           reservation_summary,
           "reservation_hold_review_required_before_import_count"
         ) do
        summary_integer(
          reservation_summary,
          "reservation_hold_review_required_before_import_count"
        )
      end

    reservation_hold_no_import_required_count =
      if Map.has_key?(reservation_summary, "reservation_hold_no_import_required_count") do
        summary_integer(reservation_summary, "reservation_hold_no_import_required_count")
      end

    reservation_hold_import_status_counts =
      Map.get(reservation_summary, "reservation_hold_import_status_counts")

    reservation_hold_required_import_action_counts =
