    match_status_counts =
      Map.get(reservation_summary, "station_reservation_match_status_counts", %{})

    reservation_status_counts = Map.get(reservation_summary, "reservation_status_counts", %{})
    reservation_ids = Map.get(reservation_summary, "reservation_ids", [])

    reservation_ids_by_match_status =
      Map.get(reservation_summary, "reservation_ids_by_match_status", %{})

    reservation_ids_by_status = Map.get(reservation_summary, "reservation_ids_by_status", %{})
    reserved_by_counts = Map.get(reservation_summary, "reserved_by_counts", %{})

    contact_ids_by_reserved_by =
      Map.get(reservation_summary, "contact_ids_by_reserved_by", %{})

    reservation_ids_by_reserved_by =
      Map.get(reservation_summary, "reservation_ids_by_reserved_by", %{})

    reservation_expiration_pressure =
      expiration_evidence_count > 0 or reservation_expires_at_s != [] or
        not is_nil(earliest_reservation_expires_at_s)

    reservation_hold_pressure =
      (reservation_hold_count || 0) > 0 or (affected_contact_reservation_hold_count || 0) > 0 or
        (provider_calendar_contention_hold_count || 0) > 0 or
        (reservation_hold_expiration_count || 0) > 0 or
        not is_nil(earliest_reservation_hold_expires_at_s) or
        map_size(reservation_hold_review_status_counts || %{}) > 0 or
        map_size(reservation_hold_expiration_status_counts || %{}) > 0 or
        map_size(reservation_hold_status_counts || %{}) > 0 or
        (reservation_hold_ids || []) != [] or
        map_size(reservation_hold_ids_by_direction || %{}) > 0 or
        map_size(reservation_hold_ids_by_expiration_status || %{}) > 0 or
        map_size(reservation_hold_ids_by_status || %{}) > 0 or
        map_size(reservation_hold_ids_by_reserved_by || %{}) > 0 or
        map_size(reservation_hold_ids_by_row_type || %{}) > 0 or
        map_size(reservation_hold_contact_ids_by_direction || %{}) > 0 or
        map_size(reservation_hold_contact_ids_by_expiration_status || %{}) > 0 or
        (reservation_hold_review_contact_ids || []) != []

    reservation_hold_import_readiness_pressure =
      reservation_hold_pressure or
        (reservation_hold_review_required_before_import_count || 0) > 0 or
        map_size(reservation_hold_import_readiness_status_counts || %{}) > 0 or
        map_size(reservation_hold_import_status_counts || %{}) > 0 or
        map_size(reservation_hold_required_import_action_counts || %{}) > 0 or
        map_size(reservation_hold_ids_by_import_status || %{}) > 0 or
        map_size(reservation_hold_ids_by_required_import_action || %{}) > 0 or
        map_size(reservation_hold_ids_by_direction || %{}) > 0 or
        map_size(reservation_hold_contact_ids_by_import_status || %{}) > 0 or
        map_size(reservation_hold_contact_ids_by_direction || %{}) > 0

    %{
