      "provider_calendar_contention_group_ids" => provider_contention_group_ids,
      "provider_calendar_contention_source_entry_ids" => provider_contention_source_entry_ids,
      "provider_calendar_contention_provider_entry_ids" => provider_contention_provider_entry_ids,
      "provider_calendar_contention_provider_entry_ids_by_provider" =>
