      "provider_calendar_contention_provider_entry_ids_by_ground_station" =>
        provider_contention_provider_entry_ids_by_ground_station,
      "provider_calendar_contention_provider_entry_ids_by_direction" =>
        provider_contention_provider_entry_ids_by_direction,
      "source_summary_model_counts" => source_summary_model_counts,
      "source_summary_schema_contract_counts" => source_summary_schema_contract_counts,
      "source_artifact_type_counts" => source_artifact_type_counts,
      "reservation_review_count" => reservation_review_count,
      "reservation_hold_count" => reservation_hold_count,
      "affected_contact_reservation_hold_count" => affected_contact_reservation_hold_count,
      "provider_calendar_contention_hold_count" => provider_calendar_contention_hold_count,
      "reservation_hold_review_status_counts" => reservation_hold_review_status_counts,
      "reservation_hold_expiration_count" => reservation_hold_expiration_count,
      "earliest_reservation_hold_expires_at_s" => earliest_reservation_hold_expires_at_s,
      "reservation_hold_expiration_status_counts" => reservation_hold_expiration_status_counts,
      "reservation_hold_status_counts" => reservation_hold_status_counts,
      "reservation_hold_import_readiness_status_counts" =>
        reservation_hold_import_readiness_status_counts,
      "reservation_hold_import_classification_counts" =>
        reservation_hold_import_classification_counts,
      "reservation_hold_ready_for_import_count" => reservation_hold_ready_for_import_count,
      "reservation_hold_review_required_before_import_count" =>
        reservation_hold_review_required_before_import_count,
      "reservation_hold_no_import_required_count" => reservation_hold_no_import_required_count,
      "reservation_hold_import_status_counts" => reservation_hold_import_status_counts,
      "reservation_hold_required_import_action_counts" =>
        reservation_hold_required_import_action_counts,
      "reservation_hold_ids" => reservation_hold_ids,
      "reservation_hold_ids_by_import_status" => reservation_hold_ids_by_import_status,
      "reservation_hold_ids_by_required_import_action" =>
        reservation_hold_ids_by_required_import_action,
      "reservation_hold_ids_by_expiration_status" => reservation_hold_ids_by_expiration_status,
      "reservation_hold_ids_by_status" => reservation_hold_ids_by_status,
      "reservation_hold_ids_by_reserved_by" => reservation_hold_ids_by_reserved_by,
      "reservation_hold_ids_by_row_type" => reservation_hold_ids_by_row_type,
      "reservation_hold_ids_by_direction" => reservation_hold_ids_by_direction,
      "reservation_hold_contact_ids_by_import_status" =>
        reservation_hold_contact_ids_by_import_status,
      "reservation_hold_contact_ids_by_expiration_status" =>
        reservation_hold_contact_ids_by_expiration_status,
      "reservation_hold_contact_ids_by_direction" => reservation_hold_contact_ids_by_direction,
      "reservation_hold_review_contact_ids" => reservation_hold_review_contact_ids,
      "station_reservation_evidence_row_count" => reservation_evidence_count,
      "station_reservation_expiration_evidence_row_count" => expiration_evidence_count,
      "reservation_expires_at_s" => reservation_expires_at_s,
      "earliest_reservation_expires_at_s" => earliest_reservation_expires_at_s,
      "station_reservation_match_status_counts" => match_status_counts,
      "reservation_status_counts" => reservation_status_counts,
      "reservation_ids" => reservation_ids,
      "reservation_ids_by_match_status" => reservation_ids_by_match_status,
      "reservation_ids_by_status" => reservation_ids_by_status,
      "reserved_by_counts" => reserved_by_counts,
      "contact_ids_by_reserved_by" => contact_ids_by_reserved_by,
      "reservation_ids_by_reserved_by" => reservation_ids_by_reserved_by,
      "trust_boundary_status" => Map.get(reservation_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(reservation_summary, "trust_boundaries", []),
      "branch_local_station_reservation_pressure" =>
        reservation_evidence_count > 0 or affected_contact_count > 0 or
          affected_contact_ids != [] or map_size(contact_ids_by_match_status) > 0 or
          map_size(contact_ids_by_status) > 0 or
          map_size(direction_counts) > 0 or map_size(contact_ids_by_direction) > 0 or
          map_size(direction_routing) > 0 or
          provider_contention_group_count > 0 or reservation_review_count > 0 or
          provider_contention_group_ids != [] or provider_contention_source_entry_ids != [] or
          provider_contention_provider_entry_ids != [] or
          map_size(provider_contention_provider_entry_ids_by_provider) > 0 or
          map_size(provider_contention_provider_entry_ids_by_ground_station) > 0 or
          map_size(provider_contention_provider_entry_ids_by_direction) > 0 or
          reservation_ids != [] or map_size(match_status_counts) > 0 or
          map_size(reservation_status_counts) > 0 or
          map_size(reservation_ids_by_match_status) > 0 or
          map_size(reservation_ids_by_status) > 0 or map_size(reserved_by_counts) > 0 or
          map_size(contact_ids_by_reserved_by) > 0 or
          map_size(reservation_ids_by_reserved_by) > 0 or reservation_expiration_pressure or
          (reservation_hold_count || 0) > 0 or (reservation_hold_ids || []) != [] or
          map_size(reservation_hold_import_status_counts || %{}) > 0 or
          map_size(reservation_hold_required_import_action_counts || %{}) > 0 or
          map_size(reservation_hold_ids_by_direction || %{}) > 0 or
          map_size(reservation_hold_contact_ids_by_direction || %{}) > 0,
      "branch_local_reservation_review_pressure" =>
        reservation_review_count > 0 or map_size(match_status_counts) > 0 or
          map_size(reservation_ids_by_match_status) > 0 or
          map_size(contact_ids_by_match_status) > 0 or map_size(contact_ids_by_status) > 0 or
          map_size(direction_counts) > 0 or map_size(contact_ids_by_direction) > 0 or
          map_size(direction_routing) > 0,
      "branch_local_reservation_owner_pressure" =>
        map_size(reserved_by_counts) > 0 or map_size(contact_ids_by_reserved_by) > 0 or
          map_size(reservation_ids_by_reserved_by) > 0,
      "branch_local_reservation_expiration_pressure" => reservation_expiration_pressure,
      "branch_local_reservation_hold_pressure" => if(reservation_hold_pressure, do: true),
      "branch_local_provider_contention_pressure" =>
        provider_contention_group_count > 0 or map_size(provider_counts) > 0 or
          map_size(provider_ground_station_counts) > 0 or provider_contention_group_ids != [] or
          provider_contention_source_entry_ids != [] or
          provider_contention_provider_entry_ids != [] or
          map_size(provider_contention_provider_entry_ids_by_provider) > 0 or
          map_size(provider_contention_provider_entry_ids_by_ground_station) > 0 or
          map_size(provider_contention_provider_entry_ids_by_direction) > 0,
      "branch_local_reservation_hold_import_readiness_pressure" =>
        if(reservation_hold_import_readiness_pressure, do: true),
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => "not_granted_by_station_reservation_replay_summary",
        "provider_reservation" => "not_performed_by_summary",
        "station_calendar_mutation" => "not_performed_by_summary",
        "schedule_mutation" => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_station_reservation_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local command-window replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not replay refresh generation, execute
  commands, select candidates, approve imports, or write to Cadence.
  """
  def command_window_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    branch_command_summary =
      source_report_summary_branch_family(refresh_or_artifact, "command_window_report")

    command_summary =
      branch_command_summary ||
        get_in(source_summary, ["source_reports", "command_window_report"]) || %{}

    {summary_source, replay_scope} =
      if branch_command_summary do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.command_window_report",
          "command_window_candidate_source_report_summary_only"
        }
      else
        {
          "candidate_refresh.source_report_provenance.command_window_report",
          "command_window_source_report_provenance_only"
        }
      end

    command_feedback_count = summary_integer(command_summary, "command_feedback_count")
    input_keys = Map.get(command_summary, "input_keys", [])
    direction_counts = Map.get(command_summary, "direction_counts", %{})
    activity_ids_by_direction = Map.get(command_summary, "activity_ids_by_direction", %{})
    window_ids_by_direction = Map.get(command_summary, "window_ids_by_direction", %{})
    direction_routing = Map.get(command_summary, "direction_routing", %{})
    required_action_counts = Map.get(command_summary, "required_operator_action_counts", %{})

    %{
      "model" => "artifact_only_candidate_refresh_command_window_replay_summary",
      "source" => summary_source,
      "contract" => source_report_summary_contract(command_summary, "command_window_report.v1"),
      "source_report_count" => summary_integer(command_summary, "count"),
      "source_report_row_count" => summary_integer(command_summary, "row_count"),
      "source_report_paths" => Map.get(command_summary, "paths", []),
      "command_feedback_count" => command_feedback_count,
      "input_keys" => input_keys,
      "direction_counts" => direction_counts,
