  @doc """
  Builds a compact branch-local timeline activity-approval-state replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not apply approval changes, mutate
  timelines, select candidates, approve imports, execute commands, or write to
  Cadence.
  """
  def timeline_activity_approval_state_replay_summary(refresh_or_artifact) do
    timeline_activity_single_state_replay_summary(
      refresh_or_artifact,
      "timeline_activity_approval_state",
      "timeline_activity_approval_state.v1",
      "artifact_only_timeline_activity_approval_state",
      "activity_approval_state_application",
      "not_granted_by_timeline_activity_approval_state_replay_summary"
    )
  end

  defp timeline_activity_single_state_replay_summary(
         refresh_or_artifact,
         family,
         contract,
         source_model,
         application_boundary,
         authority_boundary
       ) do
    {state_summary, branch_summary?} =
      refresh_or_artifact
      |> source_timeline_activity_states()
      |> Enum.filter(fn {_path, state} ->
        Map.get(state, "schema_contract") == contract or Map.get(state, "model") == source_model
      end)
      |> source_timeline_activity_state_input_summary()
      |> case do
        nil ->
          timeline_activity_single_state_summary_from_source_reports(
            refresh_or_artifact,
            contract
          )

        summary ->
          {summary, false}
      end
      |> case do
        nil -> {%{}, false}
        {summary, branch_summary?} -> {summary, branch_summary?}
      end

    {summary_source, replay_scope} =
      if branch_summary? do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.#{family}",
          "#{family}_candidate_source_report_summary_only"
        }
      else
        {
          "candidate_refresh.source_report_provenance.#{family}",
          "#{family}_source_report_provenance_only"
        }
      end

    row_count = summary_integer(state_summary, "row_count")
    review_required_count = summary_integer(state_summary, "review_required_count")
    invalid_activity_input_count = summary_integer(state_summary, "invalid_activity_input_count")

    invalid_activity_input_reason_counts =
      Map.get(state_summary, "invalid_activity_input_reason_counts", %{})

    invalid_activity_input_reasons =
      Map.get(state_summary, "invalid_activity_input_reasons", [])

    transition_decision_counts = Map.get(state_summary, "transition_decision_counts", %{})
    required_action_counts = Map.get(state_summary, "required_operator_action_counts", %{})
    import_action_counts = Map.get(state_summary, "import_action_counts", %{})
    planned_status_counts = Map.get(state_summary, "planned_status_category_counts", %{})
    realized_status_counts = Map.get(state_summary, "realized_status_category_counts", %{})
    planned_approval_counts = Map.get(state_summary, "planned_approval_category_counts", %{})
    realized_approval_counts = Map.get(state_summary, "realized_approval_category_counts", %{})
    status_transition_counts = Map.get(state_summary, "status_transition_category_counts", %{})

    approval_transition_counts =
      Map.get(state_summary, "approval_transition_category_counts", %{})

    activity_id_counts = Map.get(state_summary, "activity_id_counts", %{})
    timeline_id_counts = Map.get(state_summary, "timeline_id_counts", %{})
    review_activity_id_counts = Map.get(state_summary, "review_activity_id_counts", %{})
    action_routing = Map.get(state_summary, "action_routing", %{}) |> empty_map_if_nil()

    source_summary_model_counts =
      Map.get(state_summary, "source_summary_model_counts", %{}) |> non_empty_map()

    source_summary_schema_contract_counts =
      Map.get(state_summary, "source_summary_schema_contract_counts", %{})
      |> non_empty_map()

    review_action_counts =
      required_action_counts
      |> Enum.filter(fn {action, _count} ->
        is_binary(action) and String.starts_with?(action, "review")
      end)
      |> Map.new()

    state_evidence_pressure =
      row_count > 0 or invalid_activity_input_count > 0 or
        map_size(invalid_activity_input_reason_counts) > 0 or
        map_size(transition_decision_counts) > 0 or
        map_size(import_action_counts) > 0 or map_size(planned_status_counts) > 0 or
        map_size(realized_status_counts) > 0 or map_size(planned_approval_counts) > 0 or
        map_size(realized_approval_counts) > 0 or map_size(status_transition_counts) > 0 or
        map_size(approval_transition_counts) > 0

    review_pressure =
      review_required_count > 0 or map_size(review_action_counts) > 0 or
        map_size(review_activity_id_counts) > 0

    routing_pressure =
      map_size(activity_id_counts) > 0 or map_size(timeline_id_counts) > 0 or
        map_size(review_activity_id_counts) > 0 or map_size(action_routing) > 0

    %{
      "model" => "artifact_only_candidate_refresh_#{family}_replay_summary",
      "source" => summary_source,
      "contract" => source_report_summary_contract(state_summary, nil),
      "source_report_count" => summary_integer(state_summary, "count"),
      "source_report_row_count" => row_count,
      "source_report_paths" => Map.get(state_summary, "paths", []),
      "source_summary_model_counts" => source_summary_model_counts,
      "source_summary_schema_contract_counts" => source_summary_schema_contract_counts,
      "review_required_count" => review_required_count,
      "invalid_activity_input_count" => invalid_activity_input_count,
      "invalid_activity_input_reason_counts" => invalid_activity_input_reason_counts,
      "invalid_activity_input_reasons" => invalid_activity_input_reasons,
      "transition_decision_counts" => transition_decision_counts,
      "required_operator_action_counts" => required_action_counts,
      "import_action_counts" => import_action_counts,
      "planned_status_category_counts" => planned_status_counts,
      "realized_status_category_counts" => realized_status_counts,
      "planned_approval_category_counts" => planned_approval_counts,
      "realized_approval_category_counts" => realized_approval_counts,
      "status_transition_category_counts" => status_transition_counts,
      "approval_transition_category_counts" => approval_transition_counts,
      "activity_id_counts" => activity_id_counts,
      "timeline_id_counts" => timeline_id_counts,
      "review_activity_id_counts" => review_activity_id_counts,
      "action_routing" => action_routing,
      "trust_boundary_status" => Map.get(state_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(state_summary, "trust_boundaries", []),
      "branch_local_#{family}_pressure" =>
        state_evidence_pressure or review_pressure or routing_pressure,
      "branch_local_#{family}_review_pressure" => review_pressure,
      "branch_local_#{family}_action_pressure" => map_size(action_routing) > 0,
      "branch_local_#{family}_routing_pressure" => routing_pressure,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => authority_boundary,
        "timeline_mutation" => "not_performed_by_summary",
        application_boundary => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => authority_boundary,
        "cadence_write" => "not_performed_by_summary",
        "command_execution" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  defp timeline_activity_single_state_summary_from_source_reports(refresh_or_artifact, contract) do
    branch_state_summary =
      refresh_or_artifact
      |> source_report_summary_branch_family("timeline_activity_state")
      |> timeline_activity_single_state_summary_matching_contract(contract)

    if branch_state_summary do
      {branch_state_summary, true}
    else
      state_summary =
        refresh_or_artifact
        |> source_report_summary()
        |> get_in(["source_reports", "timeline_activity_state"])

      state_summary
      |> timeline_activity_single_state_summary_matching_contract(contract)
      |> case do
        nil -> nil
        state_summary -> {state_summary, false}
      end
    end
  end

  defp timeline_activity_single_state_summary_matching_contract(state_summary, contract) do
    contract_counts = Map.get(state_summary || %{}, "source_summary_schema_contract_counts", %{})

    cond do
      Map.get(state_summary || %{}, "contract") == contract ->
        state_summary

      map_size(contract_counts) == 1 and Map.has_key?(contract_counts, contract) ->
        state_summary

      true ->
        nil
    end
  end

  defp source_report_timeline_activity_single_state_fields(
         refresh_or_artifact,
         source_reports,
         family,
         contract,
         source_model
       ) do
    summary =
      refresh_or_artifact
      |> source_timeline_activity_states()
      |> Enum.filter(fn {_path, state} ->
        Map.get(state, "schema_contract") == contract or Map.get(state, "model") == source_model
      end)
      |> source_timeline_activity_state_input_summary()
      |> case do
        nil ->
          source_reports
          |> Map.get("timeline_activity_state")
          |> timeline_activity_single_state_summary_matching_contract(contract)

        summary ->
          summary
      end

    source_report_timeline_activity_single_state_fields(family, summary || %{})
  end

  defp source_report_timeline_activity_single_state_fields(family, state_summary) do
    prefix = "source_report_#{family}"

    %{
      "#{prefix}_contract" => source_report_summary_contract(state_summary, nil),
      "#{prefix}_count" => summary_integer(state_summary, "count"),
      "#{prefix}_row_count" => summary_integer(state_summary, "row_count"),
      "#{prefix}_paths" => Map.get(state_summary, "paths", []),
      "#{prefix}_source_summary_model_counts" =>
        Map.get(state_summary, "source_summary_model_counts", %{}),
      "#{prefix}_source_summary_schema_contract_counts" =>
        Map.get(state_summary, "source_summary_schema_contract_counts", %{}),
      "#{prefix}_review_required_count" =>
        summary_integer(state_summary, "review_required_count"),
      "#{prefix}_invalid_activity_input_count" =>
        summary_integer(state_summary, "invalid_activity_input_count"),
      "#{prefix}_invalid_activity_input_reason_counts" =>
        Map.get(state_summary, "invalid_activity_input_reason_counts", %{}),
      "#{prefix}_invalid_activity_input_reasons" =>
        Map.get(state_summary, "invalid_activity_input_reasons", []),
      "#{prefix}_transition_decision_counts" =>
        Map.get(state_summary, "transition_decision_counts", %{}),
      "#{prefix}_required_operator_action_counts" =>
        Map.get(state_summary, "required_operator_action_counts", %{}),
      "#{prefix}_import_action_counts" => Map.get(state_summary, "import_action_counts", %{}),
      "#{prefix}_planned_status_category_counts" =>
        Map.get(state_summary, "planned_status_category_counts", %{}),
      "#{prefix}_realized_status_category_counts" =>
        Map.get(state_summary, "realized_status_category_counts", %{}),
      "#{prefix}_planned_approval_category_counts" =>
        Map.get(state_summary, "planned_approval_category_counts", %{}),
      "#{prefix}_realized_approval_category_counts" =>
        Map.get(state_summary, "realized_approval_category_counts", %{}),
      "#{prefix}_status_transition_category_counts" =>
        Map.get(state_summary, "status_transition_category_counts", %{}),
      "#{prefix}_approval_transition_category_counts" =>
        Map.get(state_summary, "approval_transition_category_counts", %{}),
      "#{prefix}_activity_id_counts" => Map.get(state_summary, "activity_id_counts", %{}),
      "#{prefix}_timeline_id_counts" => Map.get(state_summary, "timeline_id_counts", %{}),
      "#{prefix}_review_activity_id_counts" =>
        Map.get(state_summary, "review_activity_id_counts", %{}),
      "#{prefix}_action_routing" => Map.get(state_summary, "action_routing", %{})
    }
  end

  @doc """
  Builds a compact branch-local timeline activity-lifecycle-state replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not apply lifecycle-state changes, mutate
  timelines, select candidates, approve imports, execute commands, or write to
  Cadence.
  """
  def timeline_activity_lifecycle_state_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    branch_lifecycle_summary =
      source_report_summary_branch_family(
        refresh_or_artifact,
        "timeline_activity_lifecycle_state"
      )

    lifecycle_summary =
      branch_lifecycle_summary ||
        get_in(source_summary, ["source_reports", "timeline_activity_lifecycle_state"]) || %{}

    {summary_source, replay_scope} =
      if branch_lifecycle_summary do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.timeline_activity_lifecycle_state",
          "timeline_activity_lifecycle_state_candidate_source_report_summary_only"
        }
      else
        {
          "candidate_refresh.source_report_provenance.timeline_activity_lifecycle_state",
          "timeline_activity_lifecycle_state_source_report_provenance_only"
        }
      end

    row_count = summary_integer(lifecycle_summary, "row_count")
    review_required_count = summary_integer(lifecycle_summary, "review_required_count")

    invalid_activity_input_count =
      summary_integer(lifecycle_summary, "invalid_activity_input_count")

    invalid_activity_input_reason_counts =
      Map.get(lifecycle_summary, "invalid_activity_input_reason_counts", %{})

    invalid_activity_input_reasons =
      Map.get(lifecycle_summary, "invalid_activity_input_reasons", [])

    transition_decision_counts = Map.get(lifecycle_summary, "transition_decision_counts", %{})

    status_transition_decision_counts =
      Map.get(lifecycle_summary, "status_transition_decision_counts", %{})

    approval_transition_decision_counts =
      Map.get(lifecycle_summary, "approval_transition_decision_counts", %{})

    required_action_counts = Map.get(lifecycle_summary, "required_operator_action_counts", %{})
    import_action_counts = Map.get(lifecycle_summary, "import_action_counts", %{})
    planned_status_counts = Map.get(lifecycle_summary, "planned_status_category_counts", %{})
    realized_status_counts = Map.get(lifecycle_summary, "realized_status_category_counts", %{})
    planned_approval_counts = Map.get(lifecycle_summary, "planned_approval_category_counts", %{})

    realized_approval_counts =
      Map.get(lifecycle_summary, "realized_approval_category_counts", %{})

    status_transition_counts =
      Map.get(lifecycle_summary, "status_transition_category_counts", %{})

    approval_transition_counts =
      Map.get(lifecycle_summary, "approval_transition_category_counts", %{})

    transition_application_provenance_count =
      summary_integer(lifecycle_summary, "transition_application_provenance_count")

    transition_application_provenance_helper_counts =
      Map.get(lifecycle_summary, "transition_application_provenance_helper_counts", %{})

    transition_application_provenance_category_counts =
      Map.get(lifecycle_summary, "transition_application_provenance_category_counts", %{})

    transition_application_provenance_operator_action_reason_counts =
      Map.get(
        lifecycle_summary,
        "transition_application_provenance_operator_action_reason_counts",
        %{}
      )

    protection_decision_counts =
      Map.get(lifecycle_summary, "protection_decision_counts", %{})

    protection_category_counts =
      Map.get(lifecycle_summary, "protection_category_counts", %{})

    activity_id_counts = Map.get(lifecycle_summary, "activity_id_counts", %{})
    timeline_id_counts = Map.get(lifecycle_summary, "timeline_id_counts", %{})
    review_activity_id_counts = Map.get(lifecycle_summary, "review_activity_id_counts", %{})
    action_routing = Map.get(lifecycle_summary, "action_routing", %{}) |> empty_map_if_nil()

    source_summary_model_counts =
      Map.get(lifecycle_summary, "source_summary_model_counts", %{}) |> non_empty_map()

    source_summary_schema_contract_counts =
      Map.get(lifecycle_summary, "source_summary_schema_contract_counts", %{})
      |> non_empty_map()

    review_action_counts =
      required_action_counts
      |> Enum.filter(fn {action, _count} ->
        is_binary(action) and String.starts_with?(action, "review")
      end)
      |> Map.new()

    lifecycle_evidence_pressure =
      row_count > 0 or invalid_activity_input_count > 0 or
        map_size(invalid_activity_input_reason_counts) > 0 or
        map_size(transition_decision_counts) > 0 or
        map_size(status_transition_decision_counts) > 0 or
        map_size(approval_transition_decision_counts) > 0 or
        map_size(planned_status_counts) > 0 or map_size(realized_status_counts) > 0 or
        map_size(planned_approval_counts) > 0 or map_size(realized_approval_counts) > 0 or
        map_size(status_transition_counts) > 0 or map_size(approval_transition_counts) > 0 or
        transition_application_provenance_count > 0 or
        map_size(transition_application_provenance_helper_counts) > 0 or
        map_size(transition_application_provenance_category_counts) > 0 or
        map_size(transition_application_provenance_operator_action_reason_counts) > 0 or
        map_size(protection_decision_counts) > 0 or map_size(protection_category_counts) > 0

    review_pressure =
      review_required_count > 0 or map_size(review_action_counts) > 0 or
        map_size(review_activity_id_counts) > 0

    routing_pressure =
      map_size(activity_id_counts) > 0 or map_size(timeline_id_counts) > 0 or
        map_size(review_activity_id_counts) > 0 or map_size(action_routing) > 0

    %{
      "model" =>
        "artifact_only_candidate_refresh_timeline_activity_lifecycle_state_replay_summary",
      "source" => summary_source,
      "contract" => source_report_summary_contract(lifecycle_summary, nil),
      "source_report_count" => summary_integer(lifecycle_summary, "count"),
      "source_report_row_count" => row_count,
      "source_report_paths" => Map.get(lifecycle_summary, "paths", []),
      "source_summary_model_counts" => source_summary_model_counts,
      "source_summary_schema_contract_counts" => source_summary_schema_contract_counts,
      "review_required_count" => review_required_count,
      "invalid_activity_input_count" => invalid_activity_input_count,
      "invalid_activity_input_reason_counts" => invalid_activity_input_reason_counts,
      "invalid_activity_input_reasons" => invalid_activity_input_reasons,
      "transition_decision_counts" => transition_decision_counts,
      "status_transition_decision_counts" => status_transition_decision_counts,
      "approval_transition_decision_counts" => approval_transition_decision_counts,
      "required_operator_action_counts" => required_action_counts,
      "import_action_counts" => import_action_counts,
      "planned_status_category_counts" => planned_status_counts,
      "realized_status_category_counts" => realized_status_counts,
      "planned_approval_category_counts" => planned_approval_counts,
      "realized_approval_category_counts" => realized_approval_counts,
      "status_transition_category_counts" => status_transition_counts,
      "approval_transition_category_counts" => approval_transition_counts,
      "transition_application_provenance_count" => transition_application_provenance_count,
      "transition_application_provenance_helper_counts" =>
        transition_application_provenance_helper_counts,
      "transition_application_provenance_category_counts" =>
        transition_application_provenance_category_counts,
      "transition_application_provenance_operator_action_reason_counts" =>
        transition_application_provenance_operator_action_reason_counts,
      "protection_decision_counts" => protection_decision_counts,
      "protection_category_counts" => protection_category_counts,
      "activity_id_counts" => activity_id_counts,
      "timeline_id_counts" => timeline_id_counts,
      "review_activity_id_counts" => review_activity_id_counts,
      "action_routing" => action_routing,
      "trust_boundary_status" => Map.get(lifecycle_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(lifecycle_summary, "trust_boundaries", []),
      "branch_local_timeline_activity_lifecycle_state_pressure" =>
        lifecycle_evidence_pressure or review_pressure or routing_pressure,
      "branch_local_activity_lifecycle_review_pressure" => review_pressure,
      "branch_local_activity_lifecycle_action_pressure" => map_size(action_routing) > 0,
      "branch_local_activity_lifecycle_routing_pressure" => routing_pressure,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => "not_granted_by_timeline_activity_lifecycle_state_replay_summary",
        "timeline_mutation" => "not_performed_by_summary",
        "activity_lifecycle_application" => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_timeline_activity_lifecycle_state_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "command_execution" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local timeline activity-precondition replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not evaluate preconditions, mutate
  timelines, select candidates, approve imports, execute commands, reserve
  resources, or write to Cadence.
  """
  def timeline_activity_precondition_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    branch_precondition_summary =
      source_report_summary_branch_family(
        refresh_or_artifact,
        "timeline_activity_precondition_summary"
      )

    precondition_summary =
      branch_precondition_summary ||
        get_in(source_summary, ["source_reports", "timeline_activity_precondition_summary"]) ||
        %{}

    {summary_source, replay_scope} =
      if branch_precondition_summary do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.timeline_activity_precondition_summary",
          "timeline_activity_precondition_candidate_source_report_summary_only"
        }
      else
        {
          "candidate_refresh.source_report_provenance.timeline_activity_precondition_summary",
          "timeline_activity_precondition_summary_source_report_provenance_only"
        }
      end

    row_count = summary_integer(precondition_summary, "row_count")

    blocked_precondition_count =
      summary_integer(precondition_summary, "blocked_precondition_count")

    review_precondition_count = summary_integer(precondition_summary, "review_precondition_count")

    invalid_activity_input_count =
      summary_integer(precondition_summary, "invalid_activity_input_count")

    precondition_status_counts =
      Map.get(precondition_summary, "precondition_status_counts", %{})

    blocked_precondition_type_counts =
      Map.get(precondition_summary, "blocked_precondition_type_counts", %{})

    review_precondition_type_counts =
      Map.get(precondition_summary, "review_precondition_type_counts", %{})

    invalid_activity_input_reason_counts =
      Map.get(precondition_summary, "invalid_activity_input_reason_counts", %{})

    invalid_activity_input_reasons =
      Map.get(precondition_summary, "invalid_activity_input_reasons", [])

    activity_id_counts = Map.get(precondition_summary, "activity_id_counts", %{})
    timeline_id_counts = Map.get(precondition_summary, "timeline_id_counts", %{})

    dependency_activity_id_counts =
      Map.get(precondition_summary, "dependency_activity_id_counts", %{})

    dependency_timeline_id_counts =
      Map.get(precondition_summary, "dependency_timeline_id_counts", %{})

    exclusive_with_activity_id_counts =
      Map.get(precondition_summary, "exclusive_with_activity_id_counts", %{})

    exclusive_with_timeline_id_counts =
      Map.get(precondition_summary, "exclusive_with_timeline_id_counts", %{})

    allow_overlap_counts = Map.get(precondition_summary, "allow_overlap_counts", %{})

    source_summary_model_counts =
      Map.get(precondition_summary, "source_summary_model_counts", %{}) |> non_empty_map()

    source_summary_schema_contract_counts =
      Map.get(precondition_summary, "source_summary_schema_contract_counts", %{})
      |> non_empty_map()

    dependency_pressure =
      map_size(dependency_activity_id_counts) > 0 or map_size(dependency_timeline_id_counts) > 0

    exclusivity_pressure =
      map_size(exclusive_with_activity_id_counts) > 0 or
        map_size(exclusive_with_timeline_id_counts) > 0 or map_size(allow_overlap_counts) > 0

    review_pressure =
      review_precondition_count > 0 or
        summary_integer(precondition_status_counts, "review_required") > 0 or
        map_size(review_precondition_type_counts) > 0

    invalid_input_pressure =
      invalid_activity_input_count > 0 or map_size(invalid_activity_input_reason_counts) > 0

    routing_pressure = map_size(activity_id_counts) > 0 or map_size(timeline_id_counts) > 0

    %{
      "model" => "artifact_only_candidate_refresh_timeline_activity_precondition_replay_summary",
      "source" => summary_source,
      "contract" =>
        source_report_summary_contract(
          precondition_summary,
          "timeline_activity_precondition_summary.v1"
        ),
      "source_report_count" => summary_integer(precondition_summary, "count"),
      "source_report_row_count" => row_count,
      "source_report_paths" => Map.get(precondition_summary, "paths", []),
      "source_summary_model_counts" => source_summary_model_counts,
      "source_summary_schema_contract_counts" => source_summary_schema_contract_counts,
      "precondition_status_counts" => precondition_status_counts,
      "blocked_precondition_count" => blocked_precondition_count,
      "review_precondition_count" => review_precondition_count,
      "blocked_precondition_type_counts" => blocked_precondition_type_counts,
      "review_precondition_type_counts" => review_precondition_type_counts,
      "invalid_activity_input_count" => invalid_activity_input_count,
      "invalid_activity_input_reason_counts" => invalid_activity_input_reason_counts,
      "invalid_activity_input_reasons" => invalid_activity_input_reasons,
      "activity_id_counts" => activity_id_counts,
      "timeline_id_counts" => timeline_id_counts,
      "dependency_activity_id_counts" => dependency_activity_id_counts,
      "dependency_timeline_id_counts" => dependency_timeline_id_counts,
      "exclusive_with_activity_id_counts" => exclusive_with_activity_id_counts,
      "exclusive_with_timeline_id_counts" => exclusive_with_timeline_id_counts,
      "allow_overlap_counts" => allow_overlap_counts,
      "trust_boundary_status" => Map.get(precondition_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(precondition_summary, "trust_boundaries", []),
      "branch_local_timeline_activity_precondition_pressure" =>
        row_count > 0 or blocked_precondition_count > 0 or review_precondition_count > 0 or
          map_size(precondition_status_counts) > 0 or
          map_size(blocked_precondition_type_counts) > 0 or review_pressure or
          dependency_pressure or exclusivity_pressure or invalid_input_pressure or
          routing_pressure,
      "branch_local_activity_precondition_review_pressure" => review_pressure,
      "branch_local_activity_precondition_dependency_pressure" => dependency_pressure,
      "branch_local_activity_precondition_exclusivity_pressure" => exclusivity_pressure,
      "branch_local_activity_precondition_invalid_input_pressure" => invalid_input_pressure,
      "branch_local_activity_precondition_routing_pressure" => routing_pressure,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => "not_granted_by_timeline_activity_precondition_replay_summary",
        "timeline_mutation" => "not_performed_by_summary",
        "activity_precondition_evaluation" => "not_performed_by_summary",
        "resource_authority" => "not_reserved_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_timeline_activity_precondition_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "command_execution" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local timeline-preservation replay summary.

  The summary is derived from candidate-refresh preservation review provenance.
  It prefers branch-local candidate-source preservation rows when present and
  falls back to candidate-refresh preservation review provenance. It does not
  apply preservation decisions, mutate timelines, select candidates, approve
  imports, execute commands, or write to Cadence.
  """
  def timeline_preservation_replay_summary(refresh_or_artifact) do
    {rows, branch_rows?} =
      timeline_preservation_replay_rows_with_source(refresh_or_artifact)

    {summary_source, replay_scope} =
      if branch_rows? do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request.timeline_preservation",
          "timeline_preservation_candidate_source_review_provenance_only"
        }
      else
        {
          "candidate_refresh.review_provenance.timeline_preservation",
          "timeline_preservation_review_provenance_only"
        }
      end

    source_paths =
      rows
      |> Enum.map(&Map.get(&1, "source"))
      |> sorted_string_values()

    required_action_counts =
      rows
      |> Enum.map(&Map.get(&1, "required_operator_action"))
      |> count_source_report_values()

    preservation_status_counts =
      rows
      |> Enum.map(&Map.get(&1, "timeline_preservation_status"))
      |> count_source_report_values()

    protection_decision_counts =
      rows
      |> Enum.map(&Map.get(&1, "timeline_preservation_protection_decision"))
      |> count_source_report_values()

    protection_category_counts =
      rows
      |> Enum.map(&Map.get(&1, "timeline_preservation_protection_category"))
      |> count_source_report_values()

    protection_reason_counts =
      rows
      |> Enum.map(&Map.get(&1, "timeline_preservation_protection_reason"))
      |> count_source_report_values()

    source_contract_counts =
      rows
      |> Enum.map(&timeline_preservation_replay_row_source_contract/1)
      |> count_source_report_values()

    source_model_counts =
      rows
      |> Enum.map(&timeline_preservation_replay_row_source_model/1)
      |> count_source_report_values()

    activity_id_counts =
      rows
      |> Enum.flat_map(&timeline_preservation_replay_row_ids(&1, "activity_id"))
      |> count_source_report_values()

    timeline_id_counts =
      rows
      |> Enum.flat_map(&timeline_preservation_replay_row_ids(&1, "timeline_id"))
      |> count_source_report_values()

    preservation_required_rows =
      Enum.filter(rows, &(&1["timeline_preservation_status"] == "preservation_required"))

    review_required_rows =
      Enum.filter(rows, &(&1["timeline_preservation_status"] == "review_required"))

    preserve_rows =
      Enum.filter(rows, &(&1["timeline_preservation_protection_decision"] == "preserve"))

    review_change_rows =
      Enum.filter(rows, &(&1["timeline_preservation_protection_decision"] == "review_change"))

    action_routing = timeline_preservation_replay_action_routing(rows)

    trust_boundaries =
      rows
      |> source_report_trust_boundaries()

    review_pressure = review_required_rows != []
    preservation_pressure = preservation_required_rows != [] or preserve_rows != []
    routing_pressure = map_size(activity_id_counts) > 0 or map_size(timeline_id_counts) > 0
    action_pressure = map_size(action_routing) > 0

    %{
      "model" => "artifact_only_candidate_refresh_timeline_preservation_replay_summary",
      "source" => summary_source,
      "contract" => source_report_summary_contract(%{"contract" => nil}, nil),
      "source_artifact_count" => length(source_paths),
      "source_report_row_count" => length(rows),
      "source_report_paths" => source_paths,
      "source_summary_schema_contract_counts" => source_contract_counts,
      "source_summary_model_counts" => source_model_counts,
      "timeline_preservation_status_counts" => preservation_status_counts,
      "required_operator_action_counts" => required_action_counts,
      "protection_decision_counts" => protection_decision_counts,
      "protection_category_counts" => protection_category_counts,
      "protection_reason_counts" => protection_reason_counts,
      "activity_id_counts" => activity_id_counts,
      "timeline_id_counts" => timeline_id_counts,
      "preservation_required_activity_ids" =>
        timeline_preservation_replay_ids(preservation_required_rows, "activity_id"),
      "preservation_required_timeline_ids" =>
        timeline_preservation_replay_ids(preservation_required_rows, "timeline_id"),
      "review_required_activity_ids" =>
        timeline_preservation_replay_ids(review_required_rows, "activity_id"),
      "review_required_timeline_ids" =>
        timeline_preservation_replay_ids(review_required_rows, "timeline_id"),
      "preserve_activity_ids" => timeline_preservation_replay_ids(preserve_rows, "activity_id"),
      "preserve_timeline_ids" => timeline_preservation_replay_ids(preserve_rows, "timeline_id"),
      "review_change_activity_ids" =>
        timeline_preservation_replay_ids(review_change_rows, "activity_id"),
      "review_change_timeline_ids" =>
        timeline_preservation_replay_ids(review_change_rows, "timeline_id"),
      "action_routing" => action_routing,
      "trust_boundary_status" => if(trust_boundaries == [], do: "missing", else: "declared"),
      "trust_boundaries" => trust_boundaries,
      "branch_local_timeline_preservation_pressure" => rows != [],
      "branch_local_timeline_preservation_review_pressure" => review_pressure,
      "branch_local_timeline_preservation_record_pressure" => preservation_pressure,
      "branch_local_timeline_preservation_action_pressure" => action_pressure,
      "branch_local_timeline_preservation_routing_pressure" => routing_pressure,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => "not_granted_by_timeline_preservation_replay_summary",
        "timeline_mutation" => "not_performed_by_summary",
        "timeline_preservation_application" => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_timeline_preservation_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "command_execution" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  defp timeline_preservation_replay_rows(refresh_or_artifact) do
    refresh_or_artifact
    |> timeline_preservation_replay_package()
    |> Map.get("rows", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.filter(&(&1["review_type"] == "timeline_preservation_review"))
  end

  defp timeline_preservation_replay_rows_with_source(refresh_or_artifact) do
    case timeline_preservation_replay_candidate_source(refresh_or_artifact) do
      nil ->
        {timeline_preservation_replay_rows(refresh_or_artifact), false}

      candidate_source ->
        branch_rows =
          candidate_source
          |> timeline_preservation_replay_rows()
          |> Enum.map(&timeline_preservation_branch_replay_row/1)

        case branch_rows do
          [] -> {timeline_preservation_replay_rows(refresh_or_artifact), false}
          rows -> {rows, true}
        end
    end
  end

  defp timeline_preservation_replay_candidate_source(refresh_or_artifact) do
    artifact = stringify_keys(refresh_or_artifact)
    candidate_source = Map.get(artifact, "candidate_source")

    cond do
      is_map(candidate_source) and
          Map.has_key?(candidate_source, "candidate_refresh_request_source_report_summary") ->
        candidate_source

      Map.has_key?(artifact, "candidate_refresh_request_source_report_summary") ->
        artifact

      true ->
        nil
    end
  end

  defp timeline_preservation_branch_replay_row(%{} = row) do
    Map.update(row, "source", nil, fn
      source when is_binary(source) ->
        String.replace_prefix(
          source,
          "candidate_refresh.",
          "candidate_source.candidate_refresh_request."
        )

      source ->
        source
    end)
  end

  defp timeline_preservation_replay_package(refresh_or_artifact) do
    artifact = stringify_keys(refresh_or_artifact)

    case Map.get(artifact, "schema_contract") do
      "timeline_preservation_report.v1" ->
        OrbitalDynamics.OperatorReview.from_timeline_preservation_report(artifact)

      "timeline_preservation_status.v1" ->
        OrbitalDynamics.OperatorReview.from_timeline_preservation_status(artifact)

      _schema_contract ->
        OrbitalDynamics.OperatorReview.from_candidate_refresh_artifact(artifact)
    end
  end

  defp timeline_preservation_replay_action_routing(rows) do
    rows
    |> Enum.group_by(&Map.get(&1, "required_operator_action"))
    |> Map.delete(nil)
    |> Map.delete("none")
    |> Enum.map(fn {action, action_rows} ->
      route =
        %{
          "review_count" => length(action_rows),
          "activity_ids" => timeline_preservation_replay_ids(action_rows, "activity_id"),
          "timeline_ids" => timeline_preservation_replay_ids(action_rows, "timeline_id"),
          "timeline_preservation_statuses" =>
            action_rows
            |> Enum.map(&Map.get(&1, "timeline_preservation_status"))
            |> sorted_string_values(),
          "protection_decisions" =>
            action_rows
            |> Enum.map(&Map.get(&1, "timeline_preservation_protection_decision"))
            |> sorted_string_values(),
          "protection_categories" =>
            action_rows
            |> Enum.map(&Map.get(&1, "timeline_preservation_protection_category"))
            |> sorted_string_values()
        }
        |> compact_map()

      {action, route}
    end)
    |> Map.new()
    |> non_empty_map()
  end

  defp timeline_preservation_replay_row_source_contract(%{} = row) do
    source = Map.get(row, "source")
    source_state = Map.get(row, "source_timeline_preservation", %{})

    cond do
      is_binary(Map.get(source_state, "schema_contract")) ->
        Map.get(source_state, "schema_contract")

      is_binary(source) and String.ends_with?(source, ".status") ->
        "timeline_preservation_status.v1"

      is_binary(source) and String.ends_with?(source, ".rows") ->
        "timeline_preservation_report.v1"

      true ->
        nil
    end
  end

  defp timeline_preservation_replay_row_source_model(%{} = row) do
    source = Map.get(row, "source")
    source_state = Map.get(row, "source_timeline_preservation", %{})

    cond do
      is_binary(Map.get(source_state, "model")) ->
        Map.get(source_state, "model")

      timeline_preservation_replay_row_source_contract(row) == "timeline_preservation_status.v1" ->
        "artifact_only_lifecycle_preservation_status"

      is_binary(source) and String.ends_with?(source, ".rows") ->
        "artifact_only_lifecycle_preservation_summary"

      true ->
        nil
    end
  end

  defp timeline_preservation_replay_ids(rows, field) do
    rows
    |> Enum.flat_map(&timeline_preservation_replay_row_ids(&1, field))
    |> sorted_string_values()
  end

  defp timeline_preservation_replay_row_ids(%{} = row, "activity_id") do
    [
      row["activity_id"],
      get_in(row, ["source_timeline_preservation", "activity_id"])
    ]
  end

  defp timeline_preservation_replay_row_ids(%{} = row, "timeline_id") do
    [
      row["timeline_id"],
      row["subject_id"],
      get_in(row, ["source_timeline_preservation", "timeline_id"])
    ]
  end

  @doc """
   Builds a compact branch-local timeline-diff replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not replay refresh generation, mutate
  timelines, select candidates, approve imports, or write to Cadence.
  """
  def timeline_diff_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    branch_diff_summary =
      source_report_summary_branch_family(refresh_or_artifact, "timeline_diff_report")

    diff_summary =
      branch_diff_summary ||
        get_in(source_summary, ["source_reports", "timeline_diff_report"]) || %{}

    {summary_source, replay_scope} =
      if branch_diff_summary do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.timeline_diff_report",
          "timeline_diff_candidate_source_report_summary_only"
        }
      else
        {
          "candidate_refresh.source_report_provenance.timeline_diff_report",
          "timeline_diff_source_report_provenance_only"
        }
      end

    duplicate_count = summary_integer(diff_summary, "duplicate_timeline_identity_count")

    duplicate_source_count =
      summary_integer(diff_summary, "duplicate_source_timeline_identity_count")

    duplicate_replacement_count =
      summary_integer(diff_summary, "duplicate_replacement_timeline_identity_count")

    removed_downlink_count = summary_integer(diff_summary, "removed_downlink_count")
    removed_observation_count = summary_integer(diff_summary, "removed_observation_count")

    changed_downlink_shortfall_count =
      summary_integer(diff_summary, "changed_downlink_shortfall_count")

    changed_contact_feedback_count =
      summary_integer(diff_summary, "changed_contact_feedback_count")

    changed_observation_count = summary_integer(diff_summary, "changed_observation_count")

    changed_observation_quality_feedback_count =
      summary_integer(diff_summary, "changed_observation_quality_feedback_count")

    changed_command_feedback_count =
      summary_integer(diff_summary, "changed_command_feedback_count")

    changed_maneuver_feedback_count =
      summary_integer(diff_summary, "changed_maneuver_feedback_count")

    status_counts = Map.get(diff_summary, "diff_status_counts", %{})
    required_action_counts = Map.get(diff_summary, "required_operator_action_counts", %{})

    duplicate_scope_counts =
      Map.get(diff_summary, "duplicate_timeline_identity_scope_counts", %{})

    source_activity_id_counts = Map.get(diff_summary, "source_activity_id_counts", %{})
    replacement_activity_id_counts = Map.get(diff_summary, "replacement_activity_id_counts", %{})

    removed_count = removed_downlink_count + removed_observation_count

    changed_feedback_count =
      changed_downlink_shortfall_count + changed_contact_feedback_count +
        changed_observation_count + changed_observation_quality_feedback_count +
        changed_command_feedback_count + changed_maneuver_feedback_count

    duplicate_identity_pressure =
      duplicate_count + duplicate_source_count + duplicate_replacement_count > 0 or
        map_size(duplicate_scope_counts) > 0

    %{
      "model" => "artifact_only_candidate_refresh_timeline_diff_replay_summary",
      "source" => summary_source,
      "contract" => source_report_summary_contract(diff_summary, "timeline_diff_report.v1"),
      "source_report_count" => summary_integer(diff_summary, "count"),
      "source_report_row_count" => summary_integer(diff_summary, "row_count"),
      "source_report_paths" => Map.get(diff_summary, "paths", []),
      "duplicate_timeline_identity_count" => duplicate_count,
      "duplicate_source_timeline_identity_count" => duplicate_source_count,
      "duplicate_replacement_timeline_identity_count" => duplicate_replacement_count,
      "removed_downlink_count" => removed_downlink_count,
      "removed_observation_count" => removed_observation_count,
      "changed_downlink_shortfall_count" => changed_downlink_shortfall_count,
      "changed_contact_feedback_count" => changed_contact_feedback_count,
      "changed_observation_count" => changed_observation_count,
      "changed_observation_quality_feedback_count" => changed_observation_quality_feedback_count,
      "changed_command_feedback_count" => changed_command_feedback_count,
      "changed_maneuver_feedback_count" => changed_maneuver_feedback_count,
      "diff_status_counts" => status_counts,
      "required_operator_action_counts" => required_action_counts,
      "duplicate_timeline_identity_scope_counts" => duplicate_scope_counts,
      "source_activity_id_counts" => source_activity_id_counts,
      "replacement_activity_id_counts" => replacement_activity_id_counts,
      "trust_boundary_status" => Map.get(diff_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(diff_summary, "trust_boundaries", []),
      "branch_local_timeline_diff_pressure" =>
        duplicate_identity_pressure or removed_count + changed_feedback_count > 0 or
          map_size(status_counts) > 0 or map_size(required_action_counts) > 0 or
          map_size(source_activity_id_counts) > 0 or map_size(replacement_activity_id_counts) > 0,
      "branch_local_duplicate_identity_pressure" => duplicate_identity_pressure,
      "branch_local_removed_activity_pressure" => removed_count > 0,
      "branch_local_changed_activity_pressure" => changed_feedback_count > 0,
      "branch_local_activity_routing_pressure" =>
        map_size(source_activity_id_counts) > 0 or map_size(replacement_activity_id_counts) > 0,
      "branch_local_operator_review_pressure" => map_size(required_action_counts) > 0,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => "not_granted_by_timeline_diff_replay_summary",
        "timeline_mutation" => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_timeline_diff_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local timeline-integrity replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not replay refresh generation, mutate
  timelines, select candidates, approve imports, or write to Cadence.
  """
  def timeline_integrity_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    branch_integrity_summary =
      source_report_summary_branch_family(refresh_or_artifact, "timeline_integrity_report")

    integrity_summary =
      branch_integrity_summary ||
        get_in(source_summary, ["source_reports", "timeline_integrity_report"]) || %{}

    {summary_source, replay_scope} =
      if branch_integrity_summary do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.timeline_integrity_report",
          "timeline_integrity_candidate_source_report_summary_only"
        }
      else
        {
          "candidate_refresh.source_report_provenance.timeline_integrity_report",
          "timeline_integrity_source_report_provenance_only"
        }
      end

    issue_count = summary_integer(integrity_summary, "timeline_integrity_issue_count")
    review_count = summary_integer(integrity_summary, "timeline_integrity_review_count")
    dependency_issue_count = summary_integer(integrity_summary, "dependency_issue_count")
    exclusivity_issue_count = summary_integer(integrity_summary, "exclusivity_issue_count")

    status_counts = Map.get(integrity_summary, "timeline_integrity_status_counts", %{})
    issue_type_counts = Map.get(integrity_summary, "timeline_integrity_issue_type_counts", %{})
    required_action_counts = Map.get(integrity_summary, "required_operator_action_counts", %{})

    operator_action_reason_counts =
      Map.get(integrity_summary, "operator_action_reason_counts", %{})

    review_activity_id_counts = Map.get(integrity_summary, "review_activity_id_counts", %{})
    review_timeline_id_counts = Map.get(integrity_summary, "review_timeline_id_counts", %{})

    missing_dependency_activity_id_counts =
      Map.get(integrity_summary, "missing_dependency_activity_id_counts", %{})

    missing_dependency_timeline_id_counts =
      Map.get(integrity_summary, "missing_dependency_timeline_id_counts", %{})

    self_dependency_activity_id_counts =
      Map.get(integrity_summary, "self_dependency_activity_id_counts", %{})

    self_dependency_timeline_id_counts =
      Map.get(integrity_summary, "self_dependency_timeline_id_counts", %{})

    dependency_cycle_activity_id_counts =
      Map.get(integrity_summary, "dependency_cycle_activity_id_counts", %{})

    dependency_cycle_timeline_id_counts =
      Map.get(integrity_summary, "dependency_cycle_timeline_id_counts", %{})

    dependency_order_violation_activity_id_counts =
      Map.get(integrity_summary, "dependency_order_violation_activity_id_counts", %{})

    dependency_order_violation_timeline_id_counts =
      Map.get(integrity_summary, "dependency_order_violation_timeline_id_counts", %{})

    exclusivity_violation_activity_id_counts =
      Map.get(integrity_summary, "exclusivity_violation_activity_id_counts", %{})

    exclusivity_violation_timeline_id_counts =
      Map.get(integrity_summary, "exclusivity_violation_timeline_id_counts", %{})

    exclusivity_violation_group_counts =
      Map.get(integrity_summary, "exclusivity_violation_group_counts", %{})

    dependency_routing_pressure =
      dependency_issue_count > 0 or map_size(missing_dependency_activity_id_counts) > 0 or
        map_size(missing_dependency_timeline_id_counts) > 0 or
        map_size(self_dependency_activity_id_counts) > 0 or
        map_size(self_dependency_timeline_id_counts) > 0 or
        map_size(dependency_cycle_activity_id_counts) > 0 or
        map_size(dependency_cycle_timeline_id_counts) > 0 or
        map_size(dependency_order_violation_activity_id_counts) > 0 or
        map_size(dependency_order_violation_timeline_id_counts) > 0

    exclusivity_routing_pressure =
      exclusivity_issue_count > 0 or map_size(exclusivity_violation_activity_id_counts) > 0 or
        map_size(exclusivity_violation_timeline_id_counts) > 0 or
        map_size(exclusivity_violation_group_counts) > 0

    review_routing_pressure =
      review_count > 0 or map_size(required_action_counts) > 0 or
        map_size(review_activity_id_counts) > 0 or map_size(review_timeline_id_counts) > 0

    %{
      "model" => "artifact_only_candidate_refresh_timeline_integrity_replay_summary",
      "source" => summary_source,
      "contract" =>
        source_report_summary_contract(integrity_summary, "timeline_integrity_report.v1"),
      "source_report_count" => summary_integer(integrity_summary, "count"),
      "source_report_row_count" => summary_integer(integrity_summary, "row_count"),
      "source_report_paths" => Map.get(integrity_summary, "paths", []),
      "timeline_integrity_issue_count" => issue_count,
      "timeline_integrity_review_count" => review_count,
      "dependency_issue_count" => dependency_issue_count,
      "exclusivity_issue_count" => exclusivity_issue_count,
      "timeline_integrity_status_counts" => status_counts,
      "timeline_integrity_issue_type_counts" => issue_type_counts,
      "required_operator_action_counts" => required_action_counts,
      "operator_action_reason_counts" => operator_action_reason_counts,
      "review_activity_id_counts" => review_activity_id_counts,
      "review_timeline_id_counts" => review_timeline_id_counts,
      "missing_dependency_activity_id_counts" => missing_dependency_activity_id_counts,
      "missing_dependency_timeline_id_counts" => missing_dependency_timeline_id_counts,
      "self_dependency_activity_id_counts" => self_dependency_activity_id_counts,
      "self_dependency_timeline_id_counts" => self_dependency_timeline_id_counts,
      "dependency_cycle_activity_id_counts" => dependency_cycle_activity_id_counts,
      "dependency_cycle_timeline_id_counts" => dependency_cycle_timeline_id_counts,
      "dependency_order_violation_activity_id_counts" =>
        dependency_order_violation_activity_id_counts,
      "dependency_order_violation_timeline_id_counts" =>
        dependency_order_violation_timeline_id_counts,
      "exclusivity_violation_activity_id_counts" => exclusivity_violation_activity_id_counts,
      "exclusivity_violation_timeline_id_counts" => exclusivity_violation_timeline_id_counts,
      "exclusivity_violation_group_counts" => exclusivity_violation_group_counts,
      "trust_boundary_status" => Map.get(integrity_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(integrity_summary, "trust_boundaries", []),
      "branch_local_timeline_integrity_pressure" =>
        issue_count > 0 or map_size(status_counts) > 0 or map_size(issue_type_counts) > 0 or
          review_routing_pressure or dependency_routing_pressure or exclusivity_routing_pressure,
      "branch_local_timeline_integrity_review_pressure" => review_routing_pressure,
      "branch_local_dependency_integrity_pressure" => dependency_routing_pressure,
      "branch_local_exclusivity_integrity_pressure" => exclusivity_routing_pressure,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => "not_granted_by_timeline_integrity_replay_summary",
        "timeline_mutation" => "not_performed_by_summary",
