  @doc """
  Builds a compact branch-local timeline lifecycle-state replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not apply lifecycle transitions, mutate
  timelines, select candidates, approve imports, write to Cadence, or regenerate
  candidates.
  """
  def timeline_lifecycle_state_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    branch_lifecycle_summary =
      source_report_summary_branch_family(
        refresh_or_artifact,
        "timeline_lifecycle_state_summary"
      )

    lifecycle_summary =
      branch_lifecycle_summary ||
        get_in(source_summary, ["source_reports", "timeline_lifecycle_state_summary"]) || %{}

    {summary_source, replay_scope} =
      if branch_lifecycle_summary do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.timeline_lifecycle_state_summary",
          "timeline_lifecycle_state_candidate_source_report_summary_only"
        }
      else
        {
          "candidate_refresh.source_report_provenance.timeline_lifecycle_state_summary",
          "timeline_lifecycle_state_source_report_provenance_only"
        }
      end

    row_count = summary_integer(lifecycle_summary, "row_count")
    planned_activity_count = summary_integer(lifecycle_summary, "planned_activity_count")
    realized_activity_count = summary_integer(lifecycle_summary, "realized_activity_count")
    recordable_count = summary_integer(lifecycle_summary, "recordable_count")
    preserved_count = summary_integer(lifecycle_summary, "preserved_count")
    review_required_count = summary_integer(lifecycle_summary, "review_required_count")

    duplicate_timeline_identity_count =
      summary_integer(lifecycle_summary, "duplicate_timeline_identity_count")

    invalid_activity_input_count =
      summary_integer(lifecycle_summary, "invalid_activity_input_count")

    transition_decision_counts = Map.get(lifecycle_summary, "transition_decision_counts", %{})
    required_action_counts = Map.get(lifecycle_summary, "required_operator_action_counts", %{})
    import_action_counts = Map.get(lifecycle_summary, "import_action_counts", %{})
    planned_status_counts = Map.get(lifecycle_summary, "planned_status_category_counts", %{})
    realized_status_counts = Map.get(lifecycle_summary, "realized_status_category_counts", %{})
    planned_approval_counts = Map.get(lifecycle_summary, "planned_approval_category_counts", %{})

    realized_approval_counts =
      Map.get(lifecycle_summary, "realized_approval_category_counts", %{})

    status_transition_counts =
      Map.get(lifecycle_summary, "status_transition_category_counts", %{})

    approval_transition_counts =
      Map.get(lifecycle_summary, "approval_transition_category_counts", %{})

    transition_application_provenance_count =
      summary_integer(lifecycle_summary, "transition_application_provenance_count")

    transition_application_provenance_helper_counts =
      Map.get(lifecycle_summary, "transition_application_provenance_helper_counts", %{})

    transition_application_provenance_category_counts =
      Map.get(lifecycle_summary, "transition_application_provenance_category_counts", %{})

    transition_application_provenance_operator_action_reason_counts =
      Map.get(
        lifecycle_summary,
        "transition_application_provenance_operator_action_reason_counts",
        %{}
      )

    recordable_timeline_ids = Map.get(lifecycle_summary, "recordable_timeline_ids", [])
    preserved_timeline_ids = Map.get(lifecycle_summary, "preserved_timeline_ids", [])
    review_timeline_ids = Map.get(lifecycle_summary, "review_timeline_ids", [])
    review_activity_ids = Map.get(lifecycle_summary, "review_activity_ids", [])
    invalid_activity_input_ids = Map.get(lifecycle_summary, "invalid_activity_input_ids", [])

    review_timeline_ids_by_action =
      Map.get(lifecycle_summary, "review_timeline_ids_by_required_operator_action", %{})

    review_timeline_ids_by_status_transition =
      Map.get(lifecycle_summary, "review_timeline_ids_by_status_transition_category", %{})

    review_timeline_ids_by_approval_transition =
      Map.get(lifecycle_summary, "review_timeline_ids_by_approval_transition_category", %{})

    review_routing =
      lifecycle_summary
      |> Map.get("review_routing", %{})
      |> empty_map_if_nil()

    source_summary_model_counts =
      Map.get(lifecycle_summary, "source_summary_model_counts", %{}) |> non_empty_map()

    source_summary_schema_contract_counts =
      Map.get(lifecycle_summary, "source_summary_schema_contract_counts", %{})
      |> non_empty_map()

    lifecycle_evidence_pressure =
      row_count + planned_activity_count + realized_activity_count > 0 or
        map_size(transition_decision_counts) > 0 or map_size(planned_status_counts) > 0 or
        map_size(realized_status_counts) > 0 or map_size(planned_approval_counts) > 0 or
        map_size(realized_approval_counts) > 0 or
        transition_application_provenance_count > 0 or
        map_size(transition_application_provenance_helper_counts) > 0 or
        map_size(transition_application_provenance_category_counts) > 0 or
        map_size(transition_application_provenance_operator_action_reason_counts) > 0

    review_pressure =
      review_required_count + duplicate_timeline_identity_count + invalid_activity_input_count >
        0 or
        required_action_counts |> Map.delete("none") |> map_size() > 0 or
        review_timeline_ids != [] or review_activity_ids != [] or invalid_activity_input_ids != [] or
        map_size(review_timeline_ids_by_action) > 0 or
        map_size(review_timeline_ids_by_status_transition) > 0 or
        map_size(review_timeline_ids_by_approval_transition) > 0 or
        map_size(review_routing) > 0

    recordable_pressure =
      recordable_count > 0 or recordable_timeline_ids != [] or
        summary_integer(transition_decision_counts, "record") > 0

    preservation_pressure =
      preserved_count > 0 or preserved_timeline_ids != [] or
        summary_integer(transition_decision_counts, "none") > 0

    %{
      "model" => "artifact_only_candidate_refresh_timeline_lifecycle_state_replay_summary",
      "source" => summary_source,
      "contract" =>
        source_report_summary_contract(
          lifecycle_summary,
          "timeline_lifecycle_state_summary.v1"
        ),
      "source_report_count" => summary_integer(lifecycle_summary, "count"),
      "source_report_row_count" => row_count,
      "source_report_paths" => Map.get(lifecycle_summary, "paths", []),
      "source_summary_model_counts" => source_summary_model_counts,
      "source_summary_schema_contract_counts" => source_summary_schema_contract_counts,
      "planned_activity_count" => planned_activity_count,
      "realized_activity_count" => realized_activity_count,
      "recordable_count" => recordable_count,
      "preserved_count" => preserved_count,
      "review_required_count" => review_required_count,
      "duplicate_timeline_identity_count" => duplicate_timeline_identity_count,
      "invalid_activity_input_count" => invalid_activity_input_count,
      "invalid_activity_input_ids" => invalid_activity_input_ids,
      "transition_decision_counts" => transition_decision_counts,
      "required_operator_action_counts" => required_action_counts,
      "import_action_counts" => import_action_counts,
      "planned_status_category_counts" => planned_status_counts,
      "realized_status_category_counts" => realized_status_counts,
      "planned_approval_category_counts" => planned_approval_counts,
      "realized_approval_category_counts" => realized_approval_counts,
      "status_transition_category_counts" => status_transition_counts,
      "approval_transition_category_counts" => approval_transition_counts,
      "transition_application_provenance_count" => transition_application_provenance_count,
      "transition_application_provenance_helper_counts" =>
        transition_application_provenance_helper_counts,
      "transition_application_provenance_category_counts" =>
        transition_application_provenance_category_counts,
      "transition_application_provenance_operator_action_reason_counts" =>
        transition_application_provenance_operator_action_reason_counts,
      "recordable_timeline_ids" => recordable_timeline_ids,
      "preserved_timeline_ids" => preserved_timeline_ids,
      "review_timeline_ids" => review_timeline_ids,
      "review_activity_ids" => review_activity_ids,
      "review_timeline_ids_by_required_operator_action" => review_timeline_ids_by_action,
      "review_timeline_ids_by_status_transition_category" =>
        review_timeline_ids_by_status_transition,
      "review_timeline_ids_by_approval_transition_category" =>
        review_timeline_ids_by_approval_transition,
      "review_routing" => review_routing,
      "trust_boundary_status" => Map.get(lifecycle_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(lifecycle_summary, "trust_boundaries", []),
      "branch_local_timeline_lifecycle_state_pressure" =>
        lifecycle_evidence_pressure or review_pressure or recordable_pressure or
          preservation_pressure,
      "branch_local_lifecycle_review_pressure" => review_pressure,
      "branch_local_lifecycle_recordable_pressure" => recordable_pressure,
      "branch_local_lifecycle_preservation_pressure" => preservation_pressure,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => "not_granted_by_timeline_lifecycle_state_replay_summary",
        "timeline_lifecycle_application" => "not_performed_by_summary",
        "timeline_mutation" => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_timeline_lifecycle_state_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

