  @doc """
  Builds a compact branch-local timeline-transition-application replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not replay refresh generation, apply
  timeline transitions, select candidates, approve imports, or write to Cadence.
  """
  def timeline_transition_application_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    branch_transition_summary =
      source_report_summary_branch_family(
        refresh_or_artifact,
        "timeline_transition_application_report"
      )

    transition_summary =
      branch_transition_summary ||
        get_in(source_summary, ["source_reports", "timeline_transition_application_report"]) ||
        %{}

    {summary_source, replay_scope} =
      if branch_transition_summary do
        {
          "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.timeline_transition_application_report",
          "timeline_transition_application_candidate_source_report_summary_only"
        }
      else
        {
          "candidate_refresh.source_report_provenance.timeline_transition_application_report",
          "timeline_transition_application_source_report_provenance_only"
        }
      end

    application_count = summary_integer(transition_summary, "application_count")
    selected_activity_count = summary_integer(transition_summary, "selected_activity_count")
    review_required_count = summary_integer(transition_summary, "review_required_count")
    preserved_source_count = summary_integer(transition_summary, "preserved_source_count")
    recorded_replacement_count = summary_integer(transition_summary, "recorded_replacement_count")
    withheld_review_count = summary_integer(transition_summary, "withheld_review_count")

    duplicate_count =
      summary_integer(transition_summary, "duplicate_timeline_identity_count")

    duplicate_source_count =
      summary_integer(transition_summary, "duplicate_source_timeline_identity_count")

    duplicate_replacement_count =
      summary_integer(transition_summary, "duplicate_replacement_timeline_identity_count")

    application_status_counts = Map.get(transition_summary, "application_status_counts", %{})
    transition_decision_counts = Map.get(transition_summary, "transition_decision_counts", %{})
    selected_activity_id_counts = Map.get(transition_summary, "selected_activity_id_counts", %{})
    review_activity_id_counts = Map.get(transition_summary, "review_activity_id_counts", %{})

    required_action_counts =
      Map.get(transition_summary, "required_operator_action_counts", %{})

    duplicate_scope_counts =
      Map.get(transition_summary, "duplicate_timeline_identity_scope_counts", %{})

    review_action_count =
      required_action_counts
      |> Map.delete("none")
      |> map_size()

    selected_activity_pressure =
      selected_activity_count > 0 or map_size(selected_activity_id_counts) > 0

    review_required_pressure =
      review_required_count + withheld_review_count > 0 or review_action_count > 0 or
        map_size(review_activity_id_counts) > 0

    preserved_transition_pressure =
      preserved_source_count + recorded_replacement_count > 0

    duplicate_identity_pressure =
      duplicate_count + duplicate_source_count + duplicate_replacement_count > 0 or
        map_size(duplicate_scope_counts) > 0

    application_evidence_pressure =
      application_count > 0 or map_size(application_status_counts) > 0 or
        map_size(transition_decision_counts) > 0

    %{
      "model" => "artifact_only_candidate_refresh_timeline_transition_application_replay_summary",
      "source" => summary_source,
      "contract" =>
        source_report_summary_contract(
          transition_summary,
          "timeline_transition_application_report.v1"
        ),
      "source_report_count" => summary_integer(transition_summary, "count"),
      "source_report_row_count" =>
        timeline_transition_application_report_source_row_count(transition_summary),
      "source_application_count" => application_count,
      "source_report_paths" => Map.get(transition_summary, "paths", []),
      "selected_activity_count" => selected_activity_count,
      "selected_activity_id_counts" => selected_activity_id_counts,
      "review_activity_id_counts" => review_activity_id_counts,
      "review_required_count" => review_required_count,
      "preserved_source_count" => preserved_source_count,
      "recorded_replacement_count" => recorded_replacement_count,
      "withheld_review_count" => withheld_review_count,
      "duplicate_timeline_identity_count" => duplicate_count,
      "duplicate_source_timeline_identity_count" => duplicate_source_count,
      "duplicate_replacement_timeline_identity_count" => duplicate_replacement_count,
      "application_status_counts" => application_status_counts,
      "transition_decision_counts" => transition_decision_counts,
      "required_operator_action_counts" => required_action_counts,
      "duplicate_timeline_identity_scope_counts" => duplicate_scope_counts,
      "trust_boundary_status" => Map.get(transition_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(transition_summary, "trust_boundaries", []),
      "branch_local_timeline_transition_application_pressure" =>
        application_evidence_pressure or selected_activity_pressure or
          review_required_pressure or preserved_transition_pressure or duplicate_identity_pressure,
      "branch_local_selected_activity_pressure" => selected_activity_pressure,
      "branch_local_review_required_pressure" => review_required_pressure,
      "branch_local_preserved_transition_pressure" => preserved_transition_pressure,
      "branch_local_duplicate_identity_pressure" => duplicate_identity_pressure,
      "branch_local_operator_review_pressure" => review_action_count > 0,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => replay_scope,
        "operator_authority" => "not_granted_by_timeline_transition_application_replay_summary",
        "timeline_application" => "not_performed_by_summary",
        "timeline_mutation" => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_timeline_transition_application_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local objective-gap replay summary.

  The summary is derived from candidate-refresh source-report provenance. It
  does not replay refresh generation, create objectives, score candidates,
  select candidates, approve imports, or write to Cadence.
  """
  def objective_gap_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    satisfaction_summary =
      get_in(source_summary, ["source_reports", "objective_satisfaction_report"]) || %{}

    tradeoff_summary =
      get_in(source_summary, ["source_reports", "objective_tradeoff_report"]) || %{}

    score_term_summary =
      get_in(source_summary, ["source_reports", "score_term_report"]) || %{}

    satisfaction_gap_count = summary_integer(satisfaction_summary, "gap_row_count")
    satisfaction_downlink_count = summary_integer(satisfaction_summary, "downlink_gap_row_count")
    satisfaction_target_count = summary_integer(satisfaction_summary, "target_gap_row_count")

    satisfaction_collection_count =
      summary_integer(satisfaction_summary, "collection_latency_gap_row_count")

    tradeoff_downlink_count = summary_integer(tradeoff_summary, "downlink_gap_row_count")
    tradeoff_target_count = summary_integer(tradeoff_summary, "target_gap_row_count")

    tradeoff_collection_count =
      summary_integer(tradeoff_summary, "collection_latency_gap_row_count")

    score_downlink_count = summary_integer(score_term_summary, "downlink_gap_row_count")
    score_target_count = summary_integer(score_term_summary, "target_gap_row_count")

    score_collection_count =
      summary_integer(score_term_summary, "collection_latency_gap_row_count")

    downlink_gap_count =
      satisfaction_downlink_count + tradeoff_downlink_count + score_downlink_count

    target_gap_count = satisfaction_target_count + tradeoff_target_count + score_target_count

    collection_latency_gap_count =
      satisfaction_collection_count + tradeoff_collection_count + score_collection_count

    routed_gap_signal_count =
      satisfaction_gap_count + tradeoff_downlink_count + tradeoff_target_count +
        tradeoff_collection_count + score_downlink_count + score_target_count +
        score_collection_count

    status_counts = Map.get(satisfaction_summary, "status_counts", %{})
    objective_type_counts = Map.get(satisfaction_summary, "objective_type_counts", %{})
    term_key_counts = Map.get(score_term_summary, "term_key_counts", %{})

    ground_station_counts =
      [
        Map.get(satisfaction_summary, "ground_station_counts"),
        Map.get(tradeoff_summary, "ground_station_counts"),
        Map.get(score_term_summary, "ground_station_counts")
      ]
      |> merge_count_maps()
      |> then(&(&1 || %{}))

    target_counts =
      [
        Map.get(satisfaction_summary, "target_counts"),
        Map.get(tradeoff_summary, "target_counts"),
        Map.get(score_term_summary, "target_counts")
      ]
      |> merge_count_maps()
      |> then(&(&1 || %{}))

    collection_counts =
      [
        Map.get(satisfaction_summary, "collection_counts"),
        Map.get(tradeoff_summary, "collection_counts"),
        Map.get(score_term_summary, "collection_counts")
      ]
      |> merge_count_maps()
      |> then(&(&1 || %{}))

    source_activity_id_counts =
      [
        Map.get(satisfaction_summary, "source_activity_id_counts"),
        Map.get(tradeoff_summary, "source_activity_id_counts"),
        Map.get(score_term_summary, "source_activity_id_counts")
      ]
      |> merge_count_maps()
      |> then(&(&1 || %{}))

    trust_boundary_status_counts =
      [satisfaction_summary, tradeoff_summary, score_term_summary]
      |> Enum.map(&Map.get(&1, "trust_boundary_status"))
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.reduce(%{}, fn status, counts -> Map.update(counts, status, 1, &(&1 + 1)) end)
      |> non_empty_map()

    trust_boundaries =
      [satisfaction_summary, tradeoff_summary, score_term_summary]
      |> Enum.flat_map(&(Map.get(&1, "trust_boundaries") || []))
      |> normalize_trust_boundaries()

    source_report_paths =
      [satisfaction_summary, tradeoff_summary, score_term_summary]
      |> Enum.flat_map(&(Map.get(&1, "paths") || []))
      |> sorted_string_values()

    contracts =
      [
        objective_gap_summary_contract(
          satisfaction_summary,
          "objective_satisfaction_report.v1"
        ),
        objective_gap_summary_contract(tradeoff_summary, "objective_tradeoff_report.v1"),
        objective_gap_summary_contract(score_term_summary, "score_term_report.v1")
      ]
      |> Enum.reject(&is_nil/1)

    objective_status_pressure =
      map_size(status_counts) > 0 or map_size(objective_type_counts) > 0

    score_term_pressure = map_size(term_key_counts) > 0

    routing_pressure =
      map_size(ground_station_counts) > 0 or map_size(target_counts) > 0 or
        map_size(collection_counts) > 0 or map_size(source_activity_id_counts) > 0

    %{
      "model" => "artifact_only_candidate_refresh_objective_gap_replay_summary",
      "source" => "candidate_refresh.source_report_provenance.objective_gap_reports",
      "contracts" => contracts,
      "source_report_count" =>
        summary_integer(satisfaction_summary, "count") +
          summary_integer(tradeoff_summary, "count") +
          summary_integer(score_term_summary, "count"),
      "source_report_row_count" =>
        summary_integer(satisfaction_summary, "row_count") +
          summary_integer(tradeoff_summary, "row_count") +
          summary_integer(score_term_summary, "row_count"),
      "source_report_paths" => source_report_paths,
      "routed_gap_signal_count" => routed_gap_signal_count,
      "downlink_gap_row_count" => downlink_gap_count,
      "target_gap_row_count" => target_gap_count,
      "collection_latency_gap_row_count" => collection_latency_gap_count,
      "objective_satisfaction_gap_row_count" => satisfaction_gap_count,
      "objective_satisfaction_status_counts" => status_counts,
      "objective_satisfaction_objective_type_counts" => objective_type_counts,
      "objective_tradeoff_downlink_gap_row_count" => tradeoff_downlink_count,
      "objective_tradeoff_target_gap_row_count" => tradeoff_target_count,
      "objective_tradeoff_collection_latency_gap_row_count" => tradeoff_collection_count,
      "score_term_downlink_gap_row_count" => score_downlink_count,
      "score_term_target_gap_row_count" => score_target_count,
      "score_term_collection_latency_gap_row_count" => score_collection_count,
      "score_term_key_counts" => term_key_counts,
      "ground_station_counts" => ground_station_counts,
      "target_counts" => target_counts,
      "collection_counts" => collection_counts,
      "source_activity_id_counts" => source_activity_id_counts,
      "trust_boundary_status_counts" => trust_boundary_status_counts,
      "trust_boundaries" => trust_boundaries,
      "branch_local_objective_gap_pressure" =>
        routed_gap_signal_count > 0 or objective_status_pressure or score_term_pressure or
          routing_pressure,
      "branch_local_downlink_gap_pressure" => downlink_gap_count > 0,
      "branch_local_target_gap_pressure" => target_gap_count > 0,
      "branch_local_collection_latency_gap_pressure" => collection_latency_gap_count > 0,
      "branch_local_objective_status_pressure" => objective_status_pressure,
      "branch_local_score_term_pressure" => score_term_pressure,
      "branch_local_routing_pressure" => routing_pressure,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => "objective_gap_source_report_provenance_only",
        "operator_authority" => "not_granted_by_objective_gap_replay_summary",
        "objective_generation" => "not_performed_by_summary",
        "score_recalculation" => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_objective_gap_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  defp objective_gap_summary_contract(summary, default_contract),
    do: source_report_summary_contract(summary, default_contract)

  defp source_report_summary_contract(summary, default_contract) when map_size(summary) > 0 do
    case Map.get(summary, "contract", default_contract) do
      contract when is_binary(contract) and contract != "" -> contract
      _contract -> nil
    end
  end

  defp source_report_summary_contract(_summary, _default_contract), do: nil

  @doc """
  Builds a compact branch-local constraint replay summary.

  The summary is derived from candidate-refresh source-report provenance. It
  does not replay refresh generation, create objectives, mutate resource state,
  select candidates, approve imports, or write to Cadence.
  """
  def constraint_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)
    constraint_summary = get_in(source_summary, ["source_reports", "constraint_report"]) || %{}

    downlink_gap_count = summary_integer(constraint_summary, "downlink_gap_row_count")
    resource_margin_count = summary_integer(constraint_summary, "resource_margin_row_count")
    status_counts = Map.get(constraint_summary, "status_counts", %{})
    ground_station_counts = Map.get(constraint_summary, "ground_station_counts", %{})
    metric_counts = Map.get(constraint_summary, "constraint_metric_counts", %{})
    constraint_id_counts = Map.get(constraint_summary, "constraint_id_counts", %{})
    source_activity_id_counts = Map.get(constraint_summary, "source_activity_id_counts", %{})
    resource_counts = Map.get(constraint_summary, "constraint_resource_counts", %{})
    spacecraft_counts = Map.get(constraint_summary, "constraint_spacecraft_counts", %{})

    resource_margin_pressure =
      resource_margin_count > 0 or map_size(resource_counts) > 0 or
        map_size(spacecraft_counts) > 0

    constraint_routing_pressure =
      map_size(ground_station_counts) > 0 or map_size(metric_counts) > 0 or
        map_size(constraint_id_counts) > 0 or map_size(source_activity_id_counts) > 0 or
        map_size(resource_counts) > 0 or map_size(spacecraft_counts) > 0

    %{
      "model" => "artifact_only_candidate_refresh_constraint_replay_summary",
      "source" => "candidate_refresh.source_report_provenance.constraint_report",
      "contract" => source_report_summary_contract(constraint_summary, "constraint_report.v1"),
      "source_report_count" => summary_integer(constraint_summary, "count"),
      "source_report_row_count" => summary_integer(constraint_summary, "row_count"),
      "source_report_paths" => Map.get(constraint_summary, "paths", []),
      "downlink_gap_row_count" => downlink_gap_count,
      "resource_margin_row_count" => resource_margin_count,
      "status_counts" => status_counts,
      "ground_station_counts" => ground_station_counts,
      "constraint_metric_counts" => metric_counts,
      "constraint_id_counts" => constraint_id_counts,
      "source_activity_id_counts" => source_activity_id_counts,
      "constraint_resource_counts" => resource_counts,
      "constraint_spacecraft_counts" => spacecraft_counts,
      "trust_boundary_status" => Map.get(constraint_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(constraint_summary, "trust_boundaries", []),
      "branch_local_constraint_pressure" =>
        downlink_gap_count > 0 or map_size(status_counts) > 0 or resource_margin_pressure or
          constraint_routing_pressure,
      "branch_local_downlink_gap_pressure" => downlink_gap_count > 0,
      "branch_local_resource_margin_pressure" => resource_margin_pressure,
      "branch_local_constraint_routing_pressure" => constraint_routing_pressure,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => "constraint_source_report_provenance_only",
        "operator_authority" => "not_granted_by_constraint_replay_summary",
        "objective_generation" => "not_performed_by_summary",
        "resource_mutation" => "not_performed_by_summary",
        "candidate_selection" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_constraint_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local timeline-feedback replay summary.

  The summary is derived from candidate-refresh source-report summaries,
  preferring branch-local candidate-source summary metadata when present and
  falling back to provenance. It does not replay refresh generation, apply
