  @doc """
  Builds a compact branch-local validation-safety-case replay summary.

  The summary is derived from candidate-refresh source-report provenance. It
  does not replay refresh generation, mutate candidates, certify safety cases,
  approve imports, or write to Cadence.
  """
  def validation_safety_case_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    safety_case_summary =
      get_in(source_summary, ["source_reports", "validation_safety_case_summary"]) || %{}

    review_required_evidence_count =
      summary_integer(safety_case_summary, "review_required_evidence_count")

    blocked_evidence_count = summary_integer(safety_case_summary, "blocked_evidence_count")

    model_review_required_count =
      summary_integer(safety_case_summary, "model_review_required_count")

    model_blocked_count = summary_integer(safety_case_summary, "model_blocked_count")

    readiness_review_required_count =
      summary_integer(safety_case_summary, "readiness_review_required_count")

    readiness_blocked_count = summary_integer(safety_case_summary, "readiness_blocked_count")
    quality_gate_review_count = summary_integer(safety_case_summary, "quality_gate_review_count")

    quality_gate_blocked_count =
      summary_integer(safety_case_summary, "quality_gate_blocked_count")

    schema_error_count = summary_integer(safety_case_summary, "schema_error_count")
    schema_warning_count = summary_integer(safety_case_summary, "schema_warning_count")

    schema_validation_failed_report_count =
      summary_integer(safety_case_summary, "schema_validation_failed_report_count")

    fixture_failed_count = summary_integer(safety_case_summary, "fixture_failed_count")
    status_counts = Map.get(safety_case_summary, "status_counts", %{})
    evidence_status_counts = Map.get(safety_case_summary, "evidence_status_counts", %{})
    input_contract_counts = Map.get(safety_case_summary, "input_contract_counts", %{})
    evidence_refs_by_status = Map.get(safety_case_summary, "evidence_refs_by_status", %{})

    evidence_refs_by_contract =
      Map.get(safety_case_summary, "evidence_refs_by_contract", %{})

    contract_pressure = fn token ->
      input_contract_counts
      |> Enum.any?(fn
        {contract, count} when is_binary(contract) ->
          String.contains?(contract, token) and summary_integer(%{"count" => count}, "count") > 0

        _entry ->
          false
      end) or
        Enum.any?(evidence_refs_by_contract, fn
          {contract, refs} when is_binary(contract) and is_list(refs) ->
            String.contains?(contract, token) and refs != []

          _entry ->
            false
        end)
    end

    review_pressure_count =
      review_required_evidence_count + blocked_evidence_count + model_review_required_count +
        model_blocked_count + readiness_review_required_count + readiness_blocked_count +
        quality_gate_review_count + quality_gate_blocked_count + schema_error_count +
        schema_warning_count + schema_validation_failed_report_count + fixture_failed_count

    blocking_pressure =
      blocked_evidence_count + model_blocked_count + readiness_blocked_count +
        quality_gate_blocked_count > 0 or summary_integer(status_counts, "blocked") > 0 or
        summary_integer(evidence_status_counts, "blocked") > 0 or
        Map.get(evidence_refs_by_status, "blocked", []) != []

    schema_pressure =
      schema_error_count + schema_warning_count + schema_validation_failed_report_count > 0 or
        contract_pressure.("schema")

    fixture_pressure = fixture_failed_count > 0 or contract_pressure.("fixture")

    review_pressure =
      review_pressure_count > 0 or blocking_pressure or schema_pressure or fixture_pressure or
        summary_integer(status_counts, "review_required") > 0 or
        summary_integer(evidence_status_counts, "review_required") > 0 or
        Map.get(evidence_refs_by_status, "review_required", []) != []

    %{
      "model" => "artifact_only_candidate_refresh_validation_safety_case_replay_summary",
      "source" => "candidate_refresh.source_report_provenance.validation_safety_case_summary",
      "contract" =>
        source_report_summary_contract(
          safety_case_summary,
          "validation_safety_case_summary.v1"
        ),
      "source_report_count" => summary_integer(safety_case_summary, "count"),
      "source_report_row_count" => summary_integer(safety_case_summary, "row_count"),
      "source_report_paths" => Map.get(safety_case_summary, "paths", []),
      "status_counts" => status_counts,
      "evidence_status_counts" => evidence_status_counts,
      "input_contract_counts" => input_contract_counts,
      "evidence_refs_by_status" => evidence_refs_by_status,
      "evidence_refs_by_contract" => evidence_refs_by_contract,
      "accepted_evidence_count" =>
        summary_integer(safety_case_summary, "accepted_evidence_count"),
      "review_required_evidence_count" => review_required_evidence_count,
      "blocked_evidence_count" => blocked_evidence_count,
      "model_accepted_count" => summary_integer(safety_case_summary, "model_accepted_count"),
      "model_review_required_count" => model_review_required_count,
      "model_blocked_count" => model_blocked_count,
      "unknown_model_count" => summary_integer(safety_case_summary, "unknown_model_count"),
      "readiness_review_required_count" => readiness_review_required_count,
      "readiness_blocked_count" => readiness_blocked_count,
      "ready_for_import_count" => summary_integer(safety_case_summary, "ready_for_import_count"),
      "quality_gate_review_count" => quality_gate_review_count,
      "quality_gate_blocked_count" => quality_gate_blocked_count,
      "schema_error_count" => schema_error_count,
      "schema_warning_count" => schema_warning_count,
      "schema_validation_report_count" =>
        summary_integer(safety_case_summary, "schema_validation_report_count"),
      "schema_validation_failed_report_count" => schema_validation_failed_report_count,
      "fixture_passed_count" => summary_integer(safety_case_summary, "fixture_passed_count"),
      "fixture_failed_count" => fixture_failed_count,
      "trust_boundary_status" => Map.get(safety_case_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(safety_case_summary, "trust_boundaries", []),
      "branch_local_review_pressure" => review_pressure,
      "branch_local_blocking_pressure" => blocking_pressure,
      "branch_local_schema_pressure" => schema_pressure,
      "branch_local_fixture_pressure" => fixture_pressure,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => "validation_safety_case_source_report_provenance_only",
        "operator_authority" => "not_granted_by_validation_safety_case_replay_summary",
        "safety_case_certification" => "not_performed_by_summary",
        "model_certification" => "not_performed_by_summary",
        "import_approval" => "not_granted_by_validation_safety_case_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local freshness replay summary.

  The summary is derived from candidate-refresh source-report provenance. It
  does not replay refresh generation, mutate candidates, approve imports, or
  write to Cadence.
  """
  def freshness_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    freshness_summary =
      get_in(source_summary, ["source_reports", "freshness_report"]) || %{}

    status_counts = Map.get(freshness_summary, "status_counts", %{})
    stale_reason_count = summary_integer(freshness_summary, "stale_reason_count")
    unknown_reason_count = summary_integer(freshness_summary, "unknown_reason_count")
    stale_reasons = Map.get(freshness_summary, "stale_reasons", [])
    unknown_reasons = Map.get(freshness_summary, "unknown_reasons", [])
    stale_reason_counts = Map.get(freshness_summary, "stale_reason_counts", %{})
    unknown_reason_counts = Map.get(freshness_summary, "unknown_reason_counts", %{})

    stale_status_count = summary_integer(status_counts, "stale")
    unknown_status_count = summary_integer(status_counts, "unknown")

    stale_pressure =
      stale_status_count + stale_reason_count > 0 or stale_reasons != [] or
        map_size(stale_reason_counts) > 0

    unknown_pressure =
      unknown_status_count + unknown_reason_count > 0 or unknown_reasons != [] or
        map_size(unknown_reason_counts) > 0

    %{
      "model" => "artifact_only_candidate_refresh_freshness_replay_summary",
      "source" => "candidate_refresh.source_report_provenance.freshness_report",
      "contract" => source_report_summary_contract(freshness_summary, "freshness_report.v1"),
      "source_report_count" => summary_integer(freshness_summary, "count"),
      "source_report_row_count" => summary_integer(freshness_summary, "row_count"),
      "source_report_paths" => Map.get(freshness_summary, "paths", []),
      "status_counts" => status_counts,
      "stale_reason_count" => stale_reason_count,
      "stale_reasons" => stale_reasons,
      "stale_reason_counts" => stale_reason_counts,
      "unknown_reason_count" => unknown_reason_count,
      "unknown_reasons" => unknown_reasons,
      "unknown_reason_counts" => unknown_reason_counts,
      "trust_boundary_status" => Map.get(freshness_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(freshness_summary, "trust_boundaries", []),
      "branch_local_stale_pressure" => stale_pressure,
      "branch_local_unknown_pressure" => unknown_pressure,
      "branch_local_freshness_pressure" => stale_pressure or unknown_pressure,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => "freshness_source_report_provenance_only",
        "operator_authority" => "not_granted_by_freshness_replay_summary",
        "import_approval" => "not_granted_by_freshness_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local refresh-budget replay summary.

  The summary is derived from candidate-refresh source-report provenance. It
  does not replay refresh generation, mutate candidates, approve imports, or
  write to Cadence.
  """
  def refresh_budget_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    budget_summary =
      get_in(source_summary, ["source_reports", "refresh_budget_report"]) || %{}

    input_candidate_count = summary_integer(budget_summary, "input_candidate_count")
    kept_candidate_count = summary_integer(budget_summary, "kept_candidate_count")
    dropped_candidate_count = summary_integer(budget_summary, "dropped_candidate_count")

    invalid_candidate_limit_policy_count =
      summary_integer(budget_summary, "invalid_candidate_limit_policy_count")

    invalid_candidate_limit_policy_reason_counts =
      Map.get(budget_summary, "invalid_candidate_limit_policy_reason_counts", %{})

    kept_candidate_ids = Map.get(budget_summary, "kept_candidate_ids", [])
    dropped_candidate_ids = Map.get(budget_summary, "dropped_candidate_ids", [])

    dropped_candidate_pressure = dropped_candidate_count > 0 or dropped_candidate_ids != []

    invalid_limit_pressure =
      invalid_candidate_limit_policy_count > 0 or
        map_size(invalid_candidate_limit_policy_reason_counts) > 0

    candidate_limit_applied =
      dropped_candidate_pressure or
        (input_candidate_count > 0 and kept_candidate_count < input_candidate_count)

    budget_pressure =
      dropped_candidate_pressure or invalid_limit_pressure or candidate_limit_applied

    %{
      "model" => "artifact_only_candidate_refresh_refresh_budget_replay_summary",
      "source" => "candidate_refresh.source_report_provenance.refresh_budget_report",
      "contract" => source_report_summary_contract(budget_summary, "refresh_budget_report.v1"),
      "source_report_count" => summary_integer(budget_summary, "count"),
      "source_report_row_count" => summary_integer(budget_summary, "row_count"),
      "source_report_paths" => Map.get(budget_summary, "paths", []),
      "input_candidate_count" => input_candidate_count,
      "kept_candidate_count" => kept_candidate_count,
      "dropped_candidate_count" => dropped_candidate_count,
      "invalid_candidate_limit_policy_count" => invalid_candidate_limit_policy_count,
      "invalid_candidate_limit_policy_reason_counts" =>
        invalid_candidate_limit_policy_reason_counts,
      "kept_candidate_ids" => kept_candidate_ids,
      "dropped_candidate_ids" => dropped_candidate_ids,
      "trust_boundary_status" => Map.get(budget_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(budget_summary, "trust_boundaries", []),
      "branch_local_budget_pressure" => budget_pressure,
      "branch_local_dropped_candidate_pressure" => dropped_candidate_pressure,
      "branch_local_invalid_limit_pressure" => invalid_limit_pressure,
      "branch_local_candidate_limit_applied" => candidate_limit_applied,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => "refresh_budget_source_report_provenance_only",
        "operator_authority" => "not_granted_by_refresh_budget_replay_summary",
        "import_approval" => "not_granted_by_refresh_budget_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Builds a compact branch-local schema-validation replay summary.

  The summary is derived from candidate-refresh source-report provenance. It
  does not replay refresh generation, mutate candidates, approve imports, or
  write to Cadence.
  """
  def schema_validation_replay_summary(refresh_or_artifact) do
    source_summary = source_report_summary(refresh_or_artifact)

    validation_summary =
      get_in(source_summary, ["source_reports", "schema_validation_report"]) || %{}

    status_counts = Map.get(validation_summary, "status_counts", %{})
    validated_contract_counts = Map.get(validation_summary, "validated_contract_counts", %{})
    validation_mode_counts = Map.get(validation_summary, "validation_mode_counts", %{})
    remediation_action_counts = Map.get(validation_summary, "remediation_action_counts", %{})
    remediation_category_counts = Map.get(validation_summary, "remediation_category_counts", %{})
    remediation_path_counts = Map.get(validation_summary, "remediation_path_counts", %{})
    error_count = summary_integer(validation_summary, "error_count")
    warning_count = summary_integer(validation_summary, "warning_count")
    remediation_count = summary_integer(validation_summary, "remediation_count")
    failed_status_count = summary_integer(status_counts, "fail")
    error_status_count = summary_integer(status_counts, "error")
    warning_status_count = summary_integer(status_counts, "warning")

    remediation_map_pressure =
      map_size(remediation_action_counts) > 0 or map_size(remediation_category_counts) > 0 or
        map_size(remediation_path_counts) > 0

    schema_error_pressure = failed_status_count + error_status_count + error_count > 0
    schema_warning_pressure = warning_status_count + warning_count > 0
    remediation_pressure = remediation_count > 0 or remediation_map_pressure

    validation_map_pressure =
      map_size(status_counts) > 0 or map_size(validated_contract_counts) > 0 or
        map_size(validation_mode_counts) > 0

    validation_pressure =
      schema_error_pressure or schema_warning_pressure or remediation_pressure or
        validation_map_pressure

    %{
      "model" => "artifact_only_candidate_refresh_schema_validation_replay_summary",
      "source" => "candidate_refresh.source_report_provenance.schema_validation_report",
      "contract" =>
        source_report_summary_contract(validation_summary, "schema_validation_report.v1"),
      "source_report_count" => summary_integer(validation_summary, "count"),
      "source_report_row_count" => summary_integer(validation_summary, "row_count"),
      "source_report_paths" => Map.get(validation_summary, "paths", []),
      "status_counts" => status_counts,
      "validated_contract_counts" => validated_contract_counts,
      "validation_mode_counts" => validation_mode_counts,
      "error_count" => error_count,
      "warning_count" => warning_count,
      "remediation_count" => remediation_count,
      "remediation_action_counts" => remediation_action_counts,
      "remediation_category_counts" => remediation_category_counts,
      "remediation_path_counts" => remediation_path_counts,
      "trust_boundary_status" => Map.get(validation_summary, "trust_boundary_status"),
      "trust_boundaries" => Map.get(validation_summary, "trust_boundaries", []),
      "branch_local_validation_pressure" => validation_pressure,
      "branch_local_schema_error_pressure" => schema_error_pressure,
      "branch_local_schema_warning_pressure" => schema_warning_pressure,
      "branch_local_remediation_pressure" => remediation_pressure,
      "assumptions" => %{
        "execution_boundary" => "artifact_only_no_refresh_replay_mutation",
        "replay_scope" => "schema_validation_source_report_provenance_only",
        "operator_authority" => "not_granted_by_schema_validation_replay_summary",
        "import_approval" => "not_granted_by_schema_validation_replay_summary",
        "cadence_write" => "not_performed_by_summary",
        "candidate_generation" => "not_performed_by_summary"
      }
    }
    |> compact_map()
  end

  @doc """
  Returns the declared model limits for candidate-refresh artifacts and reports.
  """
  def model_limits do
    capabilities()
    |> Map.fetch!(:known_limits)
    |> Enum.map(&Atom.to_string/1)
  end

  defp refreshed_windows(event_results) do
    %{
      "access_windows" => access_windows(event_results),
      "target_visibility_windows" => target_visibility_windows(event_results),
      "eclipse_intervals" => eclipse_intervals(event_results)
    }
  end

  defp canonical_event_results(event_results) do
    event_results
    |> Enum.map(&canonical_event_result/1)
    |> Enum.sort_by(&event_result_sort_key/1)
  end

  defp canonical_event_result(%{events: events} = result) when is_list(events) do
    %{result | events: Enum.sort_by(events, &event_sort_key/1)}
  end

  defp canonical_event_result(result), do: result

  defp event_result_sort_key(result) do
    {
      encode_value(Map.get(result, :scenario_id)),
      encode_value(Map.get(result, :event_type)),
      map_sort_key(Map.get(result, :source, %{}))
    }
  end

  defp event_sort_key(event) when is_map(event) do
    metadata = Map.get(event, :metadata, %{})

    {
      event_epoch_seconds(Map.get(event, :starts_at)),
      event_epoch_seconds(Map.get(event, :ends_at)),
      encode_value(Map.get(event, :type)),
      map_sort_key(Map.take(metadata, [:ground_station_id, :target_id, :source_window_id]))
    }
  end

  defp event_sort_key(event), do: inspect(event)

  defp event_epoch_seconds(%{seconds_since_j2000: seconds}), do: seconds
  defp event_epoch_seconds(_epoch), do: nil

  defp map_sort_key(%{} = map) do
    map
    |> encode_value()
    |> Enum.sort_by(fn {key, value} -> {key, inspect(value)} end)
  end

  defp map_sort_key(value), do: encode_value(value)

  defp access_windows(event_results) do
    event_results
    |> Enum.filter(&(&1.event_type == :ground_station_access))
    |> Enum.flat_map(fn result ->
      result.events
      |> Enum.with_index(1)
      |> Enum.map(fn {event, index} ->
        source_id = encode_value(result.source.ground_station_id)

        %{
          "id" => window_id(result.scenario_id, "ground_station_access", source_id, index),
          "type" => "ground_station_access",
          "scenario_id" => encode_value(result.scenario_id),
          "ground_station_id" => source_id,
          "starts_at_s" => epoch_seconds(event.starts_at),
          "ends_at_s" => epoch_seconds(event.ends_at),
          "max_elevation_deg" => event.metadata.max_elevation_deg,
          "minimum_elevation_deg" => event.metadata.minimum_elevation_deg,
          "sample_count" => refreshed_window_sample_count(event),
          "assumptions" =>
            encode_value(
              Map.take(
                event.metadata,
                [
                  :geometry_model,
                  :interpolation,
                  :refraction,
                  :terrain_mask
                ] ++ @event_timing_keys
              )
            )
        }
      end)
    end)
  end

  defp target_visibility_windows(event_results) do
    event_results
    |> Enum.filter(&(&1.event_type == :target_visibility))
    |> Enum.flat_map(fn result ->
      result.events
      |> Enum.with_index(1)
      |> Enum.map(fn {event, index} ->
        source_id = encode_value(result.source.target_id)

        %{
          "id" => window_id(result.scenario_id, "target_visibility", source_id, index),
          "type" => "target_visibility",
          "scenario_id" => encode_value(result.scenario_id),
          "target_id" => source_id,
          "starts_at_s" => epoch_seconds(event.starts_at),
          "ends_at_s" => epoch_seconds(event.ends_at),
          "max_elevation_deg" => event.metadata.max_elevation_deg,
          "minimum_elevation_deg" => event.metadata.minimum_elevation_deg,
          "target_priority" => event.metadata.target_priority,
          "sample_count" => refreshed_window_sample_count(event),
          "assumptions" =>
            encode_value(
              Map.take(
                event.metadata,
                [
                  :geometry_model,
                  :interpolation,
                  :refraction,
                  :terrain_mask
                ] ++ @event_timing_keys
              )
            )
        }
      end)
    end)
  end

  defp refreshed_window_sample_count(event) do
    sample_count = normalized_sample_count(Map.get(event.metadata, :sample_count))
    max_sample_step_s = Map.get(event.metadata, :max_sample_step_s)
    starts_at_s = epoch_seconds(event.starts_at)
    ends_at_s = epoch_seconds(event.ends_at)

    if is_number(max_sample_step_s) and max_sample_step_s > 0 do
      required_count =
        ends_at_s
        |> Kernel.-(starts_at_s)
        |> max(0.0)
        |> Kernel./(max_sample_step_s)
        |> Float.ceil()
        |> trunc()

      max(sample_count || 0, required_count)
    else
      sample_count
    end
  end

  defp normalized_sample_count(value) when is_integer(value) and value >= 0, do: value

  defp normalized_sample_count(value) when is_number(value) and value >= 0 do
    value
    |> Float.ceil()
    |> trunc()
  end

  defp normalized_sample_count(_value), do: nil

  defp eclipse_intervals(event_results) do
    event_results
    |> Enum.filter(&(&1.event_type == :eclipse))
    |> Enum.flat_map(fn result ->
      result.events
      |> Enum.with_index(1)
      |> Enum.map(fn {event, index} ->
        %{
          "id" => window_id(result.scenario_id, "eclipse", "central_body_shadow", index),
          "type" => "eclipse",
          "scenario_id" => encode_value(result.scenario_id),
          "starts_at_s" => epoch_seconds(event.starts_at),
          "ends_at_s" => epoch_seconds(event.ends_at),
          "sample_count" => refreshed_window_sample_count(event),
          "sun_direction" => encode_value(Map.get(event.metadata, :sun_direction)),
          "minimum_shadow_axis_distance_km" =>
            Map.get(event.metadata, :minimum_shadow_axis_distance_km),
          "maximum_shadow_margin_km" => Map.get(event.metadata, :maximum_shadow_margin_km),
          "assumptions" =>
            encode_value(
              Map.take(
                event.metadata,
                [
                  :shadow_model,
                  :central_body,
                  :central_body_radius_km,
                  :interpolation
                ] ++ @event_timing_keys
              )
            )
        }
      end)
    end)
  end

  defp candidate_activities(event_results, refresh, constraints, policy) do
    eclipse_intervals_by_scenario = eclipse_intervals_by_scenario(event_results)
    min_duration_s = numeric_value(Map.get(constraints, "min_activity_duration_s")) || 0.0
    avoid_eclipse? = constraint_boolean(constraints, "avoid_eclipse", true)
    horizon = remaining_horizon(refresh)

    event_results
    |> Enum.flat_map(fn
      %{event_type: :target_visibility} = result ->
        eclipse_intervals =
          Map.get(eclipse_intervals_by_scenario, encode_value(result.scenario_id), [])

        result.events
        |> Enum.with_index(1)
        |> Enum.map(&observe_candidate(result, &1, refresh, eclipse_intervals, policy))
        |> Enum.reject(fn activity ->
          activity["duration_s"] < min_duration_s or
            not within_horizon?(activity, horizon) or
            (avoid_eclipse? and activity["eclipse_overlap_s"] > 0.0)
        end)

      %{event_type: :ground_station_access} = result ->
        result.events
        |> Enum.with_index(1)
        |> Enum.map(&downlink_candidate(result, &1, refresh, policy))
        |> Enum.reject(fn activity ->
          activity["duration_s"] < min_duration_s or not within_horizon?(activity, horizon)
        end)

      _result ->
        []
    end)
  end

  defp constraint_boolean(constraints, key, default) do
    case boolean_value(Map.get(constraints, key)) do
      value when is_boolean(value) -> value
      _value -> default
    end
  end

  defp observe_candidate(result, {event, index}, refresh, eclipse_intervals, policy) do
    starts_at_s = epoch_seconds(event.starts_at)
    ends_at_s = epoch_seconds(event.ends_at)
    target_id = event.metadata.target_id
    target = target_by_id(refresh, target_id)

    {target_priority, target_priority_context} =
      target_priority(
        refresh,
        result.scenario_id,
        target_id,
        target,
        event.metadata.target_priority || 1.0
      )

    {observation_success_score_factor, observation_success_factor, observation_success_source} =
      observation_success_factor(refresh, target_id, target)

    observation_quality_context = observation_quality_context(refresh, target_id, target)
    target_metadata_context = target_metadata_context(target)

    {observation_objective_context, observation_objective_score_terms} =
      observation_objective_context(refresh, result.scenario_id, target_id, policy)

    {collection_latency_context, collection_latency_score_terms} =
      collection_latency_observation_context(refresh, result.scenario_id, target_id, policy)

    priority = target_priority * observation_success_score_factor
    duration_s = ends_at_s - starts_at_s
    eclipse_overlap_s = overlap_duration({starts_at_s, ends_at_s}, eclipse_intervals)
    lighting_summary = Eclipses.lighting_summary(duration_s, eclipse_overlap_s)
    source_window_id = window_id(result.scenario_id, "target_visibility", target_id, index)
    id = activity_id(result.scenario_id, "observe", target_id, index)

    score_terms =
      %{
        "target_value" =>
          priority * duration_s * policy_number(policy, "target_value_weight", 1.0),
        "eclipse_penalty" =>
          eclipse_overlap_s * policy_number(policy, "eclipse_penalty_weight", 1.0) * -1.0
      }
      |> Map.merge(observation_objective_score_terms)
      |> Map.merge(collection_latency_score_terms)

    %{
      "id" => id,
      "type" => "observe",
      "scenario_id" => encode_value(result.scenario_id),
      "target_id" => encode_value(target_id),
      "starts_at_s" => starts_at_s,
      "ends_at_s" => ends_at_s,
      "duration_s" => duration_s,
      "score" => score(score_terms),
      "score_terms" => score_terms,
      "target_priority" => priority,
      "observation_success_factor" => observation_success_factor,
      "observation_success_factor_source" => observation_success_source,
      "eclipse_overlap_s" => eclipse_overlap_s,
      "source_window_id" => source_window_id,
      "source_window" =>
        %{
          "id" => source_window_id,
          "type" => "target_visibility",
          "max_elevation_deg" => event.metadata.max_elevation_deg,
          "minimum_elevation_deg" => event.metadata.minimum_elevation_deg
        }
        |> Map.merge(event_timing_metadata(event.metadata)),
      "cadence_import" => %{
        "activity_type" => "observation",
        "external_id" => id
      }
    }
    |> Map.merge(target_priority_context)
    |> Map.merge(target_metadata_context)
    |> Map.merge(observation_quality_context)
    |> Map.merge(observation_objective_context)
    |> Map.merge(collection_latency_context)
    |> Map.merge(lighting_summary)
    |> compact_map()
  end

  defp downlink_candidate(result, {event, index}, refresh, policy) do
    starts_at_s = epoch_seconds(event.starts_at)
    ends_at_s = epoch_seconds(event.ends_at)
    ground_station_id = result.source.ground_station_id
    duration_s = ends_at_s - starts_at_s
    downlink_rate_mb_s = Map.get(policy, "downlink_rate_mb_s", 1.0)
    station_state = station_state(refresh, ground_station_id, starts_at_s, ends_at_s, "downlink")
    declared_capacity_fraction = station_capacity_fraction(station_state)

    {station_throughput_factor, station_throughput_source} =
      station_throughput_factor(refresh, ground_station_id, station_state)

    capacity_fraction =
      (declared_capacity_fraction * station_throughput_factor)
      |> max(0.0)
      |> min(1.0)

    station_availability = station_availability(station_state)
    station_contention_status = station_contention_status(station_state)

    {contact_success_factor, contact_success_source} =
      contact_success_factor(refresh, ground_station_id)

    id = activity_id(result.scenario_id, "downlink", ground_station_id, index)

    source_window_id =
      window_id(result.scenario_id, "ground_station_access", ground_station_id, index)

    estimated_throughput_mb = duration_s * downlink_rate_mb_s * capacity_fraction

    {downlink_completion_context, downlink_completion_score_terms} =
      downlink_completion_context(
        refresh,
        result.scenario_id,
        ground_station_id,
        estimated_throughput_mb,
        policy
      )

    downlink_demand_context = downlink_demand_context(refresh, ground_station_id)

    base_contact_value =
      duration_s * policy_number(policy, "contact_value_weight", 0.1) * capacity_fraction

    score_terms =
      %{
        "contact_value" => base_contact_value,
        "contact_success_adjustment" => base_contact_value * (contact_success_factor - 1.0)
      }
      |> Map.merge(downlink_completion_score_terms)

    %{
      "id" => id,
      "type" => "downlink",
      "direction" => "downlink",
      "scenario_id" => encode_value(result.scenario_id),
      "ground_station_id" => encode_value(ground_station_id),
      "starts_at_s" => starts_at_s,
      "ends_at_s" => ends_at_s,
      "duration_s" => duration_s,
      "estimated_throughput_mb" => estimated_throughput_mb,
      "contact_success_factor" => contact_success_factor,
      "contact_success_factor_source" => contact_success_source,
      "throughput_model" =>
        %{
          "model" => "fixed_rate_from_candidate_refresh_policy",
          "downlink_rate_mb_s" => downlink_rate_mb_s,
          "station_capacity_fraction" => capacity_fraction,
          "declared_station_capacity_fraction" => declared_capacity_fraction,
          "station_throughput_factor" => station_throughput_factor,
          "station_throughput_factor_source" => station_throughput_source,
          "contact_success_factor" => contact_success_factor,
          "confidence_source" => contact_success_source
        }
        |> Map.merge(downlink_completion_context)
        |> compact_map(),
      "station_availability" => station_availability,
      "station_contention_status" => station_contention_status,
      "station_calendar_entry_id" => station_calendar_entry_id(station_state),
      "station_calendar_provider_id" => station_calendar_provider_id(station_state),
      "station_calendar_provider_entry_id" => station_calendar_provider_entry_id(station_state),
      "station_calendar_directions" => nonempty_station_directions(station_state),
      "station_calendar_status" => Map.get(station_state, "status"),
      "station_calendar_entry_ambiguous" =>
        Map.get(station_state, "station_calendar_entry_ambiguous"),
      "station_calendar_ambiguous_entry_count" =>
        Map.get(station_state, "station_calendar_ambiguous_entry_count"),
      "station_calendar_ambiguous_entry_ids" =>
        Map.get(station_state, "station_calendar_ambiguous_entry_ids"),
      "station_calendar_overlap_count" =>
        Map.get(station_state, "station_calendar_overlap_count"),
      "station_calendar_overlap_entry_ids" =>
        Map.get(station_state, "station_calendar_overlap_entry_ids"),
      "station_calendar_overlap_availabilities" =>
        Map.get(station_state, "station_calendar_overlap_availabilities"),
      "station_reservation_id" => Map.get(station_state, "reservation_id"),
      "station_reserved_by" => Map.get(station_state, "reserved_by"),
      "station_reservation_status" => Map.get(station_state, "reservation_status"),
      "station_reservation_expires_at_s" => station_reservation_expires_at_s(station_state),
      "station_reservation_match_status" => station_reservation_match_status(station_state),
      "station_calendar_reservation_overlap_count" =>
        Map.get(station_state, "station_calendar_reservation_overlap_count"),
      "station_calendar_reservation_ids" =>
        Map.get(station_state, "station_calendar_reservation_ids") ||
          station_provider_contention_values(station_state, "reservation_ids"),
      "station_calendar_reserved_by" =>
        Map.get(station_state, "station_calendar_reserved_by") ||
          station_provider_contention_values(station_state, "reserved_by"),
      "station_calendar_reservation_statuses" =>
        Map.get(station_state, "station_calendar_reservation_statuses") ||
          station_provider_contention_values(station_state, "reservation_statuses"),
      "station_calendar_reservation_expires_at_s" =>
        station_calendar_reservation_expires_at_s(station_state),
      "station_calendar_trust_boundary_status" =>
        Map.get(station_state, "station_calendar_trust_boundary_status"),
      "trust_boundary" => Map.get(station_state, "trust_boundary"),
      "provenance" => Map.get(station_state, "provenance"),
      "source_station_calendar_entry" => Map.get(station_state, "source_station_calendar_entry"),
      "source_station_calendar_overlaps" =>
        Map.get(station_state, "source_station_calendar_overlaps"),
      "schedule_conflict_status" => "not_evaluated",
      "score" => score(score_terms),
      "score_terms" => score_terms,
      "source_window_id" => source_window_id,
      "source_window" =>
        %{
          "id" => source_window_id,
          "type" => "ground_station_access",
          "max_elevation_deg" => event.metadata.max_elevation_deg,
          "minimum_elevation_deg" => event.metadata.minimum_elevation_deg
        }
        |> Map.merge(event_timing_metadata(event.metadata)),
      "cadence_import" => %{
        "activity_type" => "contact",
        "external_id" => id,
        "schema_contract" => "proposed_contact.v1"
      }
    }
    |> Map.merge(downlink_completion_context)
    |> Map.merge(downlink_demand_context)
    |> compact_map()
  end

  defp downlink_completion_context(
         refresh,
         scenario_id,
         ground_station_id,
         estimated_throughput_mb,
         policy
       ) do
    case required_downlink_mb(refresh, scenario_id, ground_station_id) do
      {required_downlink_mb, source, sources}
      when is_number(required_downlink_mb) and required_downlink_mb > 0.0 ->
        ratio = min(estimated_throughput_mb / required_downlink_mb, 1.0)
        shortfall_mb = max(required_downlink_mb - estimated_throughput_mb, 0.0)
        weight = policy_number(policy, "downlink_completion_weight", 50.0)

        objective_context =
          downlink_completion_objective_context(refresh, scenario_id, ground_station_id)

        {
          %{
            "required_downlink_mb" => required_downlink_mb,
            "candidate_downlink_mb" => estimated_throughput_mb,
            "downlink_completion_ratio" => ratio,
            "selected_downlink_shortfall_mb" => shortfall_mb,
            "downlink_requirement_status" =>
              if(shortfall_mb > 0.0, do: "shortfall", else: "satisfied"),
            "downlink_completion_source" => source,
            "downlink_completion_sources" => sources
          }
          |> Map.merge(objective_context)
          |> compact_map(),
          %{"downlink_completion_value" => ratio * weight}
        }

      _requirement ->
        {%{}, %{}}
    end
  end

  defp downlink_completion_objective_context(refresh, scenario_id, ground_station_id) do
    objectives =
      refresh
      |> downlink_completion_objectives()
      |> Enum.filter(
        &objective_matches_downlink_candidate?(&1, refresh, scenario_id, ground_station_id)
      )

    %{
      "downlink_completion_objective_count" => length(objectives),
      "source_capacity_adjusted_throughput_mb" =>
        sum_objective_numeric_values(objectives, "source_capacity_adjusted_throughput_mb"),
      "source_selected_capacity_adjusted_throughput_mb" =>
        sum_objective_numeric_values(
          objectives,
          "source_selected_capacity_adjusted_throughput_mb"
        ),
      "source_unused_capacity_adjusted_throughput_mb" =>
        sum_objective_numeric_values(objectives, "source_unused_capacity_adjusted_throughput_mb")
    }
    |> Enum.reject(fn
      {_key, 0} -> true
      {_key, nil} -> true
      _entry -> false
    end)
    |> Map.new()
  end

  defp sum_objective_numeric_values(objectives, field) do
    values =
      objectives
      |> Enum.map(&(Map.get(&1, field) |> numeric_value()))
      |> Enum.filter(&is_number/1)

    case values do
      [] -> nil
      values -> Enum.sum(values)
    end
  end

  defp downlink_demand_context(refresh, ground_station_id) do
    feedback = operational_feedback(refresh)
    station_id = encode_value(ground_station_id)

    feedback
    |> Map.get("downlink_demand_context", %{})
    |> case do
      %{} = contexts -> Map.get(contexts, station_id) || Map.get(contexts, "default")
      _contexts -> nil
    end
    |> case do
      %{} = context ->
        context
        |> stringify_keys()
        |> Map.take([
          "collection_id",
          "product_id",
          "product_ids",
          "payload_id",
          "instrument_id",
          "target_id",
          "source_activity_id",
          "source_activity_ids",
          "missed_downlink_activity_id",
          "missed_downlink_activity_ids",
          "objective_id",
          "objective_type",
          "latency_objective",
          "max_latency_s",
          "planned_latency_s",
          "feedback_source",
          "feedback_scope",
          "trust_boundary"
        ])
        |> compact_map()

      _context ->
        %{}
    end
  end

  defp required_downlink_mb(refresh, scenario_id, ground_station_id) do
    aggregate_required_downlink_mb([
      required_downlink_mb_from_feedback(refresh, ground_station_id),
      required_downlink_mb_from_objectives(refresh, scenario_id, ground_station_id)
    ]) ||
      requirement_with_sources(required_downlink_mb_from_policy(refresh))
  end

  defp aggregate_required_downlink_mb(requirements) do
    requirements =
      requirements
      |> Enum.map(&requirement_with_sources/1)
      |> Enum.filter(
        &match?({value, _source, _sources} when is_number(value) and value > 0.0, &1)
      )

    case requirements do
      [] ->
        nil

      [{required_downlink_mb, source, sources}] ->
        {required_downlink_mb, source, sources}

      requirements ->
        required_downlink_mb =
          requirements
          |> Enum.map(fn {value, _source, _sources} -> value end)
          |> Enum.sum()

        sources =
          requirements
          |> Enum.map(fn {_value, source, _sources} -> source end)
          |> Enum.map(&required_downlink_source_category/1)
          |> Enum.uniq()
          |> Enum.sort()

        exact_sources =
          requirements
          |> Enum.flat_map(fn {_value, _source, exact_sources} -> exact_sources end)
          |> Enum.uniq()
          |> Enum.sort()

        {required_downlink_mb,
         "candidate_refresh.downlink_demand." <> Enum.join(sources, "_and_"), exact_sources}
    end
  end

  defp requirement_with_sources({required_downlink_mb, source, sources})
       when is_list(sources) do
    {required_downlink_mb, source, sources}
  end

  defp requirement_with_sources({required_downlink_mb, source}) when is_binary(source) do
    {required_downlink_mb, source, [source]}
  end

  defp requirement_with_sources(_requirement), do: nil

  defp required_downlink_source_category("operational_feedback." <> _suffix),
    do: "operational_feedback"

  defp required_downlink_source_category("candidate_refresh.objectives." <> _suffix),
    do: "objectives"

  defp required_downlink_source_category("candidate_refresh.scoring_policy." <> _suffix),
    do: "scoring_policy"

  defp required_downlink_source_category(source), do: source

  defp required_downlink_mb_from_feedback(refresh, ground_station_id) do
    feedback = operational_feedback(refresh)
    demands = Map.get(feedback, "downlink_demand_mb")

    case demands do
      %{} ->
        station_id = encode_value(ground_station_id)

        cond do
          is_number(Map.get(demands, station_id)) ->
            {demands |> Map.get(station_id) |> max(0.0),
             "operational_feedback.downlink_demand_mb.station",
             feedback_downlink_demand_sources(
               feedback,
               station_id,
               "operational_feedback.downlink_demand_mb.station"
             )}

          is_number(Map.get(demands, "default")) ->
            {demands |> Map.get("default") |> max(0.0),
             "operational_feedback.downlink_demand_mb.default",
             feedback_downlink_demand_sources(
               feedback,
               "default",
               "operational_feedback.downlink_demand_mb.default"
             )}

          true ->
            nil
        end

      _demands ->
        nil
    end
  end

  defp feedback_downlink_demand_sources(feedback, key, fallback_source) do
    feedback
    |> Map.get("downlink_demand_sources", %{})
    |> case do
      %{} = source_map -> Map.get(source_map, key)
      _source_map -> nil
    end
    |> List.wrap()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> [fallback_source]
      sources -> sources
    end
  end

  defp required_downlink_mb_from_objectives(refresh, scenario_id, ground_station_id) do
    feedback_source_paths = downlink_demand_feedback_source_paths(refresh, ground_station_id)

    downlink_completion_mb =
      refresh
      |> downlink_completion_objectives()
      |> Enum.filter(fn objective ->
        objective_matches_downlink_candidate?(objective, refresh, scenario_id, ground_station_id) and
          not duplicate_downlink_demand_feedback_objective?(objective, feedback_source_paths)
      end)
      |> Enum.map(&objective_required_downlink_mb/1)
      |> Enum.filter(&(is_number(&1) and &1 > 0.0))
      |> Enum.sum()

    collection_latency_mb =
      refresh
      |> collection_latency_objectives()
      |> Enum.filter(fn objective ->
        objective_matches_downlink_candidate?(objective, refresh, scenario_id, ground_station_id) and
          not duplicate_downlink_demand_feedback_objective?(objective, feedback_source_paths)
      end)
      |> Enum.map(&objective_required_downlink_mb/1)
      |> Enum.filter(&(is_number(&1) and &1 > 0.0))
      |> Enum.sum()

    required_downlink_mb = downlink_completion_mb + collection_latency_mb

    cond do
      required_downlink_mb <= 0.0 ->
        nil

      downlink_completion_mb > 0.0 and collection_latency_mb > 0.0 ->
        {required_downlink_mb, "candidate_refresh.objectives.downlink_completion_and_latency",
         [
           "candidate_refresh.objectives.collection_latency",
           "candidate_refresh.objectives.downlink_completion"
         ]}

      collection_latency_mb > 0.0 ->
        {required_downlink_mb, "candidate_refresh.objectives.collection_latency"}

      true ->
        {required_downlink_mb, "candidate_refresh.objectives.downlink_completion"}
    end
  end

  defp downlink_demand_feedback_source_paths(refresh, ground_station_id) do
    refresh
    |> downlink_demand_context(ground_station_id)
    |> Map.take(["feedback_source", "source_path"])
    |> Map.values()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
  end

  defp duplicate_downlink_demand_feedback_objective?(_objective, []), do: false

  defp duplicate_downlink_demand_feedback_objective?(objective, source_paths) do
    objective
    |> Map.get("source_path")
    |> encode_value()
    |> then(&(&1 in source_paths))
  end

  defp required_downlink_mb_from_policy(%{"scoring_policy" => %{} = policy}) do
    case numeric_value(Map.get(policy, "required_downlink_mb")) do
      value when is_number(value) and value > 0.0 ->
        {value, "candidate_refresh.scoring_policy.required_downlink_mb"}

      _value ->
        nil
    end
  end

  defp required_downlink_mb_from_policy(_refresh), do: nil

  defp downlink_completion_objectives(refresh) do
    refresh
    |> refresh_objectives()
    |> Enum.filter(fn
      %{"type" => type} when type in ["downlink_completion", "required_downlink_completion"] ->
        true

      _objective ->
        false
    end)
  end

  defp collection_latency_objectives(refresh) do
    refresh
    |> refresh_objectives()
    |> Enum.filter(fn
      %{"type" => type}
      when type in [
             "collection_latency",
             "collection_downlink_latency",
             "data_latency",
             "downlink_latency"
           ] ->
        true

      _objective ->
        false
    end)
  end

  defp collection_latency_observation_context(refresh, scenario_id, target_id, policy) do
    objectives =
      refresh
      |> collection_latency_objectives()
      |> Enum.filter(
        &objective_matches_observation_candidate?(&1, refresh, scenario_id, target_id)
      )

    if objectives == [] do
      {%{}, %{}}
    else
      objective_ids =
        objectives
        |> Enum.map(&objective_id/1)
        |> Enum.reject(&is_nil/1)
        |> Enum.uniq()
        |> Enum.sort()

      objective_types =
        objectives
        |> Enum.map(&Map.get(&1, "type"))
        |> Enum.reject(&is_nil/1)
        |> Enum.uniq()
        |> Enum.sort()

      required_downlink_mb =
        objectives
        |> Enum.map(&objective_required_downlink_mb/1)
        |> Enum.filter(&(is_number(&1) and &1 > 0.0))
        |> Enum.sum()

      max_latency_s =
        objectives
        |> Enum.map(&collection_latency_limit_s/1)
        |> Enum.filter(&(is_number(&1) and &1 >= 0.0))
        |> Enum.min(fn -> nil end)

      weight = policy_number(policy, "collection_latency_observation_weight", 20.0)

      context =
        %{
          "collection_latency_objective_count" => length(objectives),
          "collection_latency_objective_ids" => objective_ids,
          "collection_latency_objective_types" => objective_types,
          "collection_latency_objective_source" =>
            "candidate_refresh.objectives.collection_latency",
          "collection_id" => collection_latency_identity_value(objectives, "collection_id"),
          "product_id" => collection_latency_identity_value(objectives, "product_id"),
          "product_ids" => collection_latency_product_ids(objectives),
          "payload_id" => collection_latency_identity_value(objectives, "payload_id"),
          "instrument_id" => collection_latency_identity_value(objectives, "instrument_id"),
          "max_latency_s" => max_latency_s,
          "required_downlink_mb" => if(required_downlink_mb > 0.0, do: required_downlink_mb)
        }
        |> compact_map()

      {context, %{"collection_latency_observation_value" => length(objectives) * weight}}
    end
  end

  defp refresh_objectives(refresh) do
    [
      Map.get(refresh, "objectives", []),
      get_in(refresh, ["mission_state", "objectives"]) || [],
      get_in(refresh, ["accepted_planning_state", "objectives"]) || [],
      source_timeline_diff_report_objectives(refresh),
      source_objective_satisfaction_report_objectives(refresh),
      source_objective_tradeoff_report_objectives(refresh),
      source_score_term_report_objectives(refresh),
      source_constraint_report_objectives(refresh),
      source_resource_projection_report_objectives(refresh),
      source_contact_contention_resolution_report_objectives(refresh),
      source_contact_allocation_report_objectives(refresh),
      source_link_capacity_report_objectives(refresh)
    ]
    |> List.flatten()
    |> Enum.map(&stringify_keys/1)
  end

  defp objective_matches_station?(objective, ground_station_id) do
    objective_station_id = objective_station_id(objective)

    objective_station_id in [nil, "", encode_value(ground_station_id)]
  end

  defp objective_station_id(objective) do
    Map.get(objective, "ground_station_id") || Map.get(objective, "station_id") ||
      nested_station_id(objective)
  end

  defp objective_matches_downlink_candidate?(objective, refresh, scenario_id, ground_station_id) do
    objective_matches_station?(objective, ground_station_id) and
      objective_matches_spacecraft?(objective, refresh, scenario_id)
  end

  defp objective_matches_spacecraft?(objective, refresh, scenario_id) do
    candidate_scenario_id = encode_value(scenario_id)
    candidate_spacecraft_id = refresh_spacecraft_id(refresh, candidate_scenario_id)
    objective_scenario_id = Map.get(objective, "scenario_id")

    objective_spacecraft_id = objective_spacecraft_id(objective)

    objective_scenario_id in [nil, "", candidate_scenario_id] and
      objective_spacecraft_id in [nil, "", candidate_spacecraft_id, candidate_scenario_id]
  end

  defp objective_spacecraft_id(objective) do
    spacecraft_identity_value(Map.get(objective, "spacecraft_id")) ||
      spacecraft_identity_value(Map.get(objective, "satellite_id")) ||
      spacecraft_identity_value(Map.get(objective, "spacecraft")) ||
      spacecraft_identity_value(Map.get(objective, "satellite"))
  end

  defp refresh_spacecraft_id(refresh, scenario_id) do
    refresh
    |> spacecraft_identity_by_scenario()
    |> Map.get(scenario_id)
  end

  defp refresh_spacecraft_states(refresh) do
    [
      get_in(refresh, ["mission_state", "spacecraft_states"]) || [],
      get_in(refresh, ["accepted_planning_state", "spacecraft_states"]) || []
    ]
    |> List.flatten()
    |> Enum.map(&stringify_keys/1)
  end

  defp spacecraft_identity_by_scenario(refresh) do
    refresh
    |> refresh_spacecraft_states()
    |> Enum.reduce(%{}, fn state, acc ->
      scenario_id = encode_value(Map.get(state, "scenario_id"))
      spacecraft_id = spacecraft_state_identity(state)

      if scenario_id in [nil, ""] or spacecraft_id in [nil, ""] do
        acc
      else
        Map.put_new(acc, scenario_id, spacecraft_id)
      end
    end)
  end

  defp spacecraft_state_identity(state) do
    spacecraft_identity_value(Map.get(state, "spacecraft_id")) ||
      spacecraft_identity_value(Map.get(state, "satellite_id")) ||
      spacecraft_identity_value(Map.get(state, "spacecraft")) ||
      spacecraft_identity_value(Map.get(state, "satellite"))
  end

  defp spacecraft_identity_value(%{} = spacecraft) do
    Enum.find_value(["spacecraft_id", "satellite_id", "id"], fn field ->
      spacecraft_identity_value(Map.get(spacecraft, field))
    end)
  end

  defp spacecraft_identity_value(value), do: encode_value(value)

  defp objective_required_downlink_mb(objective) do
    Enum.find_value(
      [
        "required_downlink_mb",
        "downlink_mb",
        "required_throughput_mb",
        "required_volume_mb",
        "required_data_volume_mb",
        "min_downlink_mb"
      ],
      fn field ->
        case numeric_value(Map.get(objective, field)) do
          value when is_number(value) -> value
          _value -> nil
        end
      end
    )
  end

  defp collection_latency_limit_s(objective) do
    Enum.find_value(["max_latency_s", "required_latency_s", "target_latency_s"], fn field ->
      case numeric_value(Map.get(objective, field)) do
        value when is_number(value) -> value
        _value -> nil
      end
    end)
  end

  defp collection_latency_identity_value(objectives, field) do
    objectives
    |> Enum.flat_map(&identity_selector_values(&1, collection_latency_identity_aliases(field)))
    |> Enum.uniq()
    |> Enum.sort()
    |> List.first()
  end

  defp collection_latency_product_ids(objectives) do
    values =
      objectives
      |> Enum.flat_map(&identity_selector_values(&1, ["product_ids", "data_product_ids"]))
      |> Enum.uniq()
      |> Enum.sort()

    if values == [], do: nil, else: values
  end

  defp collection_latency_identity_aliases("collection_id"), do: ["collection_id", "collection"]
  defp collection_latency_identity_aliases("product_id"), do: ["product_id", "data_product_id"]
  defp collection_latency_identity_aliases("payload_id"), do: ["payload_id", "payload"]
  defp collection_latency_identity_aliases("instrument_id"), do: ["instrument_id", "instrument"]

  defp identity_selector_values(row, keys) when is_map(row) do
    keys
    |> Enum.flat_map(fn key ->
      case Map.get(row, key) do
        values when is_list(values) -> values
        nil -> []
        value -> [value]
      end
    end)
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp identity_selector_values(_row, _keys), do: []

  defp observation_objective_context(refresh, scenario_id, target_id, policy) do
    objectives =
      refresh
      |> observation_objectives()
      |> Enum.filter(
        &objective_matches_observation_candidate?(&1, refresh, scenario_id, target_id)
      )

    required_observations =
      objectives
      |> Enum.map(&objective_required_observations/1)
      |> Enum.filter(&(is_number(&1) and &1 > 0.0))
      |> Enum.sum()

    if objectives == [] or required_observations <= 0.0 do
      {%{}, %{}}
    else
      objective_ids =
        objectives
        |> Enum.map(&objective_id/1)
        |> Enum.reject(&is_nil/1)
        |> Enum.uniq()
        |> Enum.sort()

      objective_types =
        objectives
        |> Enum.map(&Map.get(&1, "type"))
        |> Enum.reject(&is_nil/1)
        |> Enum.uniq()
        |> Enum.sort()

      weight = policy_number(policy, "observation_objective_weight", 25.0)

      {
        %{
          "observation_objective_count" => length(objectives),
          "observation_objective_ids" => objective_ids,
          "observation_objective_types" => objective_types,
          "required_observations" => required_observations,
          "observation_objective_source" => "candidate_refresh.objectives.observation"
        },
        %{"observation_objective_value" => required_observations * weight}
      }
    end
  end

  defp observation_objectives(refresh) do
    refresh
    |> refresh_objectives()
    |> Enum.filter(fn
      %{"type" => type}
      when type in [
             "target_observation",
             "target_revisit",
             "target_coverage",
             "coverage",
             "priority_commitment",
             "urgent_target"
           ] ->
        true

      _objective ->
        false
    end)
  end

  defp objective_matches_observation_candidate?(objective, refresh, scenario_id, target_id) do
    objective_matches_target?(objective, target_id) and
      objective_matches_spacecraft?(objective, refresh, scenario_id)
  end

  defp objective_matches_target?(objective, target_id) do
    target_id = encode_value(target_id)
    objective_target_id = objective_target_id(objective)
    objective_target_ids = objective_target_ids(objective)

    cond do
      objective_target_id in [nil, ""] and objective_target_ids == [] ->
        true

      encode_value(objective_target_id) == target_id ->
        true

      target_id in objective_target_ids ->
        true

      true ->
        false
    end
  end

  defp objective_target_id(objective) do
    target_identity_value(Map.get(objective, "target_id")) ||
      target_identity_value(Map.get(objective, "target"))
  end

  defp objective_target_ids(objective) do
    objective_target_selector_aliases()
    |> Enum.map(&Map.get(objective, &1))
    |> List.flatten()
    |> Enum.map(&target_identity_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp objective_target_selector_aliases do
    [
      "target_ids",
      "targets",
      "target_specs",
      "required_target_ids",
      "required_targets",
      "committed_targets",
      "priority_targets",
      "uncovered_target_ids",
      "uncovered_targets",
      "unsatisfied_target_ids",
      "unsatisfied_targets",
      "missing_target_ids",
      "missing_targets",
      "missed_target",
      "missed_targets",
      "target_gap_ids",
      "target_gap_targets"
    ]
  end

  defp target_identity_value(%{} = target) do
    Enum.find_value(["target_id", "id"], fn field ->
      target_identity_value(Map.get(target, field))
    end)
  end

  defp target_identity_value(value), do: encode_value(value)

  defp objective_required_observations(objective) do
    Enum.find_value(
      [
        "required_observations",
        "required_revisits",
        "required_count",
        "required_observation_count",
        "min_observations",
        "missing_observation_count",
        "target_gap_count",
        "target_coverage_gap_count",
        "coverage_gap_count"
      ],
      fn field ->
        case numeric_value(Map.get(objective, field)) do
          value when is_number(value) -> max(value * 1.0, 0.0)
          _value -> nil
        end
      end
    ) || 1.0
  end

  defp objective_id(%{"id" => id}), do: encode_value(id)
  defp objective_id(%{"objective_id" => id}), do: encode_value(id)
  defp objective_id(_objective), do: nil

  defp contact_success_factor(refresh, ground_station_id) do
    rates = refresh |> operational_feedback() |> Map.get("contact_success_rate")

    case rates do
      %{} ->
        station_id = encode_value(ground_station_id)

        cond do
          is_number(Map.get(rates, station_id)) ->
            {rates |> Map.get(station_id) |> max(0.0) |> min(1.0),
             "operational_feedback.contact_success_rate.station"}

          is_number(Map.get(rates, "default")) ->
            {rates |> Map.get("default") |> max(0.0) |> min(1.0),
             "operational_feedback.contact_success_rate.default"}

          true ->
            {1.0, "not_declared"}
        end

      _other ->
        {1.0, "not_declared"}
    end
  end

  defp station_throughput_factor(_refresh, _ground_station_id, %{
         "provenance" => %{"station_throughput_factor_source" => "operational_feedback"}
       }),
       do: {1.0, nil}

  defp station_throughput_factor(refresh, ground_station_id, _station_state) do
    factors = refresh |> operational_feedback() |> Map.get("station_throughput_factor")

    case factors do
      %{} ->
        station_id = encode_value(ground_station_id)

        cond do
          is_number(Map.get(factors, station_id)) ->
            {factors |> Map.get(station_id) |> max(0.0) |> min(1.0),
             "operational_feedback.station_throughput_factor.station"}

          is_number(Map.get(factors, "default")) ->
            {factors |> Map.get("default") |> max(0.0) |> min(1.0),
             "operational_feedback.station_throughput_factor.default"}

          true ->
            {1.0, nil}
        end

      _other ->
        {1.0, nil}
    end
  end

  defp target_priority(
         refresh,
         scenario_id,
         target_id,
         %{"priority_override_source" => "operational_feedback"} = target,
         fallback
       ) do
    base_priority =
      case numeric_value(Map.get(target, "priority", fallback)) do
        value when is_number(value) -> max(value, 0.0)
        _value -> max(fallback, 0.0)
      end

    target_objective_priority(
      refresh,
      scenario_id,
      target_id,
      base_priority,
      "operational_feedback.target_priority"
    )
  end

  defp target_priority(refresh, scenario_id, target_id, target, fallback) do
    priorities = refresh |> operational_feedback() |> Map.get("target_priority_overrides")
    target_id = encode_value(target_id)

    {base_priority, source} =
      cond do
        is_map(priorities) and is_number(Map.get(priorities, target_id)) ->
          {
            priorities
            |> Map.get(target_id)
            |> max(0.0),
            "operational_feedback.target_priority_overrides"
          }

        is_map(target) and is_number(numeric_value(Map.get(target, "priority"))) ->
          {
            target
            |> Map.get("priority")
            |> numeric_value()
            |> max(0.0),
            "candidate_refresh.targets.priority"
          }

        true ->
          {max(fallback, 0.0), "source_window.target_priority"}
      end

    target_objective_priority(refresh, scenario_id, target_id, base_priority, source)
  end

  defp target_objective_priority(refresh, scenario_id, target_id, base_priority, base_source) do
    priority_objectives =
      refresh
      |> observation_objectives()
      |> Enum.filter(
        &objective_matches_observation_candidate?(&1, refresh, scenario_id, target_id)
      )
      |> Enum.map(fn objective ->
        {objective, objective_target_priority(objective, target_id)}
      end)
      |> Enum.filter(fn {_objective, priority} -> is_number(priority) end)
      |> Enum.sort_by(fn {objective, priority} -> {-priority, objective_id(objective) || ""} end)

    case priority_objectives do
      [{objective, priority} | _rest] when priority > base_priority ->
        objective_ids =
          priority_objectives
          |> Enum.filter(fn {_objective, objective_priority} ->
            objective_priority == priority
          end)
          |> Enum.map(fn {objective, _priority} -> objective_id(objective) end)
          |> Enum.reject(&is_nil/1)
          |> Enum.uniq()
          |> Enum.sort()

        {
          priority,
          %{
            "target_priority_source" => "candidate_refresh.objectives.observation_priority",
            "target_priority_objective_ids" => objective_ids,
            "target_priority_objective_type" => Map.get(objective, "type")
          }
          |> compact_map()
        }

      _objectives ->
        {base_priority, %{"target_priority_source" => base_source}}
    end
  end

  defp objective_target_priority(objective, target_id) do
    objective_target_spec_priority(objective, target_id) ||
      objective_top_level_target_priority(objective)
  end

  defp objective_target_spec_priority(objective, target_id) do
    target_id = encode_value(target_id)

    objective
    |> objective_target_specs()
    |> Enum.filter(&(target_identity_value(&1) == target_id))
    |> Enum.map(&target_spec_priority/1)
    |> Enum.filter(&is_number/1)
    |> Enum.max(fn -> nil end)
  end

  defp objective_target_specs(objective) do
    ["target" | objective_target_selector_aliases()]
    |> Enum.flat_map(&target_spec_values(Map.get(objective, &1)))
  end

  defp target_spec_values(values) when is_list(values),
    do: Enum.flat_map(values, &target_spec_values/1)

  defp target_spec_values(%{} = value), do: [value]
  defp target_spec_values(_value), do: []

  defp target_spec_priority(%{} = target) do
    Enum.find_value(["target_priority", "priority", "urgency", "target_value"], fn field ->
      case numeric_value(Map.get(target, field)) do
        value when is_number(value) ->
          max(value, 0.0)

        _value ->
          nil
      end
    end)
  end

  defp objective_top_level_target_priority(objective) do
    Enum.find_value(["target_priority", "priority", "urgency", "target_value"], fn field ->
      case numeric_value(Map.get(objective, field)) do
        value when is_number(value) ->
          max(value, 0.0)

        _value ->
          nil
      end
    end)
  end

  defp observation_success_factor(refresh, target_id, %{
         "observation_success_factor" => factor
       })
       when is_number(factor) or is_binary(factor) do
    case numeric_value(factor) do
      value when is_number(value) ->
        {1.0, value |> max(0.0) |> min(1.0),
         "operational_feedback.observation_success_rate.encoded"}

      _value ->
        observation_success_factor(refresh, target_id, %{})
    end
  end

  defp observation_success_factor(refresh, target_id, target)
       when is_map(refresh) do
    if branch_event_derived_refresh?(refresh) do
      {1.0, 1.0, nil}
    else
      case observation_success_factor_from_feedback(refresh, target_id) do
        {1.0, 1.0, nil} -> observation_success_factor_from_target_quality(target)
        factor -> factor
      end
    end
  end

  defp observation_success_factor_from_feedback(refresh, target_id) do
    feedback = operational_feedback(refresh)
    rates = Map.get(feedback, "observation_success_rate")
    image_quality_scores = Map.get(feedback, "image_quality_score")
    image_quality_statuses = Map.get(feedback, "image_quality_status")
    cloud_cover_fractions = Map.get(feedback, "cloud_cover_fraction")
    blur_scores = Map.get(feedback, "blur_score")
    target_id = encode_value(target_id)

    case rates do
      %{} ->
        cond do
          is_number(Map.get(rates, target_id)) ->
            factor = rates |> Map.get(target_id) |> max(0.0) |> min(1.0)

            {factor, factor, "operational_feedback.observation_success_rate.target"}

          is_number(Map.get(rates, "default")) ->
            factor = rates |> Map.get("default") |> max(0.0) |> min(1.0)

            {factor, factor, "operational_feedback.observation_success_rate.default"}

          true ->
            observation_success_factor_from_quality_feedback(
              image_quality_scores,
              image_quality_statuses,
              cloud_cover_fractions,
              blur_scores,
              target_id
            )
        end

      _other ->
        observation_success_factor_from_quality_feedback(
          image_quality_scores,
          image_quality_statuses,
          cloud_cover_fractions,
          blur_scores,
          target_id
        )
    end
  end

  defp observation_success_factor_from_quality_feedback(
         scores,
         statuses,
         cloud_cover_fractions,
         blur_scores,
         target_id
       ) do
    case observation_success_factor_from_image_quality(scores, target_id) do
      {1.0, 1.0, nil} ->
        case observation_success_factor_from_image_quality_status(statuses, target_id) do
          {1.0, 1.0, nil} ->
            observation_success_factor_from_cloud_or_blur(
              cloud_cover_fractions,
              blur_scores,
              target_id
            )

          factor ->
            factor
        end

      factor ->
        factor
    end
  end

  defp observation_success_factor_from_image_quality(%{} = scores, target_id) do
    cond do
      is_number(Map.get(scores, target_id)) ->
        factor = scores |> Map.get(target_id) |> max(0.0) |> min(1.0)
        {factor, factor, "operational_feedback.image_quality_score.target"}

      is_number(Map.get(scores, "default")) ->
        factor = scores |> Map.get("default") |> max(0.0) |> min(1.0)
        {factor, factor, "operational_feedback.image_quality_score.default"}

      true ->
        {1.0, 1.0, nil}
    end
  end

  defp observation_success_factor_from_image_quality(_scores, _target_id), do: {1.0, 1.0, nil}

  defp observation_success_factor_from_image_quality_status(%{} = statuses, target_id) do
    cond do
      is_binary(Map.get(statuses, target_id)) ->
        image_quality_status_factor(Map.get(statuses, target_id), "target")

      is_binary(Map.get(statuses, "default")) ->
        image_quality_status_factor(Map.get(statuses, "default"), "default")

      true ->
        {1.0, 1.0, nil}
    end
  end

  defp observation_success_factor_from_image_quality_status(_statuses, _target_id),
    do: {1.0, 1.0, nil}

  defp image_quality_status_factor(status, scope) when is_binary(status) do
    case normalized_quality_status_token(status) do
      status
      when status in [
             "failed",
             "failure",
             "rejected",
             "unusable",
             "invalid",
             "missing",
             "not_usable",
             "no_image",
             "clouded_out"
           ] ->
        {0.0, 0.0, "operational_feedback.image_quality_status.#{scope}"}

      status when status in ["poor", "degraded", "marginal", "partial"] ->
        {0.5, 0.5, "operational_feedback.image_quality_status.#{scope}"}

      _status ->
        {1.0, 1.0, nil}
    end
  end

  defp normalized_quality_status_token(status) when is_binary(status) do
    status
    |> String.trim()
    |> String.downcase()
    |> String.replace(~r/[^a-z0-9]+/, "_")
    |> String.trim("_")
  end

  defp observation_success_factor_from_cloud_or_blur(
         cloud_cover_fractions,
         blur_scores,
         target_id
       ) do
    [
      feedback_inverse_quality_factor(
        cloud_cover_fractions,
        target_id,
        "operational_feedback.cloud_cover_fraction"
      ),
      feedback_inverse_quality_factor(blur_scores, target_id, "operational_feedback.blur_score")
    ]
    |> Enum.reject(&is_nil/1)
    |> Enum.min_by(fn {factor, _score, _source} -> factor end, fn -> nil end)
    |> case do
      {factor, score, source} -> {factor, score, source}
      nil -> {1.0, 1.0, nil}
    end
  end

  defp feedback_inverse_quality_factor(%{} = values, target_id, source) do
    cond do
      is_number(Map.get(values, target_id)) ->
        factor = values |> Map.get(target_id) |> inverse_quality_factor()
        {factor, factor, "#{source}.target"}

      is_number(Map.get(values, "default")) ->
        factor = values |> Map.get("default") |> inverse_quality_factor()
        {factor, factor, "#{source}.default"}

      true ->
        nil
    end
  end

  defp feedback_inverse_quality_factor(_values, _target_id, _source), do: nil

  defp inverse_quality_factor(value) when is_number(value),
    do: 1.0 - (value |> max(0.0) |> min(1.0))

  defp inverse_quality_factor(_value), do: nil

  defp observation_success_factor_from_target_quality(%{} = target) do
    image_quality_score =
      first_probability(target, [
        "image_quality_score",
        "product_quality_score",
        "quality_score"
      ])

    cloud_cover_fraction =
      first_probability(target, ["cloud_cover_fraction", "cloud_fraction", "cloud_cover"])

    blur_score =
      first_probability(target, ["blur_score", "image_blur_score", "sharpness_loss_fraction"])

    cond do
      is_number(image_quality_score) ->
        {image_quality_score, image_quality_score, "target.image_quality_score"}

      is_number(cloud_cover_fraction) or is_number(blur_score) ->
        observation_success_factor_from_target_cloud_or_blur(cloud_cover_fraction, blur_score)

      true ->
        {1.0, 1.0, nil}
    end
  end

  defp observation_success_factor_from_target_quality(_target), do: {1.0, 1.0, nil}

  defp observation_success_factor_from_target_cloud_or_blur(cloud_cover_fraction, blur_score) do
    [
      {"target.cloud_cover_fraction", inverse_quality_factor(cloud_cover_fraction)},
      {"target.blur_score", inverse_quality_factor(blur_score)}
    ]
    |> Enum.filter(fn {_source, value} -> is_number(value) end)
    |> Enum.min_by(fn {_source, value} -> value end)
    |> then(fn {source, factor} -> {factor, factor, source} end)
  end

  defp observation_quality_context(refresh, target_id, target) do
    target_id = encode_value(target_id)
    feedback = operational_feedback(refresh)
    target = if is_map(target), do: target, else: %{}

    %{
      "image_quality_score" =>
        feedback_probability(feedback, "image_quality_score", target_id) ||
          first_probability(target, [
            "image_quality_score",
            "product_quality_score",
            "quality_score"
          ]),
      "image_quality_status" =>
        feedback_string(feedback, "image_quality_status", target_id) ||
          first_string(target, ["image_quality_status", "quality_status"]),
      "image_quality_source" =>
        feedback_string(feedback, "image_quality_source", target_id) ||
          first_string(target, ["image_quality_source", "quality_source"]),
      "cloud_cover_fraction" =>
        feedback_probability(feedback, "cloud_cover_fraction", target_id) ||
          first_probability(target, ["cloud_cover_fraction", "cloud_fraction", "cloud_cover"]),
      "blur_score" =>
        feedback_probability(feedback, "blur_score", target_id) ||
          first_probability(target, ["blur_score", "image_blur_score", "sharpness_loss_fraction"])
    }
    |> compact_map()
  end

  defp feedback_probability(%{} = feedback, field, target_id) do
    case Map.get(feedback, field) do
      %{} = values ->
        Enum.find_value([target_id, "default"], fn key ->
          case Map.get(values, key) do
            value when is_number(value) -> value |> max(0.0) |> min(1.0)
            _value -> nil
          end
        end)

      _values ->
        nil
    end
  end

  defp feedback_probability(_feedback, _field, _target_id), do: nil

  defp feedback_string(%{} = feedback, field, target_id) do
    case Map.get(feedback, field) do
      %{} = values ->
        Enum.find_value([target_id, "default"], fn key ->
          case Map.get(values, key) do
            value when is_binary(value) and value != "" -> value
            _value -> nil
          end
        end)

      _values ->
        nil
    end
  end

  defp feedback_string(_feedback, _field, _target_id), do: nil

  defp first_probability(map, fields) do
    Enum.find_value(fields, fn field ->
      case numeric_value(Map.get(map, field)) do
        value when is_number(value) -> value |> max(0.0) |> min(1.0)
        _value -> nil
      end
    end)
  end

  defp first_string(map, fields) do
    Enum.find_value(fields, fn field ->
      case encode_value(Map.get(map, field)) do
        value when is_binary(value) and value != "" -> value
        _value -> nil
      end
    end)
  end

  defp target_metadata_context(%{} = target) do
    source_target = source_target_metadata(target)

    %{
      "source_target_id" => target_identity_value(target),
      "source_target" => source_target,
      "target_latitude_deg" =>
        target_metadata_number(target, ["latitude_deg", "lat_deg", "latitude"]),
      "target_longitude_deg" =>
        target_metadata_number(target, ["longitude_deg", "lon_deg", "longitude"]),
      "target_minimum_elevation_deg" =>
        target_metadata_number(target, [
          "minimum_elevation_deg",
          "min_elevation_deg",
          "minimum_elevation",
          "min_elevation"
        ])
    }
    |> compact_map()
  end

  defp target_metadata_context(_target), do: %{}

  defp source_target_metadata(%{} = target) do
    %{
      "id" => target_identity_value(target),
      "latitude_deg" => target_metadata_number(target, ["latitude_deg", "lat_deg", "latitude"]),
      "longitude_deg" =>
        target_metadata_number(target, ["longitude_deg", "lon_deg", "longitude"]),
      "minimum_elevation_deg" =>
        target_metadata_number(target, [
          "minimum_elevation_deg",
          "min_elevation_deg",
          "minimum_elevation",
          "min_elevation"
        ]),
      "priority" => target_metadata_number(target, ["priority", "target_priority"]),
      "geometry_model" => first_string(target, ["geometry_model", "target_geometry_model"])
    }
    |> compact_map()
  end

  defp target_metadata_number(map, fields) do
    Enum.find_value(fields, fn field ->
      case numeric_value(Map.get(map, field)) do
        value when is_number(value) -> value
        _value -> nil
      end
    end)
  end

  defp branch_event_derived_refresh?(refresh) do
    refresh
    |> Map.get("model_assumptions", %{})
    |> Map.get("candidate_refresh_level") == "branch_event_derived_v1"
  end

  defp invalidated_candidates(refresh, refreshed_candidates, dropped_candidates) do
    {invalid_prior_candidates, prior_candidates} =
      refresh
      |> prior_candidate_activities()
      |> Enum.split_with(&invalid_prior_candidate_input?/1)

    {_refreshed_matches, unmatched_prior_candidates} =
      match_candidates_by_id_occurrence(prior_candidates, refreshed_candidates)

    refreshed_by_semantic_key = semantic_candidate_groups(refreshed_candidates)
    dropped_by_semantic_key = semantic_candidate_groups(dropped_candidates)

    (invalid_prior_candidates ++ unmatched_prior_candidates)
    |> Enum.map(fn candidate ->
      if invalid_prior_candidate_input?(candidate) do
        invalid_prior_candidate_row(candidate)
      else
        invalidated_candidate_row(
          candidate,
          refreshed_by_semantic_key,
          dropped_candidates,
          dropped_by_semantic_key
        )
      end
    end)
    |> Enum.sort_by(&{&1["scenario_id"] || "", &1["starts_at_s"] || 0.0, &1["id"] || ""})
  end

  defp invalidated_candidate_row(
         candidate,
         refreshed_by_semantic_key,
         dropped_candidates,
         dropped_by_semantic_key
       ) do
    refreshed_match = semantic_candidate_match(refreshed_by_semantic_key, candidate)
    dropped_match = dropped_candidate_match(dropped_candidates, candidate)

    dropped_semantic_match =
      semantic_candidate_match(dropped_by_semantic_key, candidate)

    invalidation_match =
      dropped_match || refreshed_match || dropped_semantic_match

    change_details = semantic_replacement_change_details(candidate, invalidation_match)
    change_reasons = semantic_change_detail_reasons(change_details)
    drop_reason_match = dropped_match || dropped_semantic_match

    row =
      %{
        "id" => Map.get(candidate, "id"),
        "type" => Map.get(candidate, "type"),
        "scenario_id" => Map.get(candidate, "scenario_id"),
        "starts_at_s" => Map.get(candidate, "starts_at_s"),
        "ends_at_s" => Map.get(candidate, "ends_at_s"),
        "invalidated_reason" =>
          invalidated_reason(
            if(dropped_match, do: nil, else: refreshed_match),
            drop_reason_match
          ),
        "replacement_candidate_id" => matched_candidate_id(invalidation_match),
        "source_window_id" =>
          Map.get(candidate, "source_window_id") || get_in(candidate, ["source_window", "id"])
      }
      |> Map.merge(candidate_diff_context(candidate, invalidation_match))

    row
    |> maybe_put_nonempty("semantic_change_reasons", change_reasons)
    |> maybe_put_nonempty("semantic_change_details", change_details)
    |> put_candidate_diff_changed_fields(change_details)
    |> put_semantic_match_ambiguity(invalidation_match, "replacement")
    |> put_budget_dropped_match_context(drop_reason_match)
    |> Enum.reject(fn {_key, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp invalid_prior_candidate_row(candidate) do
    %{
      "id" => candidate["id"],
      "type" => candidate["type"],
      "scenario_id" => candidate["scenario_id"],
      "spacecraft_id" => candidate["spacecraft_id"],
      "ground_station_id" => candidate["ground_station_id"],
      "target_id" => candidate["target_id"],
      "source_window_id" => candidate["source_window_id"],
      "station_calendar_entry_id" => candidate["station_calendar_entry_id"],
      "station_calendar_overlap_entry_ids" => candidate["station_calendar_overlap_entry_ids"],
      "station_calendar_ambiguous_entry_ids" => candidate["station_calendar_ambiguous_entry_ids"],
      "station_calendar_reservation_ids" => candidate["station_calendar_reservation_ids"],
      "station_reservation_id" => candidate["station_reservation_id"],
      "starts_at_s" => candidate["starts_at_s"],
      "ends_at_s" => candidate["ends_at_s"],
      "invalidated_reason" => "invalid_prior_candidate_input",
      "invalid_prior_candidate_input" => true,
      "invalid_prior_candidate_input_reason" => candidate["invalid_prior_candidate_input_reason"],
      "source_candidate" => candidate["source_candidate"]
    }
    |> Map.merge(candidate_diff_context(candidate))
    |> Enum.reject(fn {_key, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp candidate_diff_report(refresh, refreshed_candidates, invalidated_candidates) do
    prior_candidates = prior_candidate_activities(refresh)

    {invalid_prior_candidates, valid_prior_candidates} =
      Enum.split_with(prior_candidates, &invalid_prior_candidate_input?/1)

    prior_by_semantic_key = semantic_candidate_groups(valid_prior_candidates)

    {refreshed_matches, _unmatched_prior_candidates} =
      match_candidates_by_id_occurrence(valid_prior_candidates, refreshed_candidates)

    retained =
      refreshed_matches
      |> Enum.filter(fn {_candidate, prior_candidate} -> not is_nil(prior_candidate) end)
      |> Enum.map(fn {candidate, prior_candidate} ->
        candidate_diff_row(candidate, "retained", prior_candidate)
      end)
      |> sort_candidate_diff_rows()

    added =
      refreshed_matches
      |> Enum.filter(fn {_candidate, prior_candidate} -> is_nil(prior_candidate) end)
      |> Enum.map(fn {candidate, _prior_candidate} ->
        candidate_diff_row_for_new(
          candidate,
          semantic_candidate_match(prior_by_semantic_key, candidate)
        )
      end)
      |> sort_candidate_diff_rows()

    %{
      "schema_contract" => "candidate_diff_report.v1",
      "model" => "candidate_id_set_diff_with_semantic_change_reasons",
      "model_limits" => model_limits(),
      "prior_candidate_count" => length(prior_candidates),
      "valid_prior_candidate_count" => length(valid_prior_candidates),
      "invalid_prior_candidate_input_count" => length(invalid_prior_candidates),
      "invalid_prior_candidate_input_ids" => Enum.map(invalid_prior_candidates, & &1["id"]),
      "refreshed_candidate_count" => length(refreshed_candidates),
      "retained_candidate_count" => length(retained),
      "new_candidate_count" => length(added),
      "invalidated_candidate_count" => length(invalidated_candidates),
      "retained_candidates" => retained,
      "new_candidates" => added,
      "invalidated_candidates" => invalidated_candidates,
      "source_window_lineage" => source_window_lineage(refreshed_candidates)
    }
  end

  defp match_candidates_by_id_occurrence(prior_candidates, refreshed_candidates) do
    indexed_prior_candidates = Enum.with_index(prior_candidates)

    {refreshed_matches, matched_prior_indexes} =
      Enum.map_reduce(refreshed_candidates, MapSet.new(), fn candidate, matched_indexes ->
        case first_unmatched_prior_candidate(indexed_prior_candidates, candidate, matched_indexes) do
          nil ->
            {{candidate, nil}, matched_indexes}

          {prior_candidate, prior_index} ->
            {{candidate, prior_candidate}, MapSet.put(matched_indexes, prior_index)}
        end
      end)

    unmatched_prior_candidates =
      indexed_prior_candidates
      |> Enum.reject(fn {_candidate, index} -> MapSet.member?(matched_prior_indexes, index) end)
      |> Enum.map(fn {candidate, _index} -> candidate end)

    {refreshed_matches, unmatched_prior_candidates}
  end

  defp first_unmatched_prior_candidate(indexed_prior_candidates, candidate, matched_indexes) do
    Enum.find(indexed_prior_candidates, fn {prior_candidate, index} ->
      prior_candidate["id"] == candidate["id"] and not MapSet.member?(matched_indexes, index)
    end)
  end

  defp prior_candidate_activities(refresh) do
    refresh
    |> Map.get("prior_candidate_activities", [])
    |> Enum.with_index(1)
    |> Enum.map(&normalize_prior_candidate/1)
  end

  defp normalize_prior_candidate({candidate, index}) when is_map(candidate) do
    candidate =
      candidate
      |> stringify_keys()
      |> normalize_candidate_station_id()
      |> normalize_candidate_time("starts_at_s", "start_s")
      |> normalize_candidate_time("ends_at_s", "end_s")
      |> normalize_candidate_direction()
      |> normalize_candidate_type_alias()
      |> normalize_candidate_type()

    cond do
      reason = prior_candidate_id_issue(candidate["id"]) ->
        invalid_prior_candidate_input(candidate, index, reason)

      not valid_candidate_type?(candidate["type"]) ->
        invalid_prior_candidate_input(candidate, index, "missing_candidate_type")

      reason = prior_candidate_identity_issue(candidate) ->
        invalid_prior_candidate_input(candidate, index, reason)

      true ->
        candidate
    end
  end

  defp normalize_prior_candidate({candidate, index}) do
    invalid_prior_candidate_input(
      %{"raw_input" => inspect(candidate)},
      index,
      "invalid_candidate_shape"
    )
  end

  defp invalid_prior_candidate_input(candidate, index, reason) do
    candidate_id = invalid_prior_candidate_id(candidate, index, reason)

    %{
      "id" => candidate_id,
      "type" => candidate_type_or_invalid(candidate),
      "scenario_id" =>
        stable_id_or_nil(candidate["scenario_id"]) || "missing_scenario_id:#{candidate_id}",
      "spacecraft_id" => stable_id_or_nil(candidate["spacecraft_id"]),
      "ground_station_id" => stable_id_or_nil(candidate["ground_station_id"]),
      "target_id" => stable_id_or_nil(candidate["target_id"]),
      "source_window_id" => stable_id_or_nil(candidate["source_window_id"]),
      "station_calendar_entry_id" => stable_id_or_nil(candidate["station_calendar_entry_id"]),
      "station_calendar_provider_id" =>
        stable_id_or_nil(candidate["station_calendar_provider_id"]),
      "station_calendar_provider_entry_id" =>
        stable_id_or_nil(candidate["station_calendar_provider_entry_id"]),
      "station_calendar_overlap_entry_ids" => candidate["station_calendar_overlap_entry_ids"],
      "station_calendar_ambiguous_entry_ids" => candidate["station_calendar_ambiguous_entry_ids"],
      "station_calendar_reservation_ids" => candidate["station_calendar_reservation_ids"],
      "station_reservation_id" => stable_id_or_nil(candidate["station_reservation_id"]),
      "station_calendar_reservation_expires_at_s" =>
        candidate["station_calendar_reservation_expires_at_s"],
      "station_reservation_expires_at_s" =>
        numeric_or_nil(candidate["station_reservation_expires_at_s"]),
      "starts_at_s" => candidate["starts_at_s"],
      "ends_at_s" => candidate["ends_at_s"],
      "invalid_prior_candidate_input" => true,
      "invalid_prior_candidate_input_reason" => reason,
      "source_candidate" => candidate
    }
    |> normalize_station_calendar_id_lists()
    |> normalize_station_calendar_number_lists()
    |> compact_map()
  end

  defp invalid_prior_candidate_input?(%{"invalid_prior_candidate_input" => true}), do: true
  defp invalid_prior_candidate_input?(_candidate), do: false

  defp invalid_prior_candidate_id(candidate, index, reason) do
    case candidate["id"] do
      value when is_binary(value) and value != "" ->
        stable_id_or_nil(value) || "invalid_prior_candidate:#{reason}:#{index}"

      value when is_atom(value) and not is_nil(value) ->
        stable_id_or_nil(value) || "invalid_prior_candidate:#{reason}:#{index}"

      value when is_integer(value) ->
        stable_id_or_nil(value) || "invalid_prior_candidate:#{reason}:#{index}"

      _value ->
        "invalid_prior_candidate:#{reason}:#{index}"
    end
  end

  defp prior_candidate_id_issue(id) when id in [nil, ""], do: "missing_candidate_id"
  defp prior_candidate_id_issue(id), do: if(stable_id?(id), do: nil, else: "invalid_candidate_id")

  defp prior_candidate_identity_issue(candidate) do
    cond do
      Map.get(candidate, "scenario_id") in [nil, ""] ->
        "missing_scenario_id"

      not stable_id?(Map.get(candidate, "scenario_id")) ->
        "invalid_scenario_id"

      true ->
        Enum.find_value(@prior_candidate_optional_stable_identity_fields, fn field ->
          value = Map.get(candidate, field)

          cond do
            value in [nil, ""] -> nil
            stable_id?(value) -> nil
            true -> "invalid_#{field}"
          end
        end)
    end
  end

  defp stable_id?(value) when is_atom(value) and not is_nil(value) do
    value
    |> Atom.to_string()
    |> stable_id?()
  end

  defp stable_id?("nil"), do: false
  defp stable_id?(value) when is_binary(value), do: Regex.match?(@stable_id_pattern, value)
  defp stable_id?(value) when is_integer(value), do: value |> Integer.to_string() |> stable_id?()
  defp stable_id?(_value), do: false

  defp stable_id_or_nil(nil), do: nil
  defp stable_id_or_nil("nil"), do: nil
  defp stable_id_or_nil(value) when is_binary(value), do: if(stable_id?(value), do: value)

  defp stable_id_or_nil(value) when is_atom(value),
    do: value |> Atom.to_string() |> stable_id_or_nil()

  defp stable_id_or_nil(value) when is_integer(value),
    do: value |> Integer.to_string() |> stable_id_or_nil()

  defp stable_id_or_nil(_value), do: nil

  defp normalize_station_calendar_id_lists(context) do
    Enum.reduce(@station_calendar_id_list_fields, context, fn field, acc ->
      case normalize_id_list(Map.get(acc, field)) do
        nil -> Map.delete(acc, field)
        ids -> Map.put(acc, field, ids)
      end
    end)
  end

  defp normalize_station_calendar_number_lists(context) do
    Enum.reduce(@station_calendar_number_list_fields, context, fn field, acc ->
      case normalize_number_list(Map.get(acc, field)) do
        nil -> Map.delete(acc, field)
        values -> Map.put(acc, field, values)
      end
    end)
  end

  defp normalize_id_list(nil), do: nil

  defp normalize_id_list(values) when is_list(values) do
    values
    |> Enum.flat_map(&id_values/1)
    |> Enum.flat_map(&stable_id_value/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp normalize_id_list(value), do: normalize_id_list([value])

  defp normalize_number_list(nil), do: nil

  defp normalize_number_list(values) when is_list(values) do
    values
    |> List.flatten()
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      numbers -> numbers
    end
  end

  defp normalize_number_list(value), do: normalize_number_list([value])

  defp id_values(%{} = value) do
    ["id", "station_calendar_entry_id", "station_reservation_id", "reservation_id"]
    |> Enum.flat_map(fn key ->
      case Map.get(value, key) do
        nil -> []
        nested when is_list(nested) -> nested
        nested -> [nested]
      end
    end)
  end

  defp id_values(value), do: [value]

  defp stable_id_value(nil), do: []
  defp stable_id_value(value) when is_boolean(value), do: []

  defp stable_id_value(value) when is_atom(value),
    do: value |> Atom.to_string() |> stable_id_value()

  defp stable_id_value("nil"), do: []

  defp stable_id_value(value) when is_binary(value),
    do: if(stable_id?(value), do: [value], else: [])

  defp stable_id_value(value) when is_integer(value),
    do: value |> Integer.to_string() |> stable_id_value()

  defp stable_id_value(_value), do: []

  defp candidate_type_or_invalid(%{"type" => type}) when is_binary(type) and type != "",
    do: type

  defp candidate_type_or_invalid(_candidate), do: "invalid_prior_candidate_input"

  defp valid_candidate_type?(type) when is_binary(type), do: type != ""
  defp valid_candidate_type?(_type), do: false

  defp normalize_candidate_station_id(%{"ground_station_id" => station_id} = candidate)
       when not is_nil(station_id),
       do: candidate

  defp normalize_candidate_station_id(%{"station_id" => station_id} = candidate)
       when not is_nil(station_id),
       do: Map.put(candidate, "ground_station_id", station_id)

  defp normalize_candidate_station_id(candidate) do
    case nested_station_id(candidate) do
      nil -> candidate
      station_id -> Map.put(candidate, "ground_station_id", station_id)
    end
  end

  defp nested_station_id(candidate) do
    Enum.find_value(["ground_station", "station"], fn station_key ->
      case Map.get(candidate, station_key) do
        %{} = station ->
          Enum.find_value(["ground_station_id", "station_id", "id"], fn identity_key ->
            Map.get(station, identity_key)
          end)

        _station ->
          nil
      end
    end)
  end

  defp normalize_candidate_type(%{"type" => "contact", "direction" => "downlink"} = candidate),
    do: Map.put(candidate, "type", "downlink")

  defp normalize_candidate_type(candidate) do
    cond do
      provider_downlink_candidate?(candidate) ->
        candidate
        |> Map.put_new("type", "downlink")
        |> Map.put_new("direction", "downlink")

      direction_contact_candidate?(candidate) and candidate["direction"] == "health_check" ->
        Map.put_new(candidate, "type", "health_check")

      direction_contact_candidate?(candidate) ->
        Map.put_new(candidate, "type", "planned_contact")

      true ->
        candidate
    end
  end

  defp normalize_candidate_type_alias(%{"type" => type} = candidate) when not is_nil(type),
    do: candidate

  defp normalize_candidate_type_alias(%{"activity_type" => type} = candidate)
       when is_binary(type) and type != "",
       do: Map.put(candidate, "type", type)

  defp normalize_candidate_type_alias(candidate), do: candidate

  defp normalize_candidate_time(candidate, canonical_key, alternate_key) do
    case numeric_or_nil(Map.get(candidate, canonical_key)) ||
           numeric_or_nil(Map.get(candidate, alternate_key)) do
      value when is_number(value) -> Map.put(candidate, canonical_key, value)
      _value -> candidate
    end
  end

  defp normalize_candidate_direction(%{"direction" => direction} = candidate) do
    case normalize_direction(direction) do
      nil -> candidate
      normalized -> Map.put(candidate, "direction", normalized)
    end
  end

  defp normalize_candidate_direction(candidate), do: candidate

  defp provider_downlink_candidate?(candidate) do
    type = Map.get(candidate, "type") || Map.get(candidate, "activity_type")
    direction = Map.get(candidate, "direction")

    type in [nil, "contact", "planned_contact"] and
      direction in [nil, "downlink"] and
      not command_feedback_candidate?(candidate) and
      not is_nil(Map.get(candidate, "ground_station_id")) and
      is_number(Map.get(candidate, "starts_at_s")) and
      is_number(Map.get(candidate, "ends_at_s"))
  end

  defp direction_contact_candidate?(candidate) do
    type = Map.get(candidate, "type") || Map.get(candidate, "activity_type")
    direction = Map.get(candidate, "direction")

    type in [nil, "contact", "planned_contact"] and
      direction in ["tracking", "uplink", "command", "health_check"] and
      not is_nil(Map.get(candidate, "ground_station_id")) and
      is_number(Map.get(candidate, "starts_at_s")) and
      is_number(Map.get(candidate, "ends_at_s"))
  end

  defp command_feedback_candidate?(candidate) do
    Map.has_key?(candidate, "command_success") or Map.has_key?(candidate, "command_result")
  end

  defp candidate_diff_row(candidate, status, prior_candidate) do
    change_details = semantic_change_details(prior_candidate, candidate)
    change_reasons = semantic_change_detail_reasons(change_details)

    %{
      "id" => candidate["id"],
      "type" => candidate["type"],
      "scenario_id" => candidate["scenario_id"],
      "starts_at_s" => candidate["starts_at_s"],
      "ends_at_s" => candidate["ends_at_s"],
      "diff_reason" => candidate_diff_reason(status, prior_candidate, change_reasons),
      "matched_prior_candidate_id" => matched_candidate_id(prior_candidate),
      "source_window_id" =>
        Map.get(candidate, "source_window_id") || get_in(candidate, ["source_window", "id"])
    }
    |> Map.merge(candidate_diff_context(candidate, prior_candidate))
    |> maybe_put_nonempty("semantic_change_reasons", change_reasons)
    |> maybe_put_nonempty("semantic_change_details", change_details)
    |> put_candidate_diff_changed_fields(change_details)
    |> Enum.reject(fn {_key, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp candidate_diff_row_for_new(candidate, prior_match) do
    change_details = semantic_prior_change_details(prior_match, candidate)
    change_reasons = semantic_change_detail_reasons(change_details)

    %{
      "id" => candidate["id"],
      "type" => candidate["type"],
      "scenario_id" => candidate["scenario_id"],
      "starts_at_s" => candidate["starts_at_s"],
      "ends_at_s" => candidate["ends_at_s"],
      "diff_reason" => candidate_diff_reason("new", prior_match, change_reasons),
      "matched_prior_candidate_id" => matched_candidate_id(prior_match),
      "source_window_id" =>
        Map.get(candidate, "source_window_id") || get_in(candidate, ["source_window", "id"])
    }
    |> Map.merge(candidate_diff_context(candidate, prior_match))
    |> maybe_put_nonempty("semantic_change_reasons", change_reasons)
    |> maybe_put_nonempty("semantic_change_details", change_details)
    |> put_candidate_diff_changed_fields(change_details)
    |> put_semantic_match_ambiguity(prior_match, "prior")
    |> Enum.reject(fn {_key, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp candidate_diff_context(candidate, fallback_match \\ nil) do
    fallback_match
    |> candidate_from_match()
    |> candidate_diff_context_map()
    |> Map.merge(candidate_diff_context_map(candidate))
  end

  defp candidate_from_match({:unique, candidate}), do: candidate
  defp candidate_from_match(%{} = candidate), do: candidate
  defp candidate_from_match(_match), do: nil

  defp candidate_diff_context_map(%{} = candidate) do
    %{
      "target_id" => candidate["target_id"],
      "ground_station_id" => candidate["ground_station_id"],
      "direction" => candidate["direction"],
      "source_target_id" => candidate["source_target_id"],
      "source_target" => candidate["source_target"],
      "target_latitude_deg" => candidate["target_latitude_deg"],
      "target_longitude_deg" => candidate["target_longitude_deg"],
      "target_minimum_elevation_deg" => candidate["target_minimum_elevation_deg"],
      "target_priority" => candidate["target_priority"],
      "target_priority_source" => candidate["target_priority_source"],
      "target_priority_objective_ids" => candidate["target_priority_objective_ids"],
      "target_priority_objective_type" => candidate["target_priority_objective_type"]
    }
    |> Map.merge(candidate_lineage_context(candidate))
    |> compact_map()
  end

  defp candidate_diff_context_map(_candidate), do: %{}

  defp candidate_diff_reason("retained", _prior_candidate, []),
    do: "present_in_prior_candidate_set"

  defp candidate_diff_reason("retained", _prior_candidate, _change_reasons),
    do: "present_in_prior_candidate_set_with_semantic_changes"

  defp candidate_diff_reason("new", nil, _change_reasons),
    do: "not_present_in_prior_candidate_set"

  defp candidate_diff_reason("new", {:ambiguous, _prior_candidates}, _change_reasons),
    do: "ambiguous_semantic_prior_candidate_match"

  defp candidate_diff_reason("new", _prior_candidate, _change_reasons),
    do: "semantically_similar_prior_candidate_changed"

  defp invalidated_reason(nil, nil), do: "not_present_in_refreshed_candidate_set"

  defp invalidated_reason(nil, {:ambiguous, candidates}) do
    if Enum.all?(candidates, &(candidate_drop_reason(&1) == "dropped_by_candidate_budget")) do
      "ambiguous_budget_dropped_replacement_candidate"
    else
      "ambiguous_dropped_replacement_candidate"
    end
  end

  defp invalidated_reason(nil, {:unique, candidate}), do: candidate_drop_reason(candidate)

  defp invalidated_reason({:ambiguous, _refreshed_candidates}, _dropped_match),
    do: "ambiguous_semantic_replacement_candidate"

  defp invalidated_reason(_refreshed_match, _dropped_match),
    do: "replaced_by_semantically_similar_candidate"

  defp matched_candidate_id(nil), do: nil
  defp matched_candidate_id({:unique, candidate}), do: Map.get(candidate, "id")
  defp matched_candidate_id({:ambiguous, _candidates}), do: nil
  defp matched_candidate_id(candidate), do: Map.get(candidate, "id")

  defp semantic_replacement_change_details(_candidate, nil), do: []

  defp semantic_replacement_change_details(_candidate, {:ambiguous, _candidates}), do: []

  defp semantic_replacement_change_details(candidate, {:unique, match}),
    do: semantic_change_details(candidate, match)

  defp semantic_prior_change_details(nil, _candidate), do: []
  defp semantic_prior_change_details({:ambiguous, _candidates}, _candidate), do: []

  defp semantic_prior_change_details({:unique, prior_candidate}, candidate),
    do: semantic_change_details(prior_candidate, candidate)

  defp put_semantic_match_ambiguity(row, {:ambiguous, candidates}, role) do
    row
    |> Map.put("semantic_match_status", "ambiguous_#{role}_candidate")
    |> Map.put("semantic_match_candidate_count", length(candidates))
    |> Map.put("semantic_match_candidate_ids", Enum.map(candidates, &Map.get(&1, "id")))
  end

  defp put_semantic_match_ambiguity(row, _match, _role), do: row

  defp dropped_candidate_match(dropped_candidates, prior_candidate) do
    case Enum.filter(dropped_candidates, &(&1["id"] == prior_candidate["id"])) do
      [] -> nil
      [candidate] -> {:unique, candidate}
      candidates -> {:ambiguous, candidates}
    end
  end

  defp mark_dropped_candidates(candidates, reason) do
    Enum.map(candidates, &Map.put(&1, "__candidate_drop_reason__", reason))
  end

  defp candidate_drop_reason(candidate) do
    Map.get(candidate, "__candidate_drop_reason__", "dropped_by_candidate_budget")
  end

  defp put_budget_dropped_match_context(row, nil), do: row

  defp put_budget_dropped_match_context(row, {:unique, candidate}) do
    if candidate_drop_reason(candidate) == "dropped_by_candidate_budget" do
      row
      |> Map.put("candidate_budget_match_status", "budget_dropped_replacement_candidate")
      |> Map.put("candidate_budget_match_count", 1)
      |> Map.put("budget_dropped_candidate_ids", [candidate["id"]])
    else
      row
    end
  end

  defp put_budget_dropped_match_context(row, {:ambiguous, candidates}) do
    if Enum.all?(candidates, &(candidate_drop_reason(&1) == "dropped_by_candidate_budget")) do
      row
      |> Map.put(
        "candidate_budget_match_status",
        "ambiguous_budget_dropped_replacement_candidate"
      )
      |> Map.put("candidate_budget_match_count", length(candidates))
      |> Map.put("budget_dropped_candidate_ids", Enum.map(candidates, &Map.get(&1, "id")))
    else
      row
    end
  end

  defp maybe_put(map, _key, nil), do: map
  defp maybe_put(map, key, value), do: Map.put(map, key, value)

  defp maybe_put_nonempty(map, _key, []), do: map
  defp maybe_put_nonempty(map, key, values), do: Map.put(map, key, values)

  defp put_candidate_diff_changed_fields(row, change_details) do
    case semantic_change_fields(change_details) do
      [] ->
        row

      fields ->
        row
        |> Map.put("changed_fields", fields)
        |> Map.put("candidate_diff_changed_fields", fields)
        |> Map.put("candidate_diff_changed_field_count", length(fields))
    end
  end

  defp semantic_change_fields(details) do
    details
    |> List.wrap()
    |> Enum.map(&Map.get(&1, "field"))
    |> Enum.filter(&is_binary/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp semantic_change_detail_reasons(details) do
    details
    |> Enum.map(&Map.get(&1, "reason"))
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
  end

  defp semantic_change_details(nil, _candidate), do: []
  defp semantic_change_details(_prior_candidate, nil), do: []

  defp semantic_change_details(prior_candidate, candidate) do
    [
      semantic_change_detail(prior_candidate, candidate, "type"),
      semantic_change_detail(prior_candidate, candidate, "scenario_id"),
      semantic_change_detail(prior_candidate, candidate, "target_id"),
      semantic_change_detail(prior_candidate, candidate, "ground_station_id"),
      semantic_change_detail(prior_candidate, candidate, "starts_at_s"),
      semantic_change_detail(prior_candidate, candidate, "ends_at_s"),
      semantic_source_window_change_detail(prior_candidate, candidate),
      semantic_change_detail(prior_candidate, candidate, "estimated_throughput_mb"),
      semantic_change_detail(prior_candidate, candidate, "target_priority"),
      semantic_change_detail(prior_candidate, candidate, "observation_success_factor"),
      semantic_change_detail(prior_candidate, candidate, "contact_success_factor"),
      semantic_change_detail(prior_candidate, candidate, "station_availability"),
      semantic_change_detail(prior_candidate, candidate, "station_contention_status"),
      semantic_change_detail(prior_candidate, candidate, "station_calendar_entry_id"),
      semantic_change_detail(prior_candidate, candidate, "station_calendar_provider_id"),
      semantic_change_detail(prior_candidate, candidate, "station_calendar_provider_entry_id"),
      semantic_change_detail(prior_candidate, candidate, "station_reservation_id"),
      semantic_change_detail(prior_candidate, candidate, "station_reservation_status"),
      semantic_change_detail(prior_candidate, candidate, "station_reservation_expires_at_s"),
      semantic_change_detail(prior_candidate, candidate, "station_reservation_match_status"),
      semantic_nested_change_detail(
        prior_candidate,
        candidate,
        ["throughput_model", "station_capacity_fraction"],
        "station_capacity_fraction"
      ),
      semantic_nested_change_detail(
        prior_candidate,
        candidate,
        ["throughput_model", "station_throughput_factor"],
        "station_throughput_factor"
      )
    ]
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq_by(&Map.get(&1, "field"))
  end

  defp semantic_change_detail(prior_candidate, candidate, field) do
    prior_value = Map.get(prior_candidate, field)
    value = Map.get(candidate, field)

    if not is_nil(prior_value) and not is_nil(value) and prior_value != value do
      semantic_change_detail(field, prior_value, value, field, field)
    end
  end

  defp semantic_nested_change_detail(prior_candidate, candidate, path, field) do
    prior_value = get_in(prior_candidate, path)
    value = get_in(candidate, path)

    if not is_nil(prior_value) and not is_nil(value) and prior_value != value do
      path = Enum.join(path, ".")
      semantic_change_detail(field, prior_value, value, path, path)
    end
  end

  defp semantic_source_window_change_detail(prior_candidate, candidate) do
    prior_source_window_id =
      Map.get(prior_candidate, "source_window_id") ||
        get_in(prior_candidate, ["source_window", "id"])

    source_window_id =
      Map.get(candidate, "source_window_id") || get_in(candidate, ["source_window", "id"])

    if not is_nil(prior_source_window_id) and not is_nil(source_window_id) and
         prior_source_window_id != source_window_id do
      semantic_change_detail(
        "source_window_id",
        prior_source_window_id,
        source_window_id,
        source_window_id_path(prior_candidate),
        source_window_id_path(candidate)
      )
    end
  end

  defp semantic_change_detail(field, prior_value, value, prior_path, refreshed_path) do
    %{
      "field" => field,
      "reason" => field <> "_changed",
      "prior_path" => prior_path,
      "refreshed_path" => refreshed_path,
      "prior_value" => prior_value,
      "refreshed_value" => value
    }
  end

  defp source_window_id_path(candidate) do
    if Map.has_key?(candidate, "source_window_id") do
      "source_window_id"
    else
      "source_window.id"
    end
  end

  defp candidate_semantic_key(candidate) do
    type = Map.get(candidate, "type")
    scenario_id = Map.get(candidate, "scenario_id")
    subject_id = Map.get(candidate, "target_id") || Map.get(candidate, "ground_station_id")

    if type && scenario_id && subject_id do
      {type, scenario_id, subject_id}
    end
  end

  defp semantic_candidate_groups(candidates) do
    candidates
    |> Enum.map(&{candidate_semantic_key(&1), &1})
    |> Enum.reject(fn {key, _candidate} -> is_nil(key) end)
    |> Enum.group_by(fn {key, _candidate} -> key end, fn {_key, candidate} -> candidate end)
  end

  defp semantic_candidate_match(groups, candidate) do
    case Map.get(groups, candidate_semantic_key(candidate), []) do
      [] -> nil
      [match] -> {:unique, match}
      matches -> {:ambiguous, matches}
    end
  end

  defp sort_candidate_diff_rows(rows) do
    Enum.sort_by(rows, &{&1["scenario_id"] || "", &1["starts_at_s"] || 0.0, &1["id"] || ""})
  end

  defp resource_summary_inputs(refresh) do
    {summaries, invalid_summaries} =
      refresh
      |> refresh_resource_summaries()
      |> normalize_resource_summary_inputs()

    {summaries, feedback_invalid_summaries} =
      summaries
      |> apply_resource_feedback_overrides(operational_feedback(refresh))
      |> normalize_resource_summary_inputs()

    {summaries, summaries ++ invalid_summaries ++ feedback_invalid_summaries}
  end

  defp normalize_resource_summary_inputs(summaries) when is_list(summaries) do
    summaries
    |> Enum.map(&normalize_resource_summary_input/1)
    |> Enum.split_with(fn
      {:valid, _summary} -> true
      {:invalid, _summary} -> false
    end)
    |> then(fn {valid, invalid} ->
      {
        Enum.map(valid, fn {:valid, summary} -> summary end),
        Enum.map(invalid, fn {:invalid, summary} -> summary end)
      }
    end)
  end

  defp normalize_resource_summary_inputs(nil), do: {[], []}

  defp normalize_resource_summary_inputs(summaries), do: {[], [summaries]}

  defp normalize_resource_summary_input(%ResourceSummary{} = summary),
    do: {:valid, ResourceSummary.to_map(summary)}

  defp normalize_resource_summary_input(%{} = summary) do
    {:valid, summary |> ResourceSummary.from_map!() |> ResourceSummary.to_map()}
  rescue
    ArgumentError -> {:invalid, stringify_keys(summary)}
  end

  defp normalize_resource_summary_input(summary), do: {:invalid, summary}

  defp resource_summary_inputs_invalid_count(resource_filter_report) do
    Map.get(resource_filter_report, "invalid_resource_summary_input_count", 0)
  end

  defp source_resource_projection_report_invalid_input_count(refresh) do
    refresh
    |> source_resource_projection_reports()
    |> Enum.map(fn {_path, report} ->
      resource_projection_report_invalid_activity_input_count(report) +
        resource_projection_report_invalid_resource_summary_input_count(report)
    end)
    |> Enum.sum()
  end

  defp source_resource_filter_report_invalid_resource_summary_input_count(refresh) do
    refresh
    |> source_resource_filter_reports()
    |> Enum.map(fn {_path, report} ->
      resource_filter_report_invalid_resource_summary_input_count(report)
    end)
    |> Enum.sum()
  end

  defp apply_resource_feedback_overrides(summaries, feedback) do
    feedback = stringify_keys(feedback || %{})
    margin_overrides = Map.get(feedback, "resource_margin_overrides", %{})
    availability_overrides = Map.get(feedback, "resource_availability_overrides", %{})

    if margin_overrides == %{} and availability_overrides == %{} do
      summaries
    else
      override_ids =
        [margin_overrides, availability_overrides]
        |> Enum.flat_map(&Map.keys/1)
        |> Enum.reject(&(&1 in [nil, ""]))
        |> Enum.uniq()

      {summaries, existing_ids} =
        Enum.map_reduce(summaries, MapSet.new(), fn summary, ids ->
          spacecraft_id = Map.get(summary, "spacecraft_id")

          {
            apply_resource_feedback_override(
              summary,
              margin_overrides,
              availability_overrides,
              operational_feedback_trust_boundary(feedback)
            ),
            if(spacecraft_id, do: MapSet.put(ids, spacecraft_id), else: ids)
          }
        end)

      missing_summaries =
        override_ids
        |> Enum.reject(&MapSet.member?(existing_ids, &1))
        |> Enum.map(fn spacecraft_id ->
          %{"schema_contract" => "resource_summary.v1", "spacecraft_id" => spacecraft_id}
          |> apply_resource_feedback_override(
            margin_overrides,
            availability_overrides,
            operational_feedback_trust_boundary(feedback)
          )
        end)

      summaries ++ missing_summaries
    end
  end

  defp apply_resource_feedback_override(
         summary,
         margin_overrides,
         availability_overrides,
         feedback_trust_boundary
       ) do
    spacecraft_id = Map.get(summary, "spacecraft_id")

    margin_override =
      margin_overrides
      |> Map.get(spacecraft_id, %{})
      |> normalize_resource_margin_aliases()

    availability_override = Map.get(availability_overrides, spacecraft_id, %{})

    summary
    |> merge_resource_feedback_fields(margin_override, [
      "fuel_margin",
      "power_margin",
      "storage_margin",
      "downlink_margin",
      "thermal_margin_c",
      "battery_capacity_wh",
      "battery_energy_used_wh",
      "battery_state_of_charge"
    ])
    |> drop_stale_resource_feedback_derivation_inputs(margin_override)
    |> merge_resource_feedback_boolean_fields(availability_override, [
      "payload_available",
      "antenna_available",
      "degraded"
    ])
    |> merge_resource_feedback_activity_type_fields(availability_override)
    |> merge_resource_mode_feedback(availability_override)
    |> merge_spacecraft_availability_feedback(availability_override)
    |> maybe_mark_resource_feedback_source(
      margin_override,
      availability_override,
      feedback_trust_boundary
    )
  end

  defp merge_resource_feedback_fields(summary, overrides, fields) when is_map(overrides) do
    overrides = stringify_keys(overrides)

    Enum.reduce(fields, summary, fn field, acc ->
      case Map.get(overrides, field) do
        value when is_boolean(value) ->
          Map.put(acc, field, value)

        value ->
          case numeric_value(value) do
            number when is_number(number) -> Map.put(acc, field, number)
            nil -> acc
          end
      end
    end)
  end

  defp merge_resource_feedback_fields(summary, _overrides, _fields), do: summary

  defp drop_stale_resource_feedback_derivation_inputs(summary, overrides)
       when is_map(overrides) do
    overrides = stringify_keys(overrides)

    summary
    |> maybe_drop_storage_derivation_inputs(overrides)
    |> maybe_drop_battery_derivation_inputs(overrides)
  end

  defp drop_stale_resource_feedback_derivation_inputs(summary, _overrides), do: summary

  defp maybe_drop_storage_derivation_inputs(summary, %{"storage_margin" => _margin}) do
    Map.drop(summary, ["storage_capacity_mb", "storage_used_mb"])
  end

  defp maybe_drop_storage_derivation_inputs(summary, _overrides), do: summary

  defp maybe_drop_battery_derivation_inputs(
         summary,
         %{"battery_state_of_charge" => _state} = overrides
       ) do
    if Map.has_key?(overrides, "battery_capacity_wh") and
         Map.has_key?(overrides, "battery_energy_used_wh") do
      summary
    else
      Map.drop(summary, ["battery_capacity_wh", "battery_energy_used_wh"])
    end
  end

  defp maybe_drop_battery_derivation_inputs(summary, _overrides), do: summary

  defp merge_resource_feedback_boolean_fields(summary, overrides, fields)
       when is_map(overrides) do
    overrides = stringify_keys(overrides)

    Enum.reduce(fields, summary, fn field, acc ->
      case boolean_value(Map.get(overrides, field)) do
        bool when is_boolean(bool) -> Map.put(acc, field, bool)
        nil -> acc
      end
    end)
  end

  defp merge_resource_feedback_boolean_fields(summary, _overrides, _fields), do: summary

  defp merge_resource_feedback_activity_type_fields(summary, overrides) when is_map(overrides) do
    overrides = stringify_keys(overrides)

    Enum.reduce(["suppressed_activity_types", "incompatible_activity_types"], summary, fn field,
                                                                                          acc ->
      case Map.get(overrides, field) do
        nil -> acc
        value -> Map.put(acc, field, value)
      end
    end)
  end

  defp merge_resource_feedback_activity_type_fields(summary, _overrides), do: summary

  defp merge_resource_mode_feedback(summary, overrides) when is_map(overrides) do
    overrides = stringify_keys(overrides)

    case Map.get(overrides, "mode") do
      mode when is_binary(mode) and mode != "" ->
        summary
        |> Map.put("mode", mode)
        |> maybe_mark_degraded_mode(mode)

      _mode ->
        summary
    end
  end

  defp merge_resource_mode_feedback(summary, _overrides), do: summary

  defp maybe_mark_degraded_mode(summary, mode) when mode in ["degraded", "degraded_mode", "safe"],
    do: Map.put(summary, "degraded", true)

  defp maybe_mark_degraded_mode(summary, _mode), do: summary

  defp merge_spacecraft_availability_feedback(summary, overrides) when is_map(overrides) do
    overrides = stringify_keys(overrides)

    if boolean_value(Map.get(overrides, "spacecraft_available")) == false or
         boolean_value(Map.get(overrides, "spacecraft_availability")) == false do
      summary
      |> Map.put("spacecraft_available", false)
      |> Map.put("payload_available", false)
      |> Map.put("antenna_available", false)
      |> Map.put("degraded", true)
    else
      summary
    end
  end

  defp merge_spacecraft_availability_feedback(summary, _overrides), do: summary

  defp maybe_mark_resource_feedback_source(
         summary,
         margin_override,
         availability_override,
         feedback_trust_boundary
       ) do
    if resource_feedback_override_applied?(margin_override) or
         resource_feedback_override_applied?(availability_override) do
      summary
      |> Map.put("source_quality", "operational_feedback")
      |> Map.update("provenance", %{}, fn
        provenance when is_map(provenance) -> provenance
        _provenance -> %{}
      end)
      |> put_in(["provenance", "resource_feedback_source"], "operational_feedback")
      |> put_in(
        ["provenance", "trust_boundary"],
        resource_feedback_trust_boundary(summary, feedback_trust_boundary)
      )
    else
      summary
    end
  end

  defp resource_feedback_trust_boundary(summary, "operational_feedback") do
    Map.get(summary, "trust_boundary") ||
      get_in(summary, ["provenance", "trust_boundary"]) ||
      "operational_feedback"
  end

  defp resource_feedback_trust_boundary(_summary, trust_boundary), do: trust_boundary

  defp operational_feedback_trust_boundary(%{"trust_boundary" => trust_boundary})
       when is_binary(trust_boundary) and trust_boundary != "",
       do: trust_boundary

  defp operational_feedback_trust_boundary(%{
         "provenance" => %{"trust_boundary" => trust_boundary}
       })
       when is_binary(trust_boundary) and trust_boundary != "",
       do: trust_boundary

  defp operational_feedback_trust_boundary(_feedback), do: "operational_feedback"

  defp resource_feedback_override_applied?(override) when is_map(override) do
    override
    |> Map.values()
    |> Enum.any?(&(is_number(&1) or is_boolean(&1) or nonempty_binary?(&1)))
  end

  defp resource_feedback_override_applied?(_override), do: false

  defp nonempty_binary?(value), do: is_binary(value) and value != ""

  defp apply_contact_filters(candidates, refresh) do
    ContactFilter.filter_candidates(candidates, refresh_ground_network(refresh),
      approval_policy: Map.get(refresh, "approval_policy")
    )
  end

  defp contact_allocation_report(candidates, refresh) do
    ContactAllocation.report(candidates, refresh_ground_network(refresh),
      source: "candidate_refresh.candidate_activities",
      policy: Map.get(refresh, "contact_allocation_policy", %{}),
      approval_policy: Map.get(refresh, "approval_policy")
    )
  end

  defp contact_allocation_candidates(candidates, contact_filter_report) do
    contact_filter_report
    |> Map.get("suppressed_candidates", [])
    |> Enum.filter(&candidate_contact?/1)
    |> then(&(candidates ++ &1))
  end

  defp apply_contact_allocation(candidates, contact_allocation_report) do
    usable_contact_ids =
      contact_allocation_report
      |> Map.get("rows", [])
      |> Enum.filter(&(&1["effective_allocation_status"] == "allocated"))
      |> Enum.map(& &1["contact_id"])
      |> MapSet.new()

    allocation_contact_ids =
      contact_allocation_report
      |> Map.get("rows", [])
      |> Enum.map(& &1["contact_id"])
      |> MapSet.new()

    {kept, dropped} =
      Enum.split_with(candidates, fn candidate ->
        contact_id = candidate_contact_id(candidate)

        is_nil(contact_id) or
          not MapSet.member?(allocation_contact_ids, contact_id) or
          MapSet.member?(usable_contact_ids, contact_id)
      end)

    {kept, dropped}
  end

  defp candidate_contact_id(candidate) do
    if candidate_contact?(candidate) do
      Map.get(candidate, "id") || Map.get(candidate, "contact_id") ||
        Map.get(candidate, "activity_id")
    end
  end

  defp candidate_contact?(%{"type" => "contact"}), do: true
  defp candidate_contact?(%{"type" => "downlink"}), do: true
  defp candidate_contact?(%{"type" => "planned_contact"}), do: true

  defp candidate_contact?(%{"direction" => direction})
       when direction in ["downlink", "uplink", "command", "tracking"],
       do: true

  defp candidate_contact?(_candidate), do: false

  defp contact_intents(candidates, refresh) do
    ContactIntent.from_activities(candidates,
      approval_policy: Map.get(refresh, "approval_policy")
    )
  end

  defp attach_candidate_activity_context(candidates) do
    Enum.map(candidates, fn candidate ->
      context = Timeline.activity_context(candidate)

      context =
        context
        |> Map.merge(candidate_objective_context(candidate))
        |> Map.merge(%{
          "activity_id" => Map.get(candidate, "id"),
          "activity_type" => Map.get(candidate, "type"),
          "timeline_id" => get_in(context, ["timeline_identity", "timeline_id"])
        })
        |> compact_map()

      Map.put(candidate, "activity_context", context)
    end)
  end

  defp candidate_objective_context(candidate) do
    candidate
    |> Map.take([
      "observation_objective_count",
      "observation_objective_ids",
      "observation_objective_source",
      "observation_objective_types",
      "collection_latency_objective_count",
      "collection_latency_objective_ids",
      "collection_latency_objective_source",
      "collection_latency_objective_types",
      "collection_id",
      "product_id",
      "product_ids",
      "payload_id",
      "instrument_id",
      "max_latency_s",
      "required_downlink_mb",
      "downlink_completion_objective_count",
      "source_capacity_adjusted_throughput_mb",
      "source_selected_capacity_adjusted_throughput_mb",
      "source_unused_capacity_adjusted_throughput_mb",
      "required_observations",
      "source_target",
      "source_target_id",
      "target_latitude_deg",
      "target_longitude_deg",
      "target_minimum_elevation_deg"
    ])
    |> compact_map()
  end

  defp station_state(refresh, ground_station_id, starts_at_s, ends_at_s, direction) do
    refresh
    |> refresh_ground_network()
    |> Enum.map(&stringify_keys/1)
    |> Enum.map(&normalize_ground_network_station/1)
    |> Enum.filter(fn station ->
      station_id = ground_network_station_id(station)

      station_id == encode_value(ground_station_id) and
        station_direction_matches?(station, direction) and
        station_window_matches?(station, starts_at_s, ends_at_s)
    end)
    |> unambiguous_highest_severity_station_state()
  end

  defp normalize_ground_network_station(station) do
    station
    |> normalize_ground_network_station_id()
    |> normalize_ground_network_station_field("availability")
    |> normalize_ground_network_station_field("status")
    |> normalize_ground_network_station_field("station_contention_status")
    |> normalize_ground_network_station_time("starts_at_s", "start_s")
    |> normalize_ground_network_station_time("ends_at_s", "end_s")
    |> normalize_ground_network_reservation_expires_at_s()
  end

  defp normalize_ground_network_station_id(%{"ground_station_id" => station_id} = station)
       when not is_nil(station_id),
       do: station

  defp normalize_ground_network_station_id(%{"station_id" => station_id} = station)
       when not is_nil(station_id),
       do: Map.put(station, "ground_station_id", station_id)

  defp normalize_ground_network_station_id(station) do
    case nested_station_id(station) do
      nil -> station
      station_id -> Map.put(station, "ground_station_id", station_id)
    end
  end

  defp normalize_ground_network_station_field(station, field) do
    case Map.fetch(station, field) do
      {:ok, value} when value in [nil, ""] ->
        station

      {:ok, value} ->
        Map.put(station, field, normalized_availability_token(encode_value(value)))

      :error ->
        station
    end
  end

  defp normalize_ground_network_station_time(station, canonical_key, alias_key) do
    case numeric_or_nil(Map.get(station, canonical_key)) ||
           numeric_or_nil(Map.get(station, alias_key)) do
      value when is_number(value) -> Map.put(station, canonical_key, value)
      _value -> station
    end
  end

  defp normalize_ground_network_reservation_expires_at_s(station) do
    [
      "reservation_expires_at_s",
      "station_reservation_expires_at_s",
      "reservation_hold_expires_at_s",
      "hold_expires_at_s",
      "expires_at_s",
      "expires_at"
    ]
    |> Enum.find_value(&(station |> Map.get(&1) |> numeric_or_nil()))
    |> case do
      value when is_number(value) -> Map.put(station, "reservation_expires_at_s", value)
      _value -> station
    end
  end

  defp ground_network_station_id(station) do
    Map.get(station, "ground_station_id") || Map.get(station, "station_id") ||
      Map.get(station, "id")
  end

  defp unambiguous_highest_severity_station_state([]), do: %{}

  defp unambiguous_highest_severity_station_state(stations) do
    reservations = Enum.filter(stations, &station_reserved?/1)

    stations
    |> Enum.group_by(&station_severity/1)
    |> Enum.max_by(fn {severity, _stations} -> severity end)
    |> elem(1)
    |> case do
      [station] ->
        station
        |> put_station_reservation_overlap(reservations)
        |> put_station_trust_context(stations)

      ambiguous_stations ->
        ambiguous_stations
        |> ambiguous_station_state(stations)
        |> put_station_trust_context(stations)
    end
  end

  defp ambiguous_station_state([station | _rest] = ambiguous_stations, stations) do
    ambiguous_entry_ids = station_entry_ids(ambiguous_stations)
    overlap_entry_ids = station_entry_ids(stations)

    %{
      "id" => ambiguous_station_entry_id(ambiguous_entry_ids),
      "station_calendar_entry_id" => ambiguous_station_entry_id(ambiguous_entry_ids),
      "ground_station_id" => ground_network_station_id(station),
      "status" => "ambiguous",
      "availability" => station_availability(station),
      "station_calendar_entry_ambiguous" => true,
      "station_calendar_ambiguous_entry_count" => length(ambiguous_stations),
      "station_calendar_ambiguous_entry_ids" => ambiguous_entry_ids,
      "station_calendar_overlap_count" => length(stations),
      "station_calendar_overlap_entry_ids" => overlap_entry_ids,
      "station_calendar_overlap_availabilities" =>
        stations |> Enum.map(&station_availability/1) |> Enum.uniq()
    }
    |> maybe_put("capacity_fraction", unambiguous_capacity_fraction(ambiguous_stations))
    |> put_ambiguous_station_reservation_context(stations)
  end

  defp station_entry_ids(stations) do
    stations
    |> Enum.with_index(1)
    |> Enum.map(fn {station, index} -> station_entry_id(station, index) end)
    |> Enum.sort()
  end

  defp station_entry_id(station, index) do
    Map.get(station, "id") || Map.get(station, "station_calendar_entry_id") ||
      Map.get(station, "reservation_id") || derived_station_entry_id(station, index)
  end

  defp station_calendar_entry_id(station) do
    Map.get(station, "station_calendar_entry_id") || Map.get(station, "id") ||
      get_in(station, ["source_station_calendar_entry", "station_calendar_entry_id"]) ||
      get_in(station, ["source_station_calendar_entry", "id"]) ||
      Map.get(station, "reservation_id")
  end

  defp station_calendar_provider_id(station) do
    Map.get(station, "station_calendar_provider_id") ||
      Map.get(station, "provider_id") ||
      get_in(station, ["source_station_calendar_entry", "station_calendar_provider_id"]) ||
      get_in(station, ["source_station_calendar_entry", "provider_id"]) ||
      get_in(station, ["provenance", "provider_id"])
  end

  defp station_calendar_provider_entry_id(station) do
    Map.get(station, "station_calendar_provider_entry_id") ||
      Map.get(station, "provider_entry_id") ||
      get_in(station, ["source_station_calendar_entry", "station_calendar_provider_entry_id"]) ||
      get_in(station, ["source_station_calendar_entry", "provider_entry_id"]) ||
      station_calendar_entry_id(station)
  end

  defp derived_station_entry_id(station, index) do
    [
      "ground_network",
      ground_network_station_id(station) || "unknown_station",
      station_availability(station),
      Map.get(station, "starts_at_s", "open"),
      Map.get(station, "ends_at_s", "open"),
      index
    ]
    |> Enum.map(&encode_value/1)
    |> Enum.join(":")
  end

  defp ambiguous_station_entry_id(entry_ids) do
    entry_ids
    |> then(&["ambiguous_station_calendar" | &1])
    |> Enum.join(":")
  end

  defp put_station_trust_context(station, stations) do
    trust_status = station_calendar_trust_boundary_status(stations)
    trust_boundary = station_calendar_trust_boundary(station)
    provenance = station_calendar_provenance(station)

    station
    |> Map.put("station_calendar_trust_boundary_status", trust_status)
    |> maybe_put("trust_boundary", trust_boundary)
    |> maybe_put("provenance", provenance)
    |> Map.put("source_station_calendar_entry", station)
    |> Map.put("source_station_calendar_overlaps", stations)
  end

  defp station_calendar_trust_boundary_status(stations) do
    if Enum.all?(stations, &(station_calendar_trust_boundary(&1) not in [nil, ""])),
      do: "declared",
      else: "missing"
  end

  defp station_calendar_trust_boundary(station) do
    Map.get(station, "trust_boundary") || get_in(station, ["provenance", "trust_boundary"])
  end

  defp station_calendar_provenance(%{"provenance" => provenance}) when is_map(provenance),
    do: provenance

  defp station_calendar_provenance(_station), do: nil

  defp unambiguous_capacity_fraction(stations) do
    stations
    |> Enum.map(&station_capacity_fraction/1)
    |> Enum.uniq()
    |> case do
      [capacity_fraction] -> capacity_fraction
      _ambiguous_capacity -> nil
    end
  end

  defp station_direction_matches?(station, direction) do
    case station_directions(station) do
      [] -> true
      directions -> normalize_direction(direction) in directions
    end
  end

  defp station_directions(station) do
    [
      Map.get(station, "directions"),
      Map.get(station, "station_calendar_directions"),
      Map.get(station, "direction"),
      get_in(station, ["source_station_calendar_entry", "directions"]),
      get_in(station, ["source_station_calendar_entry", "station_calendar_directions"]),
      get_in(station, ["source_station_calendar_entry", "direction"])
    ]
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.map(&normalize_direction/1)
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp nonempty_station_directions(station) do
    case station_directions(station) do
      [] -> nil
      directions -> directions
    end
  end

  defp normalize_direction(direction) when direction in [nil, ""], do: nil

  defp normalize_direction(direction) do
    direction
    |> encode_value()
    |> String.trim()
    |> String.downcase()
    |> String.replace(~r/[\s-]+/, "_")
    |> case do
      token when is_map_key(@provider_direction_aliases, token) ->
        Map.fetch!(@provider_direction_aliases, token)

      "nil" ->
        nil

      "" ->
        nil

      value ->
        value
    end
  end

  defp station_window_matches?(station, starts_at_s, ends_at_s) do
    case {Map.get(station, "starts_at_s"), Map.get(station, "ends_at_s")} do
      {nil, nil} ->
        true

      {start_s, end_s} when is_number(start_s) and is_number(end_s) ->
        ends_at_s > start_s and starts_at_s < end_s

      _other ->
        true
    end
  end

  defp station_severity(station) do
    cond do
      station_unavailable?(station) -> 4
      station_reserved?(station) -> 3
      station_capacity_fraction(station) < 1.0 -> 2
      true -> 1
    end
  end

  defp put_station_reservation_overlap(station, []), do: station

  defp put_station_reservation_overlap(station, reservations) do
    reservation_ids =
      reservations
      |> Enum.flat_map(fn station ->
        [Map.get(station, "reservation_id")] ++
          List.wrap(station["station_calendar_reservation_ids"])
      end)
      |> Enum.reject(&is_nil/1)
      |> Enum.uniq()
      |> Enum.sort()

    reserved_by =
      reservations
      |> Enum.flat_map(fn station ->
        [Map.get(station, "reserved_by")] ++ List.wrap(station["station_calendar_reserved_by"])
      end)
      |> Enum.reject(&is_nil/1)
      |> Enum.uniq()
      |> Enum.sort()

    reservation_statuses =
      reservations
      |> Enum.flat_map(fn station ->
        [station["reservation_status"]] ++
          List.wrap(station["station_calendar_reservation_statuses"])
      end)
      |> Enum.reject(&(&1 in [nil, ""]))
      |> case do
        [] -> ["reserved"]
        statuses -> statuses
      end
      |> Enum.uniq()
      |> Enum.sort()

    reservation_expires_at_s = station_calendar_reservation_expires_at_s(reservations) || []

    station
    |> Map.put_new("station_contention_status", "reserved_overlap")
    |> put_singular_reservation_field("reservation_id", reservation_ids)
    |> put_singular_reservation_field("reserved_by", reserved_by)
    |> put_singular_reservation_field("reservation_status", reservation_statuses)
    |> put_singular_reservation_field("reservation_expires_at_s", reservation_expires_at_s)
    |> Map.put("station_calendar_reservation_overlap_count", length(reservations))
    |> maybe_put_nonempty("station_calendar_reservation_ids", reservation_ids)
    |> maybe_put_nonempty("station_calendar_reserved_by", reserved_by)
    |> maybe_put_nonempty("station_calendar_reservation_statuses", reservation_statuses)
    |> maybe_put_nonempty("station_calendar_reservation_expires_at_s", reservation_expires_at_s)
  end

  defp put_singular_reservation_field(station, field, [value]) do
    Map.put_new(station, field, value)
  end

  defp put_singular_reservation_field(station, _field, _values), do: station

  defp put_ambiguous_station_reservation_context(station, stations) do
    reservations = Enum.filter(stations, &station_reserved?/1)

    case reservations do
      [] ->
        station

      reservations ->
        reservation_ids =
          reservations
          |> Enum.flat_map(fn station ->
            [Map.get(station, "reservation_id")] ++
              List.wrap(station["station_calendar_reservation_ids"])
          end)
          |> Enum.reject(&is_nil/1)
          |> Enum.uniq()
          |> Enum.sort()

        reserved_by =
          reservations
          |> Enum.flat_map(fn station ->
            [Map.get(station, "reserved_by")] ++
              List.wrap(station["station_calendar_reserved_by"])
          end)
          |> Enum.reject(&is_nil/1)
          |> Enum.uniq()
          |> Enum.sort()

        reservation_statuses =
          reservations
          |> Enum.flat_map(fn station ->
            [station["reservation_status"]] ++
              List.wrap(station["station_calendar_reservation_statuses"])
          end)
          |> Enum.reject(&(&1 in [nil, ""]))
          |> case do
            [] -> ["reserved"]
            statuses -> statuses
          end
          |> Enum.uniq()
          |> Enum.sort()

        reservation_expires_at_s = station_calendar_reservation_expires_at_s(reservations) || []

        station
        |> Map.put_new("station_contention_status", "reserved_overlap")
        |> Map.put("station_calendar_reservation_overlap_count", length(reservations))
        |> maybe_put_nonempty("station_calendar_reservation_ids", reservation_ids)
        |> maybe_put_nonempty("station_calendar_reserved_by", reserved_by)
        |> maybe_put_nonempty("station_calendar_reservation_statuses", reservation_statuses)
        |> maybe_put_nonempty(
          "station_calendar_reservation_expires_at_s",
          reservation_expires_at_s
        )
    end
  end

  defp station_reservation_expires_at_s(station) do
    [
      Map.get(station, "station_reservation_expires_at_s"),
      Map.get(station, "reservation_expires_at_s"),
      Map.get(station, "reservation_hold_expires_at_s"),
      Map.get(station, "hold_expires_at_s"),
      Map.get(station, "expires_at_s"),
      Map.get(station, "expires_at"),
      get_in(station, ["source_station_calendar_entry", "station_reservation_expires_at_s"]),
      get_in(station, ["source_station_calendar_entry", "reservation_expires_at_s"]),
      get_in(station, ["source_station_calendar_entry", "reservation_hold_expires_at_s"]),
      get_in(station, ["source_station_calendar_entry", "hold_expires_at_s"]),
      get_in(station, ["source_station_calendar_entry", "expires_at_s"]),
      get_in(station, ["source_station_calendar_entry", "expires_at"])
    ]
    |> Enum.find_value(&numeric_or_nil/1)
  end

  defp station_calendar_reservation_expires_at_s(stations) when is_list(stations) do
    stations
    |> Enum.flat_map(&station_calendar_reservation_expires_at_s_candidates/1)
    |> normalize_number_list()
  end

  defp station_calendar_reservation_expires_at_s(station) do
    station
    |> station_calendar_reservation_expires_at_s_candidates()
    |> normalize_number_list()
  end

  defp station_calendar_reservation_expires_at_s_candidates(%{} = station) do
    [
      Map.get(station, "station_calendar_reservation_expires_at_s"),
      Map.get(station, "station_reservation_expires_at_s"),
      Map.get(station, "reservation_expires_at_s"),
      station_provider_contention_values(station, "reservation_expires_at_s"),
      get_in(station, [
        "source_station_calendar_entry",
        "station_calendar_reservation_expires_at_s"
      ]),
      get_in(station, ["source_station_calendar_entry", "station_reservation_expires_at_s"]),
      get_in(station, ["source_station_calendar_entry", "reservation_expires_at_s"]),
      get_in(station, ["source_station_calendar_entry", "reservation_hold_expires_at_s"]),
      get_in(station, ["source_station_calendar_entry", "hold_expires_at_s"]),
      get_in(station, ["source_station_calendar_entry", "expires_at_s"]),
      source_station_calendar_overlap_reservation_expires_at_s(station)
    ]
  end

  defp station_calendar_reservation_expires_at_s_candidates(_station), do: []

  defp source_station_calendar_overlap_reservation_expires_at_s(%{
         "source_station_calendar_overlaps" => overlaps
       })
       when is_list(overlaps) do
    overlaps
    |> Enum.filter(&is_map/1)
    |> Enum.flat_map(&station_calendar_reservation_expires_at_s_candidates/1)
  end

  defp source_station_calendar_overlap_reservation_expires_at_s(_station), do: []

  defp station_unavailable?(station) do
    availability =
      station
      |> Map.get("availability")
      |> encode_value()
      |> normalized_availability_token()

    status =
      station
      |> Map.get("status")
      |> encode_value()
      |> normalized_availability_token()

    availability in @unavailable_station_tokens or
      status in @unavailable_station_tokens or
      Map.get(station, "available") == false
  end

  defp station_reserved?(station) do
    status =
      station
      |> Map.get("status")
      |> encode_value()
      |> normalized_availability_token()

    availability =
      station
      |> Map.get("availability")
      |> encode_value()
      |> normalized_availability_token()

    contention_status =
      station
      |> Map.get("station_contention_status")
      |> encode_value()
      |> normalized_availability_token()

    status == "reserved" or
      availability == "reserved" or
      contention_status == "reserved_overlap"
  end

  defp station_capacity_fraction(station) do
    station
    |> station_capacity_fraction_candidates()
    |> Enum.find_value(&unit_interval_capacity_fraction/1)
    |> case do
      nil -> 1.0
      capacity_fraction -> capacity_fraction
    end
  end

  defp station_capacity_fraction_candidates(station) do
    station_capacity_path_candidates(station) ++
      station_source_capacity_fraction_candidates(station)
  end

  defp station_source_capacity_fraction_candidates(%{"station_calendar_entry_ambiguous" => true}),
    do: []

  defp station_source_capacity_fraction_candidates(station) do
    source_station_capacity_fraction_candidates(Map.get(station, "source_station_calendar_entry")) ++
      source_station_capacity_fraction_candidates(
        Map.get(station, "source_station_calendar_overlaps")
      )
  end

  defp source_station_capacity_fraction_candidates(sources) when is_list(sources),
    do: Enum.flat_map(sources, &source_station_capacity_fraction_candidates/1)

  defp source_station_capacity_fraction_candidates(%{} = source) do
    station_capacity_path_candidates(source)
  end

  defp source_station_capacity_fraction_candidates(_source), do: []

  defp station_capacity_path_candidates(%{} = station) do
    Enum.map(@station_capacity_fraction_paths, &path_value(station, &1)) ++
      [capacity_percent_fraction(station)]
  end

  defp station_capacity_path_candidates(_station), do: []

  defp capacity_percent_fraction(%{} = station) do
    @station_capacity_percent_paths
    |> Enum.map(&path_value(station, &1))
    |> Enum.find_value(fn value ->
      case numeric_or_nil(value) do
        value when is_number(value) and value >= 0.0 and value <= 100.0 -> value / 100.0
        _value -> nil
      end
    end)
  end

  defp path_value(%{} = map, path), do: get_in(map, path)

  defp unit_interval_capacity_fraction(value) do
    case numeric_or_nil(value) do
      value when is_number(value) and value >= 0.0 and value <= 1.0 -> value
      value when is_number(value) -> value |> max(0.0) |> min(1.0)
      _value -> nil
    end
  end

  defp station_availability(station) do
    availability =
      station
      |> Map.get("availability")
      |> encode_value()
      |> normalized_availability_token()

    cond do
      availability in ["unavailable", "reserved", "reduced_capacity"] -> availability
      station_unavailable?(station) -> "unavailable"
      station_reserved?(station) -> "reserved"
      station_capacity_fraction(station) < 1.0 -> "reduced_capacity"
      true -> "available"
    end
  end

  defp normalized_availability_token(value) when is_binary(value) do
    value
    |> String.trim()
    |> String.downcase()
    |> String.replace(~r/[\s-]+/, "_")
    |> canonical_availability_token()
  end

  defp normalized_availability_token(value), do: value

  defp canonical_availability_token(value) when value in @unavailable_availability_aliases,
    do: "unavailable"

  defp canonical_availability_token(value), do: value

  defp station_contention_status(station) do
    Map.get(station, "station_contention_status") ||
      if station_reserved?(station), do: "reserved_overlap", else: nil
  end

  defp station_reservation_match_status(%{} = station) do
    cond do
      non_empty?(Map.get(station, "station_reservation_match_status")) ->
        Map.get(station, "station_reservation_match_status")

      non_empty?(Map.get(station, "reservation_match_status")) ->
        Map.get(station, "reservation_match_status")

      station_contention_status(station) == "reserved_overlap" ->
        station_reservation_overlap_match_status(station)

      true ->
        nil
    end
  end

  defp station_reservation_overlap_match_status(station) do
    reservation_ids = Map.get(station, "station_calendar_reservation_ids", [])
    reservation_id = Map.get(station, "reservation_id")

    cond do
      non_empty?(reservation_id) -> "overlap"
      is_list(reservation_ids) and length(reservation_ids) == 1 -> "overlap"
      is_list(reservation_ids) and length(reservation_ids) > 1 -> "ambiguous"
      true -> nil
    end
  end

  defp non_empty?(value), do: value not in [nil, ""]

  defp apply_resource_filters(candidates, refresh, [], []) do
    ResourceFilter.filter_candidates(candidates, [],
      policy: Map.get(refresh, "resource_filter_policy", %{}),
      approval_policy: Map.get(refresh, "approval_policy")
    )
  end

  defp apply_resource_filters(candidates, refresh, summaries, filter_summaries) do
    candidates
    |> add_resource_spacecraft_ids(refresh, summaries)
    |> ResourceFilter.filter_candidates(filter_summaries,
      policy: Map.get(refresh, "resource_filter_policy", %{}),
      approval_policy: Map.get(refresh, "approval_policy")
    )
  end

  defp apply_candidate_budget(candidates, refresh) do
    policy = candidate_limit_policy(refresh)
    max_candidates = Map.get(policy, "max_candidate_activities")
    indexed_candidates = Enum.with_index(candidates)

    selected_indexed_candidates =
      case max_candidates do
        value when is_integer(value) and value > 0 ->
          indexed_candidates
          |> Enum.sort_by(fn {candidate, _index} -> candidate_budget_sort_key(candidate) end)
          |> Enum.take(value)
          |> Enum.sort_by(fn {candidate, _index} -> candidate_artifact_sort_key(candidate) end)

        _value ->
          indexed_candidates
      end

    selected_indexes =
      selected_indexed_candidates
      |> Enum.map(fn {_candidate, index} -> index end)
      |> MapSet.new()

    selected_candidates =
      Enum.map(selected_indexed_candidates, fn {candidate, _index} -> candidate end)

    dropped_indexed_candidates =
      indexed_candidates
      |> Enum.reject(fn {_candidate, index} -> MapSet.member?(selected_indexes, index) end)
      |> Enum.sort_by(fn {candidate, _index} -> candidate_artifact_sort_key(candidate) end)

    dropped_candidates =
      Enum.map(dropped_indexed_candidates, fn {candidate, _index} -> candidate end)

    {
      selected_candidates,
      dropped_candidates,
      refresh_budget_report(
        candidates,
        selected_indexed_candidates,
        dropped_indexed_candidates,
        policy
      )
    }
  end

  defp candidate_limit_policy(refresh) do
    policy = raw_candidate_limit_policy(refresh)
    max_candidate_activities = if is_map(policy), do: Map.get(policy, "max_candidate_activities")
    normalized_max_candidate_activities = candidate_limit_count(max_candidate_activities)

    %{
      "max_candidate_activities" => normalized_max_candidate_activities,
      "invalid_candidate_limit_policy" => invalid_candidate_limit_policy?(policy),
      "invalid_candidate_limit_policy_reason" =>
        invalid_candidate_limit_policy_reason(policy, max_candidate_activities),
      "source_candidate_limit_policy" =>
        if(invalid_candidate_limit_policy?(policy), do: source_candidate_limit_policy(policy)),
      "selection_order" => "score_descending_then_start_then_id"
    }
    |> compact_map()
  end

  defp raw_candidate_limit_policy(%{"candidate_limit_policy" => policy}), do: policy
  defp raw_candidate_limit_policy(_refresh), do: %{}

  defp invalid_candidate_limit_policy?(policy) when not is_map(policy), do: true

  defp invalid_candidate_limit_policy?(%{"max_candidate_activities" => value}) do
    not is_integer(candidate_limit_count(value))
  end

  defp invalid_candidate_limit_policy?(_policy), do: false

  defp invalid_candidate_limit_policy_reason(policy, _value) when not is_map(policy),
    do: "candidate_limit_policy_must_be_object"

  defp invalid_candidate_limit_policy_reason(%{"max_candidate_activities" => value}, value)
       when is_integer(value) and value <= 0,
       do: "max_candidate_activities_must_be_positive"

  defp invalid_candidate_limit_policy_reason(%{"max_candidate_activities" => value}, value) do
    case {candidate_limit_count(value), numeric_value(value)} do
      {count, _number} when is_integer(count) ->
        nil

      {_count, number} when is_number(number) and number <= 0.0 ->
        "max_candidate_activities_must_be_positive"

      {_count, number} when is_number(number) ->
        "max_candidate_activities_must_be_integer"

      _value ->
        "max_candidate_activities_must_be_integer"
    end
  end

  defp invalid_candidate_limit_policy_reason(_policy, _value), do: nil

  defp candidate_limit_count(value) do
    case numeric_value(value) do
      number when is_number(number) and number > 0.0 and number == trunc(number) * 1.0 ->
        trunc(number)

      _value ->
        nil
    end
  end

  defp source_candidate_limit_policy(policy) when is_map(policy), do: policy

  defp source_candidate_limit_policy(policy) do
    %{"invalid_policy_shape" => encode_value(policy)}
  end

  defp refresh_budget_report(
         candidates,
         selected_indexed_candidates,
         dropped_indexed_candidates,
         policy
       ) do
    max_candidate_activities =
      Map.get(policy, "max_candidate_activities") || length(candidates)

    budget_id_by_index = candidate_budget_id_by_index(candidates)

    %{
      "schema_contract" => "refresh_budget_report.v1",
      "model" => "deterministic_candidate_limit_after_filters",
      "model_limits" => model_limits(),
      "input_candidate_count" => length(candidates),
      "kept_candidate_count" => length(selected_indexed_candidates),
      "dropped_candidate_count" => length(dropped_indexed_candidates),
      "max_candidate_activities" => max_candidate_activities,
      "invalid_candidate_limit_policy" => Map.get(policy, "invalid_candidate_limit_policy"),
      "invalid_candidate_limit_policy_reason" =>
        Map.get(policy, "invalid_candidate_limit_policy_reason"),
      "source_candidate_limit_policy" => Map.get(policy, "source_candidate_limit_policy"),
      "selection_order" => Map.fetch!(policy, "selection_order"),
      "kept_candidate_ids" =>
        candidate_budget_ids(selected_indexed_candidates, budget_id_by_index),
      "dropped_candidate_ids" =>
        candidate_budget_ids(dropped_indexed_candidates, budget_id_by_index),
      "assumptions" => %{
        "budget_stage" => "after_contact_resource_and_allocation_filters",
        "selection_policy" => "highest_score_candidates_are_kept_then_artifact_order_is_restored",
        "optimizer_search_performed" => false
      }
    }
    |> compact_map()
  end

  defp candidate_budget_id_by_index(candidates) do
    duplicate_ids =
      candidates
      |> Enum.map(&Map.get(&1, "id"))
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.frequencies()
      |> Enum.filter(fn {_id, count} -> count > 1 end)
      |> MapSet.new(fn {id, _count} -> id end)

    {_counts, id_by_index} =
      candidates
      |> Enum.with_index()
      |> Enum.reduce({%{}, %{}}, fn candidate, {counts, id_by_candidate} ->
        {candidate, index} = candidate
        candidate_id = Map.get(candidate, "id")
        occurrence = Map.get(counts, candidate_id, 0) + 1
        counts = Map.put(counts, candidate_id, occurrence)

        budget_id =
          if MapSet.member?(duplicate_ids, candidate_id) and occurrence > 1 do
            "#{candidate_id}:occurrence:#{occurrence}"
          else
            candidate_id
          end

        {counts, Map.put(id_by_candidate, index, budget_id)}
      end)

    id_by_index
  end

  defp candidate_budget_ids(indexed_candidates, id_by_index) do
    indexed_candidates
    |> Enum.map(fn {candidate, index} ->
      Map.get(id_by_index, index) || Map.get(candidate, "id")
    end)
  end

  defp candidate_budget_sort_key(candidate) do
    {
      -(Map.get(candidate, "score", 0.0) * 1.0),
      Map.get(candidate, "starts_at_s") || :infinity,
      Map.get(candidate, "ends_at_s") || :infinity,
      Map.get(candidate, "id") || ""
    }
  end

  defp candidate_artifact_sort_key(candidate) do
    {
      Map.get(candidate, "scenario_id") || "",
      Map.get(candidate, "starts_at_s") || :infinity,
      Map.get(candidate, "id") || ""
    }
  end

  defp add_resource_spacecraft_ids(candidates, refresh, summaries) do
    summary_ids =
      summaries
      |> Enum.map(&Map.get(&1, "spacecraft_id"))
      |> Enum.reject(&is_nil/1)
      |> MapSet.new()

    spacecraft_by_scenario =
      refresh
      |> spacecraft_identity_by_scenario()

    Enum.map(candidates, fn candidate ->
      spacecraft_id = Map.get(spacecraft_by_scenario, candidate["scenario_id"])

      if is_nil(candidate["spacecraft_id"]) and MapSet.member?(summary_ids, spacecraft_id) do
        Map.put(candidate, "spacecraft_id", spacecraft_id)
      else
        candidate
      end
    end)
  end

  defp warnings(
         refresh,
         candidates,
         result_set,
         contact_filter_report,
         allocation_dropped_candidates,
         resource_filter_report,
         refresh_budget_report,
         freshness_report
       ) do
    []
    |> maybe_warn(candidates == [], "no refreshed candidate activities were generated")
    |> maybe_warn(result_set.errors != [], "study completed with propagation or event errors")
    |> maybe_warn(
      Map.get(refresh, "prior_candidate_activities", []) == [],
      "no prior candidates compared"
    )
    |> maybe_warn(
      Map.get(contact_filter_report, "suppressed_candidate_count", 0) > 0,
      "ground network filters suppressed refreshed contact candidates"
    )
    |> maybe_warn(
      allocation_dropped_candidates != [],
      "contact allocation excluded refreshed contact candidates"
    )
    |> maybe_warn(
      Map.get(resource_filter_report, "suppressed_candidate_count", 0) > 0,
      "resource summary filters suppressed refreshed candidates"
    )
    |> maybe_warn(
      resource_summary_inputs_invalid_count(resource_filter_report) > 0,
      "resource summary inputs require operator review"
    )
    |> maybe_warn(
      source_resource_projection_report_invalid_input_count(refresh) > 0,
      "source resource projection reports include invalid inputs requiring review"
    )
    |> maybe_warn(
      source_resource_filter_report_invalid_resource_summary_input_count(refresh) > 0,
      "source resource filter reports include invalid resource summaries requiring review"
    )
    |> maybe_warn(
      source_contact_filter_report_invalid_contact_input_count(refresh) > 0,
      "source contact filter reports include invalid contact inputs requiring review"
    )
    |> maybe_warn(
      source_operational_timeline_report_integrity_issue_count(refresh) > 0,
      "source operational timeline reports include dependency or exclusivity integrity issues"
    )
    |> maybe_warn(
      Map.get(refresh_budget_report, "dropped_candidate_count", 0) > 0,
      "candidate refresh budget dropped candidate activities"
    )
    |> maybe_warn(
      Map.get(refresh_budget_report, "invalid_candidate_limit_policy") == true,
      "candidate refresh budget policy is invalid"
    )
    |> maybe_warn(
      Map.get(freshness_report, "status") == "stale",
      "candidate refresh freshness policy marked the snapshot, horizon, or state quality stale"
    )
    |> maybe_warn(
      Map.get(freshness_report, "status") == "unknown",
      "candidate refresh freshness could not be fully evaluated"
    )
    |> maybe_warn(
      invalid_operational_feedback_input?(refresh),
      "operational feedback input is invalid"
    )
    |> maybe_warn(
      invalid_operational_feedback_sections(refresh) != [],
      "operational feedback input is invalid"
    )
    |> maybe_warn(
      operational_feedback_trust_boundary_status(refresh) == "missing" and
        not invalid_operational_feedback_input?(refresh) and
        operational_feedback_applied?(refresh),
      "operational feedback was applied without a declared trust boundary"
    )
    |> Enum.reverse()
  end

