  defp source_report_summary_branch_family(refresh_or_artifact, family)
       when is_map(refresh_or_artifact) do
    refresh_or_artifact = stringify_keys(refresh_or_artifact)

    (get_in(refresh_or_artifact, [
       "candidate_source",
       "candidate_refresh_request_source_report_summary",
       "source_reports",
       family
     ]) ||
       get_in(refresh_or_artifact, [
         "assumptions",
         "candidate_source",
         "candidate_refresh_request_source_report_summary",
         "source_reports",
         family
       ]) ||
       get_in(refresh_or_artifact, [
         "candidate_refresh_request_source_report_summary",
         "source_reports",
         family
       ]) ||
       source_report_summary_branch_input_family(refresh_or_artifact, family))
    |> non_empty_map()
  end

  defp source_report_summary_branch_family(_refresh_or_artifact, _family), do: nil

  defp source_report_summary_branch_input_family(
         %{"candidate_source" => %{} = candidate_source},
         "contact_intent"
       ) do
    case source_report_input_provenance(candidate_source) do
      %{} = source_reports ->
        source_reports
        |> Map.get("contact_intent")
        |> source_report_summary_relabel_branch_paths()

      _source_reports ->
        nil
    end
