  defp source_report_summary_family_has_identity_counts?(source_reports, family) do
    case Map.get(source_reports, family) do
      %{} = summary ->
        not is_nil(Map.get(summary, "count")) and not is_nil(Map.get(summary, "row_count"))

      _summary ->
        false
