  defp source_report_summary_merge_string_lists(source_reports, field) do
    source_reports
    |> Map.values()
    |> Enum.flat_map(&(Map.get(&1, field) |> List.wrap()))
    |> sorted_string_values()
    |> case do
      [] -> nil
      values -> values
    end
  end

  defp source_report_summary_merge_numeric_lists(source_reports, field) do
    source_reports
    |> Map.values()
    |> Enum.flat_map(&(Map.get(&1, field) |> List.wrap()))
    |> normalize_number_list()
  end

  defp source_report_summary_family_merge_numeric_lists(source_reports, family, field) do
    source_reports
    |> Map.take([family])
    |> source_report_summary_merge_numeric_lists(field)
  end

  defp source_report_summary_family_merge_string_lists(source_reports, family, field) do
    source_reports
    |> Map.take([family])
    |> source_report_summary_merge_string_lists(field)
  end

  defp source_report_summary_counts_by_family(source_reports, field) do
    source_reports
    |> Enum.map(fn {family, source_report} ->
      {family, source_report |> numeric_report_count(field) |> report_count()}
    end)
    |> Enum.reject(fn {_family, count} -> count == 0 end)
    |> Map.new()
    |> non_empty_map()
  end

  defp source_report_summary_counts_by_value(source_reports, group_field, count_field) do
    source_reports
    |> Enum.reduce(%{}, fn {_family, source_report}, counts ->
      source_report
      |> Map.get(group_field)
      |> case do
        value when not is_binary(value) or value == "" ->
          counts

        value ->
          Map.update(counts, value, numeric_report_count(source_report, count_field), fn count ->
            count + numeric_report_count(source_report, count_field)
          end)
      end
    end)
    |> Enum.map(fn {value, count} -> {value, report_count(count)} end)
    |> Enum.reject(fn {_value, count} -> count == 0 end)
    |> Map.new()
    |> non_empty_map()
  end

  defp source_report_summary_values(source_reports, field) do
    source_reports
    |> Map.values()
    |> Enum.map(&Map.get(&1, field))
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp source_report_summary_paths(source_reports) do
    source_reports
    |> Enum.flat_map(fn {_family, source_report} -> source_report_paths(source_report) end)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp source_report_summary_paths_by_family(source_reports) do
    source_reports
    |> Enum.map(fn {family, source_report} ->
      {family, source_report_paths(source_report)}
    end)
    |> Enum.reject(fn {_family, paths} -> paths == [] end)
    |> Map.new()
    |> non_empty_map()
  end

  defp source_report_summary_paths_by_value(source_reports, field) do
    source_reports
    |> Enum.reduce(%{}, fn {_family, source_report}, grouped_paths ->
      source_report
      |> Map.get(field)
      |> case do
        value when not is_binary(value) or value == "" ->
          grouped_paths

        value ->
          Map.update(grouped_paths, value, source_report_paths(source_report), fn paths ->
            (paths ++ source_report_paths(source_report))
            |> Enum.uniq()
            |> Enum.sort()
          end)
      end
    end)
    |> non_empty_map()
  end

  defp source_report_paths(%{"paths" => paths}) when is_list(paths) do
    paths
    |> Enum.filter(&is_binary/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp source_report_paths(%{"path" => path}) when is_binary(path), do: [path]
  defp source_report_paths(_source_report), do: []

  defp source_report_summary_count_values(source_reports, field) do
    source_reports
    |> Map.values()
    |> Enum.map(fn source_report -> Map.get(source_report, field) end)
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
    |> Enum.reduce(%{}, fn value, counts ->
      Map.update(counts, value, 1, &(&1 + 1))
    end)
    |> non_empty_map()
  end

