  defp source_timeline_activity_state_action_routing(states) do
    rows =
      states
      |> Enum.flat_map(&timeline_activity_state_rows_for_summary/1)
      |> Enum.filter(&present_timeline_activity_state_action?/1)

    rows
    |> Enum.group_by(&Map.get(&1, "required_operator_action"))
    |> Map.delete(nil)
    |> Map.delete("none")
    |> Enum.map(fn {action, action_rows} ->
      route =
        %{
          "review_count" => length(action_rows),
          "activity_ids" =>
            action_rows
            |> Enum.flat_map(&timeline_activity_state_row_ids(&1, "activity_id"))
            |> sorted_string_values(),
          "timeline_ids" =>
            action_rows
            |> Enum.flat_map(&timeline_activity_state_row_ids(&1, "timeline_id"))
            |> sorted_string_values(),
          "status_transition_categories" =>
            action_rows
            |> Enum.map(&get_in(&1, ["status_transition", "transition_category"]))
            |> sorted_string_values(),
          "approval_transition_categories" =>
            action_rows
            |> Enum.map(&get_in(&1, ["approval_transition", "transition_category"]))
            |> sorted_string_values()
        }
        |> compact_map()

      {action, route}
    end)
    |> Map.new()
    |> non_empty_map()
  end

  defp timeline_activity_state_rows_for_summary(%{"rows" => rows} = state) when is_list(rows) do
    rows
    |> Enum.map(&stringify_keys/1)
    |> Enum.filter(&is_map/1)
    |> case do
      [] -> [Map.delete(state, "rows")]
      row_maps -> row_maps
    end
  end

  defp timeline_activity_state_rows_for_summary(%{} = state), do: [stringify_keys(state)]
  defp timeline_activity_state_rows_for_summary(_state), do: []

  defp timeline_activity_state_review_required?(%{} = row) do
    Map.get(row, "review_required") == true or
      Map.get(row, "requires_operator_review") == true
  end

  defp timeline_activity_state_review_required?(_row), do: false

  defp present_timeline_activity_state_action?(%{} = row) do
    present_timeline_activity_state_action?(Map.get(row, "required_operator_action"))
  end

  defp present_timeline_activity_state_action?(action) when action in [nil, "", "none"],
    do: false

  defp present_timeline_activity_state_action?(_action), do: true

  defp timeline_activity_state_row_ids(row, "activity_id") do
    [
      row["activity_id"],
      row["planned_activity_id"],
      row["realized_activity_id"],
      get_in(row, ["timeline_identity", "activity_id"]),
      get_in(row, ["source_activity_context", "activity_id"]),
      get_in(row, ["source_activity_context", "id"]),
      get_in(row, ["realized_activity_context", "activity_id"]),
      get_in(row, ["realized_activity_context", "id"])
    ] ++ List.wrap(Map.get(row, "activity_ids")) ++ List.wrap(Map.get(row, "review_activity_ids"))
  end

  defp timeline_activity_state_row_ids(row, "timeline_id") do
