  defp source_timeline_activity_lifecycle_state_action_routing(states) do
    states
    |> Enum.flat_map(fn state ->
      state
      |> timeline_activity_lifecycle_state_required_actions()
      |> Enum.reject(&(&1 in [nil, "", "none"]))
      |> Enum.map(&{&1, state})
    end)
    |> Enum.group_by(fn {action, _state} -> action end, fn {_action, state} -> state end)
    |> Enum.map(fn {action, action_states} ->
      route =
        %{
          "review_count" => length(action_states),
          "activity_ids" =>
            action_states
            |> Enum.flat_map(&timeline_activity_state_row_ids(&1, "activity_id"))
            |> sorted_string_values(),
          "timeline_ids" =>
            action_states
            |> Enum.flat_map(&timeline_activity_state_row_ids(&1, "timeline_id"))
            |> sorted_string_values(),
          "status_transition_categories" =>
            action_states
            |> Enum.map(&get_in(&1, ["status_transition", "transition_category"]))
            |> sorted_string_values(),
          "approval_transition_categories" =>
            action_states
            |> Enum.map(&get_in(&1, ["approval_transition", "transition_category"]))
            |> sorted_string_values(),
          "protection_categories" =>
            action_states
            |> Enum.flat_map(fn state ->
              [
                get_in(state, ["planned_protection_decision", "protection_category"]),
                get_in(state, ["realized_protection_decision", "protection_category"])
              ]
            end)
            |> sorted_string_values()
        }
        |> compact_map()

      {action, route}
    end)
    |> Map.new()
    |> non_empty_map()
  end

