  defp source_timeline_lifecycle_state_review_routing(summaries) do
    action_counts =
      summaries
      |> Enum.map(&Map.get(&1, "required_operator_action_counts", %{}))
      |> merge_count_maps()
      |> Map.delete("none")
      |> empty_map_if_nil()

    timeline_ids_by_action =
      summaries
      |> Enum.map(&Map.get(&1, "review_timeline_ids_by_required_operator_action", %{}))
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    rows_by_action =
      summaries
      |> Enum.flat_map(fn summary ->
        summary
        |> Map.get("review_rows", [])
        |> List.wrap()
        |> Enum.filter(&is_map/1)
      end)
      |> Enum.group_by(&Map.get(&1, "required_operator_action"))
      |> Map.delete(nil)
      |> Map.delete("none")

    [
      Map.keys(action_counts),
      Map.keys(timeline_ids_by_action),
      Map.keys(rows_by_action)
    ]
    |> List.flatten()
    |> Enum.map(&to_string/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> Map.new(fn action ->
      rows = Map.get(rows_by_action, action, [])

      route =
        %{
          "review_count" => Map.get(action_counts, action, length(rows)),
          "activity_ids" =>
            rows
            |> Enum.flat_map(&timeline_lifecycle_state_row_activity_ids/1)
            |> sorted_string_values(),
          "timeline_ids" =>
            (Map.get(timeline_ids_by_action, action, []) ++ Enum.map(rows, & &1["timeline_id"]))
            |> sorted_string_values(),
          "status_transition_categories" =>
            rows
            |> Enum.map(&get_in(&1, ["status_transition", "transition_category"]))
            |> sorted_string_values(),
          "approval_transition_categories" =>
            rows
            |> Enum.map(&get_in(&1, ["approval_transition", "transition_category"]))
            |> sorted_string_values()
        }
        |> compact_map()

      {action, route}
    end)
    |> non_empty_map()
  end

