      "capacity_pack_required_contact_count" =>
        capacity_pack_demand["capacity_pack_required_contact_count"],
      "capacity_pack_required_capacity_fraction" =>
        capacity_pack_demand["capacity_pack_required_capacity_fraction"],
      "capacity_pack_required_capacity_fraction_by_ground_station" =>
        capacity_pack_demand["capacity_pack_required_capacity_fraction_by_ground_station_id"],
      "capacity_pack_required_capacity_fraction_by_direction" =>
        capacity_pack_demand["capacity_pack_required_capacity_fraction_by_direction"],
      "capacity_pack_required_capacity_fraction_by_direction_and_ground_station" =>
        capacity_pack_demand[
          "capacity_pack_required_capacity_fraction_by_direction_and_ground_station_id"
        ],
      "required_capacity_fraction_source_counts" =>
        capacity_pack_demand["required_capacity_fraction_source_counts"],
      "required_capacity_fraction_contact_ids_by_source" =>
        capacity_pack_demand["required_capacity_fraction_contact_ids_by_source"],
      "capacity_pack_contact_ids_by_ground_station" =>
        capacity_pack_demand["capacity_pack_contact_ids_by_ground_station_id"],
      "contact_ids_by_ground_station" => capacity_pack_demand["contact_ids_by_ground_station_id"],
      "capacity_pack_contact_ids_by_direction" =>
        capacity_pack_demand["capacity_pack_contact_ids_by_direction"],
      "capacity_pack_contact_ids_by_direction_and_ground_station" =>
        capacity_pack_demand["capacity_pack_contact_ids_by_direction_and_ground_station_id"],
      "contact_ids_by_direction_and_ground_station" =>
        capacity_pack_demand["contact_ids_by_direction_and_ground_station_id"],
      "directions" => directions,
      "direction_counts" => direction_counts,
      "contact_ids_by_direction" => contact_ids_by_direction,
      "direction_routing" =>
        contact_intent_direction_routing(
          direction_counts,
          contact_ids_by_direction,
          capacity_pack_demand["capacity_pack_required_capacity_fraction_by_direction"],
          capacity_pack_demand["capacity_pack_contact_ids_by_direction"],
          capacity_pack_demand["contact_ids_by_direction_and_ground_station_id"],
          capacity_pack_demand[
            "capacity_pack_required_capacity_fraction_by_direction_and_ground_station_id"
          ],
          capacity_pack_demand["capacity_pack_contact_ids_by_direction_and_ground_station_id"]
        ),
      "trust_boundary_status" => source_contact_intent_trust_boundary_status(intents),
      "trust_boundaries" => source_contact_intent_trust_boundaries(intents)
    }
    |> compact_map()
  end

  defp source_contact_intent_compact_summary_input_summary([]), do: nil

  defp source_contact_intent_compact_summary_input_summary(sources) do
    summaries = Enum.map(sources, fn {_path, summary} -> summary end)

    contact_ids_by_direction =
      merge_string_list_maps(Enum.map(summaries, & &1["contact_ids_by_direction"]))

    capacity_contact_ids_by_direction =
      merge_string_list_maps(Enum.map(summaries, & &1["capacity_pack_contact_ids_by_direction"]))

    required_by_direction =
      summaries
      |> Enum.map(&Map.get(&1, "capacity_pack_required_capacity_fraction_by_direction"))
      |> merge_numeric_maps()

    required_by_direction_and_station =
      summaries
      |> Enum.map(
        &Map.get(
          &1,
          "capacity_pack_required_capacity_fraction_by_direction_and_ground_station_id"
        )
      )
      |> merge_nested_numeric_maps()

    contact_ids_by_direction_and_station =
      summaries
      |> Enum.map(&Map.get(&1, "contact_ids_by_direction_and_ground_station_id"))
      |> merge_nested_string_list_maps()

    capacity_contact_ids_by_direction_and_station =
      summaries
      |> Enum.map(&Map.get(&1, "capacity_pack_contact_ids_by_direction_and_ground_station_id"))
      |> merge_nested_string_list_maps()

    directions =
      contact_intent_summary_directions(summaries, contact_ids_by_direction)

    %{
      "paths" => Enum.map(sources, fn {path, _summary} -> path end),
      "contract" => source_contact_intent_summary_contract(summaries),
      "count" => length(sources),
      "row_count" =>
        summaries
        |> Enum.map(&numeric_report_count(&1, "contact_intent_count"))
        |> Enum.sum()
        |> report_count(),
      "source_summary_model_counts" => count_report_field_values(summaries, "model"),
      "source_summary_schema_contract_counts" =>
        count_report_field_values(summaries, "schema_contract"),
      "source_artifact_type_counts" =>
        count_report_field_values(summaries, "source_artifact_type"),
      "station_feedback_count" => 0,
      "capacity_pack_required_contact_count" =>
        summaries
        |> Enum.map(&numeric_report_count(&1, "capacity_pack_required_contact_count"))
        |> Enum.sum()
        |> report_count(),
      "capacity_pack_required_capacity_fraction" =>
        summaries
        |> Enum.map(&numeric_value(Map.get(&1, "capacity_pack_required_capacity_fraction")))
        |> Enum.filter(&is_number/1)
        |> case do
          [] -> nil
          values -> Enum.sum(values)
        end,
      "capacity_pack_required_capacity_fraction_by_ground_station" =>
        summaries
        |> Enum.map(&Map.get(&1, "capacity_pack_required_capacity_fraction_by_ground_station_id"))
        |> merge_numeric_maps(),
      "capacity_pack_required_capacity_fraction_by_direction" => required_by_direction,
      "capacity_pack_required_capacity_fraction_by_direction_and_ground_station" =>
        required_by_direction_and_station,
      "required_capacity_fraction_source_counts" =>
        summaries
        |> Enum.map(&Map.get(&1, "required_capacity_fraction_source_counts"))
        |> merge_count_maps(),
      "required_capacity_fraction_contact_ids_by_source" =>
        summaries
        |> Enum.map(&Map.get(&1, "required_capacity_fraction_contact_ids_by_source"))
        |> merge_string_list_maps(),
      "capacity_pack_contact_ids_by_ground_station" =>
        summaries
        |> Enum.map(&Map.get(&1, "capacity_pack_contact_ids_by_ground_station_id"))
        |> merge_string_list_maps(),
      "contact_ids_by_ground_station" =>
        summaries
        |> Enum.map(&Map.get(&1, "contact_ids_by_ground_station_id"))
        |> merge_string_list_maps(),
      "capacity_pack_contact_ids_by_direction" => capacity_contact_ids_by_direction,
      "capacity_pack_contact_ids_by_direction_and_ground_station" =>
        capacity_contact_ids_by_direction_and_station,
      "contact_ids_by_direction_and_ground_station" => contact_ids_by_direction_and_station,
      "directions" => directions,
      "direction_counts" => string_list_map_counts(contact_ids_by_direction),
      "contact_ids_by_direction" => contact_ids_by_direction,
      "direction_routing" =>
        contact_intent_direction_routing(
          string_list_map_counts(contact_ids_by_direction),
          contact_ids_by_direction,
          required_by_direction,
          capacity_contact_ids_by_direction,
          contact_ids_by_direction_and_station,
          required_by_direction_and_station,
          capacity_contact_ids_by_direction_and_station
        ),
      "trust_boundary_status" => source_contact_intent_trust_boundary_status(summaries),
      "trust_boundaries" => source_contact_intent_trust_boundaries(summaries)
    }
    |> compact_map()
  end

  defp merge_source_contact_intent_input_summaries(summaries) do
    summaries = Enum.reject(summaries, &is_nil/1)

    case summaries do
      [] ->
        nil

      summaries ->
        direction_counts = merge_count_maps(Enum.map(summaries, & &1["direction_counts"]))

        contact_ids_by_direction =
          merge_string_list_maps(Enum.map(summaries, & &1["contact_ids_by_direction"]))

        capacity_contact_ids_by_direction =
          merge_string_list_maps(
            Enum.map(summaries, & &1["capacity_pack_contact_ids_by_direction"])
          )

        required_by_direction =
          summaries
          |> Enum.map(&Map.get(&1, "capacity_pack_required_capacity_fraction_by_direction"))
          |> merge_numeric_maps()

        required_by_direction_and_station =
          summaries
          |> Enum.map(
            &Map.get(
              &1,
              "capacity_pack_required_capacity_fraction_by_direction_and_ground_station"
            )
          )
          |> merge_nested_numeric_maps()

        contact_ids_by_direction_and_station =
          summaries
          |> Enum.map(&Map.get(&1, "contact_ids_by_direction_and_ground_station"))
          |> merge_nested_string_list_maps()

        capacity_contact_ids_by_direction_and_station =
          summaries
          |> Enum.map(&Map.get(&1, "capacity_pack_contact_ids_by_direction_and_ground_station"))
          |> merge_nested_string_list_maps()

        directions =
          contact_intent_summary_directions(summaries, contact_ids_by_direction)

        %{
          "paths" => merge_string_lists(Enum.map(summaries, & &1["paths"])),
          "contract" => source_contact_intent_summary_contract(summaries),
          "count" =>
            summaries
            |> Enum.map(&numeric_report_count(&1, "count"))
            |> Enum.sum()
            |> report_count(),
          "row_count" =>
            summaries
            |> Enum.map(&numeric_report_count(&1, "row_count"))
            |> Enum.sum()
            |> report_count(),
          "source_summary_model_counts" =>
            merge_count_maps(Enum.map(summaries, & &1["source_summary_model_counts"])),
          "source_summary_schema_contract_counts" =>
            merge_count_maps(Enum.map(summaries, & &1["source_summary_schema_contract_counts"])),
          "source_artifact_type_counts" =>
            merge_count_maps(Enum.map(summaries, & &1["source_artifact_type_counts"])),
          "station_feedback_count" =>
            summaries
            |> Enum.map(&numeric_report_count(&1, "station_feedback_count"))
            |> Enum.sum()
            |> report_count(),
          "station_calendar_status_counts" =>
            merge_count_maps(Enum.map(summaries, & &1["station_calendar_status_counts"])),
          "cadence_import_status_counts" =>
            merge_count_maps(Enum.map(summaries, & &1["cadence_import_status_counts"])),
          "policy_classification_counts" =>
            merge_count_maps(Enum.map(summaries, & &1["policy_classification_counts"])),
          "capacity_pack_required_contact_count" =>
            summaries
            |> Enum.map(&numeric_report_count(&1, "capacity_pack_required_contact_count"))
            |> Enum.sum()
            |> report_count(),
          "capacity_pack_required_capacity_fraction" =>
            summaries
            |> Enum.map(&numeric_value(Map.get(&1, "capacity_pack_required_capacity_fraction")))
            |> Enum.filter(&is_number/1)
            |> case do
              [] -> nil
              values -> Enum.sum(values)
            end,
          "capacity_pack_required_capacity_fraction_by_ground_station" =>
            summaries
            |> Enum.map(
              &Map.get(&1, "capacity_pack_required_capacity_fraction_by_ground_station")
            )
            |> merge_numeric_maps(),
          "capacity_pack_required_capacity_fraction_by_direction" => required_by_direction,
          "capacity_pack_required_capacity_fraction_by_direction_and_ground_station" =>
            required_by_direction_and_station,
          "required_capacity_fraction_source_counts" =>
            merge_count_maps(
              Enum.map(summaries, & &1["required_capacity_fraction_source_counts"])
            ),
          "required_capacity_fraction_contact_ids_by_source" =>
            merge_string_list_maps(
              Enum.map(summaries, & &1["required_capacity_fraction_contact_ids_by_source"])
            ),
          "capacity_pack_contact_ids_by_ground_station" =>
            merge_string_list_maps(
              Enum.map(summaries, & &1["capacity_pack_contact_ids_by_ground_station"])
            ),
          "contact_ids_by_ground_station" =>
            merge_string_list_maps(Enum.map(summaries, & &1["contact_ids_by_ground_station"])),
          "capacity_pack_contact_ids_by_direction" => capacity_contact_ids_by_direction,
          "capacity_pack_contact_ids_by_direction_and_ground_station" =>
            capacity_contact_ids_by_direction_and_station,
          "contact_ids_by_direction_and_ground_station" => contact_ids_by_direction_and_station,
          "directions" => directions,
          "direction_counts" => direction_counts,
          "contact_ids_by_direction" => contact_ids_by_direction,
          "direction_routing" =>
            contact_intent_direction_routing(
              direction_counts,
              contact_ids_by_direction,
              required_by_direction,
              capacity_contact_ids_by_direction,
              contact_ids_by_direction_and_station,
              required_by_direction_and_station,
              capacity_contact_ids_by_direction_and_station
            ),
          "trust_boundary_status" =>
            source_contact_intent_summary_trust_boundary_status(summaries),
          "trust_boundaries" => merge_string_lists(Enum.map(summaries, & &1["trust_boundaries"]))
        }
        |> compact_map()
    end
  end

  defp source_contact_intent_summary_contract(summaries) do
    summaries
    |> Enum.map(&Map.get(&1, "contract", Map.get(&1, "schema_contract")))
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [contract] -> contract
      [] -> nil
      contracts -> Enum.join(Enum.sort(contracts), "+")
    end
  end

  defp source_contact_intent_summary_trust_boundary_status(summaries) do
    statuses =
      summaries
      |> Enum.map(&Map.get(&1, "trust_boundary_status"))
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.uniq()

    cond do
      statuses == [] -> nil
      "declared" in statuses -> "declared"
      true -> Enum.sort(statuses) |> List.first()
    end
  end

  defp string_list_map_counts(%{} = list_map) do
    list_map
    |> Enum.map(fn {key, values} -> {key, length(list_value(values))} end)
    |> Enum.reject(fn {_key, count} -> count == 0 end)
    |> Map.new()
    |> non_empty_map()
  end

  defp string_list_map_counts(_list_map), do: nil

  defp contact_intent_summary_directions(summaries, contact_ids_by_direction) do
    summaries
    |> Enum.map(&Map.get(&1, "directions"))
    |> merge_string_lists()
    |> case do
      nil ->
        contact_intent_direction_keys(contact_ids_by_direction)

      directions ->
        directions
    end
  end

  defp contact_intent_direction_keys(%{} = contact_ids_by_direction) do
    contact_ids_by_direction
    |> Map.keys()
    |> sorted_non_empty_values()
  end

  defp contact_intent_direction_keys(_contact_ids_by_direction), do: nil

  defp source_contact_intent_capacity_pack_demand(intents) do
    ContactIntent.summary(intents)
  end

  defp contact_intent_direction_counts(intents) do
    intents
    |> contact_intent_direction_contact_pairs()
    |> grouped_source_report_id_counts()
  end

  defp contact_intent_contact_ids_by_direction(intents) do
    intents
    |> contact_intent_direction_contact_pairs()
    |> grouped_source_report_ids()
  end

  defp contact_intent_direction_routing(
         direction_counts,
         contact_ids_by_direction,
         required_capacity_by_direction,
         capacity_contact_ids_by_direction,
         contact_ids_by_direction_and_station,
         required_capacity_by_direction_and_station,
         capacity_contact_ids_by_direction_and_station
       ) do
    direction_counts = direction_counts || %{}
    contact_ids_by_direction = map_value_lists(contact_ids_by_direction) || %{}
    capacity_contact_ids_by_direction = map_value_lists(capacity_contact_ids_by_direction) || %{}

    contact_ids_by_direction_and_station =
      nested_map_value_lists(contact_ids_by_direction_and_station) || %{}

    capacity_contact_ids_by_direction_and_station =
      nested_map_value_lists(capacity_contact_ids_by_direction_and_station) || %{}

    required_capacity_by_direction =
      case normalize_numeric_map(required_capacity_by_direction) do
        nil -> %{}
        values -> values
      end

    required_capacity_by_direction_and_station =
      nested_normalize_numeric_map(required_capacity_by_direction_and_station) || %{}

    [
      Map.keys(direction_counts),
      Map.keys(contact_ids_by_direction),
      Map.keys(required_capacity_by_direction),
      Map.keys(capacity_contact_ids_by_direction),
      Map.keys(contact_ids_by_direction_and_station),
      Map.keys(required_capacity_by_direction_and_station),
      Map.keys(capacity_contact_ids_by_direction_and_station)
    ]
    |> List.flatten()
    |> Enum.map(&to_string/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> Map.new(fn direction ->
      route =
        %{
          "contact_count" => Map.get(direction_counts, direction),
          "contact_ids" => Map.get(contact_ids_by_direction, direction, []),
          "capacity_pack_required_capacity_fraction" =>
            Map.get(required_capacity_by_direction, direction),
          "capacity_pack_contact_ids" =>
            Map.get(capacity_contact_ids_by_direction, direction, []),
          "ground_station_ids" =>
            contact_ids_by_direction_and_station
            |> Map.get(direction, %{})
            |> Map.keys()
            |> Enum.sort(),
          "contact_ids_by_ground_station" =>
            Map.get(contact_ids_by_direction_and_station, direction, %{}),
          "capacity_pack_required_capacity_fraction_by_ground_station" =>
            Map.get(required_capacity_by_direction_and_station, direction, %{}),
          "capacity_pack_contact_ids_by_ground_station" =>
            Map.get(capacity_contact_ids_by_direction_and_station, direction, %{})
        }
        |> Enum.reject(fn
          {"capacity_pack_contact_ids", []} -> false
          {_key, value} when value in [nil, %{}, []] -> true
          _entry -> false
        end)
        |> Map.new()

      {direction, route}
    end)
    |> non_empty_map()
  end

  defp nested_map_value_lists(%{} = value_map) do
    value_map
    |> Enum.reduce(%{}, fn {outer_key, inner_map}, acc ->
      case map_value_lists(inner_map) do
        nil -> acc
        values -> Map.put(acc, to_string(outer_key), values)
      end
    end)
    |> non_empty_map()
  end

  defp nested_map_value_lists(_value_map), do: nil

  defp normalize_numeric_map(%{} = value_map) do
    value_map
    |> Enum.reduce(%{}, fn {key, value}, acc ->
      case numeric_value(value) do
        value when is_number(value) -> Map.put(acc, to_string(key), value)
        _value -> acc
      end
    end)
    |> non_empty_map()
  end

  defp normalize_numeric_map(_value), do: nil

  defp nested_normalize_numeric_map(%{} = value_map) do
    value_map
    |> Enum.reduce(%{}, fn {outer_key, inner_map}, acc ->
      case normalize_numeric_map(inner_map) do
        nil -> acc
        values -> Map.put(acc, to_string(outer_key), values)
      end
    end)
    |> non_empty_map()
  end

  defp nested_normalize_numeric_map(_value_map), do: nil

  defp contact_intent_direction_contact_pairs(intents) do
    intents
    |> Enum.map(&stringify_keys/1)
    |> Enum.map(fn intent ->
      {contact_intent_direction(intent), contact_intent_stable_id(intent)}
    end)
    |> Enum.reject(fn {direction, contact_id} ->
      direction in [nil, ""] or contact_id in [nil, ""]
    end)
  end

  defp contact_intent_direction(intent) do
    [
      intent["direction"],
      intent["activity_type"],
      intent["type"],
      get_in(intent, ["activity_context", "direction"]),
      get_in(intent, ["source_activity", "direction"]),
      get_in(intent, ["source_activity", "activity_context", "direction"])
    ]
    |> Enum.map(&normalize_direction/1)
    |> Enum.find(&(&1 not in [nil, ""]))
  end

  defp contact_intent_stable_id(intent) do
    [
      intent["id"],
      intent["contact_id"],
      intent["activity_id"],
      intent["source_contact_id"],
      get_in(intent, ["activity_context", "contact_id"]),
      get_in(intent, ["activity_context", "id"]),
      get_in(intent, ["source_activity", "id"]),
      get_in(intent, ["source_activity", "contact_id"])
    ]
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.find(&(&1 not in [nil, ""]))
  end

