  defp contact_contention_resolution_input_summary_contract(reports) do
    reports
    |> Enum.map(fn report ->
      Map.get(report, "source_summary_schema_contract") || Map.get(report, "schema_contract")
    end)
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
    |> Enum.uniq()
    |> case do
      [contract] -> contract
      [] -> nil
      _contracts -> "contact_contention_resolution_report.v1"
    end
  end

  defp sum_report_count(reports, counter) do
    reports
    |> Enum.map(counter)
    |> Enum.map(&report_count/1)
    |> Enum.sum()
  end

  defp sum_report_numeric_values(reports, counter) do
    values =
      reports
      |> Enum.map(counter)
      |> Enum.map(&numeric_value/1)
      |> Enum.filter(&is_number/1)

    case values do
      [] -> nil
      values -> Enum.sum(values)
    end
  end

  defp source_report_feedback_input_keys(reports, feedback_fun) do
    reports
    |> Enum.flat_map(fn report ->
      report
      |> feedback_fun.()
      |> operational_feedback_data_keys()
    end)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp merge_count_maps(count_maps) do
    count_maps
    |> Enum.reject(&(&1 in [nil, %{}]))
    |> Enum.reduce(%{}, fn count_map, acc ->
      Enum.reduce(count_map, acc, fn {key, value}, acc ->
        Map.update(acc, key, value, fn
          current when is_integer(current) and is_integer(value) -> current + value
          current -> current
        end)
      end)
    end)
    |> non_empty_map()
  end

  defp merge_numeric_maps(numeric_maps) do
    numeric_maps
    |> Enum.reject(&(&1 in [nil, %{}]))
    |> Enum.reduce(%{}, fn numeric_map, acc ->
      Enum.reduce(numeric_map, acc, fn {key, value}, acc ->
        case numeric_value(value) do
          value when is_number(value) -> Map.update(acc, key, value, &(&1 + value))
          _value -> acc
        end
      end)
    end)
    |> non_empty_map()
  end

  defp merge_nested_numeric_maps(numeric_maps) do
    numeric_maps
    |> Enum.reject(&(&1 in [nil, %{}]))
    |> Enum.reduce(%{}, fn numeric_map, acc ->
      Enum.reduce(numeric_map, acc, fn {outer_key, inner_map}, acc ->
        case inner_map do
          %{} ->
            merged_inner =
              merge_numeric_maps([Map.get(acc, to_string(outer_key), %{}), inner_map])

            if is_nil(merged_inner) do
              acc
            else
              Map.put(acc, to_string(outer_key), merged_inner)
            end

          _inner_map ->
            acc
        end
      end)
    end)
    |> non_empty_map()
  end

  defp merge_string_lists(lists) do
    lists
    |> Enum.flat_map(&List.wrap/1)
    |> sorted_non_empty_values()
  end

  defp merge_string_list_maps(list_maps) do
    list_maps
    |> Enum.reject(&(&1 in [nil, %{}]))
    |> Enum.reduce(%{}, fn list_map, acc ->
      Enum.reduce(list_map, acc, fn {key, values}, acc ->
        values =
          values
          |> list_value()
          |> Enum.reject(&(&1 in [nil, ""]))
          |> Enum.map(&to_string/1)

        Map.update(acc, to_string(key), values, fn current ->
          (current ++ values)
          |> Enum.uniq()
        end)
      end)
    end)
    |> non_empty_map()
  end

  defp merge_nested_string_list_maps(list_maps) do
    list_maps
    |> Enum.reject(&(&1 in [nil, %{}]))
    |> Enum.reduce(%{}, fn list_map, acc ->
      Enum.reduce(list_map, acc, fn {outer_key, inner_map}, acc ->
        case inner_map do
          %{} ->
            merged_inner =
              merge_string_list_maps([Map.get(acc, to_string(outer_key), %{}), inner_map])

            if is_nil(merged_inner) do
              acc
            else
              Map.put(acc, to_string(outer_key), merged_inner)
            end

          _inner_map ->
            acc
        end
      end)
    end)
    |> non_empty_map()
  end

  defp merge_numeric_list_maps(list_maps) do
    list_maps
    |> Enum.reject(&(&1 in [nil, %{}]))
    |> Enum.reduce(%{}, fn list_map, acc ->
      Enum.reduce(list_map, acc, fn {key, values}, acc ->
        values =
          values
          |> List.wrap()
          |> normalize_number_list()
          |> case do
            nil -> []
            numbers -> numbers
          end

        if values == [] do
          acc
        else
          Map.update(acc, to_string(key), values, fn current ->
            (current ++ values)
            |> Enum.uniq()
            |> Enum.sort()
          end)
        end
      end)
    end)
    |> non_empty_map()
  end

  defp map_value_lists(%{} = value_map) do
    value_map
    |> Enum.reduce(%{}, fn {key, values}, acc ->
      case sorted_string_values(List.wrap(values)) do
        [] -> acc
        values -> Map.put(acc, to_string(key), values)
      end
    end)
    |> non_empty_map()
  end

  defp map_value_lists(_value), do: nil

  defp grouped_source_report_ids(pairs) do
    pairs
    |> Enum.reject(fn {key, value} -> key in [nil, ""] or value in [nil, ""] end)
    |> Enum.group_by(fn {key, _value} -> to_string(key) end, fn {_key, value} -> value end)
    |> Map.new(fn {key, values} -> {key, sorted_non_empty_values(values)} end)
    |> non_empty_map()
  end

  defp grouped_source_report_id_counts(pairs) do
    pairs
    |> grouped_source_report_ids()
    |> case do
      nil -> nil
      ids_by_key -> Map.new(ids_by_key, fn {key, ids} -> {key, length(ids)} end)
    end
  end

  defp sorted_non_empty_values(values) do
    values
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.map(&to_string/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      values -> values
    end
  end

