    pressure_reports
    |> Enum.reduce(%{}, fn {_family, summary}, acc ->
      case Map.get(summary, "trust_boundary_status") do
        status when is_binary(status) and status != "" ->
          count = summary_integer(summary, "count")
          Map.update(acc, status, count, &(&1 + count))

        _status ->
          acc
      end
    end)
  end

