  defp station_availability_reason_counts_from_context(%{} = context) do
    station_counts =
      context
      |> Map.get("station_availability_reason_counts")
      |> station_availability_reason_count_map()

    resource_counts =
      context
      |> Map.get("resource_availability_reason_counts")
      |> station_availability_reason_count_map()

    if station_counts in [nil, %{}], do: resource_counts || %{}, else: station_counts
  end

  defp station_availability_reason_counts_from_context(_context), do: %{}

  defp station_availability_reason_count_map(%{} = counts) do
    counts
    |> Enum.reduce(%{}, fn {reason, count}, acc ->
      reason = normalized_timeline_diff_token(reason)

      if reason in operational_readiness_station_reasons() and is_integer(count) and count > 0 do
        Map.update(acc, reason, count, &(&1 + count))
      else
        acc
      end
    end)
  end

  defp station_availability_reason_count_map(_counts), do: %{}

