      resource_projection_map_keys(resource_pressure_direction_counts),
      resource_projection_map_keys(resource_pressure_activity_ids_by_direction)
    ]
    |> List.flatten()
    |> sorted_non_empty_values()
  end

  defp resource_projection_pressure_direction_routing(
         resource_pressure_direction_counts,
         resource_pressure_activity_ids_by_direction
       ) do
    resource_pressure_direction_counts = resource_pressure_direction_counts || %{}

    resource_pressure_activity_ids_by_direction =
      map_value_lists(resource_pressure_activity_ids_by_direction) || %{}

    [
      resource_projection_map_keys(resource_pressure_direction_counts),
      resource_projection_map_keys(resource_pressure_activity_ids_by_direction)
    ]
    |> List.flatten()
    |> Enum.map(&to_string/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> Map.new(fn direction ->
      route =
        %{
          "pressure_count" => Map.get(resource_pressure_direction_counts, direction),
          "activity_ids" => Map.get(resource_pressure_activity_ids_by_direction, direction, [])
        }
        |> compact_map()

      {direction, route}
    end)
    |> non_empty_map()
  end

  defp resource_projection_map_keys(%{} = map), do: Map.keys(map)
  defp resource_projection_map_keys(_map), do: []

  defp resource_projection_report_pressure_activity_pairs(report, key_fun) do
    report
    |> Map.get("projected_resources", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.flat_map(fn row ->
      keys =
        key_fun.(row)
        |> List.wrap()
        |> Enum.reject(&(&1 in [nil, ""]))

      activity_ids =
        row
        |> resource_projection_source_activity_ids()
        |> List.wrap()

      for key <- keys, activity_id <- activity_ids, do: {key, activity_id}
    end)
    |> Enum.uniq()
  end

