  defp resource_filter_row_suppressed_reason_candidate_pairs(row) do
    suppressed_reason = normalized_timeline_diff_token(row["suppressed_reason"])
    row_candidate_id = resource_filter_row_candidate_id(row)

    row
    |> contact_filter_row_source_contact_values()
    |> Kernel.++([row])
    |> Enum.map(fn candidate ->
      {normalized_timeline_diff_token(candidate["suppressed_reason"]) || suppressed_reason,
       resource_filter_row_candidate_id(candidate) || row_candidate_id}
    end)
    |> Enum.reject(fn {reason, candidate_id} ->
      reason in [nil, ""] or candidate_id in [nil, ""]
