  defp contact_contention_direction_routing(reports) do
    direction_counts =
      reports
      |> Enum.map(&contact_contention_report_direction_counts/1)
      |> merge_count_maps()
      |> empty_map_if_nil()

    contact_ids_by_direction =
      reports
      |> Enum.map(&contact_contention_report_contact_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    [
      Map.keys(direction_counts),
      Map.keys(contact_ids_by_direction)
    ]
    |> List.flatten()
    |> Enum.map(&to_string/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> Map.new(fn direction ->
      route =
        %{
          "contact_count" => Map.get(direction_counts, direction),
          "contact_ids" => Map.get(contact_ids_by_direction, direction, [])
        }
        |> compact_map()

      {direction, route}
    end)
    |> non_empty_map()
  end

