    report
    |> Map.get("conflict_groups", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.flat_map(&contact_contention_group_direction_contact_pairs/1)
  end

  defp contact_contention_group_direction_contact_pairs(group) do
    source_contacts =
      group
      |> Map.get("source_contact_candidates", [])
      |> List.wrap()
      |> List.flatten()
      |> Enum.filter(&is_map/1)
      |> Enum.map(&stringify_keys/1)

    case source_contacts do
      [] -> contact_contention_group_fallback_direction_contact_pairs(group)
      contacts -> Enum.map(contacts, &contact_contention_contact_direction_pair(&1, group))
    end
    |> Enum.reject(fn {direction, contact_id} ->
      direction in [nil, ""] or contact_id in [nil, ""]
    end)
    |> Enum.uniq()
  end

  defp contact_contention_group_fallback_direction_contact_pairs(group) do
    directions = contact_contention_group_directions(group)

    contact_ids =
      group
      |> Map.get("contact_ids", [])
      |> List.wrap()
      |> List.flatten()
      |> Enum.map(&stable_id_or_nil/1)
      |> Enum.reject(&is_nil/1)

    for direction <- directions, contact_id <- contact_ids, do: {direction, contact_id}
  end

  defp contact_contention_contact_direction_pair(contact, group) do
    direction =
      [
        contact["direction"],
        contact["type"],
        get_in(contact, ["activity_context", "direction"]),
        group["direction"]
      ]
      |> Enum.map(&normalize_direction/1)
      |> Enum.find(&(&1 not in [nil, "", "mixed", "contact"]))

    contact_id =
      [
        contact["contact_id"],
        contact["id"],
        contact["activity_id"],
        get_in(contact, ["activity_context", "contact_id"]),
        get_in(contact, ["activity_context", "id"])
      ]
      |> Enum.map(&stable_id_or_nil/1)
      |> Enum.find(&(&1 not in [nil, ""]))

    {direction, contact_id}
  end

  defp contact_contention_group_directions(group) do
    [
      group["directions"],
      group["direction"]
    ]
    |> List.flatten()
    |> Enum.map(&normalize_direction/1)
    |> Enum.reject(&(&1 in [nil, "", "mixed", "contact"]))
    |> Enum.uniq()
  end

