  defp contact_filter_report_direction_counts(report) do
    report
    |> contact_filter_report_direction_contact_pairs()
    |> case do
      [] ->
        report
        |> Map.get("direction_counts")
        |> normalize_direction_count_map()

      pairs ->
        grouped_source_report_id_counts(pairs)
    end
  end

  defp contact_filter_report_contact_ids_by_direction(report) do
    report
    |> contact_filter_report_direction_contact_pairs()
    |> case do
      [] ->
        report
        |> Map.get("contact_ids_by_direction")
        |> map_value_lists()

      pairs ->
        grouped_source_report_ids(pairs)
    end
  end

  defp contact_filter_report_direction_keys(direction_counts, contact_ids_by_direction) do
    [
      contact_filter_map_keys(direction_counts),
      contact_filter_map_keys(contact_ids_by_direction)
    ]
    |> List.flatten()
    |> sorted_non_empty_values()
  end

  defp contact_filter_direction_routing(direction_counts, contact_ids_by_direction) do
    direction_counts = direction_counts || %{}
    contact_ids_by_direction = map_value_lists(contact_ids_by_direction) || %{}

    [
      contact_filter_map_keys(direction_counts),
      contact_filter_map_keys(contact_ids_by_direction)
    ]
    |> List.flatten()
    |> Enum.map(&to_string/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> Map.new(fn direction ->
      route =
        %{
          "contact_count" => Map.get(direction_counts, direction),
          "contact_ids" => Map.get(contact_ids_by_direction, direction, [])
        }
        |> compact_map()

      {direction, route}
    end)
    |> non_empty_map()
  end

  defp contact_filter_map_keys(%{} = map), do: Map.keys(map)
  defp contact_filter_map_keys(_map), do: []

  defp contact_filter_report_direction_contact_pairs(report) do
    report
    |> Map.get("suppressed_candidates", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.flat_map(&contact_filter_row_direction_contact_pairs/1)
  end

  defp contact_filter_row_direction_contact_pairs(row) do
    row_direction = contact_filter_row_summary_direction(row)
    row_contact_id = contact_filter_row_contact_id(row)

    row
    |> contact_filter_row_source_contact_values()
    |> Kernel.++([row])
    |> Enum.map(fn contact ->
      {contact_filter_row_summary_direction(contact) || row_direction,
       contact_filter_row_contact_id(contact) || row_contact_id}
    end)
    |> Enum.reject(fn {direction, contact_id} ->
      direction in [nil, ""] or contact_id in [nil, ""]
    end)
    |> Enum.uniq()
  end

  defp contact_filter_row_source_contact_values(row) do
    [
      row["source_contact_candidate"],
      row["source_contact_candidates"],
      row["source_candidate"],
      row["contact_candidate"],
      row["source_contact"],
      row["source_contacts"],
      row["contact"]
    ]
    |> Enum.flat_map(&List.wrap/1)
    |> List.flatten()
    |> Enum.filter(&is_map/1)
    |> Enum.map(&stringify_keys/1)
  end

  defp contact_filter_row_summary_direction(row) do
    [
      row["direction"],
      row["type"],
      get_in(row, ["activity_context", "direction"]),
      get_in(row, ["source_activity_context", "direction"]),
      get_in(row, ["source_contact_candidate", "direction"]),
      get_in(row, ["source_contact_candidate", "activity_context", "direction"]),
      get_in(row, ["contact_candidate", "direction"]),
      get_in(row, ["contact_candidate", "activity_context", "direction"])
    ]
    |> Enum.map(&normalize_direction/1)
    |> Enum.find(&(&1 not in [nil, ""]))
  end

  defp contact_filter_row_contact_id(row) do
    [
      row["contact_id"],
      row["id"],
      row["candidate_id"],
      row["source_contact_id"],
      row["source_candidate_id"],
      get_in(row, ["activity_context", "contact_id"]),
      get_in(row, ["activity_context", "id"]),
      get_in(row, ["source_contact_candidate", "contact_id"]),
      get_in(row, ["source_contact_candidate", "id"]),
      get_in(row, ["contact_candidate", "contact_id"]),
      get_in(row, ["contact_candidate", "id"])
    ]
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.find(&(&1 not in [nil, ""]))
  end

  defp normalize_direction_count_map(%{} = counts) do
    counts
    |> Enum.reduce(%{}, fn {direction, count}, acc ->
      case {normalize_direction(direction), numeric_value(count)} do
        {nil, _count} -> acc
        {_direction, nil} -> acc
        {direction, count} -> Map.update(acc, direction, trunc(count), &(&1 + trunc(count)))
      end
    end)
    |> non_empty_map()
  end

  defp normalize_direction_count_map(_counts), do: nil

