  defp contact_filter_report_station_suppression_contact_ids_by(rows, key_fun) do
    contact_filter_report_station_suppression_ids_by(
      rows,
      key_fun,
      &contact_filter_row_contact_id/1
    )
  end

  defp contact_filter_report_station_suppression_ids_by(rows, key_fun, id_fun) do
    rows
    |> Enum.reduce(%{}, fn row, acc ->
      key = key_fun.(row)
      identifier = id_fun.(row)

      if key in [nil, ""] or identifier in [nil, ""] do
        acc
      else
        Map.update(acc, key, [identifier], fn current ->
          ([identifier] ++ current)
          |> Enum.uniq()
          |> Enum.sort()
        end)
      end
    end)
    |> non_empty_map()
  end

  defp contact_filter_row_station_calendar_entry_id(row) do
    source_contact =
      row
      |> contact_filter_row_source_contact_values()
      |> Enum.find(fn contact ->
        stable_id_or_nil(contact["station_calendar_entry_id"] || contact["id"]) not in [nil, ""]
      end)

    stable_id_or_nil(row["station_calendar_entry_id"]) ||
      stable_id_or_nil(
        get_in(row, ["source_station_calendar_entry", "station_calendar_entry_id"])
      ) ||
      stable_id_or_nil(get_in(row, ["source_station_calendar_entry", "id"])) ||
      stable_id_or_nil(source_contact && source_contact["station_calendar_entry_id"])
  end

  defp contact_filter_row_station_calendar_provider_entry_id(row) do
    source_contact =
      row
      |> contact_filter_row_source_contact_values()
      |> Enum.find(fn contact ->
        stable_id_or_nil(
          contact["station_calendar_provider_entry_id"] || contact["provider_entry_id"]
        ) not in [nil, ""]
      end)

    stable_id_or_nil(row["station_calendar_provider_entry_id"] || row["provider_entry_id"]) ||
      stable_id_or_nil(
        get_in(row, ["station_calendar_entry", "station_calendar_provider_entry_id"])
      ) ||
      stable_id_or_nil(get_in(row, ["station_calendar_entry", "provider_entry_id"])) ||
      stable_id_or_nil(
        get_in(row, ["source_station_calendar_entry", "station_calendar_provider_entry_id"])
      ) ||
      stable_id_or_nil(get_in(row, ["source_station_calendar_entry", "provider_entry_id"])) ||
      stable_id_or_nil(
        source_contact &&
          (source_contact["station_calendar_provider_entry_id"] ||
             source_contact["provider_entry_id"])
      )
  end

  defp contact_filter_row_station_reservation_id(row) do
