  defp command_window_direction_routing(reports) do
    direction_counts =
      reports
      |> Enum.map(&command_window_report_direction_counts/1)
      |> merge_count_maps()
      |> empty_map_if_nil()

    activity_ids_by_direction =
      reports
      |> Enum.map(&command_window_report_activity_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    window_ids_by_direction =
      reports
      |> Enum.map(&command_window_report_window_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    [
      Map.keys(direction_counts),
      Map.keys(activity_ids_by_direction),
      Map.keys(window_ids_by_direction)
    ]
    |> List.flatten()
    |> Enum.map(&to_string/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> Map.new(fn direction ->
      route =
        %{
          "activity_count" => Map.get(direction_counts, direction),
          "activity_ids" => Map.get(activity_ids_by_direction, direction, []),
          "window_ids" => Map.get(window_ids_by_direction, direction, [])
        }
        |> compact_map()

      {direction, route}
    end)
    |> non_empty_map()
  end

