  defp timeline_transition_application_report_application_count(report) do
    cond do
      timeline_transition_application_summary_source?(report) ->
        numeric_report_count(report, "application_count")

      true ->
        case timeline_transition_application_report_rows(report) do
          [] -> numeric_report_count(report, "application_count")
          rows -> length(rows)
        end
    end
  end

  defp timeline_transition_application_report_source_row_count(report) do
    cond do
      timeline_transition_application_summary_source?(report) ->
        timeline_transition_application_first_numeric_report_count(report, [
          "source_report_row_count",
          "row_count",
          "application_count"
        ])

      true ->
        case timeline_transition_application_report_rows(report) do
          [] ->
            timeline_transition_application_first_numeric_report_count(report, [
              "row_count",
              "application_count"
            ])

          rows ->
            length(rows)
        end
    end
  end

  defp timeline_transition_application_first_numeric_report_count(report, fields) do
    fields
    |> Enum.find_value(fn field ->
      case numeric_value(Map.get(report, field)) do
        value when is_number(value) -> report_count(value)
        _value -> nil
      end
    end)
    |> Kernel.||(0)
  end

  defp timeline_transition_application_summary_source?(%{} = report) do
    (Map.get(report, "source_summary_schema_contract") || Map.get(report, "schema_contract")) ==
      "timeline_transition_application_summary.v1"
  end

  defp timeline_transition_application_summary_source?(_report), do: false

  defp timeline_transition_application_summary_count_or_row_count(
         report,
         top_level_field,
         row_predicate
       ) do
    if timeline_transition_application_summary_source?(report) do
      numeric_report_count(report, top_level_field)
    else
      timeline_transition_application_report_row_count(report, top_level_field, row_predicate)
    end
  end

  defp timeline_transition_application_summary_counts_or_row_counts(
         report,
         top_level_field,
         row_field
       ) do
    if timeline_transition_application_summary_source?(report) do
      Map.get(report, top_level_field)
    else
      timeline_transition_application_report_row_counts(report, top_level_field, row_field)
    end
  end

