    activity = stringify_keys(activity)

    stable_id_or_nil(
      activity["activity_id"] ||
        activity["id"] ||
        get_in(activity, ["timeline_identity", "activity_id"]) ||
        get_in(activity, ["timeline_identity", "id"])
    )
