  defp station_calendar_direction_routing(reports) do
    direction_counts =
      reports
      |> Enum.map(&station_calendar_report_direction_counts/1)
      |> merge_count_maps()
      |> empty_map_if_nil()

    contact_ids_by_direction =
      reports
      |> Enum.map(&station_calendar_report_contact_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    station_calendar_entry_ids_by_direction =
      reports
      |> Enum.map(&station_calendar_report_entry_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    station_reservation_ids_by_direction =
      reports
      |> Enum.map(&station_calendar_report_reservation_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    station_capacity_fractions_by_direction =
      reports
      |> Enum.map(&station_calendar_report_capacity_fractions_by_direction/1)
      |> merge_numeric_list_maps()
      |> empty_map_if_nil()

    provider_contention_direction_counts =
      reports
      |> Enum.map(&station_calendar_report_provider_contention_direction_counts/1)
      |> merge_count_maps()
      |> empty_map_if_nil()

    provider_contention_group_ids_by_direction =
      reports
      |> Enum.map(&station_calendar_report_provider_contention_group_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    provider_contention_source_entry_ids_by_direction =
      reports
      |> Enum.map(&station_calendar_report_provider_contention_source_entry_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    provider_contention_provider_ids_by_direction =
      reports
      |> Enum.map(&station_calendar_report_provider_contention_provider_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    provider_contention_provider_entry_ids_by_direction =
      reports
      |> Enum.map(&station_calendar_report_provider_contention_provider_entry_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    provider_contention_capacity_fractions_by_direction =
      reports
      |> Enum.map(&station_calendar_report_provider_contention_capacity_fractions_by_direction/1)
      |> merge_numeric_list_maps()
      |> empty_map_if_nil()

    [
      Map.keys(direction_counts),
      Map.keys(contact_ids_by_direction),
      Map.keys(station_calendar_entry_ids_by_direction),
      Map.keys(station_reservation_ids_by_direction),
      Map.keys(station_capacity_fractions_by_direction),
      Map.keys(provider_contention_direction_counts),
      Map.keys(provider_contention_group_ids_by_direction),
      Map.keys(provider_contention_source_entry_ids_by_direction),
      Map.keys(provider_contention_provider_ids_by_direction),
      Map.keys(provider_contention_provider_entry_ids_by_direction),
      Map.keys(provider_contention_capacity_fractions_by_direction)
    ]
    |> List.flatten()
    |> Enum.map(&to_string/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> Map.new(fn direction ->
      route =
        %{
          "contact_count" => Map.get(direction_counts, direction),
          "contact_ids" => Map.get(contact_ids_by_direction, direction, []),
          "station_calendar_entry_ids" =>
            Map.get(station_calendar_entry_ids_by_direction, direction, []),
          "station_reservation_ids" =>
            Map.get(station_reservation_ids_by_direction, direction, []),
          "station_capacity_fractions" =>
            Map.get(station_capacity_fractions_by_direction, direction, []),
          "provider_contention_group_count" =>
            Map.get(provider_contention_direction_counts, direction),
          "provider_contention_group_ids" =>
            Map.get(provider_contention_group_ids_by_direction, direction, []),
          "provider_contention_source_entry_ids" =>
            Map.get(provider_contention_source_entry_ids_by_direction, direction, []),
          "provider_contention_provider_ids" =>
            Map.get(provider_contention_provider_ids_by_direction, direction, []),
          "provider_contention_provider_entry_ids" =>
            Map.get(provider_contention_provider_entry_ids_by_direction, direction, []),
          "provider_contention_capacity_fractions" =>
            Map.get(provider_contention_capacity_fractions_by_direction, direction, [])
        }
        |> compact_map()

      {direction, route}
    end)
    |> non_empty_map()
  end

