  defp station_reservation_direction_routing(
         direction_counts,
         contact_ids_by_direction,
         reservation_hold_ids_by_direction,
         reservation_hold_contact_ids_by_direction
       ) do
    direction_counts = empty_map_if_nil(direction_counts)
    contact_ids_by_direction = map_value_lists(contact_ids_by_direction) || %{}
    reservation_hold_ids_by_direction = map_value_lists(reservation_hold_ids_by_direction) || %{}

    reservation_hold_contact_ids_by_direction =
      map_value_lists(reservation_hold_contact_ids_by_direction) || %{}

    [
      station_reservation_map_keys(direction_counts),
      station_reservation_map_keys(contact_ids_by_direction),
      station_reservation_map_keys(reservation_hold_ids_by_direction),
      station_reservation_map_keys(reservation_hold_contact_ids_by_direction)
    ]
    |> List.flatten()
    |> Enum.map(&to_string/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> Map.new(fn direction ->
      route =
        %{
          "contact_count" => Map.get(direction_counts, direction),
          "contact_ids" => Map.get(contact_ids_by_direction, direction, []),
          "reservation_hold_ids" => Map.get(reservation_hold_ids_by_direction, direction, []),
          "reservation_hold_contact_ids" =>
            Map.get(reservation_hold_contact_ids_by_direction, direction, [])
        }
        |> compact_map()

      {direction, route}
    end)
    |> non_empty_map()
  end

