  defp link_capacity_report_row_count(report) do
    cond do
      link_capacity_summary_source?(report) ->
        summary_integer(report, "station_count")

      is_list(Map.get(report, "rows")) ->
        length(Map.get(report, "rows"))

      true ->
        1
    end
  end

  defp link_capacity_summary_source?(%{} = report) do
    Map.get(report, "source_summary_schema_contract") == "link_capacity_summary.v1" or
      Map.get(report, "schema_contract") == "link_capacity_summary.v1"
  end

  defp link_capacity_summary_source?(_report), do: false

  defp link_capacity_report_count_or_row_count(report, summary_field, row_counter) do
    if link_capacity_summary_source?(report) do
      link_capacity_summary_count_value(report, summary_field)
    else
      row_counter.(report)
    end
  end

  defp link_capacity_summary_count_value(report, field) do
    case Map.get(report, field) do
      values when is_list(values) -> length(values)
      %{} = values -> map_size(values)
      value -> summary_integer(%{"value" => value}, "value")
    end
  end

  defp link_capacity_report_numeric_map_or_summary(report, summary_field, row_field) do
    if link_capacity_summary_source?(report) do
      report |> Map.get(summary_field) |> normalize_numeric_map()
    else
      link_capacity_report_row_numeric_values_by_ground_station(report, row_field)
    end
  end

  defp link_capacity_report_string_list_map_or_summary(report, summary_field, row_fun) do
    if link_capacity_summary_source?(report) do
      link_capacity_report_explicit_string_list_map(report, summary_field)
    else
      row_fun.(report)
    end
  end

  defp link_capacity_report_string_list_or_summary(report, summary_field, row_fun) do
    if link_capacity_summary_source?(report) do
