    end
  end

  defp link_capacity_report_count_map_or_summary(report, summary_field, row_fun) do
    if link_capacity_summary_source?(report) do
      report
      |> Map.get(summary_field)
      |> List.wrap()
      |> count_link_capacity_values()
    else
      row_fun.(report)
    end
  end

