  defp link_capacity_report_numeric_total(report, field) do
    values =
      report
      |> link_capacity_report_rows_for_summary()
      |> Enum.map(&(Map.get(&1, field) |> numeric_value()))
      |> Enum.filter(&is_number/1)

    case values do
      [] -> nil
      values -> Enum.sum(values)
    end
  end

  defp link_capacity_report_numeric_values_by_ground_station(report, field) do
    summary_field = "#{field}_by_ground_station_id"

    link_capacity_report_numeric_map_or_summary(report, summary_field, field)
  end

  defp link_capacity_report_row_numeric_values_by_ground_station(report, field) do
    report
    |> link_capacity_report_rows_for_summary()
    |> Enum.reduce(%{}, fn row, totals ->
      station_id = link_capacity_station_id(row)
      value = row |> Map.get(field) |> numeric_value()

      if station_id in [nil, ""] or is_nil(value) do
        totals
      else
        Map.update(totals, station_id, value, &(&1 + value))
      end
    end)
    |> non_empty_map()
  end

  defp link_capacity_report_numeric_values_by_direction(report, field) do
    report
    |> link_capacity_report_rows_for_summary()
    |> Enum.reduce(%{}, fn row, totals ->
      direction = link_capacity_row_direction(row)
      value = row |> Map.get(field) |> numeric_value()

      if direction in [nil, ""] or is_nil(value) do
        totals
      else
        Map.update(totals, direction, value, &(&1 + value))
      end
    end)
    |> non_empty_map()
  end

