  defp link_capacity_report_directions(reports) do
    direction_counts =
      reports
      |> Enum.map(&link_capacity_report_direction_counts/1)
      |> merge_count_maps()

    contact_ids_by_direction =
      reports
      |> Enum.map(&link_capacity_report_contact_ids_by_direction/1)
      |> merge_string_list_maps()

    source_window_ids_by_direction =
      reports
      |> Enum.map(&link_capacity_report_source_window_ids_by_direction/1)
      |> merge_string_list_maps()

    station_calendar_entry_ids_by_direction =
      reports
      |> Enum.map(&link_capacity_report_station_calendar_entry_ids_by_direction/1)
      |> merge_string_list_maps()

    station_calendar_provider_entry_ids_by_direction =
      reports
      |> Enum.map(&link_capacity_report_station_calendar_provider_entry_ids_by_direction/1)
      |> merge_string_list_maps()

    capacity_adjusted_by_direction =
      link_capacity_report_numeric_values_by_direction_from_reports(
        reports,
        "capacity_adjusted_throughput_mb"
      )

    selected_capacity_adjusted_by_direction =
      link_capacity_report_numeric_values_by_direction_from_reports(
        reports,
        "selected_capacity_adjusted_throughput_mb"
      )

    unused_capacity_adjusted_by_direction =
      link_capacity_report_numeric_values_by_direction_from_reports(
        reports,
        "unused_capacity_adjusted_throughput_mb"
      )

    [
      link_capacity_map_keys(direction_counts),
      link_capacity_map_keys(contact_ids_by_direction),
      link_capacity_map_keys(source_window_ids_by_direction),
      link_capacity_map_keys(station_calendar_entry_ids_by_direction),
      link_capacity_map_keys(station_calendar_provider_entry_ids_by_direction),
      link_capacity_map_keys(capacity_adjusted_by_direction),
      link_capacity_map_keys(selected_capacity_adjusted_by_direction),
      link_capacity_map_keys(unused_capacity_adjusted_by_direction)
    ]
    |> List.flatten()
    |> sorted_non_empty_values()
  end

  defp link_capacity_report_direction_routing(reports) do
    direction_counts =
      reports
      |> Enum.map(&link_capacity_report_direction_counts/1)
      |> merge_count_maps()
      |> empty_map_if_nil()

    contact_ids_by_direction =
      reports
      |> Enum.map(&link_capacity_report_contact_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    source_window_ids_by_direction =
      reports
      |> Enum.map(&link_capacity_report_source_window_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    station_calendar_entry_ids_by_direction =
      reports
      |> Enum.map(&link_capacity_report_station_calendar_entry_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    station_calendar_provider_entry_ids_by_direction =
      reports
      |> Enum.map(&link_capacity_report_station_calendar_provider_entry_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    capacity_adjusted_by_direction =
      reports
      |> link_capacity_report_numeric_values_by_direction_from_reports(
        "capacity_adjusted_throughput_mb"
      )
      |> empty_map_if_nil()

    selected_capacity_adjusted_by_direction =
      reports
      |> link_capacity_report_numeric_values_by_direction_from_reports(
        "selected_capacity_adjusted_throughput_mb"
      )
      |> empty_map_if_nil()

    unused_capacity_adjusted_by_direction =
      reports
      |> link_capacity_report_numeric_values_by_direction_from_reports(
        "unused_capacity_adjusted_throughput_mb"
      )
      |> empty_map_if_nil()

    [
      link_capacity_map_keys(direction_counts),
      link_capacity_map_keys(contact_ids_by_direction),
      link_capacity_map_keys(source_window_ids_by_direction),
      link_capacity_map_keys(station_calendar_entry_ids_by_direction),
      link_capacity_map_keys(station_calendar_provider_entry_ids_by_direction),
      link_capacity_map_keys(capacity_adjusted_by_direction),
      link_capacity_map_keys(selected_capacity_adjusted_by_direction),
      link_capacity_map_keys(unused_capacity_adjusted_by_direction)
    ]
    |> List.flatten()
    |> Enum.map(&to_string/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> Map.new(fn direction ->
      route =
        %{
          "contact_count" => Map.get(direction_counts, direction),
          "contact_ids" => Map.get(contact_ids_by_direction, direction, []),
          "source_window_ids" => Map.get(source_window_ids_by_direction, direction, []),
          "station_calendar_entry_ids" =>
            Map.get(station_calendar_entry_ids_by_direction, direction, []),
          "station_calendar_provider_entry_ids" =>
            Map.get(station_calendar_provider_entry_ids_by_direction, direction, []),
          "capacity_adjusted_throughput_mb" => Map.get(capacity_adjusted_by_direction, direction),
          "selected_capacity_adjusted_throughput_mb" =>
            Map.get(selected_capacity_adjusted_by_direction, direction),
          "unused_capacity_adjusted_throughput_mb" =>
            Map.get(unused_capacity_adjusted_by_direction, direction)
        }
        |> compact_map()

      {direction, route}
    end)
    |> non_empty_map()
  end

  defp link_capacity_report_numeric_values_by_direction_from_reports(reports, field) do
    reports
    |> Enum.map(&link_capacity_report_numeric_values_by_direction(&1, field))
    |> merge_numeric_maps()
  end

