  defp link_capacity_report_direction_contact_pairs(row) do
    row = stringify_keys(row)
    row_direction = link_capacity_row_direction(row)

    link_capacity_source_contact_values(row)
    |> Enum.map(fn contact ->
      {link_capacity_source_contact_direction(contact) || row_direction,
       link_capacity_source_contact_id(contact)}
    end)
    |> Enum.reject(fn {direction, contact_id} ->
      direction in [nil, ""] or contact_id in [nil, ""]
    end)
    |> Enum.uniq()
