  defp link_capacity_report_direction_source_window_pairs(row) do
    row = stringify_keys(row)
    row_direction = link_capacity_row_direction(row)

    contact_pairs =
      row
      |> link_capacity_source_contact_values()
      |> Enum.filter(&is_map/1)
      |> Enum.flat_map(fn contact ->
        contact = stringify_keys(contact)
        direction = link_capacity_source_contact_direction(contact) || row_direction

        contact
        |> link_capacity_contact_source_window_ids()
        |> Enum.map(&{direction, &1})
      end)

    row_pairs =
      row
      |> link_capacity_row_source_window_ids()
      |> Enum.map(&{row_direction, &1})

    (contact_pairs ++ row_pairs)
    |> Enum.reject(fn {direction, source_window_id} ->
      direction in [nil, ""] or source_window_id in [nil, ""]
    end)
    |> Enum.uniq()
