  defp contact_allocation_report_blocked_row_count(report) do
    report
    |> Map.get("rows", [])
    |> Enum.map(&normalize_contact_allocation_row(stringify_keys(&1)))
    |> Enum.count(
      &(contact_allocation_effective_status(&1) in [
          "blocked",
          "policy_blocked",
          "blocked_by_policy"
        ])
    )
  end

