    report
    |> Map.get("rows", [])
    |> Enum.map(&normalize_contact_allocation_row(stringify_keys(&1)))
    |> Enum.count(&(contact_allocation_effective_status(&1) == "deferred"))
  end

  defp contact_allocation_report_status_counts(report) do
    case contact_allocation_report_rows_for_summary(report) do
      [] ->
        case Map.get(report, "allocation_status_counts") do
          counts when is_map(counts) -> counts
          _counts -> nil
        end

      rows ->
        rows
        |> count_contact_allocation_rows("allocation_status")
    end
  end

  defp contact_allocation_report_effective_status_counts(report) do
    case contact_allocation_report_rows_for_summary(report) do
      [] ->
        case Map.get(report, "effective_allocation_status_counts") do
          counts when is_map(counts) -> counts
          _counts -> nil
        end

      rows ->
        rows
        |> Enum.reduce(%{}, fn row, counts ->
          case contact_allocation_effective_status(row) do
            status when status in [nil, ""] -> counts
            status -> Map.update(counts, status, 1, &(&1 + 1))
          end
        end)
        |> non_empty_map()
    end
  end

