  defp contact_allocation_direction_routing(reports) do
    direction_counts =
      reports
      |> Enum.map(&contact_allocation_report_direction_counts/1)
      |> merge_count_maps()
      |> empty_map_if_nil()

    contact_ids_by_direction =
      reports
      |> Enum.map(&contact_allocation_report_contact_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    station_pressure_direction_counts =
      reports
      |> Enum.map(&contact_allocation_report_station_pressure_direction_counts/1)
      |> merge_count_maps()
      |> empty_map_if_nil()

    station_pressure_contact_ids_by_direction =
      reports
      |> Enum.map(&contact_allocation_report_station_pressure_contact_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    reservation_conflict_direction_counts =
      reports
      |> Enum.map(&contact_allocation_report_reservation_conflict_direction_counts/1)
      |> merge_count_maps()
      |> empty_map_if_nil()

    reservation_conflict_contact_ids_by_direction =
      reports
      |> Enum.map(&contact_allocation_report_reservation_conflict_contact_ids_by_direction/1)
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    provider_reservation_no_request_contact_ids_by_direction =
      reports
      |> Enum.map(
        &contact_allocation_report_provider_reservation_no_request_contact_ids_by_direction/1
      )
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    provider_reservation_request_contact_ids_by_direction =
      reports
      |> Enum.map(
        &contact_allocation_report_provider_reservation_request_contact_ids_by_direction/1
      )
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    provider_reservation_review_contact_ids_by_direction =
      reports
      |> Enum.map(
        &contact_allocation_report_provider_reservation_review_contact_ids_by_direction/1
      )
      |> merge_string_list_maps()
      |> empty_map_if_nil()

    [
      Map.keys(direction_counts),
      Map.keys(contact_ids_by_direction),
      Map.keys(station_pressure_direction_counts),
      Map.keys(station_pressure_contact_ids_by_direction),
      Map.keys(reservation_conflict_direction_counts),
      Map.keys(reservation_conflict_contact_ids_by_direction),
      Map.keys(provider_reservation_no_request_contact_ids_by_direction),
      Map.keys(provider_reservation_request_contact_ids_by_direction),
      Map.keys(provider_reservation_review_contact_ids_by_direction)
    ]
    |> List.flatten()
    |> Enum.map(&to_string/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> Map.new(fn direction ->
      route =
        %{
          "contact_count" => Map.get(direction_counts, direction),
          "contact_ids" => Map.get(contact_ids_by_direction, direction, []),
          "station_pressure_contact_count" =>
            Map.get(station_pressure_direction_counts, direction),
          "station_pressure_contact_ids" =>
            Map.get(station_pressure_contact_ids_by_direction, direction, []),
          "reservation_conflict_contact_count" =>
            Map.get(reservation_conflict_direction_counts, direction),
          "reservation_conflict_contact_ids" =>
            Map.get(reservation_conflict_contact_ids_by_direction, direction, []),
          "provider_reservation_no_request_contact_ids" =>
            Map.get(provider_reservation_no_request_contact_ids_by_direction, direction, []),
          "provider_reservation_request_contact_ids" =>
            Map.get(provider_reservation_request_contact_ids_by_direction, direction, []),
          "provider_reservation_review_contact_ids" =>
            Map.get(provider_reservation_review_contact_ids_by_direction, direction, [])
        }
        |> compact_map()

      {direction, route}
    end)
    |> non_empty_map()
  end

