  defp contact_allocation_report_capacity_pack_required_fraction_by_field(
         report,
         fallback_field,
         row_field,
         filter
       ) do
    case report |> contact_allocation_report_capacity_pack_rows() |> Enum.filter(filter) do
      [] ->
        report
        |> Map.get(fallback_field)
        |> contact_allocation_numeric_map()

      rows ->
        rows
        |> Enum.reduce(%{}, fn row, totals ->
          key = contact_allocation_capacity_pack_group_key(row, row_field)
          required_fraction = numeric_value(row["required_capacity_fraction"])

          if key in [nil, ""] or is_nil(required_fraction) do
            totals
          else
            Map.update(totals, key, required_fraction, &(&1 + required_fraction))
          end
        end)
        |> non_empty_map()
    end
  end

  defp contact_allocation_report_capacity_pack_contact_ids_by_field(
         report,
         fallback_field,
         row_field,
         filter
       ) do
    case report |> contact_allocation_report_capacity_pack_rows() |> Enum.filter(filter) do
      [] ->
        report
        |> Map.get(fallback_field)
        |> map_value_lists()

      rows ->
        rows
        |> Enum.reduce(%{}, fn row, contact_ids_by_key ->
          key = contact_allocation_capacity_pack_group_key(row, row_field)
          contact_id = contact_allocation_summary_contact_id(row)

          if key in [nil, ""] or contact_id in [nil, ""] do
            contact_ids_by_key
          else
            Map.update(contact_ids_by_key, key, [contact_id], fn contact_ids ->
              [contact_id | contact_ids]
            end)
          end
        end)
        |> map_value_lists()
    end
  end

  defp contact_allocation_report_capacity_pack_rows(report) do
    report
    |> Map.get("rows", [])
    |> Enum.map(&normalize_contact_allocation_row(stringify_keys(&1)))
    |> Enum.filter(fn row ->
      normalized_timeline_diff_token(row["capacity_pack_status"]) not in [nil, ""] and
        is_number(numeric_value(row["required_capacity_fraction"]))
    end)
  end

  defp contact_allocation_capacity_pack_selected_row?(row) do
    normalized_timeline_diff_token(row["capacity_pack_status"]) in [
      "selected_by_contention_resolution",
      "selected_by_reduced_station_capacity_pack"
    ]
  end

  defp contact_allocation_capacity_pack_deferred_row?(row) do
    normalized_timeline_diff_token(row["capacity_pack_status"]) ==
      "deferred_by_reduced_station_capacity_pack"
  end

  defp contact_allocation_reduced_capacity_packed_row?(row) do
    normalized_timeline_diff_token(row["capacity_pack_status"]) ==
      "selected_by_reduced_station_capacity_pack"
  end

  defp contact_allocation_capacity_pack_group_key(row, "capacity_pack_status") do
    normalized_timeline_diff_token(row["capacity_pack_status"])
  end

  defp contact_allocation_capacity_pack_group_key(row, "direction") do
    contact_allocation_summary_direction(row)
  end

  defp contact_allocation_capacity_pack_group_key(row, field) do
    stable_id_or_nil(row[field]) || normalized_timeline_diff_token(row[field])
  end

  defp contact_allocation_numeric_map(%{} = numeric_map) do
    numeric_map
    |> Enum.reduce(%{}, fn {key, value}, totals ->
      case numeric_value(value) do
        value when is_number(value) -> Map.put(totals, to_string(key), value)
        _value -> totals
      end
    end)
    |> non_empty_map()
  end

  defp contact_allocation_numeric_map(_numeric_map), do: nil

