  defp contact_allocation_report_station_reservation_expiration_rows(report) do
    now_s = contact_allocation_report_station_reservation_expiration_now_s(report)

    report
    |> contact_allocation_report_station_reservation_rows()
    |> Enum.map(fn row ->
      expires_at_s = contact_allocation_station_reservation_expires_at_s(row)

      row
      |> Map.put("station_reservation_summary_expires_at_s", expires_at_s)
      |> Map.put(
        "station_reservation_expiration_status",
        contact_allocation_station_reservation_expiration_status(expires_at_s, now_s)
      )
    end)
  end

  defp contact_allocation_station_reservation_expiration_status(nil, _now_s), do: "missing"

  defp contact_allocation_station_reservation_expiration_status(_expires_at_s, nil),
    do: "declared"

  defp contact_allocation_station_reservation_expiration_status(expires_at_s, now_s)
       when expires_at_s <= now_s,
       do: "expired"

  defp contact_allocation_station_reservation_expiration_status(_expires_at_s, _now_s),
    do: "active"

