  defp contact_allocation_report_provider_reservation_contact_ids(report, fallback_field, filter) do
    case contact_allocation_report_rows_for_summary(report) |> Enum.filter(filter) do
      [] ->
        report
        |> Map.get(fallback_field, [])
        |> List.wrap()
        |> sorted_non_empty_values()

      rows ->
        rows
        |> Enum.map(&contact_allocation_summary_contact_id/1)
        |> sorted_non_empty_values()
    end
  end

  defp contact_allocation_report_provider_reservation_contact_ids_by_field(
         report,
         fallback_fields,
         field,
         filter
       ) do
    case contact_allocation_report_rows_for_summary(report) |> Enum.filter(filter) do
      [] ->
        fallback_fields
        |> Enum.find_value(fn fallback_field ->
          report
          |> Map.get(fallback_field)
          |> map_value_lists()
        end)

      rows ->
        rows
        |> Enum.map(fn row ->
          {contact_allocation_provider_reservation_group_key(row, field),
           contact_allocation_summary_contact_id(row)}
        end)
        |> contact_allocation_grouped_contact_ids()
    end
  end

  defp contact_allocation_provider_reservation_group_key(row, "direction"),
    do: contact_allocation_summary_direction(row)

  defp contact_allocation_provider_reservation_group_key(row, field),
    do: contact_allocation_capacity_pack_group_key(row, field)

