  defp contact_allocation_provider_reservation_candidate_row?(row) do
    row["allocation_status"] == "allocated" and
      contact_allocation_summary_station_reservation?(row)
  end

  defp contact_allocation_contact_ids_by_direction_and_station(rows) do
    rows
    |> Enum.reduce(%{}, fn row, acc ->
      direction = contact_allocation_summary_direction(row)
      station_id = contact_allocation_capacity_pack_group_key(row, "ground_station_id")
      contact_id = contact_allocation_summary_contact_id(row)

      if direction in [nil, ""] or station_id in [nil, ""] or contact_id in [nil, ""] do
        acc
      else
        Map.update(acc, direction, %{station_id => [contact_id]}, fn station_map ->
          Map.update(station_map, station_id, [contact_id], fn contact_ids ->
            [contact_id | contact_ids]
          end)
        end)
      end
    end)
    |> Map.new(fn {direction, station_map} ->
      {direction, map_value_lists(station_map)}
    end)
    |> non_empty_map()
  end

  defp contact_allocation_provider_reservation_request_ready_row?(row) do
    normalized_timeline_diff_token(row["station_reservation_match_status"]) in [
      "matched",
      "owner_matched"
    ] and contact_allocation_station_reservation_ids(row) != []
  end

  defp contact_allocation_station_reservation_ids(row) do
    [
      row["station_reservation_id"],
      row["station_calendar_reservation_ids"]
    ]
    |> List.flatten()
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp contact_allocation_summary_station_reservation?(row) do
    Enum.any?(
      [
        row["station_reservation_match_status"],
        row["station_reservation_status"],
        row["station_reserved_by"],
        row["station_reservation_id"],
        row["station_reservation_expires_at_s"],
        row["station_calendar_reservation_expires_at_s"],
        row["reservation_expires_at_s"]
      ],
      &(contact_allocation_capacity_pack_group_key(%{"value" => &1}, "value") not in [nil, ""])
    )
  end

  defp contact_allocation_report_reservation_conflict_rows(report) do
    report
    |> Map.get("rows", [])
    |> Enum.filter(&is_map/1)
    |> Enum.map(&normalize_contact_allocation_row(stringify_keys(&1)))
    |> Enum.filter(&contact_allocation_summary_reservation_conflict?/1)
  end

  defp contact_allocation_summary_reservation_conflict?(row) do
    match_status = normalized_timeline_diff_token(row["station_reservation_match_status"])

    match_status not in [nil, "", "matched", "owner_matched"]
  end

  defp contact_allocation_report_station_pressure_rows(report) do
    report
    |> Map.get("rows", [])
    |> Enum.map(&normalize_contact_allocation_row(stringify_keys(&1)))
    |> Enum.filter(&contact_allocation_summary_station_pressure?/1)
  end

  defp contact_allocation_report_review_rows(report) do
    report
    |> Map.get("rows", [])
    |> Enum.filter(&is_map/1)
    |> Enum.map(&normalize_contact_allocation_row(stringify_keys(&1)))
    |> Enum.filter(&contact_allocation_summary_review_row?/1)
  end

  defp contact_allocation_summary_station_pressure?(row) do
    contact_allocation_summary_pressure_value?(row["station_calendar_overlap_count"]) or
      contact_allocation_summary_pressure_value?(row["station_calendar_overlap_availabilities"]) or
      contact_allocation_summary_pressure_value?(row["station_calendar_entry_id"]) or
      contact_allocation_summary_pressure_value?(row["station_reservation_match_status"]) or
      contact_allocation_summary_pressure_value?(row["station_calendar_precedence_rank"]) or
      contact_allocation_summary_pressure_value?(row["station_calendar_precedence_availability"]) or
      contact_allocation_summary_source_pressure_values(row) != []
  end

  defp contact_allocation_summary_review_row?(row) do
    row["review_status"] == "operator_review_required" or
      row["allocation_status"] in ["blocked", "deferred"] or
      row["effective_allocation_status"] == "policy_blocked"
  end

  defp contact_allocation_summary_pressure_value?(nil), do: false
  defp contact_allocation_summary_pressure_value?([]), do: false
  defp contact_allocation_summary_pressure_value?(value) when is_number(value), do: value > 0
  defp contact_allocation_summary_pressure_value?(value) when is_binary(value), do: value != ""
  defp contact_allocation_summary_pressure_value?(_value), do: true

  defp contact_allocation_summary_contact_id(row) do
    stable_id_or_nil(row["contact_id"]) ||
      stable_id_or_nil(row["id"]) ||
      stable_id_or_nil(get_in(row, ["activity_context", "activity_id"]))
  end

  defp contact_allocation_summary_direction(row) do
    [
      row["direction"],
      get_in(row, ["activity_context", "direction"]),
      get_in(row, ["source_contact_candidate", "direction"]),
      get_in(row, ["source_contact_candidate", "activity_context", "direction"]),
      get_in(row, ["source_contention_recommendation", "direction"]),
      row["type"],
      get_in(row, ["source_contact_candidate", "type"])
    ]
    |> Enum.map(&normalize_direction/1)
    |> Enum.find(&(&1 not in [nil, ""]))
  end

  defp contact_allocation_id_map_counts(%{} = contact_ids_by_key) do
    contact_ids_by_key
    |> Enum.map(fn {key, contact_ids} ->
      {to_string(key), contact_ids |> List.wrap() |> sorted_non_empty_values()}
    end)
    |> Enum.reject(fn {key, contact_ids} -> key in [nil, ""] or contact_ids in [nil, []] end)
    |> Map.new(fn {key, contact_ids} -> {key, length(contact_ids)} end)
    |> non_empty_map()
  end

  defp contact_allocation_id_map_counts(_contact_ids_by_key), do: nil

  defp contact_allocation_id_map_contact_ids(%{} = contact_ids_by_key) do
    contact_ids_by_key
    |> Map.values()
    |> Enum.flat_map(&List.wrap/1)
  end

  defp contact_allocation_id_map_contact_ids(_contact_ids_by_key), do: []

  defp contact_allocation_grouped_contact_counts(pairs) do
    pairs
    |> Enum.reject(fn {key, contact_id} -> key in [nil, ""] or contact_id in [nil, ""] end)
    |> Enum.group_by(fn {key, _contact_id} -> key end, fn {_key, contact_id} -> contact_id end)
    |> Map.new(fn {key, contact_ids} ->
      {key, contact_ids |> sorted_non_empty_values() |> length()}
    end)
    |> non_empty_map()
  end

  defp contact_allocation_grouped_contact_ids(pairs) do
    pairs
    |> Enum.reject(fn {key, contact_id} -> key in [nil, ""] or contact_id in [nil, ""] end)
    |> Enum.group_by(fn {key, _contact_id} -> key end, fn {_key, contact_id} -> contact_id end)
    |> Map.new(fn {key, contact_ids} -> {key, sorted_non_empty_values(contact_ids)} end)
    |> non_empty_map()
  end

  defp contact_allocation_summary_availability_values(row) do
    direct_values =
      row
      |> Map.take(["station_availability", "availability", "station_calendar_status"])
      |> Map.values()
      |> Kernel.++([contact_allocation_summary_reason_availability(row["allocation_reason"])])

    source_values =
      contact_allocation_summary_source_availability_candidates(
        row["source_station_calendar_entry"]
      ) ++
        contact_allocation_summary_source_availability_candidates(
          row["source_station_calendar_overlaps"]
        )

    (direct_values ++
       List.wrap(row["station_calendar_overlap_availabilities"]) ++
       source_values)
    |> Enum.map(&contact_allocation_summary_status_token/1)
    |> Enum.filter(&contact_allocation_summary_station_availability?/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp contact_allocation_summary_source_pressure_values(row) do
    (contact_allocation_summary_source_availability_candidates(
       row["source_station_calendar_entry"]
     ) ++
       contact_allocation_summary_source_availability_candidates(
         row["source_station_calendar_overlaps"]
       ) ++
       [contact_allocation_summary_reason_availability(row["allocation_reason"])])
    |> Enum.map(&contact_allocation_summary_status_token/1)
    |> Enum.filter(&contact_allocation_summary_pressure_availability?/1)
    |> Enum.uniq()
  end

  defp contact_allocation_summary_reason_availability(reason) do
    case normalized_timeline_diff_token(reason) do
      "ground_station_unavailable" -> "unavailable"
      "ground_station_reserved" -> "reserved"
      "station_reserved" -> "reserved"
      "station_maintenance" -> "maintenance"
      "ground_station_capacity_zero" -> "reduced_capacity"
      _reason -> nil
    end
  end

  defp contact_allocation_summary_source_availability_candidates(nil), do: []

  defp contact_allocation_summary_source_availability_candidates(entries) when is_list(entries) do
    Enum.flat_map(entries, &contact_allocation_summary_source_availability_candidates/1)
  end

  defp contact_allocation_summary_source_availability_candidates(%{} = entry) do
    [entry["availability"], entry["status"], entry["station_availability"]]
  end

  defp contact_allocation_summary_source_availability_candidates(_entry), do: []

  defp contact_allocation_summary_status_token(value) when is_binary(value) do
    value
    |> String.trim()
    |> String.downcase()
    |> String.replace(~r/[\s-]+/, "_")
    |> case do
      value when value in ["outage", "down", "offline"] -> "unavailable"
      value -> value
    end
  end

  defp contact_allocation_summary_status_token(value) when is_atom(value) do
    value
    |> Atom.to_string()
    |> contact_allocation_summary_status_token()
  end

  defp contact_allocation_summary_status_token(value), do: value

  defp contact_allocation_summary_station_availability?(value)
       when value in ["available", "unavailable", "maintenance", "reserved", "reduced_capacity"],
       do: true

  defp contact_allocation_summary_station_availability?(_value), do: false

  defp contact_allocation_summary_pressure_availability?(value)
       when value in ["unavailable", "maintenance", "reserved", "reduced_capacity"],
       do: true

  defp contact_allocation_summary_pressure_availability?(_value), do: false

  defp contact_contention_resolution_report_row_count(report) do
    contact_contention_resolution_report_recommendation_count(report)
  end

  defp contact_contention_resolution_report_recommendation_count(report) do
    case Map.get(report, "recommendations", []) do
      [] -> numeric_report_count(report, "recommendation_count")
      recommendations -> length(recommendations)
    end
  end

  defp contact_contention_resolution_report_deferred_contact_count(report) do
    case Map.get(report, "recommendations", []) do
      [] ->
        case numeric_report_count(report, "deferred_contact_count") do
          0 -> report |> Map.get("deferred_contact_ids", []) |> length()
          count -> count
        end

      recommendations ->
        recommendations
        |> Enum.map(&stringify_keys/1)
        |> Enum.map(&contact_contention_resolution_deferred_contacts/1)
        |> Enum.map(&length/1)
        |> Enum.sum()
    end
  end

  defp contact_contention_resolution_report_status_counts(report) do
    case Map.get(report, "recommendations", []) do
      [] ->
        Map.get(report, "resolution_status_counts")

      recommendations ->
        count_contact_contention_resolution_rows(recommendations, "resolution_status")
    end
  end

  defp contact_contention_resolution_report_selection_reason_counts(report) do
    case Map.get(report, "recommendations", []) do
      [] ->
        Map.get(report, "selection_reason_counts")

      recommendations ->
        count_contact_contention_resolution_rows(recommendations, "selection_reason")
    end
  end

  defp contact_contention_resolution_report_capacity_pack_required_fraction(report) do
    case contact_contention_resolution_capacity_pack_demand_rows(report) do
      [] -> numeric_report_count(report, "capacity_pack_required_capacity_fraction")
      rows -> contention_capacity_pack_demand_total(rows)
    end
  end

  defp contact_contention_resolution_report_capacity_pack_selected_required_fraction(report) do
    case contact_contention_resolution_capacity_pack_demand_rows(report) do
      [] ->
        numeric_report_count(report, "capacity_pack_selected_required_capacity_fraction")

      rows ->
        rows |> Enum.filter(&(&1.status == :selected)) |> contention_capacity_pack_demand_total()
    end
  end

  defp contact_contention_resolution_report_capacity_pack_deferred_required_fraction(report) do
    case contact_contention_resolution_capacity_pack_demand_rows(report) do
      [] ->
