  defp contact_contention_resolution_recommendation_station_contact_pairs(recommendation, status) do
    contact_ids =
      case status do
        :selected ->
          [stable_id_or_nil(recommendation["selected_contact_id"])]

        :deferred ->
          recommendation
          |> Map.get("deferred_contact_ids", [])
          |> List.wrap()
          |> Enum.map(&stable_id_or_nil/1)
      end
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.uniq()

    contact_ids
    |> Enum.map(fn contact_id ->
      source_contact =
        recommendation
        |> contact_contention_resolution_source_contacts()
        |> Enum.find(&contact_contention_resolution_contact_match?(&1, contact_id))

      {contact_contention_resolution_station_id(recommendation, source_contact || %{}),
       contact_id}
    end)
  end

