          report
          |> Map.get("required_operator_actions", [])
          |> List.wrap()
          |> count_source_report_values()

      recommendations ->
        recommendations
        |> Enum.map(&stringify_keys/1)
        |> Enum.flat_map(&contact_contention_resolution_recommendation_required_actions/1)
        |> count_source_report_values()
