  defp contact_contention_resolution_report_direction_contact_pairs(report) do
    report
    |> Map.get("recommendations", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.flat_map(&contact_contention_resolution_recommendation_direction_contact_pairs/1)
  end

  defp contact_contention_resolution_recommendation_direction_contact_pairs(recommendation) do
    selected_contact_id = stable_id_or_nil(recommendation["selected_contact_id"])

    deferred_contact_ids =
      recommendation
      |> Map.get("deferred_contact_ids", [])
      |> List.wrap()
      |> Enum.map(&stable_id_or_nil/1)
      |> Enum.reject(&is_nil/1)
      |> MapSet.new()

    source_contacts = contact_contention_resolution_source_contacts(recommendation)

    pairs =
      source_contacts
      |> Enum.map(&contact_contention_resolution_contact_direction_pair(&1, recommendation))
      |> Enum.filter(fn {_direction, contact_id} ->
        contact_id == selected_contact_id or MapSet.member?(deferred_contact_ids, contact_id)
      end)

    case pairs do
      [] ->
        contact_contention_resolution_recommendation_fallback_direction_contact_pairs(
          recommendation,
          selected_contact_id,
          deferred_contact_ids
        )

      pairs ->
        pairs
    end
    |> Enum.reject(fn {direction, contact_id} ->
      direction in [nil, ""] or contact_id in [nil, ""]
    end)
    |> Enum.uniq()
  end

  defp contact_contention_resolution_recommendation_fallback_direction_contact_pairs(
         recommendation,
         selected_contact_id,
         deferred_contact_ids
       ) do
    directions = contact_contention_resolution_recommendation_directions(recommendation)

    contact_ids =
      ([selected_contact_id] ++ MapSet.to_list(deferred_contact_ids))
      |> Enum.reject(&(&1 in [nil, ""]))

    for direction <- directions, contact_id <- contact_ids, do: {direction, contact_id}
  end

  defp contact_contention_resolution_contact_direction_pair(contact, recommendation) do
    direction =
      [
        contact["direction"],
        contact["type"],
        contact["activity_type"],
        get_in(contact, ["activity_context", "direction"]),
        recommendation["direction"]
      ]
      |> Enum.map(&normalize_direction/1)
      |> Enum.find(&(&1 not in [nil, "", "mixed", "contact"]))

    contact_id =
      [
        contact["id"],
        contact["contact_id"],
        contact["activity_id"],
        contact["source_activity_id"],
        get_in(contact, ["activity_context", "contact_id"]),
        get_in(contact, ["activity_context", "id"])
      ]
      |> Enum.map(&stable_id_or_nil/1)
      |> Enum.find(&(&1 not in [nil, ""]))

    {direction, contact_id}
  end

  defp contact_contention_resolution_recommendation_directions(recommendation) do
    [
      recommendation["directions"],
      recommendation["direction"]
    ]
    |> List.flatten()
    |> Enum.map(&normalize_direction/1)
    |> Enum.reject(&(&1 in [nil, "", "mixed", "contact"]))
    |> Enum.uniq()
  end

  defp contact_contention_resolution_capacity_pack_demand_rows(report) do
    report
    |> Map.get("recommendations", [])
    |> Enum.flat_map(&contact_contention_resolution_recommendation_capacity_pack_demand_rows/1)
  end

  defp contact_contention_resolution_recommendation_capacity_pack_demand_rows(recommendation) do
    recommendation = stringify_keys(recommendation)
    candidates = contact_contention_resolution_source_contacts(recommendation)
    selected_contact_id = stable_id_or_nil(recommendation["selected_contact_id"])

    deferred_contact_ids =
      recommendation
      |> Map.get("deferred_contact_ids", [])
      |> List.wrap()
      |> Enum.map(&stable_id_or_nil/1)
      |> Enum.reject(&is_nil/1)
      |> MapSet.new()

    candidates
    |> Enum.flat_map(fn contact ->
      contact_id =
        stable_id_or_nil(contact["id"]) ||
          stable_id_or_nil(contact["contact_id"]) ||
          stable_id_or_nil(contact["activity_id"])

      required_capacity_fraction =
        contact_contention_resolution_required_capacity_fraction(contact)

      cond do
        is_nil(contact_id) or is_nil(required_capacity_fraction) ->
          []

        contact_id == selected_contact_id ->
          [
            contention_capacity_pack_demand_row(
              contact,
              :selected,
              required_capacity_fraction
            )
          ]

        MapSet.member?(deferred_contact_ids, contact_id) ->
          [
            contention_capacity_pack_demand_row(
              contact,
              :deferred,
              required_capacity_fraction
            )
          ]

        true ->
          []
      end
    end)
  end

  defp contact_contention_resolution_required_capacity_fraction(contact) do
    contact
    |> objective_satisfaction_first_number([
      "required_capacity_fraction",
      "required_station_capacity_fraction",
      "station_capacity_requirement",
      ["throughput_model", "required_capacity_fraction"],
      ["throughput_model", "required_station_capacity_fraction"],
      ["throughput_model", "station_capacity_requirement"],
      ["capacity_model", "required_capacity_fraction"],
      ["capacity_model", "required_station_capacity_fraction"],
      ["capacity_model", "station_capacity_requirement"],
      ["activity_context", "required_capacity_fraction"],
      ["activity_context", "required_station_capacity_fraction"],
      ["activity_context", "station_capacity_requirement"]
    ])
    |> capacity_unit_interval_or_nil()
    |> case do
      value when is_number(value) ->
        value

      _value ->
        contact
        |> objective_satisfaction_first_number([
          "required_capacity_percent",
          "required_station_capacity_percent",
          "station_capacity_requirement_percent",
          ["throughput_model", "required_capacity_percent"],
          ["throughput_model", "required_station_capacity_percent"],
          ["throughput_model", "station_capacity_requirement_percent"],
          ["capacity_model", "required_capacity_percent"],
          ["capacity_model", "required_station_capacity_percent"],
          ["capacity_model", "station_capacity_requirement_percent"],
          ["activity_context", "required_capacity_percent"],
          ["activity_context", "required_station_capacity_percent"],
          ["activity_context", "station_capacity_requirement_percent"]
        ])
        |> capacity_percent_fraction_or_nil()
    end
  end

  defp capacity_unit_interval_or_nil(value) do
    case numeric_value(value) do
      value when is_number(value) and value >= 0.0 and value <= 1.0 -> value
      _value -> nil
    end
  end

  defp capacity_percent_fraction_or_nil(value) do
    case numeric_value(value) do
      value when is_number(value) and value >= 0.0 and value <= 100.0 -> value / 100.0
      _value -> nil
    end
  end

  defp contention_capacity_pack_demand_row(contact, status, required_capacity_fraction) do
    %{
      status: status,
      ground_station_id:
        stable_id_or_nil(contact["ground_station_id"]) || stable_id_or_nil(contact["station_id"]),
      required_capacity_fraction: required_capacity_fraction
    }
  end

  defp contention_capacity_pack_demand_total(rows) do
    rows
    |> Enum.map(& &1.required_capacity_fraction)
    |> Enum.filter(&is_number/1)
    |> case do
      [] -> nil
      values -> Enum.sum(values)
    end
  end

  defp contention_capacity_pack_demand_by_station(rows) do
    rows
    |> Enum.reduce(%{}, fn row, totals ->
      if row.ground_station_id in [nil, ""] do
        totals
      else
        Map.update(totals, row.ground_station_id, row.required_capacity_fraction, fn value ->
          value + row.required_capacity_fraction
        end)
      end
    end)
    |> non_empty_map()
  end

