  defp source_contact_contention_resolution_report_trust_boundaries(
         %{"recommendations" => recommendations} = report
       )
       when is_list(recommendations) do
    row_trust_boundaries =
      recommendations
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&contact_contention_resolution_trust_boundary/1)

    row_trust_boundaries ++ source_report_trust_boundaries([report])
  end

  defp source_contact_contention_resolution_report_trust_boundaries(%{} = report),
    do: source_report_trust_boundaries([report])

  defp source_constraint_report_trust_boundaries(reports) when is_list(reports) do
    reports
    |> Enum.flat_map(&source_constraint_report_trust_boundaries/1)
    |> normalize_trust_boundaries()
  end

