      rows
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(
        &Map.put_new(&1, "_source_report_trust_boundary", result_artifact_trust_boundary(report))
      )
      |> Enum.map(&constraint_trust_boundary/1)

    row_trust_boundaries ++ source_report_trust_boundaries([report])
