  defp normalize_trust_boundaries(values) do
    values
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp non_empty_map(map) when map_size(map) == 0, do: nil
  defp non_empty_map(map), do: map

  defp non_empty_list([]), do: nil
  defp non_empty_list(list), do: list

  defp operational_feedback_provenance(refresh) do
    feedback = operational_feedback(refresh)
    invalid_sections = invalid_operational_feedback_sections(refresh)

    cond do
      invalid_operational_feedback_input?(refresh) ->
        %{
          "trust_boundary_status" => "missing",
          "input_keys" => ["invalid_operational_feedback_input"],
          "invalid_operational_feedback_input" => true,
          "invalid_operational_feedback_input_reason" => "operational_feedback_must_be_object",
          "source_path" => operational_feedback_source_path(refresh),
          "source_operational_feedback" => %{
            "invalid_feedback_shape" => encode_value(raw_operational_feedback(refresh))
          }
        }

      operational_feedback_data_keys(feedback) == [] and invalid_sections == [] ->
        nil

      true ->
        provenance =
          feedback
          |> Map.get("provenance", %{})
          |> case do
            provenance when is_map(provenance) -> provenance
            _provenance -> %{}
          end

        trust_boundary =
          Map.get(feedback, "trust_boundary") || Map.get(provenance, "trust_boundary")

        %{
          "trust_boundary_status" =>
            if(trust_boundary in [nil, ""], do: "missing", else: "declared"),
          "trust_boundary" => trust_boundary,
          "input_keys" => operational_feedback_data_keys(feedback),
          "source_path" => operational_feedback_source_path(refresh),
          "provenance" => provenance
        }
        |> maybe_put_invalid_operational_feedback_sections(invalid_sections)
        |> maybe_put_source_result_artifact_operational_feedback_provenance(refresh)
        |> maybe_put_source_operational_timeline_report_provenance(refresh)
        |> maybe_put_source_timeline_feedback_report_provenance(refresh)
        |> maybe_put_source_timeline_diff_report_provenance(refresh)
        |> maybe_put_source_command_window_report_provenance(refresh)
        |> maybe_put_source_maneuver_review_report_provenance(refresh)
        |> maybe_put_source_realized_activity_feedback_provenance(refresh)
        |> maybe_put_realized_activity_feedback_provenance(refresh)
        |> Enum.reject(fn {_key, value} -> value in [nil, %{}, []] end)
        |> Map.new()
    end
  end

  defp maybe_put_source_operational_timeline_report_provenance(provenance, refresh) do
    sources = source_operational_timeline_report_sources(refresh)

    maybe_put_source_operational_feedback_report_provenance(provenance, sources, fn sources ->
      source = merged_operational_timeline_source(sources)
      input_keys = Map.get(source, "input_keys", [])

      {
        "derived_from_source_operational_timeline_report",
        [
          {"source_operational_timeline_report_paths",
           source_operational_timeline_report_paths(refresh)},
          {"source_operational_timeline_report_contract",
           Map.get(source, "source_report_contract")},
          {"source_operational_timeline_report_count", Map.get(source, "source_report_count")},
          {"source_operational_timeline_report_row_count",
           Map.get(source, "source_report_row_count")},
          {"source_operational_timeline_contact_feedback_count",
           Map.get(source, "source_contact_feedback_count")},
          {"source_operational_timeline_command_feedback_count",
           Map.get(source, "source_command_feedback_count")},
          {"source_operational_timeline_maneuver_feedback_count",
           Map.get(source, "source_maneuver_feedback_count")},
          {"source_operational_timeline_observation_feedback_count",
           Map.get(source, "source_observation_feedback_count")},
          {"source_operational_timeline_station_throughput_feedback_count",
           Map.get(source, "source_station_throughput_feedback_count")},
          {"source_operational_timeline_station_reservation_evidence_row_count",
           Map.get(source, "source_station_reservation_evidence_row_count")},
          {"source_operational_timeline_station_reservation_expiration_evidence_row_count",
           Map.get(source, "source_station_reservation_expiration_evidence_row_count")},
          {"source_operational_timeline_integrity_issue_count",
           Map.get(source, "source_timeline_integrity_issue_count")},
          {"source_operational_timeline_dependency_integrity_issue_count",
           Map.get(source, "source_dependency_integrity_issue_count")},
          {"source_operational_timeline_exclusivity_integrity_issue_count",
           Map.get(source, "source_exclusivity_integrity_issue_count")},
          {"source_operational_timeline_trust_boundary_status",
           Map.get(source, "trust_boundary_status")},
          {"source_operational_timeline_trust_boundaries", Map.get(source, "trust_boundaries")},
          {"source_operational_timeline_required_operator_action_counts",
           Map.get(source, "source_required_operator_action_counts")}
        ],
        input_keys
      }
    end)
  end

  defp maybe_put_source_result_artifact_operational_feedback_provenance(provenance, refresh) do
    sources = source_result_artifact_operational_feedback_sources(refresh)

    if sources == [] do
      provenance
    else
      input_keys =
        refresh
        |> source_result_artifact_operational_feedback()
        |> operational_feedback_data_keys()

      trust_boundaries =
        sources
        |> Enum.map(fn {_path, _feedback, trust_boundary} -> encode_value(trust_boundary) end)
        |> Enum.reject(&(&1 in [nil, ""]))
        |> Enum.uniq()
        |> Enum.sort()

      field_trust_boundaries =
        source_result_artifact_operational_feedback_field_trust_boundaries(sources)

      provenance
      |> Map.put("derived_from_source_result_artifact_operational_feedback", true)
      |> maybe_put(
        "source_result_artifact_operational_feedback_paths",
        Enum.map(sources, fn {path, _feedback, _trust_boundary} -> path end)
      )
      |> Map.put("source_result_artifact_operational_feedback_count", length(sources))
      |> maybe_put("source_result_artifact_operational_feedback_input_keys", input_keys)
      |> maybe_put(
        "source_result_artifact_operational_feedback_trust_boundary_status",
        if(trust_boundaries == [], do: "missing", else: "declared")
      )
      |> maybe_put(
        "source_result_artifact_operational_feedback_trust_boundaries",
        trust_boundaries
      )
      |> maybe_put(
        "source_result_artifact_operational_feedback_field_trust_boundaries",
        field_trust_boundaries
      )
      |> Map.update("input_keys", input_keys, fn keys ->
        keys
        |> Kernel.++(input_keys)
        |> Enum.uniq()
        |> Enum.sort()
      end)
    end
  end

