  defp maybe_put_source_operational_feedback_report_provenance(
         provenance,
         [],
         _source_data_fun
       ),
       do: provenance

  defp maybe_put_source_operational_feedback_report_provenance(
         provenance,
         sources,
         source_data_fun
       ) do
    {derived_from_field, fields, input_keys} = source_data_fun.(sources)

    provenance
    |> Map.put(derived_from_field, true)
    |> put_source_operational_feedback_report_fields(fields)
    |> merge_source_operational_feedback_input_keys(input_keys)
  end

  defp put_source_operational_feedback_report_fields(provenance, fields) do
    Enum.reduce(fields, provenance, fn {field, value}, acc ->
      maybe_put(acc, field, value)
    end)
  end

  defp merge_source_operational_feedback_input_keys(provenance, input_keys) do
    Map.update(provenance, "input_keys", input_keys, fn keys ->
      keys
      |> Kernel.++(input_keys)
      |> Enum.uniq()
      |> Enum.sort()
    end)
  end

  defp maybe_put_realized_activity_feedback_provenance(provenance, refresh) do
    feedback = refresh |> raw_operational_feedback() |> stringify_keys()

    case Map.get(feedback, "realized_activities") do
      rows when is_list(rows) and rows != [] ->
        timeline_source =
          feedback
          |> realized_activity_operational_feedback_report(refresh)
          |> realized_activity_operational_feedback_source()

        provenance
        |> Map.put("derived_from_realized_activities", true)
        |> Map.put("source_realized_activity_count", length(rows))
        |> maybe_put(
          "source_weighted_feedback_row_count",
          Map.get(timeline_source, "weighted_feedback_row_count")
        )
        |> maybe_put(
          "feedback_weight_sources",
          Map.get(timeline_source, "feedback_weight_sources")
        )
        |> maybe_put(
          "feedback_trust_boundaries",
          Map.get(timeline_source, "feedback_trust_boundaries")
        )
        |> maybe_put(
          "source_realized_source_quality_counts",
          Map.get(timeline_source, "source_realized_source_quality_counts")
        )
        |> maybe_put_timeline_feedback_source_identity(timeline_source)
        |> maybe_put_timeline_feedback_source_counts(timeline_source)
        |> Map.update("input_keys", ["realized_activities"], fn keys ->
          keys
          |> Kernel.++(["realized_activities"])
          |> Enum.uniq()
          |> Enum.sort()
        end)

      _rows ->
        provenance
    end
  end

  defp maybe_put_source_realized_activity_feedback_provenance(provenance, refresh) do
    rows_with_sources = source_realized_activity_feedback_rows(refresh)

    if rows_with_sources == [] do
      provenance
    else
      rows = Enum.map(rows_with_sources, fn {_path, row} -> row end)

      timeline_source =
        rows
        |> realized_activity_operational_feedback_report_for_rows(refresh)
        |> realized_activity_operational_feedback_source()

      input_keys = Map.get(timeline_source, "input_keys", [])

      provenance
      |> Map.put("derived_from_source_realized_activities", true)
      |> Map.put(
        "source_realized_activity_paths",
        rows_with_sources
        |> Enum.map(fn {path, _row} -> path end)
        |> Enum.uniq()
        |> Enum.sort()
      )
      |> Map.put("source_realized_activity_count", length(rows_with_sources))
      |> maybe_put(
        "source_realized_activity_type_counts",
        realized_activity_source_counts(rows, &realized_activity_type/1)
      )
      |> maybe_put(
        "source_realized_direction_counts",
        realized_activity_source_counts(rows, &realized_activity_direction/1)
      )
      |> maybe_put(
        "source_realized_status_counts",
        realized_activity_source_counts(rows, &realized_activity_status/1)
      )
      |> maybe_put(
        "source_realized_feedback_weight_source_counts",
        realized_activity_source_counts(rows, &realized_activity_feedback_weight_source/1)
      )
      |> maybe_put(
        "source_realized_trust_boundary_status",
        source_realized_activity_trust_boundary_status(rows)
      )
      |> maybe_put(
        "source_realized_trust_boundaries",
        source_realized_activity_trust_boundaries(rows)
      )
      |> maybe_put(
        "source_weighted_feedback_row_count",
        Map.get(timeline_source, "weighted_feedback_row_count")
      )
      |> maybe_put(
        "feedback_weight_sources",
        Map.get(timeline_source, "feedback_weight_sources")
      )
      |> maybe_put(
        "feedback_trust_boundaries",
        Map.get(timeline_source, "feedback_trust_boundaries")
      )
      |> maybe_put_timeline_feedback_source_identity(timeline_source)
      |> maybe_put_timeline_feedback_source_counts(timeline_source)
      |> Map.update("input_keys", input_keys, fn keys ->
        keys
        |> Kernel.++(input_keys)
        |> Enum.uniq()
        |> Enum.sort()
      end)
    end
  end

  defp realized_activity_source_counts(rows, value_fun) do
    rows
    |> Enum.map(value_fun)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.frequencies()
    |> non_empty_map()
  end

  defp realized_activity_type(row) do
    row
    |> stringify_keys()
    |> Map.get("type")
    |> encode_value()
  end

  defp realized_activity_direction(row) do
    row
    |> stringify_keys()
    |> Map.get("direction")
    |> encode_value()
  end

  defp realized_activity_status(row) do
    row
    |> stringify_keys()
    |> Map.get("status")
    |> encode_value()
  end

  defp realized_activity_feedback_weight_source(row) do
    row = stringify_keys(row)

    Enum.find_value(
      [
        "feedback_weight_source",
        "feedback_sample_weight_source",
        "sample_weight_source",
        "confidence_weight_source"
      ],
      &Map.get(row, &1)
    )
    |> encode_value()
  end

  defp source_realized_activity_trust_boundary_status(rows) do
    if source_realized_activity_trust_boundaries(rows) == [] do
      "missing"
    else
      "declared"
    end
  end

  defp source_realized_activity_trust_boundaries(rows) do
    rows
    |> Enum.flat_map(fn row ->
      row = stringify_keys(row)

      [
        Map.get(row, "trust_boundary"),
        Map.get(row, "_source_report_trust_boundary"),
        get_in(row, ["provenance", "trust_boundary"]),
        get_in(row, ["metadata", "trust_boundary"])
      ]
    end)
    |> normalize_trust_boundaries()
  end

  defp maybe_put_timeline_feedback_source_identity(provenance, timeline_source) do
    provenance
    |> maybe_put(
      "source_timeline_feedback_report_contract",
      Map.get(timeline_source, "source_report_contract")
    )
    |> maybe_put(
      "source_timeline_feedback_report_count",
      Map.get(timeline_source, "source_report_count")
    )
    |> maybe_put(
      "source_timeline_feedback_report_row_count",
      Map.get(timeline_source, "source_report_row_count")
    )
    |> maybe_put(
      "source_timeline_feedback_input_keys",
      Map.get(timeline_source, "input_keys")
    )
    |> maybe_put(
      "source_timeline_feedback_trust_boundary_status",
      Map.get(timeline_source, "trust_boundary_status")
    )
    |> maybe_put(
      "source_timeline_feedback_trust_boundaries",
      Map.get(timeline_source, "trust_boundaries")
    )
  end

  defp maybe_put_timeline_feedback_source_counts(provenance, timeline_source) do
    [
      "source_report_status_counts",
      "source_feedback_kind_counts",
      "source_match_strategy_counts",
      "source_cadence_import_status_counts",
      "source_planned_protection_decision_counts",
      "source_execution_uncertainty_declared_count",
      "source_execution_uncertainty_missing_count",
      "source_station_reservation_evidence_row_count",
      "source_station_reservation_expiration_evidence_row_count",
      "source_operational_feedback_excluded_count"
    ]
    |> Enum.reduce(provenance, fn key, provenance ->
      maybe_put(provenance, key, Map.get(timeline_source, key))
    end)
  end

  defp operational_feedback_trust_boundary_status(refresh) do
    case operational_feedback_provenance(refresh) do
      %{"trust_boundary_status" => status} -> status
      _provenance -> nil
    end
  end

  defp operational_feedback_applied?(refresh) do
    refresh
    |> operational_feedback()
    |> operational_feedback_data_keys()
    |> Kernel.!=([])
  end

  defp operational_feedback(refresh) do
    case refresh |> raw_operational_feedback() |> stringify_keys() do
      feedback when is_map(feedback) -> normalize_operational_feedback(feedback, refresh)
      _feedback -> %{}
    end
  end

  defp raw_operational_feedback(refresh) do
    cond do
      Map.has_key?(refresh, "operational_feedback") ->
        Map.get(refresh, "operational_feedback")

      is_map(Map.get(refresh, "mission_state")) and
          Map.has_key?(Map.get(refresh, "mission_state"), "operational_feedback") ->
        get_in(refresh, ["mission_state", "operational_feedback"])

      is_map(Map.get(refresh, "accepted_planning_state")) and
          Map.has_key?(Map.get(refresh, "accepted_planning_state"), "operational_feedback") ->
        get_in(refresh, ["accepted_planning_state", "operational_feedback"])

      true ->
        %{}
    end
  end

  defp operational_feedback_source_path(refresh) do
    cond do
      Map.has_key?(refresh, "operational_feedback") ->
        "operational_feedback"

      is_map(Map.get(refresh, "mission_state")) and
          Map.has_key?(Map.get(refresh, "mission_state"), "operational_feedback") ->
        "mission_state.operational_feedback"

      is_map(Map.get(refresh, "accepted_planning_state")) and
          Map.has_key?(Map.get(refresh, "accepted_planning_state"), "operational_feedback") ->
        "accepted_planning_state.operational_feedback"

      true ->
        nil
    end
  end

  defp invalid_operational_feedback_input?(%{"operational_feedback" => feedback}),
    do: not is_map(feedback)

  defp invalid_operational_feedback_input?(refresh),
    do: not is_map(raw_operational_feedback(refresh))

  defp operational_feedback_data_keys(feedback) when is_map(feedback) do
    feedback
    |> Map.drop(["provenance", "trust_boundary", "source", "metadata"])
    |> Enum.reject(fn {_key, value} -> value in [nil, %{}, []] end)
    |> Enum.map(fn {key, _value} -> key end)
    |> Enum.sort()
  end

  defp normalize_operational_feedback(feedback, refresh) when is_map(feedback) do
    refresh
    |> source_operational_timeline_report_operational_feedback()
    |> merge_operational_feedback(source_timeline_feedback_report_operational_feedback(refresh))
    |> merge_operational_feedback(source_timeline_diff_report_operational_feedback(refresh))
    |> merge_operational_feedback(source_command_window_report_operational_feedback(refresh))
    |> merge_operational_feedback(source_maneuver_review_report_operational_feedback(refresh))
    |> merge_operational_feedback(source_result_artifact_operational_feedback(refresh))
    |> merge_operational_feedback(source_resource_projection_report_operational_feedback(refresh))
    |> merge_operational_feedback(source_resource_filter_report_operational_feedback(refresh))
    |> merge_operational_feedback(source_link_capacity_report_operational_feedback(refresh))
    |> merge_operational_feedback(source_realized_activity_operational_feedback(refresh))
    |> merge_operational_feedback(realized_activity_operational_feedback(feedback, refresh))
    |> merge_operational_feedback(normalize_explicit_operational_feedback(feedback))
    |> compact_operational_feedback()
  end

  defp source_realized_activity_operational_feedback(refresh) do
    rows =
      refresh |> source_realized_activity_feedback_rows() |> Enum.map(fn {_path, row} -> row end)

    case realized_activity_operational_feedback_report_for_rows(rows, refresh) do
      %{} = report -> TimelineFeedback.operational_feedback(report)
      _report -> %{}
    end
  end

  defp source_result_artifact_operational_feedback(refresh) do
    sources = source_result_artifact_operational_feedback_sources(refresh)

    sources
    |> Enum.reduce(%{}, fn {_path, feedback, _trust_boundary}, merged ->
      feedback =
        feedback
        |> normalize_explicit_operational_feedback()
        |> Map.drop(["provenance", "trust_boundary"])

      merge_operational_feedback(merged, feedback)
    end)
    |> maybe_put_source_result_artifact_operational_feedback_trust_boundary(sources)
    |> compact_operational_feedback()
  end

  defp source_result_artifact_operational_feedback_sources(refresh) do
    refresh
    |> source_result_artifacts()
    |> Enum.flat_map(fn {path, artifact} ->
      case Map.get(artifact, "operational_feedback") do
        %{} = feedback ->
          [
            {
              "#{path}.operational_feedback",
              stringify_keys(feedback),
              source_result_artifact_operational_feedback_trust_boundary(feedback, artifact)
            }
          ]

        _feedback ->
          []
      end
    end)
  end

  defp maybe_put_source_result_artifact_operational_feedback_trust_boundary(feedback, sources) do
    trust_boundaries =
      sources
      |> Enum.map(fn {_path, _feedback, trust_boundary} -> encode_value(trust_boundary) end)
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.uniq()
      |> Enum.sort()

    case trust_boundaries do
      [trust_boundary] -> Map.put_new(feedback, "trust_boundary", trust_boundary)
      _trust_boundaries -> feedback
    end
  end

  defp source_result_artifact_operational_feedback_field_trust_boundaries(sources) do
    sources
    |> Enum.reduce(%{}, fn {_path, feedback, trust_boundary}, boundaries ->
      trust_boundaries =
        trust_boundary
        |> List.wrap()
        |> Enum.map(&encode_value/1)
        |> Enum.reject(&(&1 in [nil, ""]))
        |> Enum.uniq()
        |> Enum.sort()

      if trust_boundaries == [] do
        boundaries
      else
        feedback
        |> normalize_explicit_operational_feedback()
        |> Map.drop(["provenance", "trust_boundary"])
        |> Enum.reduce(boundaries, fn {field, values}, boundaries ->
          put_operational_feedback_field_trust_boundaries(
            boundaries,
            field,
            values,
            trust_boundaries
          )
        end)
      end
    end)
    |> case do
      boundaries when boundaries == %{} -> nil
      boundaries -> boundaries
    end
  end

  defp put_operational_feedback_field_trust_boundaries(
         boundaries,
         field,
         %{} = values,
         trust_boundaries
       ) do
    values
    |> Enum.reduce(boundaries, fn {key, value}, boundaries ->
      if value in [nil, %{}, []] do
        boundaries
      else
        put_feedback_trust_boundary(boundaries, field, key, trust_boundaries)
      end
    end)
  end

  defp put_operational_feedback_field_trust_boundaries(
         boundaries,
         _field,
         _values,
         _trust_boundaries
       ),
       do: boundaries

  defp put_feedback_trust_boundary(boundaries, field, key, trust_boundaries) do
    field = encode_value(field)
    key = encode_value(key) || "default"

    Map.update(boundaries, field, %{key => trust_boundaries}, fn field_boundaries ->
      Map.update(field_boundaries, key, trust_boundaries, fn existing ->
        (List.wrap(existing) ++ trust_boundaries)
        |> Enum.uniq()
        |> Enum.sort()
      end)
    end)
  end

  defp source_result_artifact_operational_feedback_trust_boundary(%{} = feedback, artifact) do
    feedback = stringify_keys(feedback)

    Map.get(feedback, "trust_boundary") ||
      get_in(feedback, ["provenance", "trust_boundary"]) ||
      result_artifact_trust_boundary(artifact)
  end

