  defp link_capacity_row_operational_feedback(%{} = row) do
    row = stringify_keys(row)
    station_id = link_capacity_station_id(row)
    factor = link_capacity_station_throughput_factor(row)

    cond do
      station_id in [nil, ""] ->
        %{}

      not is_number(factor) ->
        %{}

      true ->
        %{
          "station_throughput_factor" => %{station_id => factor}
        }
        |> compact_operational_feedback()
    end
  end

  defp link_capacity_row_operational_feedback(_row), do: %{}

  defp link_capacity_station_throughput_factor(row) do
    case objective_satisfaction_first_number(row, [
           "station_throughput_factor",
           "throughput_completion_fraction",
           "actual_completion_fraction",
           "actual_downlink_completion_ratio"
         ]) do
      factor when is_number(factor) ->
        factor |> max(0.0) |> min(1.0)

      _factor ->
        actual =
          objective_satisfaction_first_number(row, [
            "actual_throughput_mb",
            "actual_downlink_mb",
            "delivered_data_mb",
            "received_data_mb"
          ])

        planned =
          objective_satisfaction_first_number(row, [
            "selected_capacity_adjusted_throughput_mb",
            "selected_estimated_throughput_mb",
            "capacity_adjusted_throughput_mb",
            "estimated_throughput_mb"
          ])

        if is_number(actual) and is_number(planned) and planned > 0.0 do
          (actual / planned) |> max(0.0) |> min(1.0)
        end
    end
  end

