  defp source_cadence_import_realized_feedback_entries(path, manifests) when is_list(manifests) do
    manifests
    |> Enum.with_index()
    |> Enum.flat_map(fn {manifest, index} ->
      source_cadence_import_realized_feedback_entries("#{path}[#{index}]", manifest)
    end)
  end

  defp source_cadence_import_realized_feedback_entries(path, %{} = manifest) do
    manifest = stringify_keys(manifest)

    manifest
    |> Map.get("rows", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.filter(fn row ->
      row["source_review_type"] == "realized_feedback" or
        row["import_action"] in ["review_realized_feedback", "record_realized_feedback"]
    end)
    |> Enum.flat_map(fn row ->
      case realized_feedback_row_from_review_or_import_row(row, manifest) do
        %{} = realized_row ->
          row_source_path =
            if is_map(row["source_review_row"]) do
              "#{path}.rows.source_review_row.source_feedback"
            else
              "#{path}.rows.source_feedback"
            end

          [{row_source_path, realized_row}]

        _row ->
          []
      end
    end)
  end

  defp source_cadence_import_realized_feedback_entries(_path, _manifest), do: []

  defp realized_feedback_row_from_review_or_import_row(%{} = row, %{} = artifact) do
    row = stringify_keys(row)
    source_review_row = stringify_keys(Map.get(row, "source_review_row", %{}))

    source =
      cond do
        is_map(row["source_feedback"]) -> row["source_feedback"]
        is_map(source_review_row["source_feedback"]) -> source_review_row["source_feedback"]
        map_size(source_review_row) > 0 -> source_review_row
        true -> row
      end
      |> stringify_keys()

    fallback = realized_feedback_review_fallback(row, source_review_row)
    feedback_status = fallback["feedback_status"] || source["status"]

    realized_status =
      fallback["realized_status"] || source["realized_status"] || fallback["status"]

    source
    |> Map.put("schema_contract", "realized_activity.v1")
    |> maybe_put("feedback_status", feedback_status)
    |> maybe_put("status", realized_status)
    |> put_realized_feedback_fallback(fallback, "activity_id")
    |> put_realized_feedback_fallback(fallback, "id", "activity_id")
    |> put_realized_feedback_fallback(fallback, "timeline_id", "timeline_identity")
    |> put_realized_feedback_fallback(fallback, "scenario_id")
    |> put_realized_feedback_fallback(fallback, "ground_station_id")
    |> put_realized_feedback_fallback(fallback, "ground_station_id", "planned_ground_station_id")
    |> put_realized_feedback_fallback(fallback, "ground_station_id", "realized_ground_station_id")
    |> put_realized_feedback_fallback(fallback, "target_id")
    |> put_realized_feedback_fallback(fallback, "target_id", "planned_target_id")
    |> put_realized_feedback_fallback(fallback, "target_id", "realized_target_id")
    |> put_realized_feedback_fallback(fallback, "contact_success")
    |> put_realized_feedback_fallback(fallback, "contact_success_factor")
    |> put_realized_feedback_fallback(fallback, "contact_result")
    |> put_realized_feedback_fallback(fallback, "observation_success")
    |> put_realized_feedback_fallback(fallback, "observation_success_factor")
    |> put_realized_feedback_fallback(fallback, "observation_result")
    |> put_realized_feedback_fallback(fallback, "image_quality_score")
    |> put_realized_feedback_fallback(fallback, "image_quality_status")
    |> put_realized_feedback_fallback(fallback, "image_quality_source")
    |> put_realized_feedback_fallback(fallback, "cloud_cover_fraction")
    |> put_realized_feedback_fallback(fallback, "blur_score")
    |> put_realized_feedback_fallback(fallback, "command_success")
    |> put_realized_feedback_fallback(fallback, "command_success_factor")
    |> put_realized_feedback_fallback(fallback, "command_result")
    |> put_realized_feedback_fallback(fallback, "maneuver_success")
    |> put_realized_feedback_fallback(fallback, "maneuver_success_factor")
    |> put_realized_feedback_fallback(fallback, "maneuver_result")
    |> put_realized_feedback_fallback(fallback, "execution_uncertainty")
    |> put_realized_feedback_fallback(fallback, "execution_uncertainty_status")
    |> put_realized_feedback_fallback(fallback, "timing_3sigma_s")
    |> put_realized_feedback_fallback(fallback, "delta_v_3sigma_km_s")
    |> put_realized_feedback_fallback(fallback, "delta_v_3sigma_magnitude_km_s")
    |> put_realized_feedback_fallback(fallback, "execution_uncertainty_source")
    |> put_realized_feedback_fallback(fallback, "actual_throughput_mb")
    |> put_realized_feedback_fallback(fallback, "estimated_throughput_mb")
    |> put_realized_feedback_fallback(fallback, "required_downlink_mb")
    |> put_realized_feedback_fallback(fallback, "completed_fraction")
    |> put_realized_feedback_fallback(fallback, "feedback_weight")
    |> put_realized_feedback_fallback(fallback, "feedback_weight_source")
    |> put_realized_feedback_fallback(fallback, "feedback_sample_weight")
    |> put_realized_feedback_fallback(fallback, "feedback_sample_weight_source")
    |> put_realized_feedback_fallback(fallback, "sample_weight")
    |> put_realized_feedback_fallback(fallback, "sample_weight_source")
    |> put_realized_feedback_fallback(fallback, "confidence_weight")
    |> put_realized_feedback_fallback(fallback, "confidence_weight_source")
    |> maybe_put("type", realized_feedback_review_type(fallback, source))
    |> maybe_put("_operator_review_feedback_status", feedback_status)
    |> maybe_put(
      "_operator_review_match_strategy",
      fallback["match_strategy"] || source["match_strategy"]
    )
    |> put_realized_feedback_row_trust_boundary(row, source_review_row, artifact)
    |> compact_map()
  end

  defp realized_feedback_review_fallback(row, source_review_row) do
    Map.merge(source_review_row, row, fn _key, review_value, row_value ->
      if row_value in [nil, ""], do: review_value, else: row_value
    end)
  end

  defp realized_feedback_review_type(row, source) do
    row["activity_type"] || source["activity_type"] || source["planned_type"] ||
      source["realized_type"] ||
      feedback_kind_activity_type(row["feedback_kind"] || source["feedback_kind"])
  end

  defp feedback_kind_activity_type("observation"), do: "observe"
  defp feedback_kind_activity_type("contact"), do: "contact"
  defp feedback_kind_activity_type("command"), do: "command"
  defp feedback_kind_activity_type("maneuver"), do: "maneuver"
  defp feedback_kind_activity_type(_kind), do: nil

  defp put_realized_feedback_fallback(source, row, field, row_field \\ nil) do
    row_field = row_field || field

    if Map.get(source, field) in [nil, ""] and Map.get(row, row_field) not in [nil, ""] do
      Map.put(source, field, Map.get(row, row_field))
    else
      source
    end
  end

  defp put_realized_feedback_row_trust_boundary(realized_row, row, source_review_row, artifact) do
    trust_boundary =
      Map.get(realized_row, "trust_boundary") ||
        Map.get(row, "trust_boundary") ||
        get_in(row, ["provenance", "trust_boundary"]) ||
        Map.get(source_review_row, "trust_boundary") ||
        get_in(source_review_row, ["provenance", "trust_boundary"]) ||
        result_artifact_trust_boundary(artifact)

    realized_row
    |> maybe_put("trust_boundary", trust_boundary)
    |> maybe_put("_source_report_trust_boundary", trust_boundary)
  end

  defp source_realized_activity_feedback_entries(path, row_or_rows, artifact \\ nil)

  defp source_realized_activity_feedback_entries(path, %{} = row, artifact) do
    row = stringify_keys(row)

    cond do
      realized_activity_feedback_row?(row) ->
        [{path, put_realized_activity_inherited_trust_boundary(row, artifact)}]

      realized_state_snapshot_feedback_row?(row) ->
        trust_boundary =
          realized_state_snapshot_trust_boundary(row) ||
            result_artifact_trust_boundary_or_nil(artifact)

        row
        |> realized_state_snapshot_feedback_activities()
        |> Enum.flat_map(fn activity ->
          activity =
            activity
            |> stringify_keys()
            |> maybe_put("trust_boundary", trust_boundary)
            |> maybe_put("_source_report_trust_boundary", trust_boundary)

          source_realized_activity_feedback_entries("#{path}.activities", activity, artifact)
        end)

      true ->
        []
    end
  end

  defp source_realized_activity_feedback_entries(path, rows, artifact) when is_list(rows) do
    rows
    |> Enum.flat_map(&source_realized_activity_feedback_entries(path, &1, artifact))
  end

  defp source_realized_activity_feedback_entries(_path, _row_or_rows, _artifact), do: []

  defp realized_activity_feedback_row?(%{"schema_contract" => "realized_activity.v1"}), do: true
  defp realized_activity_feedback_row?(_row), do: false

  defp realized_state_snapshot_feedback_row?(%{
         "schema_contract" => "realized_state_snapshot.v1"
       }),
       do: true

  defp realized_state_snapshot_feedback_row?(_row), do: false

  defp realized_state_snapshot_feedback_activities(snapshot) do
    Map.get(snapshot, "activities") || Map.get(snapshot, "realized_activities") || []
  end

  defp realized_state_snapshot_trust_boundary(snapshot) do
    Map.get(snapshot, "trust_boundary") ||
      get_in(snapshot, ["provenance", "trust_boundary"]) ||
      get_in(snapshot, ["metadata", "trust_boundary"])
  end

  defp put_realized_activity_inherited_trust_boundary(row, %{} = artifact) do
    case result_artifact_trust_boundary(artifact) do
      trust_boundary when trust_boundary in [nil, ""] ->
        row

      trust_boundary ->
        row
        |> Map.put_new("trust_boundary", encode_value(trust_boundary))
        |> Map.put_new("_source_report_trust_boundary", encode_value(trust_boundary))
    end
  end

  defp put_realized_activity_inherited_trust_boundary(row, _artifact), do: row

  defp result_artifact_trust_boundary_or_nil(%{} = artifact),
    do: result_artifact_trust_boundary(artifact)

  defp result_artifact_trust_boundary_or_nil(_artifact), do: nil

