  defp quality_gate_report_from_import_readiness_summary(%{} = summary) do
    summary = stringify_keys(summary)
    status = quality_gate_import_readiness_status(summary)
    classification = quality_gate_import_readiness_classification(status)

    %{
      "schema_contract" => "quality_gate_report.v1",
      "model" => "preserved_operational_quality_gate_import_readiness_summary",
      "source" => summary["source"],
      "source_summary_model" => summary["model"],
      "source_summary_schema_contract" => summary["schema_contract"],
      "source_artifact_type" => summary["source_artifact_type"],
      "source_artifact_id" => summary["source_artifact_id"],
      "source_quality_gate_report_id" => summary["source_quality_gate_report_id"],
      "source_readiness_report_id" => summary["source_readiness_report_id"],
      "readiness_level" => quality_gate_import_readiness_level(classification),
      "import_classification" => classification,
      "status" => status,
      "gate_count" => summary["import_readiness_row_count"],
      "passed_gate_count" => length(list_value(summary["ready_quality_gate_row_ids"])),
      "review_gate_count" => length(list_value(summary["review_required_quality_gate_row_ids"])),
      "analysis_gate_count" => length(list_value(summary["analysis_only_quality_gate_row_ids"])),
      "blocked_gate_count" => length(list_value(summary["blocked_quality_gate_row_ids"])),
      "gate_status_counts" =>
        quality_gate_import_readiness_status_counts(summary["quality_gate_row_ids_by_status"]),
      "gate_classification_counts" =>
        quality_gate_import_readiness_classification_counts(
          summary["quality_gate_row_ids_by_status"]
        ),
      "import_readiness_row_count" => summary["import_readiness_row_count"],
      "ready_for_import_count" => summary["ready_for_import_count"],
      "manifest_review_required_count" => summary["manifest_review_required_count"],
      "blocked_import_count" => summary["blocked_import_count"],
      "missing_import_count" => summary["missing_import_count"],
      "invalid_cadence_import_count" => summary["invalid_cadence_import_count"],
      "current_freshness_count" => summary["current_freshness_count"],
      "stale_freshness_count" => summary["stale_freshness_count"],
      "unknown_freshness_count" => summary["unknown_freshness_count"],
      "freshness_status_counts" => summary["freshness_status_counts"],
      "schema_validation_pass_count" => summary["schema_validation_pass_count"],
      "schema_validation_fail_count" => summary["schema_validation_fail_count"],
      "schema_validation_error_count" => summary["schema_validation_error_count"],
      "schema_validation_warning_count" => summary["schema_validation_warning_count"],
      "schema_validation_remediation_count" => summary["schema_validation_remediation_count"],
      "schema_validation_status_counts" => summary["schema_validation_status_counts"],
      "import_status_counts" => summary["import_status_counts"],
      "cadence_import_status_counts" => summary["cadence_import_status_counts"],
      "quality_gate_row_ids_by_status" => summary["quality_gate_row_ids_by_status"],
      "quality_gate_ids_by_status" => summary["quality_gate_ids_by_status"],
      "review_required_quality_gate_row_ids" => summary["review_required_quality_gate_row_ids"],
      "blocked_quality_gate_row_ids" => summary["blocked_quality_gate_row_ids"],
      "ready_quality_gate_row_ids" => summary["ready_quality_gate_row_ids"],
      "analysis_only_quality_gate_row_ids" => summary["analysis_only_quality_gate_row_ids"],
      "stale_or_unknown_freshness_quality_gate_row_ids" =>
        summary["stale_or_unknown_freshness_quality_gate_row_ids"],
      "import_preparation_quality_gate_row_ids" =>
        summary["import_preparation_quality_gate_row_ids"],
      "blocked_import_quality_gate_row_ids" => summary["blocked_import_quality_gate_row_ids"],
      "import_readiness_gate_ids" => summary["import_readiness_gate_ids"],
      "trust_boundary" => summary["trust_boundary"],
      "trust_boundaries" => summary["trust_boundaries"],
      "assumptions" => summary["assumptions"]
    }
    |> maybe_put("provenance", summary["provenance"])
    |> compact_map()
  end

  defp quality_gate_import_readiness_status(%{} = summary) do
    cond do
      list_value(summary["blocked_quality_gate_row_ids"]) != [] or
        positive_summary_count?(summary, "blocked_import_count") or
          positive_summary_count?(summary, "invalid_cadence_import_count") ->
        "blocked"

      list_value(summary["analysis_only_quality_gate_row_ids"]) != [] ->
        "analysis_only"

      list_value(summary["review_required_quality_gate_row_ids"]) != [] or
        list_value(summary["stale_or_unknown_freshness_quality_gate_row_ids"]) != [] or
        list_value(summary["import_preparation_quality_gate_row_ids"]) != [] or
        positive_summary_count?(summary, "manifest_review_required_count") or
        positive_summary_count?(summary, "stale_freshness_count") or
          positive_summary_count?(summary, "unknown_freshness_count") ->
        "review_required"

      true ->
        "passed"
    end
  end

  defp quality_gate_import_readiness_classification("blocked"), do: "blocked"
  defp quality_gate_import_readiness_classification("analysis_only"), do: "analysis_only"
  defp quality_gate_import_readiness_classification("review_required"), do: "review_only"
  defp quality_gate_import_readiness_classification(_status), do: "importable"

  defp positive_summary_count?(summary, field), do: numeric_report_count(summary, field) > 0

  defp quality_gate_import_readiness_level("blocked"), do: "blocked"
  defp quality_gate_import_readiness_level("analysis_only"), do: "analysis_only"
  defp quality_gate_import_readiness_level("review_only"), do: "operator_review"
  defp quality_gate_import_readiness_level(_classification), do: "import_eligible"

  defp quality_gate_import_readiness_status_counts(%{} = row_ids_by_status) do
    row_ids_by_status
    |> Enum.reduce(%{}, fn {status, ids}, acc ->
      count = ids |> list_value() |> length()

      if count > 0, do: Map.put(acc, status, count), else: acc
    end)
  end

  defp quality_gate_import_readiness_status_counts(_row_ids_by_status), do: %{}

  defp quality_gate_import_readiness_classification_counts(%{} = row_ids_by_status) do
    row_ids_by_status
    |> Enum.reduce(%{}, fn {status, ids}, acc ->
      count = ids |> list_value() |> length()
      classification = quality_gate_import_readiness_classification(status)

      if count > 0, do: Map.update(acc, classification, count, &(&1 + count)), else: acc
    end)
  end

  defp quality_gate_import_readiness_classification_counts(_row_ids_by_status), do: %{}

