  defp source_schema_validation_report_entries(_path, _value), do: []

  defp source_schema_validation_batch_report_entries(path, %{} = value) do
    value = stringify_keys(value)

    batch_trust_boundary =
      Map.get(value, "trust_boundary") || get_in(value, ["provenance", "trust_boundary"])

    value
    |> Map.get("reports", [])
    |> List.wrap()
    |> Enum.with_index()
    |> Enum.flat_map(fn {entry, index} ->
      entry = stringify_keys(entry)

      case stringify_keys(Map.get(entry, "report", %{})) do
        %{} = report when map_size(report) > 0 ->
          report =
            report
            |> Map.put_new("artifact_path", entry["path"])
            |> Map.put("batch_entry_path", entry["path"])
            |> maybe_put_inherited_trust_boundary(batch_trust_boundary)

          source_schema_validation_report_entries("#{path}.reports[#{index}].report", report)

        _report ->
          []
      end
    end)
  end

  defp source_schema_validation_batch_report_entries(_path, _value), do: []

  defp maybe_put_inherited_trust_boundary(report, trust_boundary)
