  defp contact_intent_from_review_or_import_row(%{} = row) do
    embedded =
      cond do
        is_map(row["source_contact_intent"]) ->
          row["source_contact_intent"]

        is_map(get_in(row, ["source_review_row", "source_contact_intent"])) ->
          get_in(row, ["source_review_row", "source_contact_intent"])

        true ->
          %{}
      end

    embedded =
      case embedded do
        %{} = intent -> stringify_keys(intent)
        _intent -> %{}
      end

    row
    |> Map.drop(["source_review_row"])
    |> Map.merge(embedded)
    |> Map.put_new("schema_contract", "contact_intent.v1")
    |> Map.put_new("id", row["activity_id"] || row["subject_id"] || row["id"])
    |> Map.put_new("activity_id", row["activity_id"] || row["subject_id"])
    |> Map.put_new("activity_type", row["activity_type"])
    |> Map.put_new("direction", row["direction"])
    |> compact_map()
  end

  defp station_calendar_row_from_review_or_import_row(%{} = row) do
    embedded =
      cond do
        is_map(row["source_station_calendar_review"]) ->
          row["source_station_calendar_review"]

        is_map(get_in(row, ["source_review_row", "source_station_calendar_review"])) ->
          get_in(row, ["source_review_row", "source_station_calendar_review"])

        true ->
          %{}
      end

    embedded =
      case embedded do
        %{} = station_row -> stringify_keys(station_row)
        _station_row -> %{}
      end

    row
    |> Map.drop(["source_review_row"])
    |> Map.merge(embedded)
    |> Map.put_new("contact_id", row["contact_id"] || row["subject_id"])
    |> Map.put_new("contact_type", row["activity_type"])
    |> compact_map()
  end

  defp objective_satisfaction_row_from_review_or_import_row(%{} = row) do
    embedded =
      cond do
        is_map(row["source_objective_satisfaction"]) ->
          row["source_objective_satisfaction"]

        is_map(get_in(row, ["source_review_row", "source_objective_satisfaction"])) ->
          get_in(row, ["source_review_row", "source_objective_satisfaction"])

        true ->
          %{}
      end

    embedded =
      case embedded do
        %{} = objective -> stringify_keys(objective)
        _objective -> %{}
      end

    row
    |> Map.drop(["source_review_row"])
    |> Map.merge(embedded)
    |> Map.put_new("id", row["objective_id"] || row["subject_id"] || row["id"])
    |> Map.put_new("objective", row["objective"] || row["objective_type"])
    |> Map.put_new("status", row["objective_status"])
    |> Map.put_new("target_id", row["target_id"])
    |> Map.put_new("ground_station_id", row["ground_station_id"])
    |> compact_map()
    |> case do
      objective_row when is_map(objective_row) ->
        if Map.get(objective_row, "objective") not in [nil, ""], do: objective_row

      _objective_row ->
        nil
    end
  end

  defp timeline_diff_row_from_review_or_import_row(%{} = row) do
    source_application =
      row
      |> timeline_diff_source_application_from_review_or_import_row()
      |> stringify_keys()

    embedded =
      cond do
        is_map(row["source_timeline_diff"]) ->
          row["source_timeline_diff"]

        is_map(get_in(row, ["source_review_row", "source_timeline_diff"])) ->
          get_in(row, ["source_review_row", "source_timeline_diff"])

        is_map(source_application["source_timeline_diff"]) ->
          source_application["source_timeline_diff"]

        true ->
          %{}
      end

    embedded =
      case embedded do
        %{} = diff -> stringify_keys(diff)
        _diff -> %{}
      end

    row
    |> Map.drop([
      "source_review_row",
      "source_timeline_application",
      "source_timeline_transition_application"
    ])
    |> Map.merge(embedded)
