  defp timeline_dependency_impact_summary_from_embedded_rows(path, source, rows, artifact) do
    summary =
      %{
        "model" => "artifact_only_timeline_dependency_impact_summary",
        "source" => source,
        "source_artifact_type" => Map.get(artifact, "source_artifact_type"),
        "source_artifact_id" => Map.get(artifact, "source_artifact_id"),
        "dependency_impact_rows" => rows,
        "dependent_activity_count" => length(rows),
        "source_dependent_activity_count" =>
          Enum.count(rows, &(timeline_dependency_impact_row_scope(&1) == "source")),
        "replacement_dependent_activity_count" =>
          Enum.count(rows, &(timeline_dependency_impact_row_scope(&1) == "replacement")),
        "dependency_impact_status" =>
          if(Enum.any?(rows, &(&1["dependency_impact_status"] == "review_required")),
            do: "review_required",
            else: "clear"
          ),
        "impacted_source_activity_ids" =>
          rows
          |> Enum.flat_map(
            &timeline_dependency_impact_summary_values(&1, "impacted_source_activity_ids")
          )
          |> sorted_string_values(),
        "impacted_source_timeline_ids" =>
          rows
          |> Enum.flat_map(
            &timeline_dependency_impact_summary_values(&1, "impacted_source_timeline_ids")
          )
          |> sorted_string_values(),
        "impacted_dependency_activity_ids" =>
          rows
          |> Enum.flat_map(
            &timeline_dependency_impact_summary_values(&1, "impacted_dependency_activity_ids")
          )
