        "impacted_dependency_timeline_ids" =>
          rows
          |> Enum.flat_map(
            &timeline_dependency_impact_summary_values(&1, "impacted_dependency_timeline_ids")
          )
          |> sorted_string_values(),
        "impacted_exclusive_with_activity_ids" =>
          rows
          |> Enum.flat_map(
            &timeline_dependency_impact_summary_values(
              &1,
              "impacted_exclusive_with_activity_ids"
            )
          )
          |> sorted_string_values(),
        "impacted_exclusive_with_timeline_ids" =>
          rows
          |> Enum.flat_map(
            &timeline_dependency_impact_summary_values(
              &1,
              "impacted_exclusive_with_timeline_ids"
            )
          )
          |> sorted_string_values()
      }
      |> maybe_put("provenance", Map.get(artifact, "provenance"))
      |> maybe_put("trust_boundary", result_artifact_trust_boundary(artifact))
      |> compact_map()

    {path, summary}
