  defp timeline_activity_precondition_summary_from_embedded_rows(_path, _source, [], _artifact),
    do: nil

  defp timeline_activity_precondition_summary_from_embedded_rows(path, source, rows, artifact) do
    preconditions =
      rows
      |> Enum.flat_map(&(Map.get(&1, "preconditions") || []))
      |> Enum.filter(&is_map/1)

    summary =
      %{
        "schema_contract" => "timeline_activity_precondition_summary.v1",
        "model" => "artifact_only_timeline_activity_precondition_summary",
        "source" => source,
        "source_artifact_type" => Map.get(artifact, "source_artifact_type"),
        "source_artifact_id" => Map.get(artifact, "source_artifact_id"),
        "precondition_status" => timeline_activity_precondition_rows_status(rows),
        "blocked_precondition_count" =>
          sum_report_count(rows, &numeric_report_count(&1, "blocked_precondition_count")),
        "review_precondition_count" =>
          sum_report_count(rows, &numeric_report_count(&1, "review_precondition_count")),
        "blocked_precondition_types" =>
          rows
          |> Enum.flat_map(&Map.get(&1, "blocked_precondition_types", []))
          |> sorted_string_values(),
        "review_precondition_types" =>
          rows
          |> Enum.flat_map(&Map.get(&1, "review_precondition_types", []))
          |> sorted_string_values(),
        "preconditions" => preconditions,
        "activity_id" =>
          rows
          |> Enum.map(&Map.get(&1, "activity_id"))
          |> sorted_string_values()
          |> case do
            [activity_id] -> activity_id
            _activity_ids -> nil
          end,
        "timeline_id" =>
          rows
          |> Enum.map(&Map.get(&1, "timeline_id"))
          |> sorted_string_values()
          |> case do
            [timeline_id] -> timeline_id
            _timeline_ids -> nil
          end,
        "dependency_activity_ids" =>
          rows
          |> Enum.flat_map(&Map.get(&1, "dependency_activity_ids", []))
          |> sorted_string_values(),
        "dependency_timeline_ids" =>
          rows
          |> Enum.flat_map(&Map.get(&1, "dependency_timeline_ids", []))
          |> sorted_string_values(),
        "exclusive_with_activity_ids" =>
          rows
          |> Enum.flat_map(&Map.get(&1, "exclusive_with_activity_ids", []))
          |> sorted_string_values(),
        "exclusive_with_timeline_ids" =>
          rows
          |> Enum.flat_map(&Map.get(&1, "exclusive_with_timeline_ids", []))
          |> sorted_string_values(),
        "allow_overlap" => if(Enum.any?(rows, &(&1["allow_overlap"] == true)), do: true),
        "invalid_activity_input" => Enum.any?(rows, &(&1["invalid_activity_input"] == true)),
        "invalid_activity_input_count" =>
          Enum.count(rows, &(&1["invalid_activity_input"] == true)),
        "invalid_activity_input_reasons" =>
          rows
          |> Enum.flat_map(
            &timeline_activity_precondition_summary_invalid_activity_input_reasons/1
          )
          |> sorted_string_values()
      }
      |> maybe_put("provenance", Map.get(artifact, "provenance"))
      |> maybe_put("trust_boundary", result_artifact_trust_boundary(artifact))
      |> compact_map()

    {path, summary}
  end

  defp timeline_activity_precondition_rows_status(rows) do
    cond do
      Enum.any?(rows, &(&1["precondition_status"] == "blocked")) -> "blocked"
      Enum.any?(rows, &(&1["precondition_status"] == "review_required")) -> "review_required"
      Enum.any?(rows, &(&1["invalid_activity_input"] == true)) -> "review_required"
      true -> "clear"
    end
  end

