  defp provider_counteroffer_summary_count(summary, field, rows_or_count) do
    case numeric_report_count(summary, field) do
      0 when is_list(rows_or_count) -> length(rows_or_count)
      0 when is_integer(rows_or_count) -> rows_or_count
      count -> count
    end
  end

  defp contact_allocation_summary_count(summary, field, fallback_count) do
    case numeric_report_count(summary, field) do
      0 -> fallback_count
      count -> count
    end
  end

  defp summary_string_list_map(summary, field) do
    summary
    |> Map.get(field)
    |> map_value_lists()
  end

  defp summary_nested_string_list_map(summary, field) do
    summary
    |> Map.get(field)
    |> nested_map_value_lists()
  end

  defp provider_counteroffer_timing_shift_rows(rows) do
    Enum.filter(rows, fn row ->
      Enum.any?(
        [
          "provider_counteroffer_start_delta_s",
          "provider_counteroffer_end_delta_s",
          "provider_counteroffer_duration_delta_s"
        ],
        fn field ->
          case numeric_value(Map.get(row, field)) do
            nil -> false
            value -> value != 0.0
          end
        end
      )
    end)
  end

  defp provider_counteroffer_numeric_value_count(rows, field) do
    rows
    |> provider_counteroffer_numeric_values(field)
    |> length()
  end

  defp provider_counteroffer_numeric_value_sum(rows, field) do
    rows
    |> provider_counteroffer_numeric_values(field)
    |> Enum.sum()
  end

  defp provider_counteroffer_numeric_value_min(rows, field) do
    rows
    |> provider_counteroffer_numeric_values(field)
    |> Enum.min(fn -> nil end)
  end

  defp provider_counteroffer_numeric_values(rows, field) do
    rows
    |> Enum.map(&(Map.get(&1, field) |> numeric_value()))
    |> Enum.reject(&is_nil/1)
  end

  defp count_values(values) do
    values
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.reduce(%{}, fn value, counts -> Map.update(counts, value, 1, &(&1 + 1)) end)
  end

  defp sorted_string_values(values) when is_list(values) do
    values
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp sorted_string_values(_values), do: []

