  defp operational_readiness_report_from_review_or_import_rows(path, rows, artifact) do
    report =
      case rows |> Enum.map(&embedded_operational_readiness_report/1) |> Enum.reject(&is_nil/1) do
        [embedded_report | _reports] ->
          stringify_keys(embedded_report)

        [] ->
          artifact
          |> stringify_keys()
          |> Map.put("rows", rows)
          |> OperationalReadiness.report()
      end

    artifact = stringify_keys(artifact)

    report =
      report
      |> Map.put("source", "preserved_operational_readiness_review_rows")
      |> maybe_put("provenance", Map.get(artifact, "provenance"))
      |> maybe_put("trust_boundary", result_artifact_trust_boundary(artifact))
      |> compact_map()

    {path, report}
  end

  defp embedded_operational_readiness_report(%{} = row) do
    cond do
      is_map(get_in(row, ["source_review_row", "source_operational_readiness_report"])) ->
        get_in(row, ["source_review_row", "source_operational_readiness_report"])

      is_map(row["source_operational_readiness_report"]) ->
        row["source_operational_readiness_report"]

      true ->
        nil
    end
  end

