  defp resource_projection_report_from_embedded_rows(_path, _source, [], _artifact), do: nil

  defp resource_projection_report_from_embedded_rows(path, source, rows, artifact) do
    {projected_resources, invalid_activity_inputs, invalid_resource_summary_inputs} =
      split_resource_projection_embedded_rows(rows)

    report =
      %{
        "schema_contract" => "resource_projection_report.v1",
        "model" => "preserved_resource_projection_rows",
        "source" => source,
        "projected_resources" => projected_resources,
        "invalid_activity_inputs" => invalid_activity_inputs,
        "invalid_resource_summary_inputs" => invalid_resource_summary_inputs,
        "row_count" => length(rows),
        "projected_resource_count" => length(projected_resources),
        "invalid_activity_input_count" => length(invalid_activity_inputs),
        "invalid_resource_summary_input_count" => length(invalid_resource_summary_inputs),
        "invalid_activity_input_ids" =>
          Enum.map(invalid_activity_inputs, &(&1["activity_id"] || &1["subject_id"])),
        "invalid_resource_summary_input_ids" =>
          Enum.map(
            invalid_resource_summary_inputs,
            &(&1["resource_summary_id"] || &1["subject_id"])
          ),
        "resource_pressure_status_counts" =>
          count_resource_projection_rows(projected_resources, "resource_pressure_status")
      }
      |> maybe_put("provenance", Map.get(artifact, "provenance"))
      |> maybe_put("trust_boundary", result_artifact_trust_boundary(artifact))
      |> compact_map()

    {path, report}
  end

  defp split_resource_projection_embedded_rows(rows) do
    rows
    |> Enum.map(&stringify_keys/1)
    |> Enum.reduce({[], [], []}, fn row, {projected, invalid_activities, invalid_summaries} ->
      cond do
        resource_projection_invalid_activity_row?(row) ->
          {projected, [row | invalid_activities], invalid_summaries}

        resource_projection_invalid_summary_row?(row) ->
          {projected, invalid_activities, [row | invalid_summaries]}

        true ->
          {[row | projected], invalid_activities, invalid_summaries}
      end
    end)
    |> then(fn {projected, invalid_activities, invalid_summaries} ->
      {Enum.reverse(projected), Enum.reverse(invalid_activities), Enum.reverse(invalid_summaries)}
    end)
  end

  defp resource_projection_invalid_activity_row?(row) do
    row["invalid_activity_input"] == true or
      row["required_operator_action"] == "review_invalid_resource_projection_input" or
      row["action"] == "review_invalid_resource_projection_input"
  end

  defp resource_projection_invalid_summary_row?(row) do
    row["invalid_resource_summary_input"] == true or
      row["required_operator_action"] == "review_invalid_resource_projection_summary" or
      row["action"] == "review_invalid_resource_projection_summary"
  end

