  defp resource_filter_report_from_embedded_rows(path, source, rows, artifact) do
    {suppressed_candidates, invalid_resource_summary_inputs} =
      split_resource_filter_embedded_rows(rows)

    report =
      %{
        "schema_contract" => "resource_filter_report.v1",
        "model" => "preserved_resource_suppression_rows",
        "source" => source,
        "suppressed_candidates" => suppressed_candidates,
        "invalid_resource_summary_inputs" => invalid_resource_summary_inputs,
        "suppressed_candidate_count" => length(suppressed_candidates),
        "invalid_resource_summary_input_count" => length(invalid_resource_summary_inputs),
        "invalid_resource_summary_input_ids" =>
          Enum.map(
            invalid_resource_summary_inputs,
            &(&1["resource_summary_id"] || &1["subject_id"])
          ),
        "suppressed_reason_counts" =>
          count_resource_filter_rows(suppressed_candidates, "suppressed_reason")
      }
      |> maybe_put("provenance", Map.get(artifact, "provenance"))
      |> maybe_put("trust_boundary", result_artifact_trust_boundary(artifact))
      |> compact_map()

    {path, report}
  end

  defp split_resource_filter_embedded_rows(rows) do
    rows
    |> Enum.map(&stringify_keys/1)
    |> Enum.reduce({[], []}, fn row, {suppressed, invalid_summaries} ->
      if resource_filter_invalid_summary_row?(row) do
        {suppressed, [row | invalid_summaries]}
      else
        {[row | suppressed], invalid_summaries}
      end
    end)
    |> then(fn {suppressed, invalid_summaries} ->
      {Enum.reverse(suppressed), Enum.reverse(invalid_summaries)}
    end)
  end

  defp resource_filter_invalid_summary_row?(row) do
    row["invalid_resource_summary_input"] == true or
      row["required_operator_action"] == "review_invalid_resource_filter_summary" or
      row["action"] == "review_invalid_resource_filter_summary"
  end

