        "invalid_contact_input_count" => Enum.count(rows, &contact_filter_invalid_input_row?/1),
        "invalid_contact_input_ids" =>
          rows
          |> Enum.map(&stringify_keys/1)
          |> Enum.filter(&contact_filter_invalid_input_row?/1)
          |> Enum.map(& &1["id"]),
        "suppressed_reason_counts" => count_contact_filter_rows(rows, "suppressed_reason")
      }
      |> maybe_put("provenance", Map.get(artifact, "provenance"))
      |> maybe_put("trust_boundary", result_artifact_trust_boundary(artifact))
