  defp timeline_feedback_reports_from_result_artifact(path, %{} = artifact) do
    artifact = stringify_keys(artifact)

    exact =
      if timeline_feedback_report?(artifact) do
        [{path, artifact}]
      else
        []
      end

    nested =
      [
        "source_timeline_feedback_report",
        "timeline_feedback_report"
      ]
      |> Enum.flat_map(fn report_key ->
        case Map.get(artifact, report_key) do
          %{} = report ->
            [
              {"#{path}.#{report_key}", inherit_result_artifact_trust_boundary(report, artifact)}
            ]

          _report ->
            []
        end
      end)

    exact ++ nested
  end

  defp timeline_feedback_reports_from_result_artifact(_path, _artifact), do: []

  defp timeline_diff_reports_from_result_artifact(path, %{} = artifact) do
    artifact = stringify_keys(artifact)

    exact = source_timeline_diff_report_entries(path, artifact)

    nested =
      [
        {"#{path}.source_timeline_diff_summary",
         Map.get(artifact, "source_timeline_diff_summary")},
        {"#{path}.timeline_diff_summary", Map.get(artifact, "timeline_diff_summary")},
        {"#{path}.source_timeline_diff_report", Map.get(artifact, "source_timeline_diff_report")},
        {"#{path}.timeline_diff_report", Map.get(artifact, "timeline_diff_report")}
      ]
      |> Enum.flat_map(fn {entry_path, report_or_summary} ->
        source_timeline_diff_report_entries(
          entry_path,
          inherit_result_artifact_trust_boundary(report_or_summary, artifact)
        )
      end)

    exact ++ nested
  end

