  defp inherit_result_artifact_trust_boundary(reports, %{} = artifact) when is_list(reports) do
    Enum.map(reports, &inherit_result_artifact_trust_boundary(&1, artifact))
  end

  defp inherit_result_artifact_trust_boundary(%{} = report, %{} = artifact) do
    report = stringify_keys(report)

    trust_boundary = result_artifact_trust_boundary(artifact)

    if trust_boundary in [nil, ""] or source_timeline_feedback_trust_boundaries(report) != [] do
      report
    else
      Map.update(
        report,
        "provenance",
        %{"trust_boundary" => encode_value(trust_boundary)},
        fn
          %{} = provenance ->
            Map.put_new(provenance, "trust_boundary", encode_value(trust_boundary))

          _provenance ->
            %{"trust_boundary" => encode_value(trust_boundary)}
        end
      )
    end
  end

  defp inherit_result_artifact_trust_boundary(report, _artifact), do: report

  defp inherit_result_artifact_quality_gate_trust_boundary(reports, %{} = artifact)
       when is_list(reports) do
    Enum.map(reports, &inherit_result_artifact_quality_gate_trust_boundary(&1, artifact))
  end

  defp inherit_result_artifact_quality_gate_trust_boundary(%{} = report, %{} = artifact) do
    report = inherit_result_artifact_trust_boundary(report, artifact)
    trust_boundary = result_artifact_trust_boundary(artifact)

    if trust_boundary in [nil, ""] do
      report
    else
      Map.update(
        report,
        "trust_boundaries",
        [encode_value(trust_boundary)],
        fn trust_boundaries ->
          (list_value(trust_boundaries) ++ [encode_value(trust_boundary)])
          |> sorted_string_values()
        end
      )
    end
  end

  defp inherit_result_artifact_quality_gate_trust_boundary(report, _artifact), do: report

  defp result_artifact_trust_boundary(artifact) do
    artifact = stringify_keys(artifact)

    Map.get(artifact, "trust_boundary") ||
      get_in(artifact, ["provenance", "trust_boundary"]) ||
      get_in(artifact, ["metadata", "trust_boundary"]) ||
      get_in(artifact, ["assumptions", "trust_boundary"])
  end

  defp timeline_feedback_report?(%{} = report),
    do: is_list(Map.get(report, "rows") || Map.get(report, :rows))

  defp timeline_feedback_report?(_report), do: false

  defp timeline_diff_report?(%{} = report) do
    rows = Map.get(report, "rows") || Map.get(report, :rows)
    schema_contract = Map.get(report, "schema_contract") || Map.get(report, :schema_contract)

    source_summary_schema_contract =
      Map.get(report, "source_summary_schema_contract") ||
        Map.get(report, :source_summary_schema_contract)

    is_list(rows) and
      (schema_contract in [nil, "timeline_diff_report.v1", "timeline_diff_summary.v1"] or
         source_summary_schema_contract == "timeline_diff_summary.v1")
  end

  defp timeline_diff_report?(_report), do: false

  defp timeline_diff_summary?(%{} = summary) do
    review_rows = Map.get(summary, "review_rows") || Map.get(summary, :review_rows)
    model = Map.get(summary, "model") || Map.get(summary, :model)
