  defp resource_projection_report_from_flow_summary(%{} = summary) do
    summary = stringify_keys(summary)
    activity_resource_flow = Map.get(summary, "activity_resource_flow", [])

    projected_resources =
      summary
      |> Map.get("projected_resources", [])
      |> enrich_resource_projection_flow_projected_resources(activity_resource_flow)

    invalid_activity_inputs = Map.get(summary, "invalid_activity_inputs", [])
    invalid_resource_summary_inputs = Map.get(summary, "invalid_resource_summary_inputs", [])

    %{
      "schema_contract" => "resource_projection_report.v1",
      "source_artifact_type" => "resource_projection_flow_summary.v1",
      "source_flow_summary_model" => Map.get(summary, "model"),
      "projected_resources" => projected_resources,
      "invalid_activity_inputs" => invalid_activity_inputs,
      "invalid_resource_summary_inputs" => invalid_resource_summary_inputs,
      "projected_resource_count" =>
        resource_projection_flow_summary_count(
          summary,
          "projected_resource_count",
          projected_resources
        ),
      "invalid_activity_input_count" =>
        resource_projection_flow_summary_count(
          summary,
          "invalid_activity_input_count",
          invalid_activity_inputs
        ),
      "invalid_resource_summary_input_count" =>
        resource_projection_flow_summary_count(
          summary,
          "invalid_resource_summary_input_count",
          invalid_resource_summary_inputs
        ),
      "resource_pressure_status" => Map.get(summary, "resource_pressure_status"),
      "resource_pressure_types" => Map.get(summary, "resource_pressure_types"),
      "resource_pressure_ground_station_ids_by_type" =>
        Map.get(summary, "resource_pressure_ground_station_ids_by_type"),
      "resource_pressure_source_window_ids_by_type" =>
        Map.get(summary, "resource_pressure_source_window_ids_by_type"),
      "resource_pressure_station_calendar_entry_ids_by_type" =>
        Map.get(summary, "resource_pressure_station_calendar_entry_ids_by_type"),
      "resource_pressure_station_calendar_provider_ids_by_type" =>
        Map.get(summary, "resource_pressure_station_calendar_provider_ids_by_type"),
      "resource_pressure_station_calendar_provider_entry_ids_by_type" =>
        Map.get(summary, "resource_pressure_station_calendar_provider_entry_ids_by_type"),
      "activity_resource_flow" => activity_resource_flow,
      "model_limits" => Map.get(summary, "model_limits"),
      "assumptions" => Map.get(summary, "assumptions"),
      "provenance" => Map.get(summary, "provenance"),
      "trust_boundary" => Map.get(summary, "trust_boundary")
    }
    |> compact_map()
  end

  defp resource_projection_flow_summary_count(summary, field, rows) when is_list(rows) do
    numeric_report_count(summary, field)
    |> case do
      0 -> length(rows)
      count -> count
    end
  end

  defp enrich_resource_projection_flow_projected_resources(projected_resources, flow_rows)
       when is_list(projected_resources) and is_list(flow_rows) do
    flow_rows = Enum.map(flow_rows, &stringify_keys/1)

    Enum.map(projected_resources, fn row ->
      row = stringify_keys(row)

      case resource_projection_flow_pressure_row(row, flow_rows) do
        nil ->
          row

        %{} = flow_row ->
          row
          |> Map.put_new(
            "first_resource_pressure_ground_station_id",
            resource_projection_flow_station_id(flow_row)
          )
          |> Map.put_new("source_window_id", flow_row["source_window_id"])
          |> Map.put_new("source_window_type", flow_row["source_window_type"])
          |> Map.put_new("source_window", flow_row["source_window"])
          |> compact_map()
      end
    end)
  end

  defp enrich_resource_projection_flow_projected_resources(projected_resources, _flow_rows),
    do: projected_resources

  defp resource_projection_flow_pressure_row(row, flow_rows) do
    activity_id = row["first_resource_pressure_activity_id"]

    Enum.find(flow_rows, fn flow_row ->
      (activity_id not in [nil, ""] and flow_row["activity_id"] == activity_id) or
        positive_number_value?(flow_row["downlink_shortfall_mb"])
    end)
  end

  defp resource_projection_flow_station_id(flow_row) do
    stable_id_or_nil(
      flow_row["ground_station_id"] ||
        flow_row["station_id"] ||
        score_term_nested_entity_id(flow_row, "source_window", [
          "ground_station_id",
          "station_id",
          "id"
        ])
    )
  end

