       when is_list(sources) do
    trust_boundaries = source_timeline_feedback_trust_boundaries(report)

    source =
      sources
      |> Enum.find(&(&1["source"] == "timeline_feedback_report.rows"))
      |> case do
        %{} = source -> source
        _source -> %{}
      end

    source
    |> Map.put(
      "trust_boundary_status",
      if(trust_boundaries == [], do: "missing", else: "declared")
    )
    |> maybe_put("trust_boundaries", trust_boundaries)
  end

