  defp source_operational_timeline_trust_boundaries(_report), do: []

  defp maybe_put_source_operational_timeline_trust_boundary(feedback, reports) do
    trust_boundaries =
      reports
      |> Enum.flat_map(fn {_path, report} ->
        source_operational_timeline_trust_boundaries(report)
      end)
      |> Enum.uniq()
      |> Enum.sort()

    case trust_boundaries do
      [trust_boundary] -> Map.put_new(feedback, "trust_boundary", trust_boundary)
      _trust_boundaries -> feedback
    end
  end

  defp maybe_put_source_timeline_feedback_trust_boundary(feedback, reports) do
    trust_boundaries =
      reports
