        source_timeline_feedback_trust_boundaries(report)
      end)
      |> Enum.uniq()
      |> Enum.sort()

    case trust_boundaries do
      [trust_boundary] -> Map.put_new(feedback, "trust_boundary", trust_boundary)
      _trust_boundaries -> feedback
    end
  end

