  defp operational_timeline_report_operational_feedback(%{} = report) do
    report
    |> Map.get("rows", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.reduce(%{}, fn row, feedback ->
      feedback =
        if operational_timeline_contact_feedback_row?(row) do
          merge_operational_timeline_contact_feedback(row, feedback)
        else
          feedback
        end

      feedback =
        if operational_timeline_command_feedback_row?(row) do
          merge_operational_timeline_command_feedback(row, feedback)
        else
          feedback
        end

      feedback =
        if operational_timeline_maneuver_feedback_row?(row) do
          merge_operational_timeline_maneuver_feedback(row, feedback)
        else
          feedback
        end

      feedback =
        if operational_timeline_observation_feedback_row?(row) do
          merge_operational_timeline_observation_feedback(row, feedback)
        else
          feedback
        end

      if operational_timeline_station_throughput_feedback_row?(row) do
        merge_operational_timeline_station_throughput_feedback(row, feedback)
      else
        feedback
      end
    end)
    |> compact_operational_feedback()
  end

  defp operational_timeline_report_operational_feedback(_report), do: %{}

  defp operational_timeline_contact_feedback_row?(%{} = row) do
    operational_timeline_contact_key(row) not in [nil, ""] and
      is_number(operational_timeline_contact_success_factor(row))
  end

  defp operational_timeline_command_feedback_row?(%{} = row) do
    command_window_feedback_row?(row) and operational_timeline_command_activity?(row)
  end

  defp operational_timeline_maneuver_feedback_row?(%{} = row) do
    maneuver_review_success_feedback_row?(row) and operational_timeline_maneuver_activity?(row)
  end

  defp operational_timeline_observation_feedback_row?(%{} = row) do
    operational_timeline_observation_key(row) not in [nil, ""] and
      is_number(operational_timeline_observation_success_factor(row))
  end

  defp operational_timeline_station_throughput_feedback_row?(%{} = row) do
    operational_timeline_station_key(row) not in [nil, ""] and
      is_number(operational_timeline_station_throughput_factor(row))
  end

  defp operational_timeline_integrity_issue_row?(%{} = row) do
    operational_timeline_row_has_integrity_issue?(
      row,
      @operational_timeline_integrity_issue_fields
    )
  end

  defp operational_timeline_dependency_issue_row?(%{} = row) do
    operational_timeline_row_has_integrity_issue?(
      row,
      @operational_timeline_dependency_integrity_issue_fields
    )
  end

  defp operational_timeline_exclusivity_issue_row?(%{} = row) do
    operational_timeline_row_has_integrity_issue?(
      row,
      @operational_timeline_exclusivity_integrity_issue_fields
    )
  end

  defp operational_timeline_row_has_integrity_issue?(row, fields) do
    Enum.any?(fields, fn field ->
      row
      |> operational_timeline_integrity_issue_value(field)
      |> operational_timeline_integrity_issue_value_present?()
    end)
  end

  defp operational_timeline_integrity_issue_value(row, field) do
    row[field] ||
      get_in(row, ["activity_context", field]) ||
      get_in(row, ["source_activity_context", field]) ||
      get_in(row, ["import_activity_context", field])
  end

  defp operational_timeline_integrity_issue_value_present?(values) when is_list(values) do
    Enum.any?(values, &operational_timeline_integrity_issue_value_present?/1)
  end

  defp operational_timeline_integrity_issue_value_present?(%{} = value),
    do: map_size(value) > 0

  defp operational_timeline_integrity_issue_value_present?(value),
    do: value not in [nil, "", false]

  defp operational_timeline_feedback_key(row) do
    operational_timeline_contact_key(row) ||
      command_window_feedback_key(row) ||
      maneuver_review_feedback_key(row) ||
      operational_timeline_observation_key(row)
  end

  defp operational_timeline_contact_key(row) do
    if operational_timeline_contact_activity?(row) do
      stable_id_or_nil(
        row["ground_station_id"] ||
          get_in(row, ["activity_context", "ground_station_id"]) ||
          get_in(row, ["source_activity_context", "ground_station_id"]) ||
          get_in(row, ["import_activity_context", "ground_station_id"])
      )
    end
  end

  defp operational_timeline_station_key(row) do
    stable_id_or_nil(
      row["ground_station_id"] ||
        get_in(row, ["activity_context", "ground_station_id"]) ||
        get_in(row, ["source_activity_context", "ground_station_id"]) ||
        get_in(row, ["import_activity_context", "ground_station_id"])
    )
  end

  defp operational_timeline_observation_key(row) do
    if operational_timeline_observation_activity?(row) do
      stable_id_or_nil(
        row["target_id"] ||
          get_in(row, ["activity_context", "target_id"]) ||
          get_in(row, ["source_activity_context", "target_id"]) ||
          get_in(row, ["import_activity_context", "target_id"]) ||
          row["activity_id"] ||
          row["id"] ||
          row["source_window_id"] ||
          row["timeline_id"]
      )
    end
  end

  defp operational_timeline_contact_success_factor(row) do
    case timeline_diff_first_number(row, [
           "contact_success_factor",
           ["activity_context", "contact_success_factor"],
           ["source_activity_context", "contact_success_factor"],
           ["import_activity_context", "contact_success_factor"]
         ]) do
      factor when is_number(factor) ->
        factor |> max(0.0) |> min(1.0)

      _factor ->
        operational_timeline_result_factor(row, "contact")
    end
  end

  defp operational_timeline_observation_success_factor(row) do
    case timeline_diff_first_number(row, [
           "observation_success_factor",
           ["activity_context", "observation_success_factor"],
           ["source_activity_context", "observation_success_factor"],
           ["import_activity_context", "observation_success_factor"]
         ]) do
      factor when is_number(factor) ->
        factor |> max(0.0) |> min(1.0)

      _factor ->
        operational_timeline_result_factor(row, "observation")
    end
  end

  defp operational_timeline_result_factor(row, prefix) do
    success_key = "#{prefix}_success"
    result_key = "#{prefix}_result"

    cond do
      false in [
        row[success_key],
        get_in(row, ["activity_context", success_key]),
        get_in(row, ["source_activity_context", success_key]),
        get_in(row, ["import_activity_context", success_key])
      ] ->
        0.0

      timeline_diff_failure_token?(
        row[result_key] ||
          get_in(row, ["activity_context", result_key]) ||
          get_in(row, ["source_activity_context", result_key]) ||
            get_in(row, ["import_activity_context", result_key])
      ) ->
        0.0

      true ->
        nil
    end
  end

  defp operational_timeline_station_throughput_factor(row) do
    case timeline_diff_first_number(row, [
           "station_throughput_factor",
           ["activity_context", "station_throughput_factor"],
           ["source_activity_context", "station_throughput_factor"],
           ["import_activity_context", "station_throughput_factor"],
           "throughput_completion_fraction",
           ["activity_context", "throughput_completion_fraction"],
           ["source_activity_context", "throughput_completion_fraction"],
           ["import_activity_context", "throughput_completion_fraction"]
         ]) do
      factor when is_number(factor) ->
        factor |> max(0.0) |> min(1.0)

      _factor ->
        actual =
          timeline_diff_first_number(row, [
            "actual_throughput_mb",
            ["activity_context", "actual_throughput_mb"],
            ["source_activity_context", "actual_throughput_mb"],
            ["import_activity_context", "actual_throughput_mb"]
          ])

        planned =
          timeline_diff_first_number(row, [
            "planned_estimated_throughput_mb",
            ["activity_context", "planned_estimated_throughput_mb"],
            ["source_activity_context", "planned_estimated_throughput_mb"],
            ["import_activity_context", "planned_estimated_throughput_mb"],
            "estimated_throughput_mb",
            ["activity_context", "estimated_throughput_mb"],
            ["source_activity_context", "estimated_throughput_mb"],
            ["import_activity_context", "estimated_throughput_mb"],
            "planned_throughput_mb",
            ["activity_context", "planned_throughput_mb"],
            ["source_activity_context", "planned_throughput_mb"],
            ["import_activity_context", "planned_throughput_mb"],
            "estimated_downlink_mb",
            ["activity_context", "estimated_downlink_mb"],
            ["source_activity_context", "estimated_downlink_mb"],
            ["import_activity_context", "estimated_downlink_mb"],
            "required_downlink_mb",
            ["activity_context", "required_downlink_mb"],
            ["source_activity_context", "required_downlink_mb"],
            ["import_activity_context", "required_downlink_mb"]
          ])

        if is_number(actual) and is_number(planned) and planned > 0.0 do
          (actual / planned) |> max(0.0) |> min(1.0)
        end
    end
  end

  defp merge_operational_timeline_contact_feedback(row, feedback) do
    station_key = operational_timeline_contact_key(row)
    factor = operational_timeline_contact_success_factor(row)

    update_in(feedback, ["contact_success_rate"], fn values ->
      values
      |> ensure_map()
      |> Map.update(station_key, factor, &min(&1, factor))
    end)
  end

  defp merge_operational_timeline_command_feedback(row, feedback) do
    merge_command_window_feedback(row, feedback)
  end

  defp merge_operational_timeline_maneuver_feedback(row, feedback) do
    maneuver_key = maneuver_review_feedback_key(row)
    factor = maneuver_review_success_factor(row)

    update_in(feedback, ["maneuver_success_rate"], fn values ->
      values
      |> ensure_map()
      |> Map.update(maneuver_key, factor, &min(&1, factor))
    end)
  end

  defp merge_operational_timeline_observation_feedback(row, feedback) do
    observation_key = operational_timeline_observation_key(row)
    factor = operational_timeline_observation_success_factor(row)

    update_in(feedback, ["observation_success_rate"], fn values ->
      values
      |> ensure_map()
      |> Map.update(observation_key, factor, &min(&1, factor))
    end)
  end

  defp merge_operational_timeline_station_throughput_feedback(row, feedback) do
    station_key = operational_timeline_station_key(row)
    factor = operational_timeline_station_throughput_factor(row)

    update_in(feedback, ["station_throughput_factor"], fn values ->
      values
      |> ensure_map()
      |> Map.update(station_key, factor, &min(&1, factor))
    end)
  end

  defp operational_timeline_contact_activity?(row) do
    type = operational_timeline_activity_token(row)
    direction = operational_timeline_direction_token(row)
    kind = operational_timeline_kind_token(row)

    type in ["downlink", "planned_contact", "contact", "tracking"] or
      direction in ["downlink", "uplink", "tracking"] or
      kind in ["downlink", "contact", "tracking"]
  end

  defp operational_timeline_command_activity?(row) do
    type = operational_timeline_activity_token(row)
    direction = operational_timeline_direction_token(row)
    kind = operational_timeline_kind_token(row)

    type in ["command", "health_check"] or
      direction in ["command", "uplink", "health_check"] or
      kind in ["command", "health_check"]
  end

  defp operational_timeline_maneuver_activity?(row) do
    type = operational_timeline_activity_token(row)
    kind = operational_timeline_kind_token(row)

    type in [
      "maneuver",
      "impulsive_burn",
      "burn",
      "stationkeeping_burn",
      "station_keeping_burn",
      "delta_v"
    ] or kind in ["maneuver", "burn", "delta_v"]
  end

  defp operational_timeline_observation_activity?(row) do
    type = operational_timeline_activity_token(row)
    direction = operational_timeline_direction_token(row)
    kind = operational_timeline_kind_token(row)

    type in ["observation", "observe", "imaging", "payload_collection"] or
      direction in ["observation", "observe"] or
      kind in ["observation", "observe", "collection"]
  end

  defp operational_timeline_activity_token(row) do
    (row["activity_type"] ||
       row["type"] ||
       get_in(row, ["activity_context", "activity_type"]) ||
       get_in(row, ["activity_context", "type"]) ||
       get_in(row, ["source_activity_context", "activity_type"]) ||
       get_in(row, ["source_activity_context", "type"]) ||
       get_in(row, ["import_activity_context", "activity_type"]) ||
       get_in(row, ["import_activity_context", "type"]))
    |> normalized_timeline_diff_token()
  end

  defp operational_timeline_direction_token(row) do
    (row["direction"] ||
       get_in(row, ["activity_context", "direction"]) ||
       get_in(row, ["source_activity_context", "direction"]) ||
       get_in(row, ["import_activity_context", "direction"]))
    |> normalize_direction()
  end

  defp operational_timeline_kind_token(row) do
    (row["operational_kind"] ||
       get_in(row, ["activity_context", "operational_kind"]) ||
       get_in(row, ["source_activity_context", "operational_kind"]) ||
       get_in(row, ["import_activity_context", "operational_kind"]))
    |> normalized_timeline_diff_token()
  end

  defp timeline_diff_report_operational_feedback(%{} = report) do
    report
    |> Map.get("rows", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.reduce(%{}, fn row, feedback ->
      cond do
        timeline_diff_removed_downlink_feedback_row?(row) ->
          merge_timeline_diff_removed_downlink_feedback(row, feedback)

        timeline_diff_changed_downlink_shortfall_feedback_row?(row) ->
          merge_timeline_diff_changed_downlink_shortfall_feedback(row, feedback)

        timeline_diff_changed_contact_feedback_row?(row) ->
          merge_timeline_diff_changed_contact_feedback(row, feedback)

        timeline_diff_changed_observation_quality_feedback_row?(row) ->
          merge_timeline_diff_changed_observation_quality_feedback(row, feedback)

        timeline_diff_changed_command_feedback_row?(row) ->
          merge_timeline_diff_changed_command_feedback(row, feedback)

        timeline_diff_changed_maneuver_feedback_row?(row) ->
          merge_timeline_diff_changed_maneuver_feedback(row, feedback)

        true ->
          feedback
      end
    end)
    |> compact_operational_feedback()
  end

  defp timeline_diff_report_operational_feedback(_report), do: %{}

  defp command_window_report_operational_feedback(%{} = report) do
    report
    |> Map.get("rows", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.reduce(%{}, fn row, feedback ->
      if command_window_feedback_row?(row) do
        merge_command_window_feedback(row, feedback)
      else
        feedback
      end
    end)
    |> compact_operational_feedback()
  end

  defp command_window_report_operational_feedback(_report), do: %{}

  defp maneuver_review_report_operational_feedback(%{} = report) do
    report
    |> Map.get("rows", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.reduce(%{}, fn row, feedback ->
      if maneuver_review_feedback_row?(row) do
        merge_maneuver_review_feedback(row, feedback)
      else
        feedback
      end
    end)
    |> compact_operational_feedback()
  end

  defp maneuver_review_report_operational_feedback(_report), do: %{}

  defp command_window_feedback_row?(%{} = row) do
    command_window_feedback_key(row) not in [nil, ""] and
      is_number(command_window_success_factor(row))
  end

  defp command_window_feedback_key(row) do
    stable_id_or_nil(
      row["activity_id"] ||
        row["command_window_id"] ||
        get_in(row, ["activity_context", "activity_id"]) ||
        get_in(row, ["source_activity_context", "activity_id"]) ||
        get_in(row, ["activity_context", "command_window_id"]) ||
        get_in(row, ["source_activity_context", "command_window_id"]) ||
        row["id"] ||
        row["timeline_id"]
    )
  end

  defp command_window_success_factor(row) do
    case timeline_diff_first_number(row, [
           "command_success_factor",
           ["activity_context", "command_success_factor"],
           ["source_activity_context", "command_success_factor"],
           ["import_activity_context", "command_success_factor"]
         ]) do
      factor when is_number(factor) ->
        factor |> max(0.0) |> min(1.0)

      _factor ->
        command_window_result_factor(row)
    end
  end

  defp command_window_result_factor(row) do
    cond do
      false in [
        row["command_success"],
        get_in(row, ["activity_context", "command_success"]),
        get_in(row, ["source_activity_context", "command_success"]),
        get_in(row, ["import_activity_context", "command_success"])
      ] ->
        0.0

      timeline_diff_failure_token?(
        row["command_result"] ||
          get_in(row, ["activity_context", "command_result"]) ||
          get_in(row, ["source_activity_context", "command_result"]) ||
            get_in(row, ["import_activity_context", "command_result"])
      ) ->
        0.0

      true ->
        nil
    end
  end

  defp merge_command_window_feedback(row, feedback) do
    command_key = command_window_feedback_key(row)
    factor = command_window_success_factor(row)

    update_in(feedback, ["command_success_rate"], fn values ->
      values
      |> ensure_map()
      |> Map.update(command_key, factor, &min(&1, factor))
    end)
  end

  defp maneuver_review_feedback_row?(%{} = row) do
    maneuver_review_feedback_key(row) not in [nil, ""] and
      (maneuver_review_success_feedback_row?(row) or
         maneuver_review_execution_uncertainty_feedback_row?(row))
  end

  defp maneuver_review_success_feedback_row?(%{} = row) do
    maneuver_review_feedback_key(row) not in [nil, ""] and
      is_number(maneuver_review_success_factor(row))
  end

  defp maneuver_review_execution_uncertainty_feedback_row?(%{} = row) do
    maneuver_review_feedback_key(row) not in [nil, ""] and
      maneuver_review_execution_uncertainty(row) != %{}
  end

  defp maneuver_review_feedback_key(row) do
    stable_id_or_nil(
      row["maneuver_id"] ||
        get_in(row, ["source_recommendation", "id"]) ||
        row["activity_id"] ||
        row["id"] ||
        row["timeline_id"]
    )
  end

  defp maneuver_review_success_factor(row) do
    case timeline_diff_first_number(row, [
           "maneuver_success_factor",
           ["source_recommendation", "maneuver_success_factor"],
           ["source_maneuver_review", "maneuver_success_factor"]
         ]) do
      factor when is_number(factor) ->
        factor |> max(0.0) |> min(1.0)

      _factor ->
        maneuver_review_result_factor(row)
    end
  end

  defp maneuver_review_result_factor(row) do
    cond do
      false in [
        row["maneuver_success"],
        get_in(row, ["source_recommendation", "maneuver_success"]),
        get_in(row, ["source_maneuver_review", "maneuver_success"])
      ] ->
        0.0

      timeline_diff_failure_token?(
        row["maneuver_result"] ||
          get_in(row, ["source_recommendation", "maneuver_result"]) ||
            get_in(row, ["source_maneuver_review", "maneuver_result"])
      ) ->
        0.0

      true ->
        nil
    end
  end

  defp merge_maneuver_review_feedback(row, feedback) do
    maneuver_key = maneuver_review_feedback_key(row)

    feedback =
      case maneuver_review_success_factor(row) do
        factor when is_number(factor) ->
          update_in(feedback, ["maneuver_success_rate"], fn values ->
            values
            |> ensure_map()
            |> Map.update(maneuver_key, factor, &min(&1, factor))
          end)

        _factor ->
          feedback
      end

    case maneuver_review_execution_uncertainty(row) do
      uncertainty when uncertainty == %{} ->
        feedback

      uncertainty ->
        update_in(feedback, ["maneuver_execution_uncertainty"], fn values ->
          values
          |> ensure_map()
          |> Map.put(maneuver_key, uncertainty)
        end)
    end
  end

  defp maneuver_review_execution_uncertainty(%{} = row) do
    uncertainty =
      case row["execution_uncertainty"] ||
             get_in(row, ["source_recommendation", "execution_uncertainty"]) ||
             get_in(row, ["source_maneuver_review", "execution_uncertainty"]) do
        %{} = value -> stringify_keys(value)
        _value -> nil
      end

    %{
      "execution_uncertainty_status" => maneuver_review_execution_uncertainty_status(row),
      "execution_uncertainty" => uncertainty,
      "timing_3sigma_s" =>
        numeric_or_nil(
          row["timing_3sigma_s"] ||
            get_in(row, ["source_maneuver_review", "timing_3sigma_s"]) ||
            get_in(uncertainty || %{}, ["timing_3sigma_s"])
        ),
      "delta_v_3sigma_km_s" =>
        numeric_triplet_or_nil(
          row["delta_v_3sigma_km_s"] ||
            get_in(row, ["source_maneuver_review", "delta_v_3sigma_km_s"]) ||
            get_in(uncertainty || %{}, ["delta_v_3sigma_km_s"])
        ),
      "delta_v_3sigma_magnitude_km_s" =>
        numeric_or_nil(
          row["delta_v_3sigma_magnitude_km_s"] ||
            get_in(row, ["source_maneuver_review", "delta_v_3sigma_magnitude_km_s"]) ||
            get_in(uncertainty || %{}, ["delta_v_3sigma_magnitude_km_s"])
        ),
      "execution_uncertainty_source" =>
        row["execution_uncertainty_source"] ||
          get_in(row, ["source_maneuver_review", "execution_uncertainty_source"]) ||
          get_in(uncertainty || %{}, ["source"])
    }
    |> compact_map()
  end

  defp maneuver_review_execution_uncertainty_status(%{} = row) do
    status =
      row["execution_uncertainty_status"] ||
        get_in(row, ["source_maneuver_review", "execution_uncertainty_status"])

    case status |> encode_value() do
      value when value in ["declared", "missing"] ->
        value

      _value ->
        if is_map(row["execution_uncertainty"]) or
             is_map(get_in(row, ["source_recommendation", "execution_uncertainty"])) or
             is_map(get_in(row, ["source_maneuver_review", "execution_uncertainty"])) do
          "declared"
        end
    end
  end

  defp source_timeline_diff_report_objectives(refresh) do
    refresh
    |> source_timeline_diff_reports()
    |> Enum.flat_map(fn {path, report} ->
      report
      |> Map.get("rows", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.flat_map(fn row ->
        cond do
          timeline_diff_removed_observation_objective_row?(row) ->
            [timeline_diff_removed_observation_objective(path, row)]

          timeline_diff_changed_observation_objective_row?(row) ->
            [timeline_diff_changed_observation_objective(path, row)]

          true ->
            []
        end
      end)
    end)
  end

