  defp objective_tradeoff_row_objectives(path, row, index) do
    row = stringify_keys(row)

    cond do
      objective_tradeoff_collection_latency_gap?(row) ->
        objective_tradeoff_collection_latency_objectives(path, row, index)

      objective_tradeoff_downlink_gap?(row) ->
        objective_tradeoff_downlink_objectives(path, row, index)

      objective_tradeoff_target_gap?(row) ->
        objective_tradeoff_target_objectives(path, row, index)

      true ->
        []
    end
  end

  defp objective_tradeoff_downlink_objectives(path, row, index) do
    required_downlink_mb = objective_tradeoff_required_downlink_mb(row)
    station_id = objective_tradeoff_station_id(row)

    if positive_number_value?(required_downlink_mb) and station_id not in [nil, ""] do
      [
        %{
          "id" => objective_tradeoff_objective_id(path, row, index, "downlink_completion"),
          "type" => "downlink_completion",
          "scenario_id" => stable_id_or_nil(row["scenario_id"]),
          "spacecraft_id" => objective_tradeoff_spacecraft_id(row),
          "ground_station_id" => station_id,
          "required_downlink_mb" => required_downlink_mb,
          "source" => "objective_tradeoff_report.tradeoffs",
          "source_path" => path,
          "source_tradeoff_score" => numeric_value(row["score"]),
          "source_score_delta_from_selected" => numeric_value(row["score_delta_from_selected"]),
          "source_activity_ids" => objective_tradeoff_source_activity_ids(row),
          "trust_boundary" => objective_tradeoff_trust_boundary(row)
        }
        |> compact_map()
      ]
    else
      []
    end
  end

