    required_revisits = objective_tradeoff_required_observations(row)

    row
    |> objective_satisfaction_target_ids()
    |> Enum.map(fn target_id ->
      %{
        "id" => objective_tradeoff_objective_id(path, row, index, "target_revisit", target_id),
        "type" => objective_tradeoff_target_type(row),
        "scenario_id" => stable_id_or_nil(row["scenario_id"]),
        "spacecraft_id" => objective_tradeoff_spacecraft_id(row),
        "target_id" => target_id,
        "required_revisits" => required_revisits,
        "source" => "objective_tradeoff_report.tradeoffs",
        "source_path" => path,
        "source_tradeoff_score" => numeric_value(row["score"]),
        "source_score_delta_from_selected" => numeric_value(row["score_delta_from_selected"]),
        "source_activity_ids" => objective_tradeoff_source_activity_ids(row),
        "trust_boundary" => objective_tradeoff_trust_boundary(row)
      }
      |> compact_map()
    end)
  end

  defp objective_tradeoff_collection_latency_objectives(path, row, index) do
    required_downlink_mb = objective_tradeoff_collection_required_downlink_mb(row)
    max_latency_s = objective_tradeoff_latency_s(row)

