  defp contact_contention_resolution_deferred_contact_objectives(
         path,
         recommendation,
         source_contact,
         recommendation_index,
         contact_index
       ) do
    required_downlink_mb =
      contact_contention_resolution_required_downlink_mb(recommendation, source_contact)

    station_id = contact_contention_resolution_station_id(recommendation, source_contact)

    if contact_contention_resolution_downlink_candidate?(recommendation, source_contact) and
         positive_number_value?(required_downlink_mb) and station_id not in [nil, ""] do
      [
        %{
          "id" =>
            contact_contention_resolution_objective_id(
              path,
              recommendation,
              source_contact,
              recommendation_index,
              contact_index,
              "downlink_completion"
            ),
          "type" => "downlink_completion",
          "scenario_id" =>
            stable_id_or_nil(source_contact["scenario_id"] || recommendation["scenario_id"]),
          "spacecraft_id" =>
            stable_id_or_nil(source_contact["spacecraft_id"] || recommendation["spacecraft_id"]),
          "ground_station_id" => station_id,
          "required_downlink_mb" => required_downlink_mb,
          "source" => "contact_contention_resolution_report.recommendations",
          "source_path" => path,
          "source_contention_group_id" => stable_id_or_nil(recommendation["group_id"]),
          "source_selected_contact_id" => stable_id_or_nil(recommendation["selected_contact_id"]),
          "source_contact_id" =>
            stable_id_or_nil(
              source_contact["id"] || source_contact["contact_id"] ||
                source_contact["activity_id"]
            ),
          "source_selection_reason" => recommendation["selection_reason"],
          "source_resolution_status" => recommendation["resolution_status"],
          "source_review_status" => recommendation["review_status"],
          "source_policy_classification" =>
            get_in(recommendation, ["policy_decision", "classification"]) ||
              get_in(recommendation, ["source_policy_decision", "classification"]),
          "source_activity_ids" =>
            contact_contention_resolution_source_activity_ids(recommendation, source_contact),
          "source_window_id" =>
            contact_contention_resolution_source_window_id(recommendation, source_contact),
          "source_window_ids" =>
            contact_contention_resolution_source_window_ids(recommendation, source_contact),
          "trust_boundary" => contact_contention_resolution_trust_boundary(recommendation)
        }
        |> compact_map()
      ]
    else
      []
    end
  end

