  defp contact_allocation_downlink_objectives(path, row, index) do
    source_contact = contact_allocation_source_contact(row)
    required_downlink_mb = contact_allocation_required_downlink_mb(row, source_contact)
    station_id = contact_allocation_station_id(row, source_contact)

    if positive_number_value?(required_downlink_mb) and station_id not in [nil, ""] do
      [
        %{
          "id" => contact_allocation_objective_id(path, row, index, "downlink_completion"),
          "type" => "downlink_completion",
          "scenario_id" => stable_id_or_nil(row["scenario_id"] || source_contact["scenario_id"]),
          "spacecraft_id" =>
            stable_id_or_nil(row["spacecraft_id"] || source_contact["spacecraft_id"]),
          "ground_station_id" => station_id,
          "required_downlink_mb" => required_downlink_mb,
          "source" => "contact_allocation_report.rows",
          "source_path" => path,
          "source_contact_id" => contact_allocation_contact_id(row, source_contact),
          "source_allocation_status" => row["allocation_status"],
          "source_effective_allocation_status" => row["effective_allocation_status"],
          "source_allocation_reason" => row["allocation_reason"],
          "source_review_status" => row["review_status"],
          "source_approval_status" => row["approval_status"],
          "source_policy_classification" => get_in(row, ["policy_decision", "classification"]),
          "source_activity_ids" => contact_allocation_source_activity_ids(row, source_contact),
          "source_window_id" => contact_allocation_source_window_id(row, source_contact),
          "source_window_ids" => contact_allocation_source_window_ids(row, source_contact),
          "trust_boundary" => contact_allocation_trust_boundary(row)
        }
        |> compact_map()
      ]
    else
      []
    end
