  defp link_capacity_report_objective_rows(%{"rows" => rows} = report) when is_list(rows) do
    rows =
      rows
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&Map.put_new(&1, "source_report", "rows"))

    if Enum.any?(rows, &link_capacity_downlink_pressure?/1) do
      rows
    else
      [Map.put(report, "source_report", "top_level")]
    end
  end

  defp link_capacity_report_objective_rows(%{} = report),
    do: [Map.put(report, "source_report", "top_level")]

  defp link_capacity_row_objectives(path, row, index) do
    row = stringify_keys(row)

