        score_term_downlink_objectives(path, row, index)

      score_term_target_gap?(term) ->
        score_term_target_objectives(path, row, index, term)

      score_term_collection_latency_gap?(term) ->
        score_term_collection_latency_objectives(path, row, index)

      true ->
        []
    end
  end

