  defp source_objective_satisfaction_report_objectives(refresh) do
    refresh
    |> source_objective_satisfaction_reports()
    |> Enum.flat_map(fn {path, report} ->
      report
      |> Map.get("rows", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.with_index(1)
      |> Enum.flat_map(fn {row, index} ->
        row =
          Map.put_new(
            row,
            "_source_report_trust_boundary",
            result_artifact_trust_boundary(report)
          )

        objective_satisfaction_row_objectives(path, row, index)
      end)
    end)
  end

  defp objective_satisfaction_row_objectives(path, row, index) do
    row =
      row
      |> stringify_keys()
      |> normalize_objective_satisfaction_row()

    if objective_satisfaction_gap_status?(row["status"]) do
      case objective_satisfaction_objective_type(row) do
        type when type in ["downlink_completion", "required_downlink_completion"] ->
          objective_satisfaction_downlink_objectives(path, row, index)

        type
        when type in [
               "target_coverage",
               "coverage",
               "target_commitment",
               "priority_commitment",
               "target_observation",
               "target_revisit"
             ] ->
          objective_satisfaction_target_objectives(path, row, index, type)

        type when type in ["collection_latency", "collection_downlink_latency", "data_latency"] ->
          objective_satisfaction_collection_latency_objectives(path, row, index)

        _type ->
          []
      end
    else
      []
    end
  end

  defp normalize_objective_satisfaction_row(row) do
    row
    |> maybe_put("objective", objective_satisfaction_objective_type(row))
    |> maybe_put("status", objective_satisfaction_row_status(row))
  end

  defp objective_satisfaction_downlink_objectives(path, row, index) do
    required_downlink_mb = objective_satisfaction_required_downlink_mb(row)

    if positive_number_value?(required_downlink_mb) do
      [
        %{
          "id" => objective_satisfaction_objective_id(path, row, index, "downlink_completion"),
          "type" => "downlink_completion",
          "scenario_id" => stable_id_or_nil(row["scenario_id"]),
          "spacecraft_id" => objective_satisfaction_spacecraft_id(row),
          "ground_station_id" => objective_satisfaction_station_id(row),
          "required_downlink_mb" => required_downlink_mb,
          "source" => "objective_satisfaction_report.rows",
          "source_path" => path,
          "source_objective" => row["objective"],
          "source_objective_status" => row["status"],
          "provider_objective_status" => row["_source_objective_status"],
          "planned_downlink_mb" => objective_satisfaction_planned_downlink_mb(row),
          "selected_downlink_mb" => objective_satisfaction_selected_downlink_mb(row),
          "source_activity_ids" => objective_satisfaction_source_activity_ids(row),
          "trust_boundary" => objective_satisfaction_trust_boundary(row)
        }
        |> compact_map()
      ]
    else
      []
    end
  end

  defp objective_satisfaction_target_objectives(path, row, index, type) do
    row
    |> objective_satisfaction_target_ids()
    |> Enum.map(fn target_id ->
      %{
        "id" => objective_satisfaction_objective_id(path, row, index, type, target_id),
        "type" => objective_satisfaction_refresh_target_type(type),
        "scenario_id" => stable_id_or_nil(row["scenario_id"]),
        "spacecraft_id" => objective_satisfaction_spacecraft_id(row),
        "target_id" => target_id,
        "required_revisits" => objective_satisfaction_required_observations(row),
        "source" => "objective_satisfaction_report.rows",
        "source_path" => path,
        "source_objective" => row["objective"],
        "source_objective_status" => row["status"],
        "provider_objective_status" => row["_source_objective_status"],
        "source_activity_ids" => objective_satisfaction_source_activity_ids(row),
        "trust_boundary" => objective_satisfaction_trust_boundary(row)
      }
      |> compact_map()
    end)
  end

  defp objective_satisfaction_collection_latency_objectives(path, row, index) do
    required_downlink_mb = objective_satisfaction_required_downlink_mb(row)
    max_latency_s = objective_satisfaction_latency_s(row)

    if positive_number_value?(required_downlink_mb) or positive_number_value?(max_latency_s) do
      [
        %{
          "id" => objective_satisfaction_objective_id(path, row, index, "collection_latency"),
          "type" => "collection_latency",
          "scenario_id" => stable_id_or_nil(row["scenario_id"]),
          "spacecraft_id" => objective_satisfaction_spacecraft_id(row),
          "target_id" => objective_satisfaction_primary_target_id(row),
          "ground_station_id" => objective_satisfaction_station_id(row),
          "collection_id" => objective_satisfaction_identity_value(row, "collection_id"),
          "product_id" => objective_satisfaction_identity_value(row, "product_id"),
          "product_ids" => objective_satisfaction_identity_values(row, "product_id"),
          "payload_id" => objective_satisfaction_identity_value(row, "payload_id"),
          "instrument_id" => objective_satisfaction_identity_value(row, "instrument_id"),
          "required_downlink_mb" => required_downlink_mb,
          "max_latency_s" => max_latency_s,
          "source" => "objective_satisfaction_report.rows",
          "source_path" => path,
          "source_objective" => row["objective"],
          "source_objective_status" => row["status"],
          "provider_objective_status" => row["_source_objective_status"],
          "planned_latency_s" => objective_satisfaction_planned_latency_s(row),
          "source_activity_ids" => objective_satisfaction_source_activity_ids(row),
          "trust_boundary" => objective_satisfaction_trust_boundary(row)
        }
        |> compact_map()
      ]
    else
      []
    end
