  defp objective_satisfaction_refresh_target_type("coverage"), do: "target_coverage"
  defp objective_satisfaction_refresh_target_type("target_commitment"), do: "target_revisit"
  defp objective_satisfaction_refresh_target_type(type), do: type

  defp objective_satisfaction_objective_type(row) do
    (row["objective"] || row["objective_type"] || row["type"])
    |> normalized_timeline_diff_token()
  end

  defp objective_satisfaction_row_status(row) do
    [
      row["status"],
      row["objective_status"],
      row["satisfaction_status"],
      row["objective_satisfaction_status"],
      row["completion_status"],
      row["requirement_status"],
      row["downlink_requirement_status"],
      row["coverage_status"],
      row["delivery_requirement_status"],
      row["source_objective_status"]
    ]
    |> Enum.find(&(&1 not in [nil, ""]))
    |> case do
      nil -> objective_satisfaction_boolean_status(row)
      status -> objective_satisfaction_status_value(status)
    end
  end

  defp objective_satisfaction_boolean_status(row) do
    [
      row["satisfied"],
      row["objective_satisfied"],
      row["requirement_satisfied"],
      row["downlink_requirement_satisfied"],
      row["coverage_satisfied"],
      row["delivery_satisfied"],
      row["met"],
      row["objective_met"]
    ]
    |> Enum.find_value(fn value ->
      case boolean_value(value) do
        true -> "met"
        false -> "unmet"
        nil -> nil
      end
    end)
  end

  defp objective_satisfaction_status_value(status) when is_boolean(status),
    do: if(status, do: "met", else: "unmet")

  defp objective_satisfaction_status_value(status) do
    case normalized_timeline_diff_token(status) do
      status when status in ["satisfied", "complete", "completed", "selected", "met"] ->
        "met"

      status
      when status in [
             "unsatisfied",
             "not_satisfied",
             "not_met",
             "missing",
             "missed",
             "failed",
             "late",
             "overdue",
             "violated",
             "breached"
           ] ->
        "unmet"

      status
      when status in [
             "partial",
             "shortfall",
             "insufficient",
             "below_target",
             "below_threshold",
             "under_target",
             "under_threshold",
             "gap",
             "has_gap",
             "at_risk",
             "needs_replan",
             "needs_refresh",
             "requires_attention",
             "degraded",
             "behind_plan"
           ] ->
        "partial"

      status
      when status in ["candidate_found", "candidate_window_available", "viable_candidate"] ->
        "candidate_available"

      status when status in ["no_candidate", "no_window", "no_viable_candidate"] ->
        "no_candidate_window"

      status ->
        status
    end
  end

  defp objective_satisfaction_gap_status?(status),
    do: status in ["partial", "unmet", "candidate_available", "no_candidate_window"]

  defp objective_satisfaction_required_downlink_mb(row) do
    objective_satisfaction_first_positive_number(row, [
      "required_downlink_mb",
      "required_data_volume_mb",
      "target_data_volume_mb",
      "required_volume_mb",
      "min_downlink_mb",
      "downlink_completion_gap_mb",
      "selected_downlink_shortfall_mb",
      "downlink_shortfall_mb",
      "data_volume_shortfall_mb",
      "missing_data_volume_mb",
      ["score_terms", "downlink_shortfall_mb"],
      ["score_terms", "downlink_completion_gap_mb"],
      ["score_terms", "required_downlink_mb"]
    ])
  end

  defp objective_satisfaction_planned_downlink_mb(row) do
    objective_satisfaction_first_number(row, [
      "planned_downlink_mb",
      "selected_downlink_mb",
      "satisfied_downlink_mb",
      "actual_downlink_mb",
      "selected_data_volume_mb",
      "planned_data_volume_mb"
    ])
  end

  defp objective_satisfaction_selected_downlink_mb(row) do
    objective_satisfaction_first_number(row, [
      "selected_downlink_mb",
      "satisfied_downlink_mb",
      "actual_downlink_mb",
      "selected_data_volume_mb"
    ])
  end

  defp objective_satisfaction_required_observations(row) do
    explicit =
      objective_satisfaction_first_positive_number(row, [
        "required_observations",
        "required_observation_count",
        "required_revisits",
        "required_revisit_count",
        "required_count",
        "target_gap_count",
        "missing_observation_count",
        "missing_revisit_count",
        "coverage_shortfall_count",
        ["score_terms", "target_gap_count"],
        ["score_terms", "missing_observation_count"],
        ["score_terms", "missing_revisit_count"],
        ["score_terms", "coverage_gap_count"]
      ])

    planned =
      objective_satisfaction_first_number(row, [
        "planned_observations",
        "selected_observations",
        "selected_count",
        "satisfied_count",
        "planned_revisits",
        "selected_revisits"
      ])

    cond do
      positive_number_value?(explicit) and is_number(planned) and explicit > planned ->
        max(explicit - planned, 1.0)

      positive_number_value?(explicit) ->
        explicit

      true ->
        1.0
    end
  end

  defp objective_satisfaction_latency_s(row) do
    objective_satisfaction_first_positive_number(row, [
      "max_latency_s",
      "required_latency_s",
      "target_latency_s",
      "latency_limit_s",
      "max_delivery_latency_s",
      "required_delivery_latency_s",
      "target_delivery_latency_s"
    ])
  end

  defp objective_satisfaction_planned_latency_s(row) do
    objective_satisfaction_first_number(row, [
      "planned_latency_s",
      "actual_latency_s",
      "delivery_latency_s",
      "planned_delivery_latency_s",
      "actual_delivery_latency_s"
    ])
  end

  defp objective_satisfaction_first_positive_number(row, paths) do
    paths
    |> Enum.find_value(fn path ->
      case objective_satisfaction_number(row, path) do
        value when is_number(value) and value > 0.0 -> value
        _value -> nil
      end
    end)
  end

  defp objective_satisfaction_first_number(row, paths) do
    paths
    |> Enum.find_value(fn
      path -> objective_satisfaction_number(row, path)
    end)
  end

  defp objective_satisfaction_number(row, path) when is_list(path),
    do: row |> get_in(path) |> numeric_value()

  defp objective_satisfaction_number(row, path), do: row |> Map.get(path) |> numeric_value()

  defp objective_satisfaction_station_id(row) do
    stable_id_or_nil(
      row["ground_station_id"] ||
        row["station_id"] ||
        objective_satisfaction_entity_id(row["ground_station"], [
          "ground_station_id",
          "station_id",
          "id"
        ]) ||
        objective_satisfaction_entity_id(row["station"], ["ground_station_id", "station_id", "id"])
    )
  end

  defp objective_satisfaction_spacecraft_id(row) do
    stable_id_or_nil(
      row["spacecraft_id"] ||
        row["satellite_id"] ||
        objective_satisfaction_entity_id(row["spacecraft"], [
          "spacecraft_id",
          "satellite_id",
          "id"
        ]) ||
        objective_satisfaction_entity_id(row["satellite"], ["spacecraft_id", "satellite_id", "id"])
    )
  end

  defp objective_satisfaction_primary_target_id(row) do
    row
    |> objective_satisfaction_target_ids()
    |> List.first()
  end

  defp objective_satisfaction_target_ids(row) do
    gap_targets =
      objective_satisfaction_target_values(row, [
        "uncovered_target_ids",
        "uncovered_targets",
        "unsatisfied_target_ids",
        "unsatisfied_targets",
        "missing_target_ids",
        "missing_targets",
        "missed_target",
        "missed_targets",
        "missing_revisit_target_ids",
        "missing_revisit_targets",
        "missing_coverage_target_ids",
        "missing_coverage_targets",
        "target_gap_ids",
        "target_gap_targets"
      ])

    if gap_targets == [] do
      objective_satisfaction_target_values(row, [
        "target_id",
        "target",
        "target_ids",
        "targets",
        "target_spec",
        "target_specs",
        "required_target_ids",
        "required_targets",
        "committed_targets",
        "priority_targets",
        "candidate_target_ids",
        "candidate_targets"
      ])
    else
      gap_targets
    end
  end

  defp objective_satisfaction_target_values(row, fields) do
    fields
    |> Enum.flat_map(fn field -> objective_satisfaction_target_value(Map.get(row, field)) end)
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp objective_satisfaction_target_value(values) when is_list(values),
    do: Enum.flat_map(values, &objective_satisfaction_target_value/1)

  defp objective_satisfaction_target_value(%{} = target) do
    [Map.get(target, "target_id") || Map.get(target, "id")]
  end

  defp objective_satisfaction_target_value(value), do: [value]

  defp objective_satisfaction_identity_value(row, field) do
    case objective_satisfaction_identity_values(row, field) do
      values when is_list(values) -> List.first(values)
      _values -> nil
    end
  end

  defp objective_satisfaction_identity_values(row, field) do
    field
    |> objective_satisfaction_identity_aliases()
    |> Enum.flat_map(fn alias_field ->
      objective_satisfaction_identity_value_from_source(Map.get(row, alias_field), field)
    end)
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      values -> values
    end
  end

  defp objective_satisfaction_identity_value_from_source(values, field) when is_list(values),
    do: Enum.flat_map(values, &objective_satisfaction_identity_value_from_source(&1, field))

  defp objective_satisfaction_identity_value_from_source(%{} = value, field) do
    field
    |> objective_satisfaction_identity_nested_keys()
    |> Enum.map(&Map.get(value, &1))
  end

  defp objective_satisfaction_identity_value_from_source(value, _field), do: [value]

  defp objective_satisfaction_identity_aliases("collection_id"),
    do: ["collection_id", "collection_ids", "collection", "collections"]

  defp objective_satisfaction_identity_aliases("product_id"),
    do: [
      "product_id",
      "data_product_id",
      "product_ids",
      "data_product_ids",
      "product",
      "products"
    ]

  defp objective_satisfaction_identity_aliases("payload_id"),
    do: ["payload_id", "payload_ids", "payload", "payloads"]

  defp objective_satisfaction_identity_aliases("instrument_id"),
    do: ["instrument_id", "instrument_ids", "instrument", "instruments"]

  defp objective_satisfaction_identity_nested_keys("collection_id"), do: ["collection_id", "id"]

  defp objective_satisfaction_identity_nested_keys("product_id"),
    do: ["product_id", "data_product_id", "id"]

  defp objective_satisfaction_identity_nested_keys("payload_id"), do: ["payload_id", "id"]
  defp objective_satisfaction_identity_nested_keys("instrument_id"), do: ["instrument_id", "id"]

  defp objective_satisfaction_entity_id(%{} = entity, fields) do
    entity = stringify_keys(entity)
    Enum.find_value(fields, &Map.get(entity, &1))
  end

  defp objective_satisfaction_entity_id(_entity, _fields), do: nil

  defp objective_satisfaction_source_activity_ids(row) do
    [
      row["source_activity_id"],
      row["source_activity_ids"],
      row["selected_activity_ids"],
      row["selected_contact_ids"],
      row["satisfied_contact_ids"],
      row["missed_downlink_activity_id"],
      row["missed_downlink_activity_ids"]
    ]
    |> List.flatten()
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp objective_satisfaction_trust_boundary(row) do
    Map.get(row, "trust_boundary") ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

  defp objective_satisfaction_objective_id(path, row, index, type, subject \\ nil) do
    base =
      stable_id_or_nil(row["id"]) ||
        stable_id_or_nil(row["objective_id"]) ||
        "#{type}:#{index}"

    subject = stable_id_or_nil(subject)

    hash =
      :crypto.hash(:sha256, :erlang.term_to_binary({path, row, index, type, subject}))
      |> Base.encode16(case: :lower)
      |> binary_part(0, 8)

    ["objective_satisfaction", type, subject || base, hash]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.join(":")
  end

  defp score_term_key(row) do
    row["term_key"] ||
      row["score_term_key"] ||
      row["metric"] ||
      row["name"] ||
      row["key"]
  end

  defp score_term_value(row) do
    objective_satisfaction_first_number(row, [
      "value",
      "score_term_value",
      "term_value",
      "gap_value"
    ])
  end

  defp score_term_downlink_gap?(term) do
    term in [
      "downlink_shortfall_mb",
      "downlink_completion_gap_mb",
      "selected_downlink_shortfall_mb",
      "data_volume_shortfall_mb",
      "missing_data_volume_mb",
      "required_data_volume_gap_mb",
      "required_downlink_mb",
      "downlink_gap_mb",
      "downlink_demand_gap_mb"
    ]
  end

  defp score_term_target_gap?(term) do
    term in [
      "target_gap_count",
      "target_coverage_gap_count",
      "coverage_gap_count",
      "missing_observation_count",
      "missing_revisit_count",
      "revisit_shortfall_count",
      "target_revisit_gap_count",
      "observation_shortfall_count"
    ]
  end

  defp score_term_collection_latency_gap?(term) do
    term in [
      "collection_latency_gap",
      "collection_latency_shortfall",
      "collection_latency_downlink_gap_mb",
      "collection_latency_data_volume_gap_mb",
      "late_collection_latency",
      "data_latency_gap",
      "delivery_latency_gap"
    ] or String.contains?(term || "", "collection_latency")
  end

  defp score_term_required_downlink_mb(row) do
    objective_satisfaction_first_positive_number(row, [
      "required_downlink_mb",
      "required_data_volume_mb",
      "target_data_volume_mb",
      "required_volume_mb",
      "min_downlink_mb",
      "downlink_completion_gap_mb",
      "selected_downlink_shortfall_mb",
      "downlink_shortfall_mb",
      "data_volume_shortfall_mb",
      "missing_data_volume_mb",
      ["score_terms", "downlink_shortfall_mb"],
      ["score_terms", "downlink_completion_gap_mb"],
      ["score_terms", "required_downlink_mb"]
    ]) || score_term_gap_value(row)
  end

  defp score_term_required_observations(row) do
    objective_satisfaction_first_positive_number(row, [
      "required_observations",
      "required_observation_count",
      "required_revisits",
      "required_revisit_count",
      "required_count",
      "target_gap_count",
      "target_coverage_gap_count",
      "coverage_gap_count",
      "missing_observation_count",
      "missing_revisit_count",
      "revisit_shortfall_count",
      ["score_terms", "target_gap_count"],
      ["score_terms", "missing_observation_count"],
      ["score_terms", "missing_revisit_count"],
      ["score_terms", "coverage_gap_count"]
    ]) || score_term_gap_value(row) || 1.0
  end

  defp score_term_latency_s(row) do
    objective_satisfaction_first_positive_number(row, [
      "max_latency_s",
      "required_latency_s",
      "target_latency_s",
      "latency_limit_s",
      "max_delivery_latency_s",
      "required_delivery_latency_s",
      "target_delivery_latency_s",
      "collection_latency_gap_s",
      "latency_gap_s"
    ])
  end

  defp score_term_collection_required_downlink_mb(row) do
    explicit =
      objective_satisfaction_first_positive_number(row, [
        "required_downlink_mb",
        "required_data_volume_mb",
        "target_data_volume_mb",
        "required_volume_mb",
        "min_downlink_mb",
        "collection_latency_downlink_gap_mb",
        "collection_latency_data_volume_gap_mb",
        "data_volume_shortfall_mb",
        "missing_data_volume_mb"
      ])

    term = row |> score_term_key() |> normalized_timeline_diff_token()

    cond do
      positive_number_value?(explicit) ->
        explicit

      term in ["collection_latency_downlink_gap_mb", "collection_latency_data_volume_gap_mb"] ->
        score_term_gap_value(row)

      true ->
        nil
    end
  end

  defp score_term_gap_value(row) do
    case score_term_value(row) do
      value when is_number(value) and value > 0.0 -> value
      _value -> nil
    end
  end

  defp score_term_target_refresh_type(term)
       when term in ["target_coverage_gap_count", "coverage_gap_count"],
       do: "target_coverage"

  defp score_term_target_refresh_type(_term), do: "target_revisit"

  defp score_term_station_id(row) do
    stable_id_or_nil(
      objective_satisfaction_station_id(row) ||
        score_term_nested_entity_id(row, "source_contact", [
          "ground_station_id",
          "station_id",
          "id"
        ]) ||
        score_term_nested_entity_id(row, "contact_candidate", [
          "ground_station_id",
          "station_id",
          "id"
        ]) ||
        score_term_nested_entity_id(row, "selected_contact", [
          "ground_station_id",
          "station_id",
          "id"
        ]) ||
        score_term_nested_entity_id(row, "source_activity", [
          "ground_station_id",
          "station_id",
          "id"
        ])
    )
  end

  defp score_term_spacecraft_id(row) do
    stable_id_or_nil(
      objective_satisfaction_spacecraft_id(row) ||
        score_term_nested_entity_id(row, "source_activity", [
          "spacecraft_id",
          "satellite_id"
        ]) ||
        score_term_nested_entity_id(row, "source_contact", [
          "spacecraft_id",
          "satellite_id"
        ]) ||
        score_term_nested_entity_id(row, "contact_candidate", [
          "spacecraft_id",
          "satellite_id"
        ])
    )
  end

  defp score_term_nested_entity_id(row, field, keys) do
    case Map.get(row, field) do
      %{} = entity -> objective_satisfaction_entity_id(entity, keys)
      _entity -> nil
    end
  end

  defp score_term_source_activity_ids(row) do
    [
      objective_satisfaction_source_activity_ids(row),
      score_term_nested_entity_id(row, "source_activity", ["activity_id", "id"]),
      score_term_nested_entity_id(row, "source_contact", ["contact_id", "activity_id", "id"]),
      score_term_nested_entity_id(row, "contact_candidate", ["contact_id", "activity_id", "id"]),
      score_term_nested_entity_id(row, "selected_contact", ["contact_id", "activity_id", "id"])
    ]
    |> List.flatten()
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp score_term_trust_boundary(row) do
    Map.get(row, "trust_boundary") ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

  defp score_term_objective_id(path, row, index, type, subject \\ nil) do
    base =
      stable_id_or_nil(row["id"]) ||
        stable_id_or_nil(row["term_id"]) ||
        "#{type}:#{index}"

    subject = stable_id_or_nil(subject)

    hash =
      :crypto.hash(:sha256, :erlang.term_to_binary({path, row, index, type, subject}))
      |> Base.encode16(case: :lower)
      |> binary_part(0, 8)

    ["score_term", type, subject || base, hash]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.join(":")
  end

  defp objective_tradeoff_report_rows(report) do
    Map.get(report, "tradeoffs") || Map.get(report, "rows") || []
  end

  defp objective_tradeoff_downlink_gap?(row) do
    positive_number_value?(objective_tradeoff_required_downlink_mb(row)) and
      objective_tradeoff_station_id(row) not in [nil, ""]
  end

  defp objective_tradeoff_target_gap?(row) do
    positive_number_value?(objective_tradeoff_required_observations(row)) and
      objective_satisfaction_target_ids(row) != []
  end

  defp objective_tradeoff_collection_latency_gap?(row) do
    positive_number_value?(objective_tradeoff_latency_s(row)) or
      positive_number_value?(objective_tradeoff_collection_required_downlink_mb(row))
  end

  defp objective_tradeoff_required_downlink_mb(row) do
    objective_satisfaction_first_positive_number(row, [
      "required_downlink_mb",
      "required_data_volume_mb",
      "target_data_volume_mb",
      "required_volume_mb",
      "min_downlink_mb",
      "downlink_completion_gap_mb",
      "selected_downlink_shortfall_mb",
      "downlink_shortfall_mb",
      "data_volume_shortfall_mb",
      "missing_data_volume_mb",
      ["score_terms", "downlink_shortfall_mb"],
      ["score_terms", "downlink_completion_gap_mb"],
      ["score_terms", "selected_downlink_shortfall_mb"],
      ["score_terms", "data_volume_shortfall_mb"],
      ["score_terms", "missing_data_volume_mb"]
    ])
  end

  defp objective_tradeoff_required_observations(row) do
    objective_satisfaction_first_positive_number(row, [
      "required_observations",
      "required_observation_count",
      "required_revisits",
      "required_revisit_count",
      "required_count",
      "target_gap_count",
      "target_coverage_gap_count",
      "coverage_gap_count",
      "missing_observation_count",
      "missing_revisit_count",
      "revisit_shortfall_count",
      ["score_terms", "target_gap_count"],
      ["score_terms", "target_coverage_gap_count"],
      ["score_terms", "coverage_gap_count"],
      ["score_terms", "missing_observation_count"],
      ["score_terms", "missing_revisit_count"],
      ["score_terms", "revisit_shortfall_count"]
    ])
  end

  defp objective_tradeoff_collection_required_downlink_mb(row) do
    objective_satisfaction_first_positive_number(row, [
      "required_downlink_mb",
      "required_data_volume_mb",
      "target_data_volume_mb",
      "required_volume_mb",
      "min_downlink_mb",
      "collection_latency_downlink_gap_mb",
      "collection_latency_data_volume_gap_mb",
      ["score_terms", "collection_latency_downlink_gap_mb"],
      ["score_terms", "collection_latency_data_volume_gap_mb"]
    ])
  end

  defp objective_tradeoff_latency_s(row) do
    objective_satisfaction_first_positive_number(row, [
      "max_latency_s",
      "required_latency_s",
      "target_latency_s",
      "latency_limit_s",
      "max_delivery_latency_s",
      "required_delivery_latency_s",
      "target_delivery_latency_s",
      "collection_latency_gap_s",
      "latency_gap_s",
      ["score_terms", "collection_latency_gap_s"],
      ["score_terms", "latency_gap_s"]
    ])
  end

  defp objective_tradeoff_target_type(row) do
    if positive_number_value?(
         objective_satisfaction_first_positive_number(row, [
           "target_coverage_gap_count",
           "coverage_gap_count",
           ["score_terms", "target_coverage_gap_count"],
           ["score_terms", "coverage_gap_count"]
         ])
       ) do
      "target_coverage"
    else
      "target_revisit"
    end
  end

  defp objective_tradeoff_station_id(row), do: score_term_station_id(row)
  defp objective_tradeoff_spacecraft_id(row), do: score_term_spacecraft_id(row)

  defp objective_tradeoff_source_activity_ids(row) do
    [
      row["activity_ids"],
      row["source_activity_ids"],
      score_term_source_activity_ids(row)
    ]
    |> List.flatten()
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp objective_tradeoff_trust_boundary(row), do: score_term_trust_boundary(row)

  defp objective_tradeoff_objective_id(path, row, index, type, subject \\ nil) do
    base =
      stable_id_or_nil(row["id"]) ||
        stable_id_or_nil(row["tradeoff_id"]) ||
        stable_id_or_nil(row["scenario_id"]) ||
        "#{type}:#{index}"

    subject = stable_id_or_nil(subject)

    hash =
      :crypto.hash(:sha256, :erlang.term_to_binary({path, row, index, type, subject}))
      |> Base.encode16(case: :lower)
      |> binary_part(0, 8)

    ["objective_tradeoff", type, subject || base, hash]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.join(":")
  end

  defp constraint_pressure_status?(row) do
    constraint_status_value(row["status"] || row["constraint_status"]) in [
      "fail",
      "warning",
      "violated"
    ]
  end

  defp constraint_status_value(status) do
    case normalized_timeline_diff_token(status) do
      status when status in ["pass", "passed", "satisfied", "met", "ok"] -> "pass"
      status when status in ["fail", "failed", "violation", "violated", "breached"] -> "fail"
      status when status in ["warn", "warning", "at_risk", "degraded"] -> "warning"
      status -> status
    end
  end

  defp constraint_downlink_gap?(row) do
    positive_number_value?(constraint_required_downlink_mb(row)) and
      constraint_station_id(row) not in [nil, ""]
  end

  defp constraint_resource_margin_gap?(row) do
    metric = constraint_metric(row)

    constraint_pressure_status?(row) and
      (constraint_resource_margin_metric?(metric) or constraint_resource_id(row) not in [nil, ""])
  end

  defp constraint_resource_margin_metric?(metric) do
    metric in [
      "resource_margin",
      "resource_margin_value",
      "resource_margin_percent",
      "minimum_resource_margin",
      "min_resource_margin",
      "remaining_resource_margin",
      "resource_minimum_margin",
      "battery_margin",
      "power_margin",
      "energy_margin",
      "storage_margin",
      "data_storage_margin",
      "propellant_margin",
      "fuel_margin",
      "thermal_margin"
    ] or String.contains?(metric || "", "resource_margin") or
      String.ends_with?(metric || "", "_margin")
  end

  defp constraint_required_downlink_mb(row) do
    explicit =
      objective_satisfaction_first_positive_number(row, [
        "required_downlink_mb",
        "required_data_volume_mb",
        "target_data_volume_mb",
        "required_volume_mb",
        "min_downlink_mb",
        "downlink_completion_gap_mb",
        "selected_downlink_shortfall_mb",
        "selected_data_volume_shortfall_mb",
        "downlink_shortfall_mb",
        "data_volume_shortfall_mb",
        "missing_data_volume_mb",
        ["throughput_model", "required_downlink_mb"],
        ["throughput_model", "target_data_volume_mb"],
        ["activity_context", "required_downlink_mb"],
        ["activity_context", "target_data_volume_mb"]
      ])

    cond do
      positive_number_value?(explicit) ->
        explicit

      constraint_metric(row) in [
        "selected_downlink_shortfall_mb",
        "selected_data_volume_shortfall_mb",
        "downlink_shortfall_mb",
        "data_volume_shortfall_mb",
        "missing_data_volume_mb",
        "required_data_volume_gap_mb"
      ] ->
        objective_satisfaction_first_positive_number(row, ["value", "score"])

      true ->
        nil
    end
  end

  defp constraint_metric(row),
    do: normalized_timeline_diff_token(row["metric"] || row["constraint_id"])

  defp constraint_id(row), do: stable_id_or_nil(row["constraint_id"] || row["id"])

  defp constraint_resource_id(row) do
    stable_id_or_nil(
      row["resource_id"] ||
        row["resource_name"] ||
        row["battery_id"] ||
        row["energy_resource_id"] ||
        row["storage_resource_id"] ||
        row["consumable_id"] ||
        row["resource"]
    )
  end

  defp constraint_station_id(row), do: score_term_station_id(row)
  defp constraint_spacecraft_id(row), do: score_term_spacecraft_id(row)

  defp constraint_source_activity_ids(row) do
    [
      objective_satisfaction_source_activity_ids(row),
      score_term_source_activity_ids(row),
      row["activity_id"],
      row["activity_ids"]
    ]
    |> List.flatten()
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp constraint_trust_boundary(row), do: score_term_trust_boundary(row)

  defp constraint_objective_id(path, row, index, type) do
    base =
      stable_id_or_nil(row["id"]) ||
        stable_id_or_nil(row["constraint_id"]) ||
        "#{type}:#{index}"

    hash =
      :crypto.hash(:sha256, :erlang.term_to_binary({path, row, index, type}))
      |> Base.encode16(case: :lower)
      |> binary_part(0, 8)

    ["constraint", type, base, hash]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.join(":")
  end

  defp link_capacity_downlink_pressure?(row) do
    positive_number_value?(link_capacity_required_downlink_mb(row)) and
      link_capacity_station_id(row) not in [nil, ""]
  end

  defp link_capacity_required_downlink_mb(row) do
    objective_satisfaction_first_positive_number(row, [
      "selected_downlink_shortfall_mb",
      "actual_downlink_shortfall_mb"
    ])
  end

  defp link_capacity_station_id(row) do
    [
      row["ground_station_id"],
      row["station_id"],
      nested_station_id(row)
    ]
    |> Enum.find_value(&stable_id_or_nil/1)
  end

  defp link_capacity_spacecraft_id(row) do
    [
      row["spacecraft_id"],
      row["scenario_id"],
      link_capacity_source_contact_values(row)
      |> Enum.filter(&is_map/1)
      |> Enum.map(&stringify_keys/1)
      |> Enum.flat_map(fn contact ->
        [
          contact["spacecraft_id"],
          contact["scenario_id"],
          get_in(contact, ["spacecraft", "id"]),
          get_in(contact, ["satellite", "id"])
        ]
      end)
    ]
    |> List.flatten()
    |> Enum.find_value(&stable_id_or_nil/1)
  end

  defp link_capacity_source_contact_ids(row) do
    row
    |> link_capacity_source_contact_values()
    |> Enum.map(&link_capacity_source_contact_id/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp link_capacity_source_contact_values(row) do
    [
      row["selected_contact_ids"],
      row["selected_contact_id"],
      row["actual_throughput_contact_ids"],
      row["actual_throughput_contact_id"],
      row["actual_completion_contact_ids"],
      row["actual_completion_contact_id"],
      row["required_downlink_contact_ids"],
      row["required_downlink_contact_id"],
      row["contact_ids"],
      row["contact_id"],
      row["selected_contacts"],
      row["selected_contact"],
      row["actual_throughput_contacts"],
      row["actual_throughput_contact"],
      row["actual_completion_contacts"],
      row["actual_completion_contact"],
      row["required_downlink_contacts"],
      row["required_downlink_contact"],
      row["source_contacts"],
      row["source_contact"],
      row["contacts"],
      row["contact"]
    ]
    |> List.flatten()
  end

  defp link_capacity_source_contact_id(%{} = contact) do
    contact = stringify_keys(contact)

    [
      contact["id"],
      contact["activity_id"],
      contact["contact_id"],
      get_in(contact, ["activity_context", "id"]),
      get_in(contact, ["activity_context", "activity_id"])
    ]
    |> Enum.find_value(&stable_id_or_nil/1)
  end

  defp link_capacity_source_contact_id(value), do: stable_id_or_nil(value)

