  defp link_capacity_trust_boundary(row) do
    Map.get(row, "trust_boundary") ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      get_in(row, ["source_link_capacity", "trust_boundary"]) ||
      get_in(row, ["source_link_capacity", "provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

  defp link_capacity_objective_id(path, row, index, type) do
    base =
      stable_id_or_nil(row["id"]) ||
        stable_id_or_nil(row["ground_station_id"]) ||
        stable_id_or_nil(row["station_id"]) ||
        "#{type}:#{index}"

    hash =
      :crypto.hash(:sha256, :erlang.term_to_binary({path, row, index, type}))
      |> Base.encode16(case: :lower)
      |> binary_part(0, 8)

    ["link_capacity", type, base, hash]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.join(":")
  end

  defp normalize_contact_allocation_row(row) do
    row
    |> normalize_contact_allocation_status_field("allocation_status")
    |> normalize_contact_allocation_status_field("effective_allocation_status")
    |> normalize_contact_allocation_status_field("review_status")
    |> normalize_contact_allocation_status_field("approval_status")
    |> normalize_contact_allocation_policy_decision()
  end

  defp normalize_contact_allocation_status_field(row, field) do
    case Map.get(row, field) do
      value when value in [nil, ""] -> row
      value -> Map.put(row, field, normalized_timeline_diff_token(value))
    end
  end

  defp normalize_contact_allocation_policy_decision(%{"policy_decision" => %{} = decision} = row) do
    decision =
      decision
      |> stringify_keys()
      |> normalize_contact_allocation_status_field("classification")

    Map.put(row, "policy_decision", decision)
  end

  defp normalize_contact_allocation_policy_decision(row), do: row

  defp contact_allocation_downlink_pressure?(row) do
    status = contact_allocation_effective_status(row)

    status in ["deferred", "blocked", "policy_blocked", "blocked_by_policy"] and
      contact_allocation_downlink_row?(row) and
      positive_number_value?(
        contact_allocation_required_downlink_mb(row, contact_allocation_source_contact(row))
      ) and
      contact_allocation_station_id(row, contact_allocation_source_contact(row)) not in [nil, ""]
  end

  defp contact_allocation_effective_status(row) do
    Map.get(row, "effective_allocation_status") ||
      Map.get(row, "allocation_status") ||
      Map.get(row, "approval_status") ||
      get_in(row, ["policy_decision", "classification"])
  end

  defp contact_allocation_downlink_row?(row) do
    contact_allocation_downlink_candidate?(row) or
      contact_allocation_downlink_candidate?(contact_allocation_source_contact(row))
  end

  defp contact_allocation_downlink_candidate?(%{} = row) do
    type =
      row["type"] ||
        row["activity_type"] ||
        get_in(row, ["activity_context", "type"])

    direction =
      row["direction"] ||
        get_in(row, ["activity_context", "direction"])

    type in ["downlink", :downlink] or direction in ["downlink", :downlink]
  end

  defp contact_allocation_downlink_candidate?(_row), do: false

  defp contact_allocation_source_contact(row) do
    contact_id = contact_allocation_contact_id(row, %{})

    cond do
      is_map(row["source_contact_candidate"]) ->
        stringify_keys(row["source_contact_candidate"])

      source_contact = contact_allocation_direct_source_contact(row, contact_id) ->
        source_contact

      is_list(get_in(row, ["source_contention_recommendation", "source_contact_candidates"])) ->
        row
        |> get_in(["source_contention_recommendation", "source_contact_candidates"])
        |> Enum.map(&stringify_keys/1)
        |> Enum.find(%{}, &contact_allocation_contact_match?(&1, contact_id))

      true ->
        %{}
    end
  end

  defp contact_allocation_direct_source_contact(row, contact_id) do
    [
      row["source_contact"],
      row["contact_candidate"],
      row["contact"],
      row["source_contacts"],
      row["contact_candidates"],
      row["contacts"]
    ]
    |> List.flatten()
    |> Enum.filter(&is_map/1)
    |> Enum.map(&stringify_keys/1)
    |> Enum.find(&contact_allocation_contact_match?(&1, contact_id))
  end

  defp contact_allocation_contact_match?(contact, contact_id) do
    contact_id in [nil, ""] or contact_allocation_contact_id(contact, %{}) == contact_id
  end

  defp contact_allocation_contact_id(row, source_contact) do
    [
      row["contact_id"],
      row["activity_id"],
      row["source_activity_id"],
      row["downlink_activity_id"],
      row["id"],
      source_contact["contact_id"],
      source_contact["activity_id"],
      source_contact["source_activity_id"],
      source_contact["downlink_activity_id"],
      source_contact["id"]
    ]
    |> Enum.find_value(&stable_id_or_nil/1)
  end

  defp contact_allocation_required_downlink_mb(row, source_contact) do
    objective_satisfaction_first_positive_number(row, [
      "selected_downlink_shortfall_mb",
      "required_downlink_mb",
      "candidate_downlink_mb",
      "estimated_throughput_mb",
      "planned_throughput_mb",
      ["throughput_model", "required_downlink_mb"],
      ["throughput_model", "estimated_throughput_mb"],
      ["throughput_model", "planned_throughput_mb"]
    ]) ||
      objective_satisfaction_first_positive_number(source_contact, [
        "selected_downlink_shortfall_mb",
        "required_downlink_mb",
        "candidate_downlink_mb",
        "estimated_throughput_mb",
        "planned_throughput_mb",
        ["throughput_model", "required_downlink_mb"],
        ["throughput_model", "estimated_throughput_mb"],
        ["throughput_model", "planned_throughput_mb"]
      ])
  end

  defp contact_allocation_station_id(row, source_contact) do
    [
      row["ground_station_id"],
      row["station_id"],
      nested_station_id(row),
      source_contact["ground_station_id"],
      source_contact["station_id"],
      nested_station_id(source_contact)
    ]
    |> Enum.find_value(&stable_id_or_nil/1)
  end

  defp contact_allocation_source_activity_ids(row, source_contact) do
    [
      contact_allocation_contact_id(row, source_contact),
      row["source_activity_ids"],
      row["deferred_contact_ids"],
      source_contact["source_activity_ids"]
    ]
    |> List.flatten()
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp contact_allocation_source_window_id(row, source_contact) do
    case contact_allocation_source_window_ids(row, source_contact) do
      [source_window_id] -> source_window_id
      _source_window_ids -> nil
    end
  end

  defp contact_allocation_source_window_ids(row, source_contact) do
    [
      row["source_window_id"],
      row["source_window_ids"],
      get_in(row, ["source_window", "id"]),
      get_in(row, ["activity_context", "source_window_id"]),
      source_contact["source_window_id"],
      source_contact["source_window_ids"],
      get_in(source_contact, ["source_window", "id"]),
      get_in(source_contact, ["activity_context", "source_window_id"])
    ]
    |> List.flatten()
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp contact_allocation_trust_boundary(row) do
    Map.get(row, "trust_boundary") ||
      Map.get(row, "resource_trust_boundary") ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      get_in(row, ["source_contact_allocation", "trust_boundary"]) ||
      get_in(row, ["source_contact_allocation", "provenance", "trust_boundary"]) ||
      get_in(row, ["source_resource_suppression", "resource_trust_boundary"]) ||
      get_in(row, ["source_resource_suppression", "resource_provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

  defp contact_allocation_objective_id(path, row, index, type) do
    base =
      contact_allocation_contact_id(row, contact_allocation_source_contact(row)) ||
        stable_id_or_nil(row["id"]) ||
        "#{type}:#{index}"

    hash =
      :crypto.hash(:sha256, :erlang.term_to_binary({path, row, index, type}))
      |> Base.encode16(case: :lower)
      |> binary_part(0, 8)

    ["contact_allocation", type, base, hash]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.join(":")
  end

  defp contact_contention_resolution_deferred_contacts(recommendation) do
    recommendation = stringify_keys(recommendation)
    deferred_ids = Map.get(recommendation, "deferred_contact_ids", [])
    candidates = contact_contention_resolution_source_contacts(recommendation)

    contacts =
      deferred_ids
      |> List.wrap()
      |> Enum.map(&stable_id_or_nil/1)
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.map(fn contact_id ->
        contact =
          Enum.find(candidates, &contact_contention_resolution_contact_match?(&1, contact_id)) ||
            %{"id" => contact_id}

        contact
        |> stringify_keys()
        |> Map.put_new("id", contact_id)
      end)

    case contacts do
      [] ->
        recommendation
        |> contact_contention_resolution_source_contact()
        |> case do
          %{} = contact -> [contact]
          _contact -> []
        end

      contacts ->
        contacts
    end
  end

  defp contact_contention_resolution_source_contacts(recommendation) do
    [
      recommendation["source_contact_candidates"],
      recommendation["contact_candidates"],
      recommendation["source_contacts"],
      recommendation["contacts"]
    ]
    |> List.flatten()
    |> Enum.filter(&is_map/1)
    |> Enum.map(&stringify_keys/1)
  end

  defp contact_contention_resolution_source_contact(recommendation) do
    cond do
      is_map(recommendation["source_contact"]) ->
        recommendation["source_contact"] |> stringify_keys()

      is_map(recommendation["contact_candidate"]) ->
        recommendation["contact_candidate"] |> stringify_keys()

      true ->
        %{}
    end
  end

  defp contact_contention_resolution_contact_match?(%{} = contact, contact_id) do
    [
      contact["id"],
      contact["contact_id"],
      contact["activity_id"],
      contact["source_activity_id"]
    ]
    |> Enum.any?(&(stable_id_or_nil(&1) == contact_id))
  end

  defp contact_contention_resolution_downlink_candidate?(recommendation, source_contact) do
    recommendation = stringify_keys(recommendation)
    source_contact = stringify_keys(source_contact || %{})

    downlink_direction? =
      [
        source_contact["type"],
        source_contact["activity_type"],
        source_contact["direction"],
        recommendation["direction"]
      ]
      |> Enum.any?(&(normalized_timeline_diff_token(&1) == "downlink"))

    downlink_direction? or
      positive_number_value?(
        contact_contention_resolution_required_downlink_mb(recommendation, source_contact)
      )
  end

  defp contact_contention_resolution_required_downlink_mb(recommendation, source_contact) do
    objective_satisfaction_first_positive_number(source_contact, [
      "selected_downlink_shortfall_mb",
      "required_downlink_mb",
      "candidate_downlink_mb",
      "estimated_throughput_mb",
      "planned_throughput_mb",
      ["throughput_model", "required_downlink_mb"],
      ["throughput_model", "estimated_throughput_mb"],
      ["throughput_model", "planned_throughput_mb"]
    ]) ||
      objective_satisfaction_first_positive_number(recommendation, [
        "selected_downlink_shortfall_mb",
        "required_downlink_mb",
        "candidate_downlink_mb",
        "estimated_throughput_mb",
        "planned_throughput_mb",
        ["throughput_model", "required_downlink_mb"],
        ["throughput_model", "estimated_throughput_mb"],
        ["throughput_model", "planned_throughput_mb"]
      ])
  end

  defp contact_contention_resolution_station_id(recommendation, source_contact) do
    [
      source_contact["ground_station_id"],
      source_contact["station_id"],
      nested_station_id(source_contact),
      recommendation["ground_station_id"],
      recommendation["station_id"],
      nested_station_id(recommendation)
    ]
    |> Enum.find_value(&stable_id_or_nil/1)
  end

  defp contact_contention_resolution_source_activity_ids(recommendation, source_contact) do
    [
      source_contact["id"],
      source_contact["contact_id"],
      source_contact["activity_id"],
      source_contact["source_activity_id"],
      recommendation["selected_contact_id"]
    ]
    |> List.flatten()
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp contact_contention_resolution_source_window_id(recommendation, source_contact) do
    case contact_contention_resolution_source_window_ids(recommendation, source_contact) do
      [source_window_id] -> source_window_id
      _source_window_ids -> nil
    end
  end

  defp contact_contention_resolution_source_window_ids(recommendation, source_contact) do
    [
      source_contact["source_window_id"],
      source_contact["source_window_ids"],
      get_in(source_contact, ["source_window", "id"]),
      get_in(source_contact, ["activity_context", "source_window_id"]),
      recommendation["source_window_id"],
      recommendation["source_window_ids"]
    ]
    |> List.flatten()
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp contact_contention_resolution_trust_boundary(recommendation) do
    Map.get(recommendation, "trust_boundary") ||
      get_in(recommendation, ["provenance", "trust_boundary"]) ||
      get_in(recommendation, ["source_recommendation", "trust_boundary"]) ||
      get_in(recommendation, ["source_recommendation", "provenance", "trust_boundary"]) ||
      recommendation["_source_report_trust_boundary"]
  end

  defp contact_contention_resolution_objective_id(
         path,
         recommendation,
         source_contact,
         recommendation_index,
         contact_index,
         type
       ) do
    base =
      stable_id_or_nil(
        source_contact["id"] ||
          source_contact["contact_id"] ||
          source_contact["activity_id"] ||
          recommendation["group_id"]
      ) || "#{type}:#{recommendation_index}:#{contact_index}"

    hash =
      :crypto.hash(
        :sha256,
        :erlang.term_to_binary(
          {path, recommendation, source_contact, recommendation_index, contact_index, type}
        )
      )
      |> Base.encode16(case: :lower)
      |> binary_part(0, 8)

    ["contact_contention_resolution", type, base, hash]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.join(":")
  end

  defp resource_projection_downlink_pressure?(row) do
    positive_number_value?(resource_projection_required_downlink_mb(row)) and
      resource_projection_station_id(row) not in [nil, ""]
  end

  defp resource_projection_required_downlink_mb(row) do
    objective_satisfaction_first_positive_number(row, [
      "projected_downlink_shortfall_mb",
      "peak_downlink_shortfall_mb",
      "downlink_shortfall_mb",
      "selected_downlink_shortfall_mb",
      "required_downlink_mb",
      "required_data_volume_mb",
      "target_data_volume_mb",
      ["first_resource_pressure", "downlink_shortfall_mb"],
      ["first_resource_pressure", "projected_downlink_shortfall_mb"],
      ["source_activity", "downlink_shortfall_mb"],
      ["source_activity", "required_downlink_mb"],
      ["source_activity", "target_data_volume_mb"]
    ])
  end

  defp resource_projection_row_margin_feedback(row) do
    %{
      "storage_margin" =>
        first_resource_projection_margin(row, [
          "projected_storage_margin",
          "storage_margin",
          "starting_storage_margin"
        ]) ||
          negative_resource_projection_pressure(row, [
            "projected_storage_overflow_mb",
            "storage_overflow_mb"
          ]),
      "downlink_margin" =>
        first_resource_projection_margin(row, [
          "projected_downlink_margin",
          "downlink_margin",
          "starting_downlink_margin"
        ]) ||
          negative_resource_projection_pressure(row, [
            "projected_downlink_shortfall_mb",
            "downlink_shortfall_mb"
          ]),
      "power_margin" =>
        first_resource_projection_margin(row, [
          "projected_power_margin",
          "projected_battery_state_of_charge",
          "battery_state_of_charge",
          "power_margin"
        ]) ||
          negative_resource_projection_pressure(row, [
            "projected_battery_overuse_wh",
            "battery_overuse_wh"
          ]),
      "battery_capacity_wh" => first_resource_projection_number(row, ["battery_capacity_wh"]),
      "battery_energy_used_wh" =>
        first_resource_projection_number(row, [
          "projected_battery_energy_used_wh",
          "battery_energy_used_wh"
        ]),
      "battery_state_of_charge" =>
        first_resource_projection_number(row, [
          "projected_battery_state_of_charge",
          "battery_state_of_charge"
        ])
    }
    |> compact_map()
  end

  defp resource_projection_row_availability_feedback(row) do
    %{
      "payload_available" => resource_projection_boolean_feedback(row, "payload_available"),
      "antenna_available" => resource_projection_boolean_feedback(row, "antenna_available"),
      "spacecraft_available" => resource_projection_boolean_feedback(row, "spacecraft_available"),
      "degraded" => resource_projection_boolean_feedback(row, "degraded")
    }
    |> compact_map()
  end

  defp resource_filter_row_margin_feedback(row) do
    reason = normalized_timeline_diff_token(row["suppressed_reason"])

    %{
      "fuel_margin" =>
        resource_filter_unit_margin(row, "fuel_margin") ||
          if(reason == "fuel_margin_below_policy", do: 0.0),
      "power_margin" =>
        resource_filter_unit_margin(row, "power_margin") ||
          if(
            reason in ["power_margin_below_observe_policy", "power_margin_below_downlink_policy"],
            do: 0.0
          ),
      "storage_margin" =>
        resource_filter_unit_margin(row, "storage_margin") ||
          if(reason == "storage_margin_below_observe_policy", do: 0.0),
      "downlink_margin" =>
        resource_filter_unit_margin(row, "downlink_margin") ||
          if(reason == "downlink_margin_below_policy", do: 0.0),
      "thermal_margin_c" =>
        resource_filter_number(row, "thermal_margin_c") ||
          if(reason == "thermal_margin_below_policy", do: 0.0),
      "battery_capacity_wh" => resource_filter_number(row, "battery_capacity_wh"),
      "battery_energy_used_wh" => resource_filter_number(row, "battery_energy_used_wh"),
      "battery_state_of_charge" => resource_filter_unit_margin(row, "battery_state_of_charge")
    }
    |> compact_map()
  end

  defp resource_filter_row_availability_feedback(row) do
    reason = normalized_timeline_diff_token(row["suppressed_reason"])

    %{
      "payload_available" =>
        resource_filter_first_boolean(
          resource_filter_boolean_feedback(row, "payload_available"),
          if(reason in ["payload_unavailable", "spacecraft_degraded_payload_unavailable"],
            do: false
          )
        ),
      "antenna_available" =>
        resource_filter_first_boolean(
          resource_filter_boolean_feedback(row, "antenna_available"),
          if(reason == "antenna_unavailable", do: false)
        ),
      "spacecraft_available" =>
        resource_filter_first_boolean(
          resource_filter_boolean_feedback(row, "spacecraft_available"),
          if(reason == "spacecraft_unavailable", do: false)
        ),
      "degraded" =>
        resource_filter_first_boolean(
          resource_filter_boolean_feedback(row, "degraded"),
          if(reason == "spacecraft_degraded_payload_unavailable", do: true)
        ),
      "mode" => resource_filter_mode_feedback(row)
    }
    |> compact_map()
  end

  defp resource_filter_first_boolean(value, _fallback) when is_boolean(value), do: value
  defp resource_filter_first_boolean(_value, fallback) when is_boolean(fallback), do: fallback
  defp resource_filter_first_boolean(_value, _fallback), do: nil

  defp resource_filter_unit_margin(row, field) do
    case resource_filter_number(row, field) do
      value when is_number(value) and value < 0.0 -> 0.0
      value when is_number(value) and value > 1.0 -> 1.0
      value when is_number(value) -> value
      _value -> nil
    end
  end

  defp resource_filter_number(row, field) do
    case numeric_value(Map.get(row, field)) do
      value when is_number(value) -> value
      _value -> nil
    end
  end

  defp resource_filter_boolean_feedback(row, field) do
    case boolean_value(Map.get(row, field)) do
      bool when is_boolean(bool) -> bool
      nil -> nil
    end
  end

  defp resource_filter_mode_feedback(row) do
    case Map.get(row, "mode") do
      mode when is_binary(mode) and mode != "" -> mode
      _mode -> nil
    end
  end

  defp first_resource_projection_number(row, fields) do
    Enum.find_value(fields, fn field ->
      case numeric_value(Map.get(row, field)) do
        value when is_number(value) -> value
        _value -> nil
      end
    end)
  end

  defp first_resource_projection_margin(row, fields) do
    case first_resource_projection_number(row, fields) do
      value when is_number(value) and value < 0.0 -> 0.0
      value when is_number(value) and value > 1.0 -> 1.0
      value when is_number(value) -> value
      _value -> nil
    end
  end

  defp negative_resource_projection_pressure(row, fields) do
    case first_resource_projection_number(row, fields) do
      value when is_number(value) and value > 0.0 -> 0.0
      _value -> nil
    end
  end

  defp resource_projection_boolean_feedback(row, field) do
    case boolean_value(Map.get(row, field)) do
      bool when is_boolean(bool) -> bool
      nil -> nil
    end
  end

  defp resource_projection_station_id(row) do
    stable_id_or_nil(
      row["first_resource_pressure_ground_station_id"] ||
        row["ground_station_id"] ||
        row["station_id"] ||
        score_term_nested_entity_id(row, "first_resource_pressure", [
          "ground_station_id",
          "station_id",
          "id"
        ]) ||
        score_term_nested_entity_id(row, "source_activity", [
          "ground_station_id",
          "station_id",
          "id"
        ]) ||
        score_term_nested_entity_id(row, "source_contact", [
          "ground_station_id",
          "station_id",
          "id"
        ]) ||
        objective_satisfaction_station_id(row)
    )
  end

  defp resource_projection_spacecraft_id(row) do
    stable_id_or_nil(
      row["spacecraft_id"] ||
        score_term_nested_entity_id(row, "first_resource_pressure", [
          "spacecraft_id",
          "satellite_id"
        ]) ||
        score_term_nested_entity_id(row, "source_activity", [
          "spacecraft_id",
          "satellite_id"
        ]) ||
        objective_satisfaction_spacecraft_id(row)
    )
  end

  defp resource_projection_pressure_status(row) do
    normalized_timeline_diff_token(row["resource_pressure_status"])
  end

  defp resource_projection_pressure_types(row) do
    row
    |> Map.get("resource_pressure_types")
    |> List.wrap()
    |> Enum.map(&normalized_timeline_diff_token/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      types -> types
    end
  end

  defp resource_projection_source_activity_ids(row) do
    [
      row["first_resource_pressure_activity_id"],
      row["activity_ids"],
      row["source_activity_ids"],
      score_term_nested_entity_id(row, "first_resource_pressure", ["activity_id", "id"]),
      score_term_nested_entity_id(row, "source_activity", ["activity_id", "id"]),
      objective_satisfaction_source_activity_ids(row)
    ]
    |> List.flatten()
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp resource_projection_direction(row) do
    [
      row["first_resource_pressure_direction"],
      row["direction"],
      get_in(row, ["first_resource_pressure", "direction"]),
      get_in(row, ["activity_context", "direction"]),
      get_in(row, ["source_activity", "direction"]),
      get_in(row, ["source_activity", "activity_context", "direction"]),
      row["first_resource_pressure_activity_type"],
      row["activity_type"],
      get_in(row, ["first_resource_pressure", "activity_type"]),
      get_in(row, ["source_activity", "activity_type"]),
      row["type"],
      get_in(row, ["source_activity", "type"])
    ]
    |> Enum.map(&normalize_direction/1)
    |> Enum.find(&(&1 not in [nil, ""]))
  end

  defp resource_projection_trust_boundary(row) do
    row["resource_trust_boundary"] ||
      row["trust_boundary"] ||
      get_in(row, ["resource_provenance", "trust_boundary"]) ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

  defp resource_projection_objective_id(path, row, index, type) do
    base =
      stable_id_or_nil(row["id"]) ||
        stable_id_or_nil(row["spacecraft_id"]) ||
        "#{type}:#{index}"

    hash =
      :crypto.hash(:sha256, :erlang.term_to_binary({path, row, index, type}))
      |> Base.encode16(case: :lower)
      |> binary_part(0, 8)

    ["resource_projection", type, base, hash]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.join(":")
  end

  defp timeline_diff_removed_observation_objective_row?(%{} = row) do
    timeline_diff_status(row) == "removed" and
      timeline_diff_observation_activity?(row, "source") and
      timeline_diff_removed_observation_target_id(row) not in [nil, ""]
  end

  defp timeline_diff_changed_observation_objective_row?(%{} = row) do
    timeline_diff_status(row) == "changed" and
      timeline_diff_observation_activity?(row) and
      timeline_diff_changed_observation_target_id(row) not in [nil, ""] and
      is_number(timeline_diff_changed_observation_success_factor(row))
  end

  defp timeline_diff_changed_observation_quality_feedback_row?(%{} = row) do
    timeline_diff_status(row) == "changed" and
      timeline_diff_observation_activity?(row) and
      timeline_diff_changed_observation_target_id(row) not in [nil, ""] and
      (is_number(timeline_diff_changed_observation_image_quality_score(row)) or
         is_number(timeline_diff_changed_observation_cloud_cover_fraction(row)) or
         is_number(timeline_diff_changed_observation_blur_score(row)) or
         timeline_diff_changed_observation_image_quality_status(row) not in [nil, ""] or
         timeline_diff_changed_observation_image_quality_source(row) not in [nil, ""])
  end

  defp timeline_diff_observation_activity?(row) do
    timeline_diff_observation_activity?(row, "source") or
      timeline_diff_observation_activity?(row, "replacement")
  end

  defp timeline_diff_observation_activity?(row, side) do
    activity_type =
      row["#{side}_activity_type"] ||
        get_in(row, ["#{side}_activity_context", "activity_type"]) ||
        get_in(row, ["#{side}_activity_context", "type"])

    activity_type
    |> normalized_timeline_diff_token()
    |> case do
      type when type in ["observe", "observation", "target_visibility", "imaging"] -> true
      _type -> false
    end
  end

  defp timeline_diff_removed_observation_target_id(row) do
    target_identity_value(
      row["source_target_id"] ||
        get_in(row, ["source_activity_context", "target_id"]) ||
        get_in(row, ["source_activity_context", "target"]) ||
        get_in(row, ["source_activity_context", "timeline_identity", "subject_id"])
    )
  end

  defp timeline_diff_changed_observation_target_id(row) do
    target_identity_value(
      row["replacement_target_id"] ||
        row["source_target_id"] ||
        get_in(row, ["replacement_activity_context", "target_id"]) ||
        get_in(row, ["source_activity_context", "target_id"]) ||
        get_in(row, ["replacement_activity_context", "target"]) ||
        get_in(row, ["source_activity_context", "target"]) ||
        get_in(row, ["replacement_activity_context", "timeline_identity", "subject_id"]) ||
        get_in(row, ["source_activity_context", "timeline_identity", "subject_id"])
    )
  end

  defp timeline_diff_changed_observation_success_factor(row) do
    case timeline_diff_first_number(row, [
           "observation_success_factor",
           "replacement_observation_success_factor",
           ["replacement_activity_context", "observation_success_factor"]
         ]) do
      factor when is_number(factor) ->
        factor |> max(0.0) |> min(1.0)

      _factor ->
        timeline_diff_changed_observation_result_factor(row) ||
          timeline_diff_changed_source_observation_success_factor(row)
    end
  end

  defp timeline_diff_changed_observation_image_quality_score(row) do
    row
    |> timeline_diff_first_number([
      "image_quality_score",
      "replacement_image_quality_score",
      "replacement_product_quality_score",
      "replacement_quality_score",
      ["replacement_activity_context", "image_quality_score"],
      ["replacement_activity_context", "product_quality_score"],
      ["replacement_activity_context", "quality_score"],
      ["replacement_activity_context", "quality", "image_quality_score"],
      ["replacement_activity_context", "quality", "product_quality_score"],
      ["replacement_activity_context", "quality", "score"],
      "source_image_quality_score",
      "source_product_quality_score",
      "source_quality_score",
      ["source_activity_context", "image_quality_score"],
      ["source_activity_context", "product_quality_score"],
      ["source_activity_context", "quality_score"],
      ["source_activity_context", "quality", "image_quality_score"],
      ["source_activity_context", "quality", "product_quality_score"],
      ["source_activity_context", "quality", "score"]
    ])
    |> unit_interval_or_nil()
  end

  defp timeline_diff_changed_observation_cloud_cover_fraction(row) do
    row
    |> timeline_diff_first_number([
      "cloud_cover_fraction",
      "replacement_cloud_cover_fraction",
      "replacement_cloud_fraction",
      "replacement_cloud_cover",
      ["replacement_activity_context", "cloud_cover_fraction"],
      ["replacement_activity_context", "cloud_fraction"],
      ["replacement_activity_context", "cloud_cover"],
      ["replacement_activity_context", "quality", "cloud_cover_fraction"],
      ["replacement_activity_context", "quality", "cloud_fraction"],
      ["replacement_activity_context", "quality", "cloud_cover"],
      "source_cloud_cover_fraction",
      "source_cloud_fraction",
      "source_cloud_cover",
      ["source_activity_context", "cloud_cover_fraction"],
      ["source_activity_context", "cloud_fraction"],
      ["source_activity_context", "cloud_cover"],
      ["source_activity_context", "quality", "cloud_cover_fraction"],
      ["source_activity_context", "quality", "cloud_fraction"],
      ["source_activity_context", "quality", "cloud_cover"]
    ])
    |> unit_interval_or_nil()
  end

  defp timeline_diff_changed_observation_blur_score(row) do
    row
    |> timeline_diff_first_number([
      "blur_score",
      "replacement_blur_score",
      "replacement_image_blur_score",
      "replacement_sharpness_loss_fraction",
      ["replacement_activity_context", "blur_score"],
      ["replacement_activity_context", "image_blur_score"],
      ["replacement_activity_context", "sharpness_loss_fraction"],
      ["replacement_activity_context", "quality", "blur_score"],
      ["replacement_activity_context", "quality", "image_blur_score"],
      ["replacement_activity_context", "quality", "sharpness_loss_fraction"],
      "source_blur_score",
      "source_image_blur_score",
      "source_sharpness_loss_fraction",
      ["source_activity_context", "blur_score"],
      ["source_activity_context", "image_blur_score"],
      ["source_activity_context", "sharpness_loss_fraction"],
      ["source_activity_context", "quality", "blur_score"],
      ["source_activity_context", "quality", "image_blur_score"],
      ["source_activity_context", "quality", "sharpness_loss_fraction"]
    ])
    |> unit_interval_or_nil()
  end

  defp timeline_diff_changed_observation_image_quality_status(row) do
    timeline_diff_first_string(row, [
      "image_quality_status",
      "replacement_image_quality_status",
      "replacement_product_quality_status",
      "replacement_quality_status",
      ["replacement_activity_context", "image_quality_status"],
      ["replacement_activity_context", "product_quality_status"],
      ["replacement_activity_context", "quality_status"],
      ["replacement_activity_context", "quality", "status"],
      "source_image_quality_status",
      "source_product_quality_status",
      "source_quality_status",
      ["source_activity_context", "image_quality_status"],
      ["source_activity_context", "product_quality_status"],
      ["source_activity_context", "quality_status"],
      ["source_activity_context", "quality", "status"]
    ])
  end

  defp timeline_diff_changed_observation_image_quality_source(row) do
    timeline_diff_first_string(row, [
      "image_quality_source",
      "replacement_image_quality_source",
      "replacement_product_quality_source",
      "replacement_quality_source",
      ["replacement_activity_context", "image_quality_source"],
      ["replacement_activity_context", "product_quality_source"],
      ["replacement_activity_context", "quality_source"],
      ["replacement_activity_context", "quality", "source"],
      "source_image_quality_source",
      "source_product_quality_source",
      "source_quality_source",
      ["source_activity_context", "image_quality_source"],
      ["source_activity_context", "product_quality_source"],
      ["source_activity_context", "quality_source"],
      ["source_activity_context", "quality", "source"]
    ])
  end

  defp timeline_diff_changed_source_observation_success_factor(row) do
    case timeline_diff_first_number(row, [
           "source_observation_success_factor",
           ["source_activity_context", "observation_success_factor"]
         ]) do
      factor when is_number(factor) and factor < 1.0 -> factor |> max(0.0) |> min(1.0)
      _factor -> nil
    end
  end

  defp timeline_diff_changed_observation_result_factor(row) do
    cond do
      false in [
        row["observation_success"],
        row["replacement_observation_success"],
        get_in(row, ["replacement_activity_context", "observation_success"]),
        get_in(row, ["source_activity_context", "observation_success"])
      ] ->
        0.0

      timeline_diff_failure_token?(
        row["observation_result"] ||
          row["replacement_observation_result"] ||
          get_in(row, ["replacement_activity_context", "observation_result"]) ||
            get_in(row, ["source_activity_context", "observation_result"])
      ) ->
        0.0

      timeline_diff_failure_token?(
        row["replacement_status"] ||
          get_in(row, ["replacement_activity_context", "status"]) ||
            get_in(row, ["replacement_activity_context", "realized_status"])
      ) ->
        0.0

      true ->
        nil
    end
  end

  defp timeline_diff_removed_observation_required_revisits(row) do
    numeric_value(
      row["source_required_revisits"] ||
        row["source_required_observations"] ||
        get_in(row, ["source_activity_context", "required_revisits"]) ||
        get_in(row, ["source_activity_context", "required_observations"])
    ) || 1.0
  end

  defp timeline_diff_removed_observation_objective(path, row) do
    target_id = timeline_diff_removed_observation_target_id(row)
    required_revisits = max(timeline_diff_removed_observation_required_revisits(row), 1.0)

    %{
      "id" =>
        "timeline_diff:target_revisit:#{target_id}:#{timeline_diff_objective_suffix(path, row)}",
      "type" => "target_revisit",
      "target_id" => target_id,
      "scenario_id" => stable_id_or_nil(row["scenario_id"]),
      "spacecraft_id" =>
        stable_id_or_nil(
          row["source_spacecraft_id"] ||
            get_in(row, ["source_activity_context", "spacecraft_id"])
        ),
      "required_revisits" => required_revisits,
      "source" => "timeline_diff_report.rows",
      "source_path" => path,
      "source_diff_status" => timeline_diff_status(row),
      "source_timeline_id" => stable_id_or_nil(row["timeline_id"]),
      "source_activity_id" => stable_id_or_nil(row["source_activity_id"]),
      "source_activity_type" => row["source_activity_type"],
      "source_required_operator_action" => row["required_operator_action"],
      "source_reason" => row["reason"],
      "source_starts_at_s" => numeric_value(row["source_starts_at_s"]),
      "source_ends_at_s" => numeric_value(row["source_ends_at_s"])
    }
    |> compact_map()
  end

  defp timeline_diff_changed_observation_objective(path, row) do
    target_id = timeline_diff_changed_observation_target_id(row)
    success_factor = timeline_diff_changed_observation_success_factor(row)

    %{
      "id" =>
        "timeline_diff:target_revisit:#{target_id}:#{timeline_diff_objective_suffix(path, row)}",
      "type" => "target_revisit",
      "target_id" => target_id,
      "scenario_id" => stable_id_or_nil(row["scenario_id"]),
      "spacecraft_id" =>
        stable_id_or_nil(
          row["replacement_spacecraft_id"] ||
            row["source_spacecraft_id"] ||
            get_in(row, ["replacement_activity_context", "spacecraft_id"]) ||
            get_in(row, ["source_activity_context", "spacecraft_id"])
        ),
      "required_revisits" => 1.0,
      "source" => "timeline_diff_report.rows",
      "source_path" => path,
      "source_diff_status" => timeline_diff_status(row),
      "source_timeline_id" => stable_id_or_nil(row["timeline_id"]),
      "source_activity_id" => stable_id_or_nil(row["source_activity_id"]),
      "replacement_activity_id" => stable_id_or_nil(row["replacement_activity_id"]),
      "source_activity_type" => row["source_activity_type"],
      "replacement_activity_type" => row["replacement_activity_type"],
      "source_required_operator_action" => row["required_operator_action"],
      "source_reason" => row["reason"],
      "source_changed_fields" => timeline_diff_changed_fields(row),
      "observation_success_factor" => success_factor,
      "source_starts_at_s" => numeric_value(row["source_starts_at_s"]),
      "source_ends_at_s" => numeric_value(row["source_ends_at_s"]),
      "replacement_starts_at_s" => numeric_value(row["replacement_starts_at_s"]),
      "replacement_ends_at_s" => numeric_value(row["replacement_ends_at_s"])
    }
    |> compact_map()
  end

  defp timeline_diff_objective_suffix(path, row) do
    :crypto.hash(
      :sha256,
      :erlang.term_to_binary({
        path,
        row["timeline_id"],
        row["source_activity_id"],
        row["replacement_activity_id"],
        row["source_target_id"],
        row["replacement_target_id"],
        row["source_activity_context"],
        row["replacement_activity_context"]
      })
    )
    |> Base.encode16(case: :lower)
    |> binary_part(0, 8)
  end

  defp timeline_diff_removed_downlink_feedback_row?(%{} = row) do
    timeline_diff_status(row) == "removed" and
      timeline_diff_removed_downlink_activity?(row) and
      timeline_diff_removed_downlink_station_id(row) not in [nil, ""] and
      positive_number_value?(timeline_diff_removed_downlink_required_mb(row))
  end

  defp timeline_diff_changed_downlink_shortfall_feedback_row?(%{} = row) do
    timeline_diff_status(row) == "changed" and
      timeline_diff_downlink_activity?(row) and
      timeline_diff_changed_downlink_station_id(row) not in [nil, ""] and
      positive_number_value?(timeline_diff_changed_downlink_shortfall_mb(row))
  end

  defp timeline_diff_changed_contact_feedback_row?(%{} = row) do
    timeline_diff_status(row) == "changed" and
      timeline_diff_contact_activity?(row) and
      timeline_diff_changed_contact_station_id(row) not in [nil, ""] and
      is_number(timeline_diff_changed_contact_success_factor(row))
  end

  defp timeline_diff_changed_command_feedback_row?(%{} = row) do
    timeline_diff_status(row) == "changed" and
      timeline_diff_command_activity?(row) and
      timeline_diff_changed_command_key(row) not in [nil, ""] and
      is_number(timeline_diff_changed_command_success_factor(row))
  end

  defp timeline_diff_changed_maneuver_feedback_row?(%{} = row) do
    timeline_diff_status(row) == "changed" and
      timeline_diff_maneuver_activity?(row) and
      timeline_diff_changed_maneuver_key(row) not in [nil, ""] and
      is_number(timeline_diff_changed_maneuver_success_factor(row))
  end

  defp timeline_diff_removed_downlink_activity?(row) do
    timeline_diff_downlink_activity?(row, "source")
  end

  defp timeline_diff_downlink_activity?(row) do
    timeline_diff_downlink_activity?(row, "source") or
      timeline_diff_downlink_activity?(row, "replacement")
  end

  defp timeline_diff_downlink_activity?(row, side) do
    activity_type =
      row["#{side}_activity_type"] ||
        get_in(row, ["#{side}_activity_context", "activity_type"]) ||
        get_in(row, ["#{side}_activity_context", "type"])

    direction = row["#{side}_direction"] || get_in(row, ["#{side}_activity_context", "direction"])

    activity_type = normalized_timeline_diff_token(activity_type)

    activity_type in ["downlink", "planned_contact", "contact"] or
      normalize_direction(direction) == "downlink"
  end

  defp timeline_diff_contact_activity?(row) do
    timeline_diff_contact_activity?(row, "source") or
      timeline_diff_contact_activity?(row, "replacement")
  end

  defp timeline_diff_contact_activity?(row, side) do
    activity_type =
      row["#{side}_activity_type"] ||
        get_in(row, ["#{side}_activity_context", "activity_type"]) ||
        get_in(row, ["#{side}_activity_context", "type"])

    direction = row["#{side}_direction"] || get_in(row, ["#{side}_activity_context", "direction"])

    activity_type = normalized_timeline_diff_token(activity_type)
    direction = normalize_direction(direction)

    activity_type in ["downlink", "planned_contact", "contact", "tracking"] or
      direction in ["downlink", "uplink", "tracking"]
  end

  defp timeline_diff_command_activity?(row) do
    timeline_diff_command_activity?(row, "source") or
      timeline_diff_command_activity?(row, "replacement")
  end

  defp timeline_diff_command_activity?(row, side) do
    activity_type =
      row["#{side}_activity_type"] ||
        get_in(row, ["#{side}_activity_context", "activity_type"]) ||
        get_in(row, ["#{side}_activity_context", "type"])

    direction = row["#{side}_direction"] || get_in(row, ["#{side}_activity_context", "direction"])

    activity_type = normalized_timeline_diff_token(activity_type)
    direction = normalize_direction(direction)

    activity_type in ["command", "health_check"] or
      direction in ["command", "uplink", "health_check"]
  end

  defp timeline_diff_maneuver_activity?(row) do
    timeline_diff_maneuver_activity?(row, "source") or
      timeline_diff_maneuver_activity?(row, "replacement")
  end

  defp timeline_diff_maneuver_activity?(row, side) do
    activity_type =
      row["#{side}_activity_type"] ||
        get_in(row, ["#{side}_activity_context", "activity_type"]) ||
        get_in(row, ["#{side}_activity_context", "type"])

    activity_type =
      activity_type
      |> normalized_timeline_diff_token()

    activity_type in [
      "maneuver",
      "impulsive_burn",
      "burn",
      "stationkeeping_burn",
      "station_keeping_burn",
      "delta_v",
      "orbit_adjust",
      "orbit_adjustment"
    ]
  end

  defp timeline_diff_removed_downlink_station_id(row) do
    stable_id_or_nil(
      row["source_ground_station_id"] ||
        get_in(row, ["source_activity_context", "ground_station_id"]) ||
        get_in(row, ["source_activity_context", "timeline_identity", "subject_id"])
    )
  end

  defp timeline_diff_removed_downlink_required_mb(row) do
    numeric_value(
      row["source_required_downlink_mb"] ||
        get_in(row, ["source_activity_context", "required_downlink_mb"])
    )
  end

  defp timeline_diff_changed_downlink_station_id(row) do
    stable_id_or_nil(
      row["replacement_ground_station_id"] ||
        row["source_ground_station_id"] ||
        get_in(row, ["replacement_activity_context", "ground_station_id"]) ||
        get_in(row, ["source_activity_context", "ground_station_id"]) ||
        get_in(row, ["replacement_activity_context", "station_id"]) ||
        get_in(row, ["source_activity_context", "station_id"]) ||
        get_in(row, ["replacement_activity_context", "timeline_identity", "subject_id"]) ||
        get_in(row, ["source_activity_context", "timeline_identity", "subject_id"])
    )
  end

  defp timeline_diff_changed_contact_station_id(row) do
    stable_id_or_nil(
      row["replacement_ground_station_id"] ||
        row["source_ground_station_id"] ||
        get_in(row, ["replacement_activity_context", "ground_station_id"]) ||
        get_in(row, ["source_activity_context", "ground_station_id"]) ||
        get_in(row, ["replacement_activity_context", "station_id"]) ||
        get_in(row, ["source_activity_context", "station_id"]) ||
        get_in(row, ["replacement_activity_context", "timeline_identity", "subject_id"]) ||
        get_in(row, ["source_activity_context", "timeline_identity", "subject_id"])
    )
  end

  defp timeline_diff_changed_contact_success_factor(row) do
    case timeline_diff_first_number(row, [
           "contact_success_factor",
           "replacement_contact_success_factor",
           ["replacement_activity_context", "contact_success_factor"]
         ]) do
      factor when is_number(factor) ->
        factor |> max(0.0) |> min(1.0)

      _factor ->
        timeline_diff_changed_contact_result_factor(row) ||
          timeline_diff_changed_source_contact_success_factor(row)
    end
  end

  defp timeline_diff_changed_command_key(row) do
    stable_id_or_nil(
      row["replacement_command_window_id"] ||
        row["source_command_window_id"] ||
        get_in(row, ["replacement_activity_context", "command_window_id"]) ||
        get_in(row, ["source_activity_context", "command_window_id"]) ||
        row["replacement_activity_id"] ||
        row["source_activity_id"] ||
        get_in(row, ["replacement_activity_context", "id"]) ||
        get_in(row, ["source_activity_context", "id"]) ||
        row["timeline_id"]
    )
  end

  defp timeline_diff_changed_command_success_factor(row) do
    case timeline_diff_first_number(row, [
           "command_success_factor",
           "replacement_command_success_factor",
           ["replacement_activity_context", "command_success_factor"]
         ]) do
      factor when is_number(factor) ->
        factor |> max(0.0) |> min(1.0)

      _factor ->
        timeline_diff_changed_command_result_factor(row) ||
          timeline_diff_changed_source_command_success_factor(row)
    end
  end

  defp timeline_diff_changed_maneuver_key(row) do
    stable_id_or_nil(
      row["replacement_maneuver_id"] ||
        row["source_maneuver_id"] ||
        get_in(row, ["replacement_activity_context", "maneuver_id"]) ||
        get_in(row, ["source_activity_context", "maneuver_id"]) ||
        get_in(row, ["replacement_timeline_identity", "subject_id"]) ||
        get_in(row, ["source_timeline_identity", "subject_id"]) ||
        get_in(row, ["replacement_activity_context", "timeline_identity", "subject_id"]) ||
        get_in(row, ["source_activity_context", "timeline_identity", "subject_id"]) ||
        row["replacement_activity_id"] ||
        row["source_activity_id"] ||
        get_in(row, ["replacement_activity_context", "id"]) ||
        get_in(row, ["source_activity_context", "id"]) ||
        row["timeline_id"]
    )
  end

  defp timeline_diff_changed_maneuver_success_factor(row) do
    case timeline_diff_first_number(row, [
           "maneuver_success_factor",
           "replacement_maneuver_success_factor",
           ["replacement_activity_context", "maneuver_success_factor"]
         ]) do
      factor when is_number(factor) ->
        factor |> max(0.0) |> min(1.0)

      _factor ->
        timeline_diff_changed_maneuver_result_factor(row) ||
          timeline_diff_changed_source_maneuver_success_factor(row)
    end
  end

  defp timeline_diff_changed_source_maneuver_success_factor(row) do
    case timeline_diff_first_number(row, [
           "source_maneuver_success_factor",
           ["source_activity_context", "maneuver_success_factor"]
         ]) do
      factor when is_number(factor) and factor < 1.0 -> factor |> max(0.0) |> min(1.0)
      _factor -> nil
    end
  end

  defp timeline_diff_changed_maneuver_result_factor(row) do
    cond do
      false in [
        row["maneuver_success"],
        row["replacement_maneuver_success"],
        get_in(row, ["replacement_activity_context", "maneuver_success"]),
        get_in(row, ["source_activity_context", "maneuver_success"])
      ] ->
        0.0

      timeline_diff_failure_token?(
        row["maneuver_result"] ||
          row["replacement_maneuver_result"] ||
          get_in(row, ["replacement_activity_context", "maneuver_result"]) ||
            get_in(row, ["source_activity_context", "maneuver_result"])
      ) ->
        0.0

      timeline_diff_failure_token?(
        row["replacement_status"] ||
          get_in(row, ["replacement_activity_context", "status"]) ||
            get_in(row, ["replacement_activity_context", "realized_status"])
      ) ->
        0.0

      true ->
        nil
    end
  end

  defp timeline_diff_changed_source_command_success_factor(row) do
    case timeline_diff_first_number(row, [
           "source_command_success_factor",
           ["source_activity_context", "command_success_factor"]
         ]) do
      factor when is_number(factor) and factor < 1.0 -> factor |> max(0.0) |> min(1.0)
      _factor -> nil
    end
  end

  defp timeline_diff_changed_command_result_factor(row) do
    cond do
      false in [
        row["command_success"],
        row["replacement_command_success"],
        get_in(row, ["replacement_activity_context", "command_success"]),
        get_in(row, ["source_activity_context", "command_success"])
      ] ->
        0.0

      timeline_diff_failure_token?(
        row["command_result"] ||
          row["replacement_command_result"] ||
          get_in(row, ["replacement_activity_context", "command_result"]) ||
            get_in(row, ["source_activity_context", "command_result"])
      ) ->
        0.0

      timeline_diff_failure_token?(
        row["replacement_status"] ||
          get_in(row, ["replacement_activity_context", "status"]) ||
            get_in(row, ["replacement_activity_context", "realized_status"])
      ) ->
        0.0

      true ->
        nil
    end
  end

  defp timeline_diff_changed_source_contact_success_factor(row) do
    case timeline_diff_first_number(row, [
           "source_contact_success_factor",
           ["source_activity_context", "contact_success_factor"]
         ]) do
      factor when is_number(factor) and factor < 1.0 -> factor |> max(0.0) |> min(1.0)
      _factor -> nil
    end
  end

  defp timeline_diff_changed_contact_result_factor(row) do
    cond do
      false in [
        row["contact_success"],
        row["replacement_contact_success"],
        get_in(row, ["replacement_activity_context", "contact_success"]),
        get_in(row, ["source_activity_context", "contact_success"])
      ] ->
        0.0

      timeline_diff_failure_token?(
        row["contact_result"] ||
          row["replacement_contact_result"] ||
          get_in(row, ["replacement_activity_context", "contact_result"]) ||
            get_in(row, ["source_activity_context", "contact_result"])
      ) ->
        0.0

      timeline_diff_failure_token?(
        row["replacement_status"] ||
          get_in(row, ["replacement_activity_context", "status"]) ||
            get_in(row, ["replacement_activity_context", "realized_status"])
      ) ->
        0.0

      true ->
        nil
    end
  end

  defp timeline_diff_failure_token?(value) do
    value
    |> normalized_timeline_diff_token()
    |> case do
      token
      when token in [
             "failed",
             "failure",
             "contact_failed",
             "link_failed",
             "no_contact",
             "missed",
             "lost",
             "dropped",
             "timeout",
             "timed_out",
             "aborted",
             "incomplete",
             "unsuccessful"
           ] ->
        true

      _token ->
        false
    end
  end

  defp timeline_diff_changed_downlink_shortfall_mb(row) do
    timeline_diff_first_positive_number(row, [
      "selected_downlink_shortfall_mb",
      "downlink_shortfall_mb",
      "data_volume_shortfall_mb",
      "selected_data_volume_shortfall_mb",
      "missing_data_volume_mb",
      "required_data_volume_gap_mb",
      "replacement_selected_downlink_shortfall_mb",
      "source_selected_downlink_shortfall_mb",
      ["replacement_activity_context", "selected_downlink_shortfall_mb"],
      ["source_activity_context", "selected_downlink_shortfall_mb"],
      ["replacement_activity_context", "downlink_shortfall_mb"],
      ["source_activity_context", "downlink_shortfall_mb"],
      ["replacement_activity_context", "data_volume_shortfall_mb"],
      ["source_activity_context", "data_volume_shortfall_mb"],
      ["replacement_activity_context", "selected_data_volume_shortfall_mb"],
      ["source_activity_context", "selected_data_volume_shortfall_mb"],
      ["replacement_activity_context", "missing_data_volume_mb"],
      ["source_activity_context", "missing_data_volume_mb"],
      ["replacement_activity_context", "required_data_volume_gap_mb"],
      ["source_activity_context", "required_data_volume_gap_mb"],
      ["throughput_model", "selected_downlink_shortfall_mb"],
      ["throughput_model", "data_volume_shortfall_mb"],
      ["replacement_activity_context", "throughput_model", "selected_downlink_shortfall_mb"],
      ["source_activity_context", "throughput_model", "selected_downlink_shortfall_mb"]
    ]) ||
      timeline_diff_required_vs_planned_downlink_shortfall(row)
  end

  defp timeline_diff_required_vs_planned_downlink_shortfall(row) do
    required_mb =
      timeline_diff_first_positive_number(row, [
        "required_downlink_mb",
        "source_required_downlink_mb",
        "replacement_required_downlink_mb",
        "required_data_volume_mb",
        "source_required_data_volume_mb",
        "replacement_required_data_volume_mb",
        "target_downlink_mb",
        "target_data_volume_mb",
        "min_downlink_mb",
        ["replacement_activity_context", "required_downlink_mb"],
        ["source_activity_context", "required_downlink_mb"],
        ["replacement_activity_context", "required_data_volume_mb"],
        ["source_activity_context", "required_data_volume_mb"],
        ["replacement_activity_context", "target_downlink_mb"],
        ["source_activity_context", "target_downlink_mb"],
        ["replacement_activity_context", "target_data_volume_mb"],
        ["source_activity_context", "target_data_volume_mb"],
        ["replacement_activity_context", "min_downlink_mb"],
        ["source_activity_context", "min_downlink_mb"]
      ])

    planned_mb =
      timeline_diff_first_number(row, [
        "planned_downlink_mb",
        "selected_downlink_mb",
        "candidate_downlink_mb",
        "estimated_downlink_mb",
        "planned_data_volume_mb",
        "selected_data_volume_mb",
        "replacement_planned_downlink_mb",
        "replacement_selected_downlink_mb",
        "replacement_candidate_downlink_mb",
        "replacement_estimated_downlink_mb",
        "source_planned_downlink_mb",
        "source_selected_downlink_mb",
        "source_candidate_downlink_mb",
        "source_estimated_downlink_mb",
        ["replacement_activity_context", "planned_downlink_mb"],
        ["replacement_activity_context", "selected_downlink_mb"],
        ["replacement_activity_context", "candidate_downlink_mb"],
        ["replacement_activity_context", "estimated_downlink_mb"],
        ["replacement_activity_context", "planned_data_volume_mb"],
        ["replacement_activity_context", "selected_data_volume_mb"],
        ["source_activity_context", "planned_downlink_mb"],
        ["source_activity_context", "selected_downlink_mb"],
        ["source_activity_context", "candidate_downlink_mb"],
        ["source_activity_context", "estimated_downlink_mb"],
        ["source_activity_context", "planned_data_volume_mb"],
        ["source_activity_context", "selected_data_volume_mb"],
        ["throughput_model", "estimated_downlink_mb"],
        ["throughput_model", "candidate_downlink_mb"],
        ["throughput_model", "selected_downlink_mb"],
        ["replacement_activity_context", "throughput_model", "estimated_downlink_mb"],
        ["replacement_activity_context", "throughput_model", "candidate_downlink_mb"],
        ["replacement_activity_context", "throughput_model", "selected_downlink_mb"],
        ["source_activity_context", "throughput_model", "estimated_downlink_mb"],
        ["source_activity_context", "throughput_model", "candidate_downlink_mb"],
        ["source_activity_context", "throughput_model", "selected_downlink_mb"]
      ])

    case {required_mb, planned_mb} do
      {required_mb, planned_mb} when is_number(required_mb) and is_number(planned_mb) ->
        max(required_mb - max(planned_mb, 0.0), 0.0)

      _values ->
        nil
    end
  end

  defp timeline_diff_first_positive_number(row, paths) do
    paths
    |> Enum.find_value(fn path ->
      case timeline_diff_number(row, path) do
        value when is_number(value) and value > 0.0 -> value
        _value -> nil
      end
    end)
  end

  defp timeline_diff_first_number(row, paths) do
    paths
    |> Enum.find_value(fn path ->
      case timeline_diff_number(row, path) do
        value when is_number(value) -> value
        _value -> nil
      end
    end)
  end

  defp timeline_diff_number(row, path) when is_list(path),
    do: row |> get_in(path) |> numeric_value()

  defp timeline_diff_number(row, path), do: row |> Map.get(path) |> numeric_value()

  defp timeline_diff_first_string(row, paths) do
    paths
    |> Enum.find_value(fn path ->
      value =
        case path do
          path when is_list(path) -> get_in(row, path)
          path -> Map.get(row, path)
        end

      case feedback_source_string(value) do
        value when is_binary(value) and value != "" -> value
        _value -> nil
      end
    end)
  end

  defp unit_interval_or_nil(value) when is_number(value) and value >= 0.0 and value <= 1.0,
    do: value * 1.0

  defp unit_interval_or_nil(_value), do: nil

  defp merge_timeline_diff_removed_downlink_feedback(row, feedback) do
    station_id = timeline_diff_removed_downlink_station_id(row)
    required_mb = timeline_diff_removed_downlink_required_mb(row)
    source = timeline_diff_removed_downlink_source(row)
    context = timeline_diff_removed_downlink_context(row)

    feedback
    |> update_in(["downlink_demand_mb"], fn values ->
      values
      |> ensure_map()
      |> Map.update(station_id, required_mb, &(&1 + required_mb))
    end)
    |> update_in(["downlink_demand_sources"], fn values ->
      values
      |> ensure_map()
      |> Map.update(station_id, [source], fn existing ->
        (List.wrap(existing) ++ [source])
        |> Enum.uniq()
        |> Enum.sort()
      end)
    end)
    |> update_in(["downlink_demand_context"], fn values ->
      values
      |> ensure_map()
      |> Map.update(station_id, context, &merge_downlink_demand_context(&1, context))
    end)
  end

  defp merge_timeline_diff_changed_downlink_shortfall_feedback(row, feedback) do
    station_id = timeline_diff_changed_downlink_station_id(row)
    shortfall_mb = timeline_diff_changed_downlink_shortfall_mb(row)
    source = timeline_diff_changed_downlink_shortfall_source(row)
    context = timeline_diff_changed_downlink_shortfall_context(row)

    feedback
    |> update_in(["downlink_demand_mb"], fn values ->
      values
      |> ensure_map()
      |> Map.update(station_id, shortfall_mb, &(&1 + shortfall_mb))
    end)
    |> update_in(["downlink_demand_sources"], fn values ->
      values
      |> ensure_map()
      |> Map.update(station_id, [source], fn existing ->
        (List.wrap(existing) ++ [source])
        |> Enum.uniq()
        |> Enum.sort()
      end)
    end)
    |> update_in(["downlink_demand_context"], fn values ->
      values
      |> ensure_map()
      |> Map.update(station_id, context, &merge_downlink_demand_context(&1, context))
    end)
  end

  defp merge_timeline_diff_changed_contact_feedback(row, feedback) do
    station_id = timeline_diff_changed_contact_station_id(row)
    factor = timeline_diff_changed_contact_success_factor(row)

    update_in(feedback, ["contact_success_rate"], fn values ->
      values
      |> ensure_map()
      |> Map.update(station_id, factor, &min(&1, factor))
    end)
  end

  defp merge_timeline_diff_changed_observation_quality_feedback(row, feedback) do
    target_id = timeline_diff_changed_observation_target_id(row)

    feedback
    |> put_timeline_diff_quality_number(
      "image_quality_score",
      target_id,
      timeline_diff_changed_observation_image_quality_score(row),
      :min
    )
    |> put_timeline_diff_quality_number(
      "cloud_cover_fraction",
      target_id,
      timeline_diff_changed_observation_cloud_cover_fraction(row),
      :max
    )
    |> put_timeline_diff_quality_number(
      "blur_score",
      target_id,
      timeline_diff_changed_observation_blur_score(row),
      :max
    )
    |> put_timeline_diff_quality_string(
      "image_quality_status",
      target_id,
      timeline_diff_changed_observation_image_quality_status(row)
    )
    |> put_timeline_diff_quality_string(
      "image_quality_source",
      target_id,
      timeline_diff_changed_observation_image_quality_source(row)
    )
  end

  defp put_timeline_diff_quality_number(feedback, _field, _target_id, nil, _merge_mode),
    do: feedback

  defp put_timeline_diff_quality_number(feedback, field, target_id, value, :min) do
    update_in(feedback, [field], fn values ->
      values
      |> ensure_map()
      |> Map.update(target_id, value, &min(&1, value))
    end)
  end

  defp put_timeline_diff_quality_number(feedback, field, target_id, value, :max) do
    update_in(feedback, [field], fn values ->
      values
      |> ensure_map()
      |> Map.update(target_id, value, &max(&1, value))
    end)
  end

  defp put_timeline_diff_quality_string(feedback, _field, _target_id, nil), do: feedback

  defp put_timeline_diff_quality_string(feedback, field, target_id, value) do
    update_in(feedback, [field], fn values ->
      values
      |> ensure_map()
      |> Map.put(target_id, value)
    end)
  end

  defp merge_timeline_diff_changed_command_feedback(row, feedback) do
    command_key = timeline_diff_changed_command_key(row)
    factor = timeline_diff_changed_command_success_factor(row)

    update_in(feedback, ["command_success_rate"], fn values ->
      values
      |> ensure_map()
      |> Map.update(command_key, factor, &min(&1, factor))
    end)
  end

  defp merge_timeline_diff_changed_maneuver_feedback(row, feedback) do
    maneuver_key = timeline_diff_changed_maneuver_key(row)
    factor = timeline_diff_changed_maneuver_success_factor(row)

    update_in(feedback, ["maneuver_success_rate"], fn values ->
      values
      |> ensure_map()
      |> Map.update(maneuver_key, factor, &min(&1, factor))
    end)
  end

  defp timeline_diff_removed_downlink_source(row) do
    activity_id =
      stable_id_or_nil(row["source_activity_id"]) ||
        stable_id_or_nil(get_in(row, ["source_activity_context", "id"])) ||
        stable_id_or_nil(row["timeline_id"]) ||
        "removed_downlink"

    "timeline_diff.removed.required_downlink_mb:#{activity_id}"
  end

  defp timeline_diff_removed_downlink_context(row) do
    %{
      "source" => "timeline_diff_report.rows",
      "source_diff_status" => timeline_diff_status(row),
      "source_timeline_id" => row["timeline_id"],
      "source_activity_id" => row["source_activity_id"],
      "source_activity_type" => row["source_activity_type"],
      "source_required_operator_action" => row["required_operator_action"],
