  defp timeline_diff_changed_downlink_shortfall_source(row) do
    source_activity_id =
      stable_id_or_nil(row["source_activity_id"]) ||
        stable_id_or_nil(get_in(row, ["source_activity_context", "id"])) ||
        stable_id_or_nil(row["timeline_id"]) ||
