    replacement_activity_id =
      stable_id_or_nil(row["replacement_activity_id"]) ||
        stable_id_or_nil(get_in(row, ["replacement_activity_context", "id"])) ||
        "replacement"

    "timeline_diff.changed.downlink_shortfall_mb:#{source_activity_id}:#{replacement_activity_id}"
  end

