  defp timeline_diff_status(row), do: normalized_timeline_diff_token(row["diff_status"])

  defp normalized_timeline_diff_token(value) do
    value
    |> encode_value()
    |> case do
      nil ->
        nil

      value ->
        value
        |> String.trim()
        |> String.downcase()
        |> String.replace(~r/[\s-]+/, "_")
        |> String.trim("_")
    end
  end

