  defp sum_source_count(sources, key) do
    sources
    |> Enum.map(&(numeric_value(Map.get(&1, key)) || 0))
    |> Enum.sum()
    |> case do
      0 -> nil
      value -> value
    end
  end

  defp merge_source_count_maps(sources, key) do
    sources
    |> Enum.map(&Map.get(&1, key))
    |> Enum.filter(&is_map/1)
    |> Enum.reduce(%{}, fn counts, merged ->
      Enum.reduce(counts, merged, fn {count_key, count_value}, merged ->
        Map.update(merged, count_key, numeric_value(count_value) || 0, fn existing ->
          existing + (numeric_value(count_value) || 0)
        end)
      end)
    end)
    |> case do
      counts when map_size(counts) == 0 -> nil
      counts -> counts
    end
  end

  defp normalize_explicit_operational_feedback(feedback) when is_map(feedback) do
    %{
      "contact_success_rate" =>
        normalize_feedback_factor_map(Map.get(feedback, "contact_success_rate", %{})),
      "observation_success_rate" =>
        normalize_feedback_factor_map(Map.get(feedback, "observation_success_rate", %{})),
      "image_quality_score" =>
        normalize_feedback_factor_map(Map.get(feedback, "image_quality_score", %{})),
      "image_quality_status" =>
        normalize_string_map(Map.get(feedback, "image_quality_status", %{})),
      "image_quality_source" =>
        normalize_string_map(Map.get(feedback, "image_quality_source", %{})),
      "cloud_cover_fraction" =>
        normalize_feedback_factor_map(Map.get(feedback, "cloud_cover_fraction", %{})),
      "blur_score" => normalize_feedback_factor_map(Map.get(feedback, "blur_score", %{})),
      "maneuver_success_rate" =>
        normalize_feedback_factor_map(Map.get(feedback, "maneuver_success_rate", %{})),
      "maneuver_execution_uncertainty" =>
        normalize_maneuver_execution_uncertainty_feedback_map(
          Map.get(feedback, "maneuver_execution_uncertainty", %{})
        ),
      "command_success_rate" =>
        normalize_feedback_factor_map(Map.get(feedback, "command_success_rate", %{})),
      "station_throughput_factor" =>
        normalize_feedback_factor_map(Map.get(feedback, "station_throughput_factor", %{})),
      "downlink_demand_mb" =>
        normalize_nonnegative_number_map(Map.get(feedback, "downlink_demand_mb", %{})),
      "downlink_demand_sources" =>
        normalize_string_list_map(Map.get(feedback, "downlink_demand_sources", %{})),
      "downlink_demand_context" =>
        normalize_object_map(Map.get(feedback, "downlink_demand_context", %{})),
      "target_priority_overrides" =>
        normalize_nonnegative_number_map(Map.get(feedback, "target_priority_overrides", %{})),
      "resource_margin_overrides" =>
        normalize_resource_margin_feedback_map(
          Map.get(feedback, "resource_margin_overrides", %{})
        ),
      "resource_availability_overrides" =>
        feedback
        |> availability_override_feedback()
        |> normalize_resource_availability_feedback_map(),
      "trust_boundary" => Map.get(feedback, "trust_boundary"),
      "provenance" => Map.get(feedback, "provenance")
    }
    |> compact_operational_feedback()
  end

  defp realized_activity_operational_feedback(feedback, refresh) do
    case realized_activity_operational_feedback_report(feedback, refresh) do
      %{} = report -> TimelineFeedback.operational_feedback(report)
      _report -> %{}
    end
  end

  defp realized_activity_operational_feedback_report(feedback, refresh) do
    case Map.get(feedback, "realized_activities") do
      rows when is_list(rows) and rows != [] ->
        realized_activity_operational_feedback_report_for_rows(rows, refresh)

      _rows ->
        nil
    end
  end

  defp realized_activity_operational_feedback_report_for_rows([], _refresh), do: nil

  defp realized_activity_operational_feedback_report_for_rows(rows, refresh) when is_list(rows) do
    realized_rows = sanitize_realized_activity_operational_feedback_rows(rows)

    refresh
    |> prior_candidate_activities()
    |> Enum.reject(&invalid_prior_candidate_input?/1)
    |> TimelineFeedback.reconcile(realized_rows)
  end

  defp realized_activity_operational_feedback_source(%{
         "operational_feedback_provenance" => %{"sources" => sources}
       })
       when is_list(sources) do
    Enum.find(sources, &(&1["source"] == "timeline_feedback_report.rows")) || %{}
  end

  defp realized_activity_operational_feedback_source(_report), do: %{}

  defp merge_operational_feedback(derived, explicit) do
    Map.merge(derived, explicit, fn _key, derived_value, explicit_value ->
      if is_map(derived_value) and is_map(explicit_value) do
        Map.merge(derived_value, explicit_value)
      else
        explicit_value
      end
    end)
  end

  defp compact_operational_feedback(feedback) do
    feedback
    |> Enum.reject(fn {_key, value} -> value in [nil, %{}, []] end)
    |> Map.new()
  end

  defp availability_override_feedback(feedback) do
    alias_overrides =
      case Map.get(feedback, "availability_overrides") do
        %{} = overrides -> overrides
        _other -> %{}
      end

    canonical_overrides =
      case Map.get(feedback, "resource_availability_overrides") do
        %{} = overrides -> overrides
        _other -> %{}
      end

    Map.merge(alias_overrides, canonical_overrides)
  end

  defp normalize_feedback_factor_map(%{} = factors) do
    factors
    |> stringify_keys()
    |> Enum.reduce(%{}, fn {key, value}, normalized ->
      case numeric_value(value) do
        number when is_number(number) and number >= 0.0 and number <= 1.0 ->
          put_operational_feedback_entry(normalized, key, number)

        _value ->
          normalized
      end
    end)
  end

  defp normalize_feedback_factor_map(_factors), do: %{}

  defp normalize_nonnegative_number_map(%{} = values) do
    values
    |> stringify_keys()
    |> Enum.reduce(%{}, fn {key, value}, normalized ->
      case numeric_value(value) do
        number when is_number(number) and number >= 0.0 ->
          put_operational_feedback_entry(normalized, key, number)

        _value ->
          normalized
      end
    end)
  end

  defp normalize_nonnegative_number_map(_values), do: %{}

  defp normalize_string_list_map(%{} = values) do
    values
    |> stringify_keys()
    |> Enum.reduce(%{}, fn {key, value}, normalized ->
      if operational_feedback_key?(key) and is_list(value) and
           Enum.all?(value, &valid_feedback_source_string?/1) do
        sources =
          value
          |> Enum.map(&feedback_source_string/1)
          |> Enum.reject(&is_nil/1)
          |> Enum.uniq()
          |> Enum.sort()

        if sources == [] do
          normalized
        else
          put_operational_feedback_entry(normalized, key, sources)
        end
      else
        normalized
      end
    end)
  end

  defp normalize_string_list_map(_values), do: %{}

  defp normalize_object_map(%{} = values) do
    values
    |> stringify_keys()
    |> Enum.reduce(%{}, fn {key, value}, normalized ->
      if operational_feedback_key?(key) and is_map(value) do
        put_operational_feedback_entry(
          normalized,
          key,
          value |> stringify_keys() |> compact_map()
        )
      else
        normalized
      end
    end)
  end

  defp normalize_object_map(_values), do: %{}

  defp normalize_string_map(%{} = values) do
    values
    |> stringify_keys()
    |> Enum.reduce(%{}, fn {key, value}, normalized ->
      case feedback_source_string(value) do
        value when is_binary(value) and value != "" ->
          put_operational_feedback_entry(normalized, key, value)

        _value ->
          normalized
      end
    end)
  end

  defp normalize_string_map(_values), do: %{}

  defp feedback_source_string(value) when is_binary(value) and value != "", do: value

  defp feedback_source_string(value) when is_atom(value) and not is_nil(value),
    do: Atom.to_string(value)

  defp feedback_source_string(_value), do: nil

  defp normalize_maneuver_execution_uncertainty_feedback_map(%{} = values) do
    values
    |> stringify_keys()
    |> Enum.reduce(%{}, fn
      {key, %{} = value}, normalized ->
        put_operational_feedback_entry(
          normalized,
          key,
          normalize_maneuver_execution_uncertainty_feedback(value)
        )

      {_key, _value}, normalized ->
        normalized
    end)
  end

  defp normalize_maneuver_execution_uncertainty_feedback_map(_values), do: %{}

  defp normalize_maneuver_execution_uncertainty_feedback(%{} = value) do
    value = stringify_keys(value)

    %{
      "execution_uncertainty_status" => Map.get(value, "execution_uncertainty_status"),
      "execution_uncertainty" => stringify_map_or_nil(Map.get(value, "execution_uncertainty")),
      "timing_3sigma_s" => numeric_or_nil(Map.get(value, "timing_3sigma_s")),
      "delta_v_3sigma_km_s" => numeric_triplet_or_nil(Map.get(value, "delta_v_3sigma_km_s")),
      "delta_v_3sigma_magnitude_km_s" =>
        numeric_or_nil(Map.get(value, "delta_v_3sigma_magnitude_km_s")),
      "execution_uncertainty_source" => Map.get(value, "execution_uncertainty_source")
    }
    |> compact_map()
  end

  defp stringify_map_or_nil(%{} = value), do: stringify_keys(value)
  defp stringify_map_or_nil(_value), do: nil

  defp numeric_or_nil(value), do: numeric_value(value)

  defp numeric_triplet_or_nil(values) when is_list(values) and length(values) == 3 do
    triplet = Enum.map(values, &numeric_or_nil/1)

    if Enum.all?(triplet, &is_number/1), do: triplet, else: nil
  end

  defp numeric_triplet_or_nil(_values), do: nil

  defp normalize_resource_margin_feedback_map(%{} = values) do
    values
    |> stringify_keys()
    |> Enum.reduce(%{}, fn
      {key, %{} = value}, normalized ->
        put_operational_feedback_entry(normalized, key, normalize_resource_margin_aliases(value))

      {_key, _value}, normalized ->
        normalized
    end)
  end

  defp normalize_resource_margin_feedback_map(_values), do: %{}

  defp normalize_resource_margin_aliases(%{} = value) do
    value
    |> stringify_keys()
    |> copy_resource_margin_alias("storage_margin", "storage_capacity_margin")
    |> copy_resource_margin_alias("downlink_margin", "downlink_capacity_margin")
    |> copy_resource_margin_alias("battery_state_of_charge", "battery_soc")
    |> put_power_margin_from_battery_state_of_charge()
    |> normalize_resource_margin_values()
  end

  defp copy_resource_margin_alias(value, canonical_key, alias_key) do
    value =
      if Map.has_key?(value, canonical_key) or not Map.has_key?(value, alias_key) do
        value
      else
        Map.put(value, canonical_key, Map.get(value, alias_key))
      end

    Map.delete(value, alias_key)
  end

  defp put_power_margin_from_battery_state_of_charge(value) do
    case {Map.get(value, "power_margin"),
          numeric_value(Map.get(value, "battery_state_of_charge"))} do
      {nil, state_of_charge} when is_number(state_of_charge) ->
        Map.put(value, "power_margin", state_of_charge)

      _values ->
        value
    end
  end

  defp normalize_resource_margin_values(value) do
    Enum.reduce(
      [
        "fuel_margin",
        "power_margin",
        "storage_margin",
        "downlink_margin",
        "thermal_margin_c",
        "battery_capacity_wh",
        "battery_energy_used_wh",
        "battery_state_of_charge"
      ],
      value,
      fn field, normalized ->
        case {Map.get(normalized, field), numeric_value(Map.get(normalized, field))} do
          {raw_value, number} when is_number(raw_value) and is_number(number) ->
            Map.put(normalized, field, number)

          {raw_value, number} when is_binary(raw_value) and is_number(number) ->
            Map.put(normalized, field, number)

          {raw_value, nil} when is_binary(raw_value) ->
            Map.delete(normalized, field)

          _value ->
            normalized
        end
      end
    )
  end

  defp normalize_resource_availability_feedback_map(%{} = values) do
    values
    |> stringify_keys()
    |> Enum.reduce(%{}, fn
      {key, %{} = value}, normalized ->
        put_operational_feedback_entry(
          normalized,
          key,
          normalize_resource_availability_aliases(value)
        )

      {_key, _value}, normalized ->
        normalized
    end)
  end

  defp normalize_resource_availability_feedback_map(_values), do: %{}

  defp put_operational_feedback_entry(map, key, value) do
    case stable_id_or_nil(key) do
      nil -> map
      key -> Map.put(map, key, value)
    end
  end

  defp operational_feedback_key?(key), do: not is_nil(stable_id_or_nil(key))

  defp normalize_resource_availability_aliases(%{} = value) do
    value
    |> stringify_keys()
    |> copy_resource_availability_aliases(@resource_availability_value_aliases)
    |> copy_boolean_resource_availability_aliases(@resource_availability_boolean_aliases)
    |> copy_resource_availability_status_aliases(@resource_availability_status_aliases)
    |> copy_resource_availability_alias("degraded", "degraded?")
    |> normalize_resource_availability_boolean_values()
  end

  defp normalize_resource_availability_boolean_values(value) do
    Enum.reduce(
      ["payload_available", "antenna_available", "spacecraft_available", "degraded"],
      value,
      fn field, normalized ->
        case resource_availability_boolean_value(Map.get(normalized, field)) do
          bool when is_boolean(bool) -> Map.put(normalized, field, bool)
          nil -> normalized
        end
      end
    )
  end

  defp copy_resource_availability_alias(value, canonical_key, alias_key) do
    value =
      if Map.has_key?(value, canonical_key) or not Map.has_key?(value, alias_key) do
        value
      else
        Map.put(value, canonical_key, Map.get(value, alias_key))
      end

    Map.delete(value, alias_key)
  end

  defp copy_resource_availability_aliases(value, aliases_by_field) do
    Enum.reduce(aliases_by_field, value, fn {canonical_key, aliases}, normalized ->
      Enum.reduce(aliases, normalized, fn alias_key, normalized ->
        copy_resource_availability_alias(normalized, canonical_key, alias_key)
      end)
    end)
  end

  defp copy_boolean_resource_availability_alias(value, canonical_key, alias_key) do
    alias_value = resource_availability_boolean_value(Map.get(value, alias_key))

    if Map.has_key?(value, canonical_key) or not is_boolean(alias_value) do
      value
    else
      value
      |> Map.put(canonical_key, alias_value)
      |> Map.delete(alias_key)
    end
  end

  defp copy_boolean_resource_availability_aliases(value, aliases_by_field) do
    Enum.reduce(aliases_by_field, value, fn {canonical_key, aliases}, normalized ->
      Enum.reduce(aliases, normalized, fn alias_key, normalized ->
        copy_boolean_resource_availability_alias(normalized, canonical_key, alias_key)
      end)
    end)
  end

  defp copy_resource_availability_status_alias(value, canonical_key, alias_key) do
    alias_value = resource_availability_boolean_value(Map.get(value, alias_key))

    if Map.has_key?(value, canonical_key) or not is_boolean(alias_value) do
      value
    else
      Map.put(value, canonical_key, alias_value)
    end
  end

  defp copy_resource_availability_status_aliases(value, aliases_by_field) do
    Enum.reduce(aliases_by_field, value, fn {canonical_key, aliases}, normalized ->
      Enum.reduce(aliases, normalized, fn alias_key, normalized ->
        copy_resource_availability_status_alias(normalized, canonical_key, alias_key)
      end)
    end)
  end

  defp resource_availability_boolean_value(value) when is_boolean(value), do: value

  defp resource_availability_boolean_value(value) when is_number(value) do
    cond do
      value == 1 -> true
      value == 0 -> false
      true -> nil
    end
  end

  defp resource_availability_boolean_value(value) when is_binary(value) do
    case String.downcase(String.trim(value)) do
      value when value in @resource_availability_true_tokens -> true
      value when value in @resource_availability_false_tokens -> false
      _value -> nil
    end
  end

  defp resource_availability_boolean_value(_value), do: nil

  defp maybe_put_invalid_operational_feedback_sections(provenance, []), do: provenance

  defp maybe_put_invalid_operational_feedback_sections(provenance, invalid_sections) do
    provenance
    |> Map.put(
      "input_keys",
      Enum.uniq(provenance["input_keys"] ++ ["invalid_operational_feedback_input"])
    )
    |> Map.put("invalid_operational_feedback_input", true)
    |> Map.put(
      "invalid_operational_feedback_input_reason",
      "operational_feedback_sections_invalid"
    )
    |> Map.put("invalid_operational_feedback_sections", invalid_sections)
    |> Map.put("source_operational_feedback", %{"invalid_feedback_sections" => invalid_sections})
  end

  defp invalid_operational_feedback_sections(refresh) do
    case raw_operational_feedback(refresh) |> stringify_keys() do
      %{} = feedback ->
        invalid_operational_feedback_sections_for(feedback)

      _feedback ->
        []
    end
  end

  defp invalid_operational_feedback_sections_for(feedback) do
    scalar_map_fields = [
      "contact_success_rate",
      "observation_success_rate",
      "maneuver_success_rate",
      "command_success_rate",
      "station_throughput_factor",
      "downlink_demand_mb",
      "target_priority_overrides",
      "image_quality_score",
      "cloud_cover_fraction",
      "blur_score"
    ]

    string_map_fields = ["image_quality_status", "image_quality_source"]

    string_list_map_fields = ["downlink_demand_sources"]

    nested_map_fields = [
      "maneuver_execution_uncertainty",
      "resource_margin_overrides",
      "resource_availability_overrides",
      "availability_overrides"
    ]

    array_fields = ["realized_activities"]

    map_fields =
      scalar_map_fields ++ string_map_fields ++ string_list_map_fields ++ nested_map_fields

    invalid_key_sections =
      map_fields
      |> Enum.flat_map(&invalid_operational_feedback_key_sections(feedback, &1))

    scalar_sections =
      scalar_map_fields
      |> Enum.flat_map(
        &invalid_operational_feedback_field_sections(feedback, &1, :number_entries)
      )

    string_list_sections =
      string_list_map_fields
      |> Enum.flat_map(&invalid_string_list_operational_feedback_sections(feedback, &1))

    string_map_sections =
      string_map_fields
      |> Enum.flat_map(&invalid_string_operational_feedback_sections(feedback, &1))

    nested_sections =
      nested_map_fields
      |> Enum.flat_map(&invalid_nested_operational_feedback_sections(feedback, &1))

    array_sections =
      array_fields
      |> Enum.flat_map(&invalid_array_operational_feedback_sections(feedback, &1))

    realized_activity_sections = invalid_realized_activity_operational_feedback_sections(feedback)

    (invalid_key_sections ++
       scalar_sections ++
       string_list_sections ++
       string_map_sections ++
       nested_sections ++
       array_sections ++
       realized_activity_sections)
    |> Enum.sort_by(&{&1["field"], Map.get(&1, "key", "")})
  end

  defp invalid_operational_feedback_key_sections(feedback, field) do
    case Map.get(feedback, field) do
      %{} = entries ->
        entries
        |> stringify_keys()
        |> Enum.flat_map(fn {key, _value} ->
          if operational_feedback_key?(key) do
            []
          else
            [
              %{
                "field" => field,
                "key" => invalid_operational_feedback_key_label(key),
                "reason" => "key_must_be_stable_id"
              }
            ]
          end
        end)

      _entries ->
        []
    end
  end

  defp invalid_operational_feedback_key_label(key) when is_binary(key), do: key
  defp invalid_operational_feedback_key_label(key), do: inspect(key)

  defp invalid_array_operational_feedback_sections(feedback, field) do
    if Map.has_key?(feedback, field) and not is_list(Map.get(feedback, field)) do
      [
        %{
          "field" => field,
          "reason" => "field_must_be_array",
          "invalid_feedback_shape" => encode_value(Map.get(feedback, field))
        }
      ]
    else
      []
    end
  end

  defp invalid_realized_activity_operational_feedback_sections(%{
         "realized_activities" => rows
       })
       when is_list(rows) do
    rows
    |> Enum.with_index(1)
    |> Enum.flat_map(fn {row, index} ->
      case stringify_keys(row) do
        %{} = row ->
          (invalid_realized_activity_operational_feedback_identity_sections(row) ++
             invalid_realized_activity_operational_feedback_unit_interval_sections(row) ++
             invalid_realized_activity_operational_feedback_nonnegative_number_sections(row))
          |> Enum.map(&Map.put(&1, "row_index", index))

        invalid_shape ->
          [
            %{
              "field" => "realized_activities",
              "reason" => "entry_must_be_object",
              "row_index" => index,
              "invalid_feedback_shape" => encode_value(invalid_shape)
            }
          ]
      end
    end)
  end

  defp invalid_realized_activity_operational_feedback_sections(_feedback), do: []

  defp sanitize_realized_activity_operational_feedback_rows(rows) do
    Enum.map(rows, &sanitize_realized_activity_operational_feedback_row/1)
  end

  defp sanitize_realized_activity_operational_feedback_row(%{} = row) do
    row = stringify_keys(row)

    realized_activity_operational_feedback_unit_interval_paths()
    |> Enum.reduce(row, fn {_field, path}, sanitized ->
      case unit_interval_number_status(get_in(sanitized, path)) do
        {:invalid_number, _number} -> delete_feedback_path(sanitized, path)
        {:invalid_shape, _shape} -> delete_feedback_path(sanitized, path)
        _status -> sanitized
      end
    end)
  end

  defp sanitize_realized_activity_operational_feedback_row(row), do: row

  defp delete_feedback_path(row, [field]), do: Map.delete(row, field)

  defp delete_feedback_path(row, [section, field]) do
    case Map.get(row, section) do
      %{} = section_map ->
        section_map = Map.delete(section_map, field)

        if map_size(section_map) == 0 do
          Map.delete(row, section)
        else
          Map.put(row, section, section_map)
        end

      _section ->
        row
    end
  end

  defp invalid_realized_activity_operational_feedback_identity_sections(row) do
    row
    |> realized_activity_operational_feedback_identity_values()
    |> Enum.flat_map(fn {field, value} ->
      case raw_feedback_identifier(value) do
        nil ->
          []

        identifier ->
          if stable_id_or_nil(identifier) do
            []
          else
            [
              %{
                "field" => "realized_activities.#{field}",
                "key" => identifier,
                "reason" => "key_must_be_stable_id",
                "row_id" => realized_activity_operational_feedback_row_id(row)
              }
              |> compact_map()
            ]
          end
      end
    end)
  end

  defp realized_activity_operational_feedback_identity_values(row) do
    [
      {"id", row["id"]},
      {"realized_activity_id", row["realized_activity_id"]},
      {"planned_activity_id", row["planned_activity_id"]},
      {"activity_id", row["activity_id"]},
      {"timeline_id", row["timeline_id"]},
      {"metadata.timeline_id", get_in(row, ["metadata", "timeline_id"])},
      {"scenario_id", row["scenario_id"]},
      {"metadata.scenario_id", get_in(row, ["metadata", "scenario_id"])},
      {"ground_station_id", row["ground_station_id"]},
      {"station_id", row["station_id"]},
      {"metadata.ground_station_id", get_in(row, ["metadata", "ground_station_id"])},
      {"metadata.station_id", get_in(row, ["metadata", "station_id"])},
      {"target_id", row["target_id"]},
      {"metadata.target_id", get_in(row, ["metadata", "target_id"])},
      {"spacecraft_id", row["spacecraft_id"]},
      {"satellite_id", row["satellite_id"]},
      {"metadata.spacecraft_id", get_in(row, ["metadata", "spacecraft_id"])},
      {"resource_id", row["resource_id"]},
      {"source_window_id", row["source_window_id"]},
      {"metadata.source_window_id", get_in(row, ["metadata", "source_window_id"])},
      {"target.id", nested_feedback_identifier(row, "target", ["target_id", "id"])},
      {"station.id", nested_feedback_identifier(row, "station", ["station_id", "id"])},
      {"ground_station.id",
       nested_feedback_identifier(row, "ground_station", ["ground_station_id", "station_id", "id"])},
      {"spacecraft.id", nested_feedback_identifier(row, "spacecraft", ["spacecraft_id", "id"])},
      {"satellite.id", nested_feedback_identifier(row, "satellite", ["satellite_id", "id"])},
      {"source_window.id",
       nested_feedback_identifier(row, "source_window", ["source_window_id", "id"])}
    ]
  end

  defp invalid_realized_activity_operational_feedback_unit_interval_sections(row) do
    row
    |> realized_activity_operational_feedback_unit_interval_values()
    |> Enum.flat_map(fn {field, value} ->
      case unit_interval_number_status(value) do
        {:ok, _value} ->
          []

        :missing ->
          []

        {:invalid_number, number} ->
          [
            %{
              "field" => "realized_activities.#{field}",
              "reason" => "entry_must_be_unit_interval_number",
              "invalid_feedback_shape" => number,
              "row_id" => realized_activity_operational_feedback_row_id(row)
            }
            |> compact_map()
          ]

        {:invalid_shape, shape} ->
          [
            %{
              "field" => "realized_activities.#{field}",
              "reason" => "entry_must_be_unit_interval_number",
              "invalid_feedback_shape" => encode_value(shape),
              "row_id" => realized_activity_operational_feedback_row_id(row)
            }
            |> compact_map()
          ]
      end
    end)
  end

  defp invalid_realized_activity_operational_feedback_nonnegative_number_sections(row) do
    row
    |> realized_activity_operational_feedback_nonnegative_number_values()
    |> Enum.flat_map(fn {field, value} ->
      case nonnegative_number_status(value) do
        {:ok, _value} ->
          []

        :missing ->
          []

        {:invalid_number, number} ->
          [
            %{
              "field" => "realized_activities.#{field}",
              "reason" => "entry_must_be_nonnegative_number",
              "invalid_feedback_shape" => number,
              "row_id" => realized_activity_operational_feedback_row_id(row)
            }
            |> compact_map()
          ]

        {:invalid_shape, shape} ->
          [
            %{
              "field" => "realized_activities.#{field}",
              "reason" => "entry_must_be_nonnegative_number",
              "invalid_feedback_shape" => encode_value(shape),
              "row_id" => realized_activity_operational_feedback_row_id(row)
            }
            |> compact_map()
          ]
      end
    end)
  end

  defp realized_activity_operational_feedback_nonnegative_number_values(row) do
    realized_activity_operational_feedback_nonnegative_number_paths()
    |> Enum.map(fn {field, path} -> {field, get_in(row, path)} end)
    |> Enum.reject(fn {_field, value} -> feedback_value_missing?(value) end)
  end

  defp realized_activity_operational_feedback_nonnegative_number_paths do
    [
      {"feedback_weight", ["feedback_weight"]},
      {"feedback_sample_weight", ["feedback_sample_weight"]},
      {"sample_weight", ["sample_weight"]},
      {"confidence_weight", ["confidence_weight"]}
    ]
  end

  defp realized_activity_operational_feedback_unit_interval_values(row) do
    realized_activity_operational_feedback_unit_interval_paths()
    |> Enum.map(fn {field, path} -> {field, get_in(row, path)} end)
    |> Enum.reject(fn {_field, value} -> feedback_value_missing?(value) end)
  end

  defp realized_activity_operational_feedback_unit_interval_paths do
    [
      {"completed_fraction", ["completed_fraction"]},
      {"image_quality_score", ["image_quality_score"]},
      {"product_quality_score", ["product_quality_score"]},
      {"quality_score", ["quality_score"]},
      {"cloud_cover_fraction", ["cloud_cover_fraction"]},
      {"cloud_fraction", ["cloud_fraction"]},
      {"cloud_cover", ["cloud_cover"]},
      {"blur_score", ["blur_score"]},
      {"image_blur_score", ["image_blur_score"]},
      {"sharpness_loss_fraction", ["sharpness_loss_fraction"]},
      {"quality.image_quality_score", ["quality", "image_quality_score"]},
      {"quality.product_quality_score", ["quality", "product_quality_score"]},
      {"quality.score", ["quality", "score"]},
      {"quality.cloud_cover_fraction", ["quality", "cloud_cover_fraction"]},
      {"quality.cloud_fraction", ["quality", "cloud_fraction"]},
      {"quality.cloud_cover", ["quality", "cloud_cover"]},
      {"quality.blur_score", ["quality", "blur_score"]},
      {"quality.image_blur_score", ["quality", "image_blur_score"]},
      {"quality.sharpness_loss_fraction", ["quality", "sharpness_loss_fraction"]},
      {"metadata.image_quality_score", ["metadata", "image_quality_score"]},
      {"metadata.product_quality_score", ["metadata", "product_quality_score"]},
      {"metadata.quality_score", ["metadata", "quality_score"]},
      {"metadata.cloud_cover_fraction", ["metadata", "cloud_cover_fraction"]},
      {"metadata.cloud_fraction", ["metadata", "cloud_fraction"]},
      {"metadata.cloud_cover", ["metadata", "cloud_cover"]},
      {"metadata.blur_score", ["metadata", "blur_score"]},
      {"metadata.image_blur_score", ["metadata", "image_blur_score"]},
      {"metadata.sharpness_loss_fraction", ["metadata", "sharpness_loss_fraction"]}
    ]
  end

  defp feedback_value_missing?(nil), do: true
  defp feedback_value_missing?(""), do: true
  defp feedback_value_missing?(_value), do: false

  defp unit_interval_number_status(value) do
    case numeric_value(value) do
      number when is_number(number) and number >= 0.0 and number <= 1.0 ->
        {:ok, number * 1.0}

      number when is_number(number) ->
        {:invalid_number, number}

      _value ->
        if feedback_value_missing?(value), do: :missing, else: {:invalid_shape, value}
    end
  end

  defp nonnegative_number_status(value) do
    case numeric_value(value) do
      number when is_number(number) and number >= 0.0 ->
        {:ok, number * 1.0}

      number when is_number(number) ->
        {:invalid_number, number}

      _value ->
        if feedback_value_missing?(value), do: :missing, else: {:invalid_shape, value}
    end
  end

  defp realized_activity_operational_feedback_row_id(row) do
    raw_feedback_identifier(row["id"]) ||
      raw_feedback_identifier(row["realized_activity_id"]) ||
      raw_feedback_identifier(row["activity_id"])
  end

  defp nested_feedback_identifier(row, object_key, identity_keys) do
    case Map.get(row, object_key) do
      %{} = object -> Enum.find_value(identity_keys, &Map.get(object, &1))
      _value -> nil
    end
  end

  defp raw_feedback_identifier(nil), do: nil
  defp raw_feedback_identifier(value) when is_binary(value) and value != "", do: value
  defp raw_feedback_identifier(value) when is_atom(value), do: Atom.to_string(value)
  defp raw_feedback_identifier(value) when is_integer(value), do: Integer.to_string(value)
  defp raw_feedback_identifier(_value), do: nil

  defp invalid_operational_feedback_field_sections(feedback, field) do
    if Map.has_key?(feedback, field) and not is_map(Map.get(feedback, field)) do
      [
        %{
          "field" => field,
          "reason" => "field_must_be_object",
          "invalid_feedback_shape" => encode_value(Map.get(feedback, field))
        }
      ]
    else
      []
    end
  end

  defp invalid_operational_feedback_field_sections(feedback, field, :number_entries) do
    cond do
      not Map.has_key?(feedback, field) ->
        []

      not is_map(Map.get(feedback, field)) ->
        invalid_operational_feedback_field_sections(feedback, field)

      true ->
        feedback
        |> Map.fetch!(field)
        |> stringify_keys()
        |> Enum.flat_map(fn {key, value} ->
          number = numeric_value(value)

          cond do
            not operational_feedback_key?(key) ->
              []

            is_number(number) and
              not unit_interval_operational_feedback_field?(field) and number >= 0.0 ->
              []

            is_number(number) and number >= 0.0 and number <= 1.0 ->
              []

            is_number(number) and not unit_interval_operational_feedback_field?(field) ->
              [
                %{
                  "field" => field,
                  "key" => key,
                  "reason" => "entry_must_be_nonnegative_number",
                  "invalid_feedback_shape" => encode_value(value)
                }
              ]

            is_number(number) ->
              [
                %{
                  "field" => field,
                  "key" => key,
                  "reason" => "entry_must_be_unit_interval_number",
                  "invalid_feedback_shape" => encode_value(value)
                }
              ]

            true ->
              [
                %{
                  "field" => field,
                  "key" => key,
                  "reason" => "entry_must_be_number",
                  "invalid_feedback_shape" => encode_value(value)
                }
              ]
          end
        end)
    end
  end

  defp invalid_string_list_operational_feedback_sections(feedback, field) do
    cond do
      not Map.has_key?(feedback, field) ->
        []

      not is_map(Map.get(feedback, field)) ->
        [
          %{
            "field" => field,
            "reason" => "field_must_be_object",
            "invalid_feedback_shape" => encode_value(Map.get(feedback, field))
          }
        ]

      true ->
        feedback
        |> Map.fetch!(field)
        |> stringify_keys()
        |> Enum.flat_map(fn
          {key, values} when is_list(values) ->
            if Enum.all?(values, &valid_feedback_source_string?/1) do
              []
            else
              [
                %{
                  "field" => field,
                  "key" => key,
                  "reason" => "entry_must_be_string_array",
                  "invalid_feedback_shape" => encode_value(values)
                }
              ]
            end

          {key, value} ->
            [
              %{
                "field" => field,
                "key" => key,
                "reason" => "entry_must_be_string_array",
                "invalid_feedback_shape" => encode_value(value)
              }
            ]
        end)
    end
  end

  defp unit_interval_operational_feedback_field?(field)
       when field in [
              "contact_success_rate",
              "observation_success_rate",
              "maneuver_success_rate",
              "command_success_rate",
              "station_throughput_factor",
              "image_quality_score",
              "cloud_cover_fraction",
              "blur_score"
            ],
       do: true

  defp unit_interval_operational_feedback_field?(_field), do: false

  defp valid_feedback_source_string?(value) when is_binary(value), do: value != ""
  defp valid_feedback_source_string?(value) when is_atom(value), do: not is_nil(value)
  defp valid_feedback_source_string?(_value), do: false

  defp invalid_string_operational_feedback_sections(feedback, field) do
    cond do
      not Map.has_key?(feedback, field) ->
        []

      not is_map(Map.get(feedback, field)) ->
        [
          %{
            "field" => field,
            "reason" => "field_must_be_object",
            "invalid_feedback_shape" => encode_value(Map.get(feedback, field))
          }
        ]

      true ->
        feedback
        |> Map.fetch!(field)
        |> stringify_keys()
        |> Enum.flat_map(fn
          {_key, value} when is_binary(value) and value != "" ->
            []

          {_key, value} when is_atom(value) and not is_nil(value) ->
            []

          {key, value} ->
            [
              %{
                "field" => field,
                "key" => key,
                "reason" => "entry_must_be_string",
                "invalid_feedback_shape" => encode_value(value)
              }
            ]
        end)
    end
  end

  defp invalid_nested_operational_feedback_sections(feedback, field) do
    cond do
      not Map.has_key?(feedback, field) ->
        []

      not is_map(Map.get(feedback, field)) ->
        [
          %{
            "field" => field,
            "reason" => "field_must_be_object",
            "invalid_feedback_shape" => encode_value(Map.get(feedback, field))
          }
        ]

      true ->
        feedback
        |> Map.fetch!(field)
        |> stringify_keys()
        |> Enum.flat_map(fn
          {_key, %{}} ->
            []

          {key, value} ->
            [
              %{
                "field" => field,
                "key" => key,
                "reason" => "entry_must_be_object",
                "invalid_feedback_shape" => encode_value(value)
              }
            ]
        end)
    end
  end

  defp source_window_lineage(candidates) do
    candidates
    |> Enum.map(fn candidate ->
      %{
        "schema_contract" => "source_window_lineage.v1",
        "candidate_activity_id" => candidate["id"],
        "source_window_id" => candidate["source_window_id"],
        "source_window_type" => get_in(candidate, ["source_window", "type"]),
        "scenario_id" => candidate["scenario_id"],
        "source_window" => lineage_source_window(candidate)
      }
      |> Map.merge(candidate_lineage_context(candidate))
      |> compact_map()
    end)
    |> Enum.sort_by(&{&1["scenario_id"], &1["source_window_id"], &1["candidate_activity_id"]})
  end

  defp lineage_source_window(%{"source_window" => %{} = source_window} = candidate) do
    source_window
    |> Map.merge(%{
      "id" => candidate["source_window_id"],
      "type" => Map.get(source_window, "type"),
      "scenario_id" => candidate["scenario_id"],
      "target_id" => candidate["target_id"],
      "ground_station_id" => candidate["ground_station_id"],
      "starts_at_s" => candidate["starts_at_s"],
      "ends_at_s" => candidate["ends_at_s"],
      "duration_s" => candidate["duration_s"]
    })
    |> Map.merge(candidate_lineage_context(candidate))
    |> compact_map()
  end

  defp lineage_source_window(_candidate), do: nil

  defp candidate_lineage_context(candidate) do
    candidate
    |> Map.take([
      "target_id",
      "ground_station_id",
      "direction",
      "collection_id",
      "product_id",
      "product_ids",
      "payload_id",
      "instrument_id",
      "source_activity_id",
      "source_activity_ids",
      "missed_downlink_activity_id",
      "missed_downlink_activity_ids",
      "objective_id",
      "objective_type",
      "collection_latency_objective_count",
      "collection_latency_objective_ids",
      "collection_latency_objective_source",
      "collection_latency_objective_types",
      "latency_objective",
      "max_latency_s",
      "planned_latency_s",
      "required_downlink_mb",
      "candidate_downlink_mb",
      "downlink_completion_ratio",
      "selected_downlink_shortfall_mb",
      "downlink_requirement_status",
      "downlink_completion_source",
      "downlink_completion_sources",
      "downlink_completion_objective_count",
      "source_capacity_adjusted_throughput_mb",
      "source_selected_capacity_adjusted_throughput_mb",
      "source_unused_capacity_adjusted_throughput_mb",
      "feedback_source",
      "feedback_scope",
      "trust_boundary"
    ])
    |> compact_map()
  end

  defp accepted_planning_state_ref(refresh) do
    accepted_state = accepted_planning_state(refresh)

    %{
      "snapshot_id" => Map.get(accepted_state, "snapshot_id"),
      "accepted_at" => Map.get(accepted_state, "accepted_at"),
      "spacecraft_state_count" => length(Map.get(accepted_state, "spacecraft_states", [])),
      "maneuver_execution_delta_count" =>
        length(Map.get(accepted_state, "maneuver_execution_deltas", []))
    }
  end

  defp accepted_planning_state(refresh) do
    Map.get(refresh, "accepted_planning_state") || %{}
  end

  defp freshness_report(refresh, generated_at) do
    accepted_state = accepted_planning_state(refresh)
    horizon = remaining_horizon(refresh)
    current_epoch = current_epoch_s(refresh)
    policy = freshness_policy(refresh)

    accepted_snapshot_age_s =
      accepted_snapshot_age_s(Map.get(accepted_state, "accepted_at"), generated_at)

    horizon_start_offset_s =
      horizon_start_offset_s(current_epoch, Map.get(horizon, "starts_at_s"))

    accepted_quality_level = accepted_quality_level(accepted_state)
    state_quality_status = state_quality_status(accepted_quality_level, policy)

    stale_reasons =
      []
      |> maybe_stale_reason(
        not is_nil(accepted_snapshot_age_s) and
          accepted_snapshot_age_s > policy["max_snapshot_age_s"],
        "accepted_snapshot_older_than_policy"
      )
      |> maybe_stale_reason(
        not is_nil(horizon_start_offset_s) and
          abs(horizon_start_offset_s) > policy["max_horizon_start_offset_s"],
        "remaining_horizon_does_not_start_at_current_epoch"
      )
      |> maybe_stale_reason(
        state_quality_status == "not_accepted",
        "accepted_state_quality_below_policy"
      )
      |> Enum.reverse()

    unknown_reasons =
      []
      |> maybe_unknown_reason(
        is_nil(accepted_snapshot_age_s),
        "accepted_snapshot_age_unknown"
      )
      |> maybe_unknown_reason(
        is_nil(horizon_start_offset_s),
        "horizon_alignment_unknown"
      )
      |> maybe_unknown_reason(
        state_quality_status == "unknown",
        "accepted_state_quality_unknown"
      )
      |> Enum.reverse()

    status =
      cond do
        stale_reasons != [] ->
          "stale"

        unknown_reasons != [] ->
          "unknown"

        true ->
          "current"
      end

    %{
      "schema_contract" => "freshness_report.v1",
      "model" => "accepted_snapshot_horizon_and_quality_freshness",
      "model_limits" => model_limits(),
      "generated_at" => DateTime.to_iso8601(generated_at),
      "accepted_at" => Map.get(accepted_state, "accepted_at"),
      "accepted_state_quality_level" => accepted_quality_level,
      "allowed_state_quality_levels" => policy["allowed_state_quality_levels"],
      "state_quality_status" => state_quality_status,
      "current_epoch_s" => current_epoch,
      "horizon_starts_at_s" => Map.get(horizon, "starts_at_s"),
      "accepted_snapshot_age_s" => accepted_snapshot_age_s,
      "horizon_start_offset_s" => horizon_start_offset_s,
      "max_snapshot_age_s" => policy["max_snapshot_age_s"],
      "max_horizon_start_offset_s" => policy["max_horizon_start_offset_s"],
      "status" => status,
      "stale_reasons" => stale_reasons,
      "unknown_reasons" => unknown_reasons
    }
  end

  defp freshness_policy(refresh) do
    policy = Map.get(refresh, "freshness_policy", %{})

    %{
      "max_snapshot_age_s" => policy_number(policy, "max_snapshot_age_s", 86_400.0),
      "max_horizon_start_offset_s" => policy_number(policy, "max_horizon_start_offset_s", 1.0),
      "allowed_state_quality_levels" =>
        policy_list(policy, "allowed_state_quality_levels", ["accepted", "planning_accepted"])
    }
  end

  defp policy_number(policy, key, default) do
    case numeric_value(Map.get(policy, key)) do
      value when is_number(value) -> value
      _value -> default
    end
  end

  defp policy_list(policy, key, default) do
    case Map.get(policy, key) do
      values when is_list(values) ->
        accepted_values = Enum.filter(values, &is_binary/1)

        if accepted_values == [] do
          default
        else
          accepted_values
        end

      _value ->
        default
    end
  end

  defp accepted_quality_level(accepted_state) do
    accepted_state
    |> Map.get("quality", %{})
    |> Map.get("level")
  end

  defp state_quality_status(nil, _policy), do: "unknown"

  defp state_quality_status(level, policy) do
    if level in policy["allowed_state_quality_levels"] do
      "accepted"
    else
      "not_accepted"
    end
  end

  defp accepted_snapshot_age_s(nil, _generated_at), do: nil

  defp accepted_snapshot_age_s(accepted_at, generated_at) when is_binary(accepted_at) do
    with {:ok, accepted_at, _offset} <- DateTime.from_iso8601(accepted_at) do
      DateTime.diff(generated_at, accepted_at, :second) * 1.0
    else
      _error -> nil
    end
  end

  defp accepted_snapshot_age_s(_accepted_at, _generated_at), do: nil

  defp horizon_start_offset_s(current_epoch, horizon_starts_at_s)
       when is_number(current_epoch) and is_number(horizon_starts_at_s),
       do: horizon_starts_at_s - current_epoch

  defp horizon_start_offset_s(_current_epoch, _horizon_starts_at_s), do: nil

  defp snapshot_id(refresh), do: Map.get(accepted_planning_state(refresh), "snapshot_id")

  defp current_epoch_s(refresh) do
    [
      Map.get(refresh, "current_epoch_s"),
      get_in(refresh, ["current_epoch", "seconds_since_j2000"]),
      get_in(refresh, ["mission_state", "current_epoch_s"]),
      get_in(refresh, ["mission_state", "current_epoch", "seconds_since_j2000"]),
      get_in(refresh, ["accepted_planning_state", "current_epoch_s"]),
      get_in(refresh, ["accepted_planning_state", "current_epoch", "seconds_since_j2000"]),
      accepted_state_spacecraft_epoch_s(refresh)
    ]
    |> Enum.find_value(&numeric_value/1)
  end

  defp accepted_state_spacecraft_epoch_s(refresh) do
    refresh
    |> accepted_planning_state()
    |> Map.get("spacecraft_states", [])
    |> List.first(%{})
    |> get_in(["epoch", "seconds_since_j2000"])
    |> numeric_value()
  end

  defp remaining_horizon(refresh) do
    [
      Map.get(refresh, "remaining_horizon"),
      get_in(refresh, ["mission_state", "remaining_horizon"]),
      get_in(refresh, ["accepted_planning_state", "remaining_horizon"])
    ]
    |> Enum.find(&is_map/1)
    |> case do
      %{} = horizon -> normalize_remaining_horizon(horizon)
      _horizon -> %{}
    end
  end

  defp normalize_remaining_horizon(horizon) do
    horizon
    |> Map.take(["starts_at_s", "ends_at_s", "duration_s", "output_step_s"])
    |> Map.new(fn {key, value} ->
      case numeric_value(value) do
        number when is_number(number) -> {key, number}
        nil -> {key, value}
      end
    end)
  end

  defp refresh_id(refresh, study_id) do
    stable_input =
      {
        encode_value(study_id),
        snapshot_id(refresh),
        accepted_planning_state(refresh),
        current_epoch_s(refresh),
        remaining_horizon(refresh),
        refresh_targets(refresh),
        refresh_objectives(refresh),
        refresh_spacecraft_states(refresh),
        refresh_ground_network(refresh),
        refresh_resource_summaries(refresh),
        Map.get(refresh, "prior_candidate_activities", []),
        Map.get(refresh, "freshness_policy", %{}),
        Map.get(refresh, "resource_filter_policy", %{}),
        Map.get(refresh, "candidate_limit_policy", %{}),
        Map.get(refresh, "contact_allocation_policy", %{}),
        Map.get(refresh, "approval_policy", %{}),
        raw_operational_feedback(refresh),
        Map.get(refresh, "model_assumptions", %{}),
        Map.get(refresh, "constraints", %{}),
        Map.get(refresh, "scoring_policy", %{})
      }

    hash =
      :crypto.hash(:sha256, :erlang.term_to_binary(stable_input))
      |> Base.encode16(case: :lower)
      |> binary_part(0, 16)

    "candidate_refresh:" <> encode_value(study_id) <> ":" <> hash
  end

  defp refresh_ground_network(refresh) do
    raw_entries =
      refresh_ground_network_entries(Map.get(refresh, "ground_network")) ++
        refresh_ground_network_entries(Map.get(refresh, "station_calendar")) ++
        refresh_ground_network_entries(get_in(refresh, ["mission_state", "ground_network"])) ++
        refresh_ground_network_entries(get_in(refresh, ["mission_state", "station_calendar"])) ++
        refresh_ground_network_entries(
          get_in(refresh, ["accepted_planning_state", "ground_network"])
        ) ++
        refresh_ground_network_entries(
          get_in(refresh, ["accepted_planning_state", "station_calendar"])
        ) ++
        source_station_calendar_report_ground_network_entries(refresh) ++
        source_contact_intent_ground_network_entries(refresh) ++
        source_contact_filter_report_ground_network_entries(refresh) ++
        source_contact_allocation_report_ground_network_entries(refresh)

    provider_entries =
      refresh_station_calendar_provider_entries(Map.get(refresh, "station_calendar_provider")) ++
        refresh_station_calendar_provider_entries(
          get_in(refresh, ["mission_state", "station_calendar_provider"])
        ) ++
        refresh_station_calendar_provider_entries(
          get_in(refresh, ["accepted_planning_state", "station_calendar_provider"])
        )

    prefer_provider_station_calendar_entries(raw_entries, provider_entries)
  end

  defp prefer_provider_station_calendar_entries(raw_entries, []), do: raw_entries

  defp prefer_provider_station_calendar_entries(raw_entries, provider_entries) do
    provider_entry_ids =
      provider_entries
      |> Enum.flat_map(&station_calendar_explicit_entry_ids/1)
      |> MapSet.new()

    raw_entries
    |> Enum.reject(fn entry ->
      entry
      |> station_calendar_explicit_entry_ids()
      |> Enum.any?(&MapSet.member?(provider_entry_ids, &1))
    end)
    |> Kernel.++(provider_entries)
  end

  defp station_calendar_explicit_entry_ids(station) do
    station
    |> Map.take(["station_calendar_entry_id", "id", "provider_entry_id"])
    |> Map.values()
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
  end

  defp refresh_ground_network_entries(entries) when is_list(entries) do
    entries
    |> Enum.map(&stringify_keys/1)
    |> Enum.map(&normalize_ground_network_station/1)
  end

  defp refresh_ground_network_entries(_entries), do: []

  defp refresh_station_calendar_provider_entries(%{} = provider),
    do: StationCalendar.to_ground_network(provider)

  defp refresh_station_calendar_provider_entries(providers) when is_list(providers) do
    Enum.flat_map(providers, &refresh_station_calendar_provider_entries/1)
  end

  defp refresh_station_calendar_provider_entries(_provider), do: []

  defp source_station_calendar_report_ground_network_entries(refresh) do
    refresh
    |> source_station_calendar_reports()
    |> Enum.flat_map(fn {path, report} ->
      affected_contact_entries =
        report
        |> Map.get("affected_contacts", [])
        |> Enum.map(&station_calendar_row_ground_network_entry(path, &1, report))

      provider_contention_entries =
        report
        |> Map.get("provider_calendar_contention_groups", [])
        |> Enum.map(&station_calendar_provider_contention_ground_network_entry(path, &1, report))

      affected_contact_entries ++ provider_contention_entries
    end)
    |> Enum.reject(&is_nil/1)
  end

  defp station_calendar_row_ground_network_entry(path, %{} = row, %{} = report) do
    report = stringify_keys(report)
    row = station_calendar_report_row_with_context(row, report)
    ground_station_id = stable_id_or_nil(row["ground_station_id"] || nested_station_id(row))
    station_state = station_calendar_row_station_state(row)

    with station_id when station_id not in [nil, ""] <- ground_station_id,
         %{} = station_state <- station_state do
      %{
        "id" => station_calendar_row_station_entry_id(path, row),
        "ground_station_id" => station_id,
        "starts_at_s" => numeric_or_nil(row["starts_at_s"] || row["overlap_starts_at_s"]),
        "ends_at_s" => numeric_or_nil(row["ends_at_s"] || row["overlap_ends_at_s"]),
        "direction" => row["direction"],
        "availability" => station_state["availability"],
        "status" => station_state["status"],
        "capacity_fraction" => station_state["capacity_fraction"],
        "station_calendar_entry_id" => stable_id_or_nil(row["station_calendar_entry_id"]),
        "reservation_id" => stable_id_or_nil(row["station_reservation_id"]),
        "reserved_by" => row["station_reserved_by"],
        "reservation_status" => row["station_reservation_status"],
        "reservation_expires_at_s" => numeric_or_nil(row["station_reservation_expires_at_s"]),
        "station_calendar_reservation_expires_at_s" =>
          normalize_number_list(row["station_calendar_reservation_expires_at_s"]),
        "station_contention_status" => row["station_contention_status"],
        "source_station_calendar_review" => row,
        "source_station_calendar_entry" => station_calendar_row_source_entry(row),
        "source_station_calendar_overlaps" => row["source_station_calendar_overlaps"],
        "provenance" =>
          %{
            "source" => "station_calendar_report.affected_contacts",
            "source_path" => path,
            "trust_boundary" => station_calendar_row_trust_boundary(row)
          }
          |> compact_map()
      }
      |> compact_map()
    else
      _value -> nil
    end
  end

  defp station_calendar_row_ground_network_entry(_path, _row, _report), do: nil

  defp station_calendar_report_row_with_context(%{} = row, %{} = report) do
    row = stringify_keys(row)

    row
    |> maybe_put("trust_boundary", row["trust_boundary"] || report["trust_boundary"])
    |> maybe_put("provenance", row["provenance"] || report["provenance"])
  end

  defp station_calendar_row_source_entry(%{} = row) do
    source_entry =
      case row["source_station_calendar_entry"] do
        %{} = entry -> stringify_keys(entry)
        _entry -> %{}
      end

    source_entry
    |> Map.put_new("id", stable_id_or_nil(row["station_calendar_entry_id"]))
    |> Map.put_new(
      "station_calendar_entry_id",
      stable_id_or_nil(row["station_calendar_entry_id"])
    )
    |> Map.put_new("provenance", row["provenance"])
    |> Map.put_new(
      "reservation_expires_at_s",
      numeric_or_nil(row["station_reservation_expires_at_s"])
    )
    |> maybe_put(
      "station_calendar_reservation_expires_at_s",
      normalize_number_list(row["station_calendar_reservation_expires_at_s"])
    )
    |> Map.put("source_station_calendar_review", row)
    |> compact_map()
  end

  defp station_calendar_provider_contention_ground_network_entry(path, %{} = group, %{} = report) do
    report = stringify_keys(report)
    group = station_calendar_provider_contention_group_with_context(group, report)
    ground_station_id = stable_id_or_nil(group["ground_station_id"] || nested_station_id(group))
    station_state = station_calendar_provider_contention_station_state(group)

    with station_id when station_id not in [nil, ""] <- ground_station_id,
         %{} = station_state <- station_state do
      %{
        "id" => station_calendar_provider_contention_entry_id(path, group),
        "ground_station_id" => station_id,
        "starts_at_s" => numeric_or_nil(group["starts_at_s"] || group["overlap_starts_at_s"]),
        "ends_at_s" => numeric_or_nil(group["ends_at_s"] || group["overlap_ends_at_s"]),
        "directions" => station_calendar_provider_contention_directions(group),
        "availability" => station_state["availability"],
        "status" => station_state["status"],
        "capacity_fraction" => station_state["capacity_fraction"],
        "station_calendar_entry_id" => stable_id_or_nil(group["id"]),
        "station_calendar_provider_id" => one_or_nil(group["provider_ids"]),
        "station_calendar_provider_entry_id" => one_or_nil(group["provider_entry_ids"]),
        "station_calendar_overlap_entry_ids" => station_calendar_group_ids(group["entry_ids"]),
        "station_calendar_overlap_availabilities" =>
          station_calendar_group_values(group["availabilities"]),
        "station_calendar_reservation_ids" =>
          station_calendar_group_ids(group["reservation_ids"]),
        "station_calendar_reserved_by" => station_calendar_group_values(group["reserved_by"]),
        "station_calendar_reservation_statuses" =>
          station_calendar_group_values(group["reservation_statuses"]),
        "station_calendar_reservation_expires_at_s" =>
          station_calendar_group_numbers(group["reservation_expires_at_s"]),
        "station_calendar_trust_boundary_status" =>
          station_calendar_group_trust_boundary_status(group),
        "station_contention_status" => "provider_calendar_overlap",
        "source_station_calendar_entry" =>
          station_calendar_provider_contention_source_entry(group),
        "source_station_calendar_overlaps" =>
          station_calendar_provider_contention_source_entries(group),
        "source_station_calendar_provider_contention" => group,
        "provenance" =>
          %{
            "source" => "station_calendar_report.provider_calendar_contention_groups",
            "source_path" => path,
            "trust_boundary" => station_calendar_provider_contention_trust_boundary(group)
          }
          |> compact_map()
      }
      |> compact_map()
    else
      _value -> nil
    end
  end

  defp station_calendar_provider_contention_ground_network_entry(_path, _group, _report),
    do: nil

  defp station_calendar_provider_contention_group_with_context(%{} = group, %{} = report) do
    group = stringify_keys(group)

    group
    |> maybe_put("trust_boundary", group["trust_boundary"] || report["trust_boundary"])
    |> maybe_put("provenance", group["provenance"] || report["provenance"])
  end

  defp station_calendar_provider_contention_station_state(%{} = group) do
    availability_tokens =
      (station_calendar_group_values(group["availabilities"]) ++
         (group
          |> station_calendar_provider_contention_source_entries()
          |> Enum.flat_map(fn entry ->
            [entry["availability"], entry["station_availability"], entry["status"]]
          end)))
      |> Enum.map(&normalized_availability_token(encode_value(&1)))

    capacity_fraction = station_calendar_provider_contention_capacity_fraction(group)
    reservation_ids = station_calendar_group_ids(group["reservation_ids"])

    cond do
      Enum.any?(availability_tokens, &(&1 in ["unavailable", "maintenance"])) ->
        %{"availability" => "unavailable", "status" => "unavailable"}

      "reserved" in availability_tokens or reservation_ids != [] ->
        %{"availability" => "reserved", "status" => "reserved"}

      is_number(capacity_fraction) and capacity_fraction <= 0.0 ->
        %{"availability" => "reduced_capacity", "capacity_fraction" => 0.0}

      true ->
        nil
    end
  end

  defp station_calendar_provider_contention_capacity_fraction(group) do
    candidates =
      [group["capacity_fraction"], group["capacity_pack_capacity_fraction"]] ++
        (group["capacity_fractions"] |> List.wrap()) ++
        (group["capacity_pack_capacity_fractions"] |> List.wrap()) ++
        (group
         |> station_calendar_provider_contention_source_entries()
         |> Enum.map(&station_capacity_fraction/1))

    candidates
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.filter(&is_number/1)
    |> case do
      [] -> nil
      fractions -> Enum.min(fractions)
    end
  end

  defp station_calendar_provider_contention_directions(group) do
    [
      group["directions"],
      group["provider_calendar_contention_directions"],
      group["direction"],
      group["station_calendar_directions"],
      group
      |> station_calendar_provider_contention_source_entries()
      |> Enum.flat_map(&station_directions/1)
    ]
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.map(&normalize_direction/1)
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      directions -> directions
    end
  end

  defp station_calendar_provider_contention_source_entry(%{} = group) do
    %{
      "id" => stable_id_or_nil(group["id"]),
      "station_calendar_entry_id" => stable_id_or_nil(group["id"]),
      "provider_ids" => station_calendar_group_ids(group["provider_ids"]),
      "provider_entry_ids" => station_calendar_group_ids(group["provider_entry_ids"]),
      "directions" => station_calendar_provider_contention_directions(group),
      "station_calendar_reservation_expires_at_s" =>
        station_calendar_group_numbers(group["reservation_expires_at_s"]),
      "source_station_calendar_provider_contention" => group,
      "source_station_calendar_entries" =>
        station_calendar_provider_contention_source_entries(group),
      "provenance" => group["provenance"]
    }
    |> compact_map()
  end

  defp station_calendar_provider_contention_source_entries(%{} = group) do
    [
      group["source_station_calendar_entries"],
      group["source_station_calendar_overlaps"]
    ]
    |> List.flatten()
    |> Enum.filter(&is_map/1)
    |> Enum.map(&stringify_keys/1)
  end

  defp station_calendar_provider_contention_source_entries(_group), do: []

  defp station_provider_contention_values(row, field) do
    [
      get_in(row, ["source_station_calendar_provider_contention", field]),
      get_in(row, [
        "source_station_calendar_entry",
        "source_station_calendar_provider_contention",
        field
      ])
    ]
    |> Enum.concat(station_provider_contention_overlap_values(row, field))
    |> List.flatten()
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      values -> values
    end
  end

  defp station_provider_contention_overlap_values(
         %{"source_station_calendar_overlaps" => overlaps},
         field
       )
       when is_list(overlaps) do
    overlaps
    |> Enum.map(fn
      %{} = overlap ->
        station_provider_contention_overlap_value(overlap, field)

      _overlap ->
        nil
    end)
  end

  defp station_provider_contention_overlap_values(_row, _field), do: []

  defp station_provider_contention_overlap_value(overlap, field) do
    contention_value =
      get_in(overlap, [
        "source_station_calendar_entry",
        "source_station_calendar_provider_contention",
        field
      ])

    entry_field =
      case field do
        "reservation_ids" -> "reservation_id"
        "reserved_by" -> "reserved_by"
        "reservation_statuses" -> "reservation_status"
        "reservation_expires_at_s" -> "reservation_expires_at_s"
        _field -> nil
      end

    entry_values =
      overlap
      |> get_in(["source_station_calendar_entry", "source_station_calendar_entries"])
      |> List.wrap()
      |> Enum.filter(&is_map/1)
      |> Enum.map(&Map.get(&1, entry_field))

    [contention_value | entry_values]
  end

  defp station_calendar_provider_contention_trust_boundary(group) do
    group["trust_boundary"] ||
      get_in(group, ["provenance", "trust_boundary"]) ||
      group
      |> station_calendar_provider_contention_source_entries()
      |> Enum.find_value(&station_calendar_row_trust_boundary/1)
  end

  defp station_calendar_group_trust_boundary_status(group) do
    group["station_calendar_trust_boundary_status"] ||
      group
      |> Map.get("trust_boundary_statuses")
      |> station_calendar_group_values()
      |> case do
        [status] -> status
        [] -> nil
        statuses -> Enum.join(statuses, ",")
      end
  end

  defp station_calendar_provider_contention_entry_id(path, group) do
    base =
      stable_id_or_nil(group["id"]) ||
        group["entry_ids"] |> station_calendar_group_ids() |> Enum.join(":") |> stable_id_or_nil() ||
        stable_id_or_nil(group["ground_station_id"]) ||
        "provider_calendar_contention"

    hash =
      :crypto.hash(:sha256, :erlang.term_to_binary({path, group}))
      |> Base.encode16(case: :lower)
      |> binary_part(0, 8)

    ["station_calendar_provider_contention", base, hash]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.join(":")
  end

  defp station_calendar_group_ids(values) do
    values
    |> station_calendar_group_values()
    |> Enum.map(&stable_id_or_nil/1)
    |> Enum.reject(&is_nil/1)
  end

  defp station_calendar_group_numbers(values) do
    values
    |> List.wrap()
    |> normalize_number_list()
  end

  defp station_calendar_group_values(values) do
    values
    |> List.wrap()
    |> Enum.reject(&is_nil/1)
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp one_or_nil([value]), do: value
  defp one_or_nil(_values), do: nil

  defp station_calendar_row_station_state(%{} = row) do
    availability =
      [
        row["station_availability"],
        row["station_calendar_status"],
        row["availability"],
        row["status"]
      ]
      |> Enum.find_value(fn value ->
        normalized = value |> encode_value() |> normalized_availability_token()
        if normalized in ["unavailable", "maintenance", "reserved"], do: normalized
      end)

    capacity_fraction = station_capacity_fraction(row)

    cond do
      availability in ["unavailable", "maintenance"] ->
        %{"availability" => "unavailable", "status" => "unavailable"}

      availability == "reserved" or row["station_contention_status"] == "reserved_overlap" ->
        %{"availability" => "reserved", "status" => "reserved"}

      is_number(capacity_fraction) and capacity_fraction <= 0.0 ->
        %{"availability" => "reduced_capacity", "capacity_fraction" => 0.0}

      true ->
        nil
    end
  end

  defp station_calendar_row_trust_boundary(row) do
    row["trust_boundary"] ||
      row["station_calendar_trust_boundary"] ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      get_in(row, ["source_station_calendar_entry", "provenance", "trust_boundary"])
  end

  defp station_calendar_row_station_entry_id(path, row) do
    base =
      stable_id_or_nil(row["station_calendar_entry_id"]) ||
        stable_id_or_nil(row["station_reservation_id"]) ||
        stable_id_or_nil(row["id"]) ||
        stable_id_or_nil(row["ground_station_id"]) ||
        "station_calendar_report"

    hash =
      :crypto.hash(:sha256, :erlang.term_to_binary({path, row}))
      |> Base.encode16(case: :lower)
      |> binary_part(0, 8)

    ["station_calendar_report", base, hash]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.join(":")
  end

  defp source_contact_intent_ground_network_entries(refresh) do
    refresh
    |> source_contact_intents()
    |> Enum.map(fn {path, intent} -> contact_intent_ground_network_entry(path, intent) end)
    |> Enum.reject(&is_nil/1)
  end

  defp contact_intent_ground_network_entry(path, %{} = intent) do
    intent = stringify_keys(intent)
    ground_station_id = stable_id_or_nil(intent["ground_station_id"] || nested_station_id(intent))
    station_state = contact_intent_station_state(intent)

    with station_id when station_id not in [nil, ""] <- ground_station_id,
         %{} = station_state <- station_state do
      %{
        "id" => contact_intent_station_entry_id(path, intent),
        "ground_station_id" => station_id,
        "starts_at_s" => numeric_or_nil(intent["starts_at_s"]),
        "ends_at_s" => numeric_or_nil(intent["ends_at_s"]),
        "direction" => intent["direction"],
        "availability" => station_state["availability"],
        "status" => station_state["status"],
        "capacity_fraction" => station_state["capacity_fraction"],
        "station_calendar_entry_id" => stable_id_or_nil(intent["station_calendar_entry_id"]),
        "reservation_id" => stable_id_or_nil(intent["station_reservation_id"]),
        "reserved_by" => intent["station_reserved_by"],
        "reservation_status" => intent["station_reservation_status"],
        "station_contention_status" => intent["station_contention_status"],
        "source_contact_intent" => intent,
        "provenance" =>
          %{
            "source" => "contact_intent.v1",
            "source_path" => path,
            "trust_boundary" => contact_intent_trust_boundary(intent)
          }
          |> compact_map()
      }
      |> compact_map()
    else
      _value -> nil
    end
  end

  defp contact_intent_ground_network_entry(_path, _intent), do: nil

  defp contact_intent_station_state(%{} = intent) do
    availability =
      [
        intent["station_availability"],
        intent["station_calendar_status"],
        intent["availability"],
        intent["status"]
      ]
      |> Enum.find_value(fn value ->
        normalized = value |> encode_value() |> normalized_availability_token()
        if normalized in ["unavailable", "maintenance", "reserved"], do: normalized
      end)

    capacity_fraction = station_capacity_fraction(intent)

    cond do
      availability in ["unavailable", "maintenance"] ->
        %{"availability" => "unavailable", "status" => "unavailable"}

      availability == "reserved" ->
        %{"availability" => "reserved", "status" => "reserved"}

      is_number(capacity_fraction) and capacity_fraction <= 0.0 ->
        %{"availability" => "reduced_capacity", "capacity_fraction" => 0.0}

      true ->
        nil
    end
  end

  defp contact_intent_station_feedback?(%{} = intent),
    do: is_map(contact_intent_station_state(intent))

  defp contact_intent_station_feedback?(_intent), do: false

  defp contact_intent_station_calendar_status(%{} = intent) do
    case contact_intent_station_state(intent) do
      %{"status" => status} -> status
      _state -> nil
    end
  end

  defp contact_intent_station_calendar_status(_intent), do: nil

  defp source_contact_intent_trust_boundaries(intents) when is_list(intents) do
    intents
    |> Enum.map(&contact_intent_trust_boundary/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp source_contact_intent_trust_boundary_status(intents) do
    case source_contact_intent_trust_boundaries(intents) do
      [] -> "missing"
      _trust_boundaries -> "declared"
    end
  end

  defp contact_intent_trust_boundary(intent) do
    intent["trust_boundary"] ||
      intent["station_calendar_trust_boundary"] ||
      get_in(intent, ["provenance", "trust_boundary"]) ||
      get_in(intent, ["source_station_calendar_entry", "provenance", "trust_boundary"])
  end

  defp contact_intent_station_entry_id(path, intent) do
    base =
      stable_id_or_nil(intent["station_calendar_entry_id"]) ||
        stable_id_or_nil(intent["station_reservation_id"]) ||
        stable_id_or_nil(intent["id"]) ||
        stable_id_or_nil(intent["ground_station_id"]) ||
        "contact_intent_station_feedback"

    hash =
      :crypto.hash(:sha256, :erlang.term_to_binary({path, intent}))
      |> Base.encode16(case: :lower)
      |> binary_part(0, 8)

    ["contact_intent", base, hash]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.join(":")
  end

  defp source_contact_filter_report_ground_network_entries(refresh) do
    refresh
    |> source_contact_filter_reports()
    |> Enum.flat_map(fn {path, report} ->
      report
      |> Map.get("suppressed_candidates", [])
      |> Enum.map(&contact_filter_row_ground_network_entry(path, &1))
      |> Enum.reject(&is_nil/1)
    end)
  end

  defp contact_filter_row_ground_network_entry(path, %{} = row) do
    row = stringify_keys(row)
    reason = normalized_timeline_diff_token(row["suppressed_reason"])
    ground_station_id = stable_id_or_nil(row["ground_station_id"] || nested_station_id(row))

    with station_state when not is_nil(station_state) <-
           contact_filter_station_state_for_reason(reason),
         station_id when station_id not in [nil, ""] <- ground_station_id do
      %{
        "id" => contact_filter_station_entry_id(path, row),
        "ground_station_id" => station_id,
        "starts_at_s" => numeric_or_nil(row["starts_at_s"]),
        "ends_at_s" => numeric_or_nil(row["ends_at_s"]),
        "direction" => row["direction"] || contact_filter_row_direction(row),
        "availability" => station_state["availability"],
        "status" => station_state["status"],
        "capacity_fraction" => station_state["capacity_fraction"],
        "station_calendar_entry_id" => stable_id_or_nil(row["station_calendar_entry_id"]),
        "reservation_id" => stable_id_or_nil(row["station_reservation_id"]),
        "reserved_by" => row["station_reserved_by"],
        "reservation_status" => row["station_reservation_status"],
        "station_contention_status" => row["station_contention_status"],
        "source_contact_suppression" => row,
        "provenance" =>
          %{
            "source" => "contact_filter_report.suppressed_candidates",
            "source_path" => path,
            "trust_boundary" => contact_filter_row_trust_boundary(row)
          }
          |> compact_map()
      }
      |> compact_map()
    else
      _value -> nil
    end
  end

  defp contact_filter_row_ground_network_entry(_path, _row), do: nil

  defp contact_filter_station_state_for_reason("ground_station_unavailable"),
    do: %{"availability" => "unavailable", "status" => "unavailable"}

  defp contact_filter_station_state_for_reason("ground_station_reserved"),
    do: %{"availability" => "reserved", "status" => "reserved"}

  defp contact_filter_station_state_for_reason("ground_station_capacity_zero"),
    do: %{"availability" => "reduced_capacity", "capacity_fraction" => 0.0}

  defp contact_filter_station_state_for_reason(_reason), do: nil

  defp contact_filter_row_direction(row) do
    case row["type"] do
      type when type in ["downlink", "uplink", "command", "tracking", "health_check"] -> type
      _type -> nil
    end
  end

  defp contact_filter_row_trust_boundary(row) do
    row["trust_boundary"] ||
      row["station_calendar_trust_boundary"] ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      get_in(row, ["source_station_calendar_entry", "provenance", "trust_boundary"])
  end

  defp contact_filter_station_entry_id(path, row) do
    base =
      stable_id_or_nil(row["station_calendar_entry_id"]) ||
        stable_id_or_nil(row["station_reservation_id"]) ||
        stable_id_or_nil(row["id"]) ||
        stable_id_or_nil(row["ground_station_id"]) ||
        "contact_filter_suppression"

    hash =
      :crypto.hash(:sha256, :erlang.term_to_binary({path, row}))
      |> Base.encode16(case: :lower)
      |> binary_part(0, 8)

    ["contact_filter", base, hash]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.join(":")
  end

  defp source_contact_allocation_report_ground_network_entries(refresh) do
    refresh
    |> source_contact_allocation_reports()
    |> Enum.flat_map(fn {path, report} ->
      report
      |> Map.get("rows", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.with_index(1)
      |> Enum.map(fn {row, index} ->
        row =
          Map.put_new(
            row,
            "_source_report_trust_boundary",
            result_artifact_trust_boundary(report)
          )

        contact_allocation_row_ground_network_entry(path, row, index)
      end)
      |> Enum.reject(&is_nil/1)
    end)
  end

  defp contact_allocation_row_ground_network_entry(path, %{} = row, index) do
    row = stringify_keys(row)
    source_contact = contact_allocation_source_contact(row)
    station_state = contact_allocation_row_station_state(row, source_contact)
    ground_station_id = contact_allocation_station_id(row, source_contact)

    with station_id when station_id not in [nil, ""] <- ground_station_id,
         %{} = station_state <- station_state do
      %{
        "id" => contact_allocation_station_entry_id(path, row, index),
        "ground_station_id" => station_id,
        "starts_at_s" => numeric_or_nil(row["starts_at_s"] || source_contact["starts_at_s"]),
        "ends_at_s" => numeric_or_nil(row["ends_at_s"] || source_contact["ends_at_s"]),
        "direction" => contact_allocation_row_direction(row, source_contact),
        "availability" => station_state["availability"],
        "status" => station_state["status"],
        "capacity_fraction" => station_state["capacity_fraction"],
        "station_calendar_entry_id" =>
          stable_id_or_nil(row["station_calendar_entry_id"]) ||
            stable_id_or_nil(source_contact["station_calendar_entry_id"]),
        "reservation_id" =>
          stable_id_or_nil(row["station_reservation_id"] || row["reservation_id"]) ||
            stable_id_or_nil(
              source_contact["station_reservation_id"] || source_contact["reservation_id"]
            ),
        "reserved_by" =>
          row["station_reserved_by"] || row["reserved_by"] ||
            source_contact["station_reserved_by"] || source_contact["reserved_by"],
        "reservation_status" =>
          row["station_reservation_status"] || row["reservation_status"] ||
            source_contact["station_reservation_status"] || source_contact["reservation_status"],
        "station_contention_status" => row["station_contention_status"],
        "source_contact_allocation" => row,
        "provenance" =>
          %{
            "source" => "contact_allocation_report.rows",
            "source_path" => path,
            "trust_boundary" => contact_allocation_trust_boundary(row)
          }
          |> compact_map()
      }
      |> compact_map()
    else
      _value -> nil
    end
  end

  defp contact_allocation_row_station_state(row, source_contact) do
    reason = normalized_timeline_diff_token(row["allocation_reason"] || row["suppressed_reason"])

    precedence_availability =
      row["station_calendar_precedence_availability"]
      |> encode_value()
      |> normalized_availability_token()

    availability =
      normalized_availability_token(
        encode_value(
          row["station_availability"] ||
            row["availability"] ||
            row["station_calendar_status"] ||
            row["status"] ||
            source_contact["station_availability"] ||
            source_contact["availability"]
        )
      )

    cond do
      reason == "ground_station_unavailable" or availability in ["unavailable", "maintenance"] or
          precedence_availability in ["unavailable", "maintenance"] ->
        %{"availability" => "unavailable", "status" => "unavailable"}

      reason == "ground_station_reserved" or availability == "reserved" or
        row["station_contention_status"] == "reserved_overlap" or
          precedence_availability == "reserved" ->
        %{"availability" => "reserved", "status" => "reserved"}

      reason == "ground_station_capacity_zero" ->
        %{"availability" => "reduced_capacity", "capacity_fraction" => 0.0}

      reason == "ground_station_reduced_capacity_insufficient" or
        availability == "reduced_capacity" or precedence_availability == "reduced_capacity" ->
        %{
          "availability" => "reduced_capacity",
          "capacity_fraction" => contact_allocation_row_capacity_fraction(row, source_contact)
        }
        |> compact_map()

      true ->
        nil
    end
  end

  defp contact_allocation_row_capacity_fraction(row, source_contact) do
    [
      row["capacity_fraction"],
      row["station_capacity_fraction"],
      row["capacity_pack_capacity_fraction"],
      get_in(row, ["source_station_calendar_entry", "capacity_fraction"]),
      source_contact["capacity_fraction"],
      source_contact["station_capacity_fraction"],
      source_contact["capacity_pack_capacity_fraction"],
      get_in(source_contact, ["source_station_calendar_entry", "capacity_fraction"])
    ]
    |> Enum.find_value(&station_capacity_fraction_or_nil/1)
  end

  defp station_capacity_fraction_or_nil(value) when value in [nil, ""], do: nil

  defp station_capacity_fraction_or_nil(value) do
    case numeric_value(value) do
      number when is_number(number) -> number |> max(0.0) |> min(1.0)
      _value -> nil
    end
  end

  defp contact_allocation_row_direction(row, source_contact) do
    direction =
      row["direction"] ||
        get_in(row, ["activity_context", "direction"]) ||
        source_contact["direction"] ||
        get_in(source_contact, ["activity_context", "direction"]) ||
        row["type"] ||
        source_contact["type"]

    direction
    |> encode_value()
    |> normalized_timeline_diff_token()
  end

  defp contact_allocation_station_entry_id(path, row, index) do
    base =
      stable_id_or_nil(row["station_calendar_entry_id"]) ||
        stable_id_or_nil(row["station_reservation_id"]) ||
        stable_id_or_nil(row["contact_id"]) ||
        stable_id_or_nil(row["id"]) ||
        stable_id_or_nil(row["ground_station_id"]) ||
        "contact_allocation_row"

    hash =
      :crypto.hash(:sha256, :erlang.term_to_binary({path, index, row}))
      |> Base.encode16(case: :lower)
      |> binary_part(0, 8)

    ["contact_allocation", base, hash]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.join(":")
  end

  defp refresh_resource_summaries(refresh) do
    [
      Map.get(refresh, "resource_summaries", []),
      get_in(refresh, ["mission_state", "resource_summaries"]) || [],
      get_in(refresh, ["accepted_planning_state", "resource_summaries"]) || []
    ]
    |> Enum.flat_map(&List.wrap/1)
  end

  defp within_horizon?(activity, %{"starts_at_s" => start_s, "ends_at_s" => end_s})
       when is_number(start_s) and is_number(end_s) do
    activity["ends_at_s"] > start_s and activity["starts_at_s"] < end_s
  end

  defp within_horizon?(_activity, _horizon), do: true

  defp target_by_id(refresh, target_id) do
    target_id = encode_value(target_id)

    target_rows =
      refresh
      |> refresh_targets()
      |> Enum.map(&stringify_keys/1)
      |> Enum.group_by(&Map.get(&1, "id"))
      |> Map.get(target_id, [])

    case target_rows do
      [] -> objective_target_spec_by_id(refresh, target_id)
      rows -> unique_target_match(rows)
    end
  end

  defp objective_target_spec_by_id(refresh, target_id) do
    refresh
    |> refresh_objectives()
    |> Enum.flat_map(&objective_target_specs/1)
    |> Enum.filter(&(target_identity_value(&1) == target_id))
    |> unique_target_match()
  end

  defp unique_target_match([target]), do: target
  defp unique_target_match(_matches), do: nil

  defp refresh_targets(refresh) do
    [
      Map.get(refresh, "targets", []),
      get_in(refresh, ["mission_state", "targets"]) || [],
      get_in(refresh, ["accepted_planning_state", "targets"]) || []
    ]
    |> Enum.flat_map(&List.wrap/1)
  end

  defp eclipse_intervals_by_scenario(event_results) do
    event_results
    |> Enum.filter(&(&1.event_type == :eclipse))
    |> Enum.group_by(
      &encode_value(&1.scenario_id),
      fn result ->
        Enum.map(result.events, fn event ->
          {epoch_seconds(event.starts_at), epoch_seconds(event.ends_at)}
        end)
      end
    )
    |> Map.new(fn {scenario_id, grouped_intervals} ->
      {scenario_id, List.flatten(grouped_intervals)}
    end)
  end

  defp overlap_duration(interval, intervals) do
    intervals
    |> Enum.map(fn other -> interval_overlap_duration(interval, other) end)
    |> Enum.sum()
  end

  defp interval_overlap_duration({left_start, left_end}, {right_start, right_end}) do
    max(0.0, min(left_end, right_end) - max(left_start, right_start))
  end

  defp score(score_terms), do: score_terms |> Map.values() |> Enum.sum()

  defp event_timing_metadata(metadata) do
    metadata
    |> Map.take(@event_timing_keys)
    |> encode_value()
  end

  defp epoch_seconds(%{seconds_since_j2000: seconds}), do: seconds

  defp window_id(scenario_id, type, source_id, index) do
    ["window", scenario_id, type, source_id, index]
    |> Enum.map(&encode_value/1)
    |> Enum.join(":")
  end

  defp activity_id(scenario_id, type, source_id, index) do
    [scenario_id, type, source_id, index]
    |> Enum.map(&encode_value/1)
    |> Enum.join("_")
  end

  defp maybe_warn(warnings, true, message), do: [message | warnings]
  defp maybe_warn(warnings, false, _message), do: warnings

  defp maybe_stale_reason(reasons, true, reason), do: [reason | reasons]
  defp maybe_stale_reason(reasons, false, _reason), do: reasons

  defp maybe_unknown_reason(reasons, true, reason), do: [reason | reasons]
  defp maybe_unknown_reason(reasons, false, _reason), do: reasons

  defp compact_map(map) when is_map(map) do
    map
    |> Enum.reject(fn {_key, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp stringify_keys(%_struct{} = struct), do: struct |> Map.from_struct() |> stringify_keys()

  defp stringify_keys(%{} = map) do
    Map.new(map, fn {key, value} -> {encode_value(key), stringify_keys(value)} end)
  end

  defp stringify_keys(values) when is_list(values), do: Enum.map(values, &stringify_keys/1)
  defp stringify_keys(value), do: encode_value(value)

  defp numeric_value(value) when is_number(value), do: value * 1.0

  defp numeric_value(value) when is_binary(value) do
    case Float.parse(String.trim(value)) do
      {number, ""} -> number
      _error -> nil
    end
  end

  defp numeric_value(_value), do: nil

  defp boolean_value(value) when is_boolean(value), do: value

  defp boolean_value(value) when is_number(value) do
    cond do
      value == 1 -> true
      value == 0 -> false
      true -> nil
    end
  end

  defp boolean_value(value) when is_binary(value) do
    case String.downcase(String.trim(value)) do
      value when value in @boolean_true_tokens -> true
      value when value in @boolean_false_tokens -> false
      _value -> nil
    end
  end

  defp boolean_value(_value), do: nil

  defp encode_value(%{} = map) do
    Map.new(map, fn {key, value} -> {encode_value(key), encode_value(value)} end)
  end

  defp encode_value(values) when is_list(values) do
    if Keyword.keyword?(values) do
      Map.new(values, fn {key, value} -> {encode_value(key), encode_value(value)} end)
    else
      Enum.map(values, &encode_value/1)
    end
  end

  defp encode_value(value) when is_tuple(value), do: value |> Tuple.to_list() |> encode_value()
  defp encode_value(nil), do: nil
  defp encode_value(value) when is_boolean(value), do: value
  defp encode_value(value) when is_atom(value), do: Atom.to_string(value)
  defp encode_value(value), do: value
end
